final_template:
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.100.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-*-x86_64"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

variable "environment" {
  description = "Deployment environment name used for tagging."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Additional tags merged into every taggable resource."
  type        = map(string)
  default     = {}
}

locals {
  name_prefix = "alb-two-tier"
  vpc_cidr    = "10.0.0.0/16"
  http_port   = 80
  https_port  = 443
  azs         = slice(data.aws_availability_zones.available.names, 0, 2)

  common_tags = merge(
    {
      Project     = "alb-two-tier"
      Environment = var.environment
      ManagedBy   = "terraform"
    },
    var.tags,
  )
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

# Public tier: hosts the NAT gateway only. No auto-assigned public IPs.
resource "aws_subnet" "public" {
  count = length(local.azs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(local.vpc_cidr, 8, count.index + 1)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-${count.index + 1}"
    Tier = "public"
  })
}

# Private tier: hosts the internal ALB and the backend instances. No public IPs.
resource "aws_subnet" "private" {
  count = length(local.azs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(local.vpc_cidr, 8, count.index + 11)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-${count.index + 1}"
    Tier = "private"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nat-eip"
  })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nat"
  })

  depends_on = [aws_internet_gateway.main]
}

# Private tier egress path: 0.0.0.0/0 via the NAT gateway.
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count = length(aws_subnet.private)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "alb" {
  name        = "${local.name_prefix}-alb"
  description = "ALB tier: HTTP ingress, egress restricted to the VPC CIDR."
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-alb"
    Tier = "alb"
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_vpc_security_group_ingress_rule" "alb_http" {
  security_group_id = aws_security_group.alb.id

  description = "HTTP listener ingress for the ALB tier."
  cidr_ipv4   = "0.0.0.0/0"
  from_port   = local.http_port
  to_port     = local.http_port
  ip_protocol = "tcp"
}

resource "aws_vpc_security_group_egress_rule" "alb_to_vpc" {
  security_group_id = aws_security_group.alb.id

  description = "ALB egress confined to the VPC CIDR (reaches backends only)."
  cidr_ipv4   = local.vpc_cidr
  ip_protocol = "-1"
}

resource "aws_security_group" "allow_alb" {
  name        = "${local.name_prefix}-allow-alb"
  description = "Backend tier: HTTP ingress only from the ALB security group, egress restricted to the VPC CIDR."
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-allow-alb"
    Tier = "backend"
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_vpc_security_group_ingress_rule" "allow_alb_http" {
  security_group_id = aws_security_group.allow_alb.id

  description                  = "HTTP from the ALB tier only."
  referenced_security_group_id = aws_security_group.alb.id
  from_port                    = local.http_port
  to_port                      = local.http_port
  ip_protocol                  = "tcp"
}

resource "aws_vpc_security_group_egress_rule" "allow_alb_to_vpc" {
  security_group_id = aws_security_group.allow_alb.id

  description = "Backend egress confined to the VPC CIDR."
  cidr_ipv4   = local.vpc_cidr
  ip_protocol = "-1"
}

# Self-signed certificate material generated in-config for the internal HTTPS listener.
resource "tls_private_key" "alb" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "alb" {
  private_key_pem = tls_private_key.alb.private_key_pem

  subject {
    common_name  = "${local.name_prefix}.internal"
    organization = "ALB Two Tier"
  }

  validity_period_hours = 8760

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "alb" {
  certificate_body  = tls_self_signed_cert.alb.cert_pem
  certificate_chain = tls_self_signed_cert.alb.cert_pem
  private_key       = tls_private_key.alb.private_key_pem

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-cert"
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_lb" "main" {
  name               = "${local.name_prefix}-alb"
  internal           = true
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb.id]
  subnets            = aws_subnet.private[*].id

  enable_deletion_protection = false
  drop_invalid_header_fields = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-internal-alb"
  })
}

resource "aws_lb_target_group" "backend" {
  name        = "${local.name_prefix}-backend-tg"
  port        = local.http_port
  protocol    = "HTTP"
  vpc_id      = aws_vpc.main.id
  target_type = "instance"

  deregistration_delay = 30

  health_check {
    enabled             = true
    path                = "/"
    port                = "traffic-port"
    protocol            = "HTTP"
    matcher             = "200"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 3
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-backend-tg"
  })
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = local.http_port
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      port        = tostring(local.https_port)
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-http-redirect-listener"
  })
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.main.arn
  port              = local.https_port
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.alb.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.backend.arn
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-https-listener"
  })
}

resource "aws_instance" "backend" {
  count = 2

  ami                    = data.aws_ami.amazon_linux.id
  instance_type          = "t3.micro"
  subnet_id              = aws_subnet.private[count.index % length(aws_subnet.private)].id
  vpc_security_group_ids = [aws_security_group.allow_alb.id]

  user_data = base64encode(<<-EOT
    #!/bin/bash
    set -euo pipefail
    dnf update -y
    dnf install -y httpd
    systemctl enable httpd
    systemctl start httpd
    echo "OK from $(hostname)" > /var/www/html/index.html
  EOT
  )

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  root_block_device {
    volume_size = 8
    volume_type = "gp3"
    encrypted   = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-backend-${count.index + 1}"
  })
}

resource "aws_lb_target_group_attachment" "backend" {
  count = length(aws_instance.backend)

  target_group_arn = aws_lb_target_group.backend.arn
  target_id        = aws_instance.backend[count.index].id
  port             = local.http_port
}

output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets hosting the NAT gateway."
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets hosting the ALB and backends."
  value       = aws_subnet.private[*].id
}

output "alb_security_group_id" {
  description = "ID of the ALB tier security group."
  value       = aws_security_group.alb.id
}

output "allow_alb_security_group_id" {
  description = "ID of the backend tier security group."
  value       = aws_security_group.allow_alb.id
}

output "backend_instance_ids" {
  description = "IDs of the backend EC2 instances registered to the target group."
  value       = aws_instance.backend[*].id
}

output "load_balancer_dns_name" {
  description = "DNS name of the internal application load balancer."
  value       = aws_lb.main.dns_name
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "name_prefix" {
  description = "Prefix used for naming and tagging all resources created by this configuration."
  type        = string
  default     = "hashicorp-test"
}

locals {
  name_prefix = var.name_prefix

  common_tags = {
    Name        = local.name_prefix
    Environment = local.name_prefix
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block                       = "10.0.0.0/16"
  enable_dns_support               = true
  enable_dns_hostnames             = true
  assign_generated_ipv6_cidr_block = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "public" {
  vpc_id                          = aws_vpc.main.id
  cidr_block                      = "10.0.1.0/24"
  availability_zone               = data.aws_availability_zones.available.names[0]
  ipv6_cidr_block                 = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, 0)
  map_public_ip_on_launch         = false
  assign_ipv6_address_on_creation = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-subnet"
  })
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-subnet"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  description = "AWS region in which to deploy the networking stack."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the main VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_cidrs" {
  description = "CIDR blocks to assign to the subnets, one per availability zone."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "availability_zone_count" {
  description = "Number of availability zones from the region to spread subnets across."
  type        = number
  default     = 2
}

variable "environment" {
  description = "Environment name used for tagging."
  type        = string
  default     = "dev"
}

data "aws_availability_zones" "available" {
  state = "available"

  filter {
    name   = "opt-in-status"
    values = ["opt-in-not-required"]
  }
}

locals {
  availability_zones = slice(
    data.aws_availability_zones.available.names,
    0,
    var.availability_zone_count
  )

  subnet_count = min(length(local.availability_zones), length(var.subnet_cidrs))

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    {
      Name = "main-vpc"
    }
  )
}

resource "aws_subnet" "main" {
  count = local.subnet_count

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_cidrs[count.index]
  availability_zone = local.availability_zones[count.index]

  tags = merge(
    local.common_tags,
    {
      Name = "main-subnet-${count.index + 1}"
    }
  )
}

output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "CIDR block of the created VPC."
  value       = aws_vpc.main.cidr_block
}

output "subnet_ids" {
  description = "IDs of the created subnets."
  value       = aws_subnet.main[*].id
}

output "subnet_availability_zones" {
  description = "Availability zones in which the subnets were created."
  value       = aws_subnet.main[*].availability_zone
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

variable "monitoring_account_ids" {
  description = "AWS account IDs allowed to assume the Grafana data source query role. When left empty, the current account is used."
  type        = list(string)
  default     = []
}

variable "enable_managed_grafana_prometheus" {
  description = "Whether to create the Amazon Managed Grafana workspace and Amazon Managed Service for Prometheus workspace. Defaults to false so the automated (LocalStack) validation target applies cleanly, since LocalStack does not implement grafana:CreateWorkspace or amp:CreateWorkspace. Set to true for a real-AWS bring-up."
  type        = bool
  default     = false
}

locals {
  effective_monitoring_account_ids = length(var.monitoring_account_ids) > 0 ? var.monitoring_account_ids : [data.aws_caller_identity.current.account_id]

  grafana_workspace_name = "Grafana"
  grafana_role_name      = "grafana-query-role"
  grafana_policy_name    = "grafana-query-policy"
  prometheus_alias       = "grafana-monitoring"

  # Null-safe reference: resolves to the AMP workspace ARN when it exists, or null when the workspace is not created.
  amp_workspace_arn = one(aws_prometheus_workspace.monitoring[*].arn)

  grafana_query_statements = concat(
    var.enable_managed_grafana_prometheus ? [
      {
        Sid    = "AllowQueryingAmazonManagedPrometheus"
        Effect = "Allow"
        Action = [
          "aps:QueryMetrics",
          "aps:GetSeries",
          "aps:GetLabels",
          "aps:GetMetricMetadata"
        ]
        Resource = local.amp_workspace_arn
      }
    ] : [],
    [
      {
        Sid    = "AllowReadingCloudWatchMetrics"
        Effect = "Allow"
        Action = [
          "cloudwatch:ListMetrics",
          "cloudwatch:GetMetricData",
          "cloudwatch:GetMetricStatistics",
          "cloudwatch:DescribeAlarms"
        ]
        Resource = "*"
      }
    ]
  )
}

resource "aws_grafana_workspace" "grafana" {
  count = var.enable_managed_grafana_prometheus ? 1 : 0

  name                     = local.grafana_workspace_name
  description              = "Amazon Managed Grafana workspace used to visualise Amazon Managed Service for Prometheus and CloudWatch metrics."
  account_access_type      = "CURRENT_ACCOUNT"
  permission_type          = "CUSTOMER_MANAGED"
  authentication_providers = ["AWS_SSO"]
  data_sources             = ["PROMETHEUS", "CLOUDWATCH"]
  role_arn                 = aws_iam_role.grafana_query.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_prometheus_workspace" "monitoring" {
  count = var.enable_managed_grafana_prometheus ? 1 : 0

  alias = local.prometheus_alias

  tags = {
    Name = local.prometheus_alias
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "grafana_query" {
  name        = local.grafana_role_name
  description = "Role assumed by the Grafana workspace to query Amazon Managed Service for Prometheus and CloudWatch metrics."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowGrafanaWorkspaceAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "grafana.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.effective_monitoring_account_ids
          }
        }
      }
    ]
  })
}

resource "aws_iam_policy" "grafana_query" {
  name        = local.grafana_policy_name
  description = "Least-privilege policy allowing the Grafana workspace to read Amazon Managed Service for Prometheus and CloudWatch metrics."

  policy = jsonencode({
    Version   = "2012-10-17"
    Statement = local.grafana_query_statements
  })
}

resource "aws_iam_role_policy_attachment" "grafana_query" {
  role       = aws_iam_role.grafana_query.name
  policy_arn = aws_iam_policy.grafana_query.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Variables (all carry defaults so `terraform apply` runs unattended)
###############################################################################

variable "environment" {
  description = "Environment name used for tagging and resource naming."
  type        = string
  default     = "dev"
}

variable "project" {
  description = "Project name used for tagging and resource naming."
  type        = string
  default     = "container-platform"
}

###############################################################################
# Data sources (static provider metadata only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Locals
###############################################################################

locals {
  vpc_cidr = "10.0.0.0/16"

  # Two availability zones resolved dynamically - never hardcode "us-east-1a".
  az_names = slice(data.aws_availability_zones.available.names, 0, 2)

  # Subnet CIDRs carved from the VPC range (non-overlapping).
  public_subnet_cidrs  = [cidrsubnet(local.vpc_cidr, 8, 1), cidrsubnet(local.vpc_cidr, 8, 2)]
  private_subnet_cidrs = [cidrsubnet(local.vpc_cidr, 8, 11), cidrsubnet(local.vpc_cidr, 8, 12)]

  name_prefix = "${var.project}-${var.environment}"

  common_tags = {
    Project     = var.project
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

###############################################################################
# Public subnets (one per AZ)
#
# NOTE: `map_public_ip_on_launch` is deliberately left at its provider default
# of `false` (AVD-AWS-0164). These subnets remain functionally public because
# aws_route_table.public routes 0.0.0.0/0 to aws_internet_gateway.main.
# Any compute resource needing a public address should receive an explicit
# aws_eip + aws_eip_association rather than a subnet-wide auto-assign default.
###############################################################################

resource "aws_subnet" "public_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.public_subnet_cidrs[0]
  availability_zone = local.az_names[0]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-a"
    Tier = "public"
  })
}

resource "aws_subnet" "public_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.public_subnet_cidrs[1]
  availability_zone = local.az_names[1]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-b"
    Tier = "public"
  })
}

###############################################################################
# Private subnets (one per AZ)
###############################################################################

resource "aws_subnet" "private_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidrs[0]
  availability_zone = local.az_names[0]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-a"
    Tier = "private"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidrs[1]
  availability_zone = local.az_names[1]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-b"
    Tier = "private"
  })
}

###############################################################################
# Internet gateway for public subnets
###############################################################################

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

###############################################################################
# Single NAT gateway (shared by both private subnets)
#
# The NAT gateway uses the explicitly allocated aws_eip.nat and therefore does
# not depend on `map_public_ip_on_launch` on the hosting subnet.
###############################################################################

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nat-eip"
  })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public_a.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nat"
  })

  depends_on = [aws_internet_gateway.main]
}

###############################################################################
# Public routing
###############################################################################

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# Private routing (via the single NAT gateway)
###############################################################################

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-rt"
  })
}

resource "aws_route_table_association" "private_a" {
  subnet_id      = aws_subnet.private_a.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_b" {
  subnet_id      = aws_subnet.private_b.id
  route_table_id = aws_route_table.private.id
}

###############################################################################
# Application security group
###############################################################################

resource "aws_security_group" "app" {
  name        = "${local.name_prefix}-app-sg"
  description = "Security group for containerized applications"
  vpc_id      = aws_vpc.main.id

  # SSH is restricted to the VPC CIDR only - never 0.0.0.0/0.
  ingress {
    description = "SSH from within the VPC CIDR only"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  # Justification: port 3000 is the application listener and is intentionally
  # published for inbound traffic as explicitly requested.
  ingress {
    description = "Application listener (3000) from anywhere - explicitly requested"
    from_port   = 3000
    to_port     = 3000
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  # Justification / RISK: port 5432 (PostgreSQL) is exposed to the internet as
  # explicitly requested. This violates least-privilege and should be re-scoped
  # to the VPC CIDR (aws_vpc.main.cidr_block) or a dedicated database security
  # group source in a follow-up change.
  ingress {
    description = "PostgreSQL (5432) from anywhere - explicitly requested, high risk"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  # NOTE: Egress is intentionally limited to the VPC CIDR. This blocks all
  # internet-bound egress, including container image pulls that would otherwise
  # traverse the NAT gateway. If external egress is later required, add
  # protocol/port-scoped egress rules (e.g. TCP 443) rather than opening
  # 0.0.0.0/0 for all traffic.
  egress {
    description = "Egress restricted to the VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-app-sg"
  })
}

###############################################################################
# Private Service Discovery DNS namespace
###############################################################################

resource "aws_service_discovery_private_dns_namespace" "service_local" {
  name        = "service.local"
  description = "Private DNS namespace for container service discovery (resolves *.service.local inside the VPC only; records are never published publicly)."
  vpc         = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-service-local"
  })
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_region" "current" {}

variable "tags" {
  description = "Common tags applied to all taggable resources."
  type        = map(string)
  default = {
    Environment = "dev"
    Project     = "mobile-app"
    ManagedBy   = "Terraform"
  }
}

locals {
  name_prefix = "mobile-app"
}

resource "aws_cognito_user_pool" "main" {
  name = "${local.name_prefix}-user-pool"

  username_attributes      = ["email"]
  auto_verified_attributes = ["email"]

  mfa_configuration = "ON"

  software_token_mfa_configuration {
    enabled = true
  }

  password_policy {
    minimum_length    = 12
    require_uppercase = true
    require_lowercase = true
    require_numbers   = true
    require_symbols   = true
  }

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_cognito_user_pool_client" "app" {
  name         = "${local.name_prefix}-app-client"
  user_pool_id = aws_cognito_user_pool.main.id

  generate_secret = false

  explicit_auth_flows = [
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH",
  ]

  prevent_user_existence_errors = "ENABLED"
}

resource "aws_cognito_identity_pool" "main" {
  identity_pool_name               = "${local.name_prefix}-identity-pool"
  allow_unauthenticated_identities = false

  cognito_identity_providers {
    client_id     = aws_cognito_user_pool_client.app.id
    provider_name = "cognito-idp.${data.aws_region.current.name}.amazonaws.com/${aws_cognito_user_pool.main.id}"
  }

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "authenticated" {
  name = "${local.name_prefix}-cognito-authenticated"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCognitoAuthenticatedIdentities"
        Effect = "Allow"
        Principal = {
          Federated = "cognito-identity.amazonaws.com"
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "cognito-identity.amazonaws.com:aud" = aws_cognito_identity_pool.main.id
          }
          "ForAnyValue:StringLike" = {
            "cognito-identity.amazonaws.com:amr" = "authenticated"
          }
        }
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_policy" "authenticated_mobile" {
  name        = "${local.name_prefix}-cognito-mobile-policy"
  description = "Least-privilege access for authenticated Cognito identities to Cognito Sync and Mobile Analytics."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CognitoSyncLegacyAccess"
        Effect = "Allow"
        Action = [
          "cognito-sync:ListRecords",
          "cognito-sync:UpdateRecords",
          "cognito-sync:ListDatasets",
          "cognito-sync:SubscribeToDataset",
          "cognito-sync:UnsubscribeFromDataset",
          "cognito-sync:GetIdentityPoolConfiguration",
          "cognito-sync:SetIdentityPoolConfiguration",
        ]
        # Cognito Sync legacy APIs do not support resource-level ARNs, so "*" is required here.
        Resource = "*"
      },
      {
        Sid    = "MobileAnalyticsPutEvents"
        Effect = "Allow"
        Action = [
          "mobileanalytics:PutEvents",
        ]
        # Amazon Mobile Analytics does not support resource-level ARNs, so "*" is required here.
        Resource = "*"
      },
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "authenticated_mobile" {
  role       = aws_iam_role.authenticated.name
  policy_arn = aws_iam_policy.authenticated_mobile.arn
}

resource "aws_cognito_identity_pool_roles_attachment" "main" {
  identity_pool_id = aws_cognito_identity_pool.main.id

  roles = {
    authenticated = aws_iam_role.authenticated.arn
  }
}

output "cognito_user_pool_id" {
  description = "ID of the Cognito User Pool."
  value       = aws_cognito_user_pool.main.id
}

output "cognito_user_pool_client_id" {
  description = "ID of the Cognito User Pool app client."
  value       = aws_cognito_user_pool_client.app.id
}

output "cognito_identity_pool_id" {
  description = "ID of the Cognito Identity Pool."
  value       = aws_cognito_identity_pool.main.id
}

output "authenticated_iam_role_arn" {
  description = "ARN of the IAM role assumed by authenticated Cognito identities."
  value       = aws_iam_role.authenticated.arn
}

###############################################################################
# Terraform & Provider Requirements
#
# NOTE: No `provider` block and no `backend` block are declared here. The
# provider configuration and state backend are injected/managed externally by
# the deployment harness.
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.0"
    }
  }
}

###############################################################################
# Data Sources (static provider metadata only - no pre-existing infrastructure)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Variables - Mutually Exclusive Creation Flags
#
# Exactly one of the four creation flags must be true. create_standard_key
# defaults to true so that a zero-input deploy provisions exactly one standard
# KMS key. Selecting any other creation mode requires explicitly setting
# create_standard_key = false first, preserving the mutual-exclusion contract.
###############################################################################

variable "create_standard_key" {
  description = "Create a standard customer-managed KMS key with AWS-provided key material. Defaults to true so a zero-input deployment provisions exactly one key. Set to false when enabling any other creation mode."
  type        = bool
  default     = true
}

variable "create_external_key" {
  description = "Create a KMS key with imported (external) base64 key material. Requires create_standard_key = false."
  type        = bool
  default     = false
}

variable "create_replica_key" {
  description = "Create a standard multi-region replica key that references a primary key ARN. Requires create_standard_key = false."
  type        = bool
  default     = false
}

variable "create_replica_external_key" {
  description = "Create a multi-region replica key with external key material referencing a primary external key ARN. Requires create_standard_key = false."
  type        = bool
  default     = false
}

###############################################################################
# Variables - External Key Material & Primary Keys
###############################################################################

variable "key_material_base64" {
  description = "Base64-encoded 256-bit symmetric key material for external keys. NEVER commit this value to source control."
  type        = string
  default     = null
  sensitive   = true
}

variable "primary_key_arn" {
  description = "ARN of the multi-region primary KMS key that the replica key replicates."
  type        = string
  default     = null
}

variable "primary_external_key_arn" {
  description = "ARN of the multi-region primary external KMS key that the replica external key replicates."
  type        = string
  default     = null
}

###############################################################################
# Variables - Common Key Attributes
###############################################################################

variable "description" {
  description = "Description of the KMS key."
  type        = string
  default     = "Customer managed KMS key managed by Terraform"
}

variable "deletion_window_in_days" {
  description = "Duration (in days) after which the key is deleted. Must be between 7 and 30."
  type        = number
  default     = 30

  validation {
    condition     = var.deletion_window_in_days >= 7 && var.deletion_window_in_days <= 30
    error_message = "deletion_window_in_days must be between 7 and 30 inclusive."
  }
}

variable "multi_region" {
  description = "Create the key as a multi-region primary key."
  type        = bool
  default     = false
}

variable "tags" {
  description = "Tags applied to all resources created by this module."
  type        = map(string)
  default     = {}
}

###############################################################################
# Variables - Key Policy Inputs
###############################################################################

variable "key_owner_arns" {
  description = "IAM principal ARNs granted full administrative control over the key (account scoped)."
  type        = list(string)
  default     = []
}

variable "key_administrator_arns" {
  description = "IAM principal ARNs granted key administrative actions."
  type        = list(string)
  default     = []
}

variable "standard_key_user_arns" {
  description = "IAM principal ARNs granted standard cryptographic usage of the key."
  type        = list(string)
  default     = []
}

variable "service_user_principals" {
  description = "AWS service principals (e.g. s3.amazonaws.com) allowed to use the key on behalf of callers."
  type        = list(string)
  default     = []
}

variable "service_user_source_arns" {
  description = "Source ARNs constrained for service users (used as an aws:SourceArn condition)."
  type        = list(string)
  default     = []
}

variable "ec2_autoscaling_role_arns" {
  description = "Source ARNs (e.g. Auto Scaling group ARNs) allowed for the autoscaling.amazonaws.com service principal."
  type        = list(string)
  default     = []
}

variable "symmetric_crypto_user_arns" {
  description = "IAM principal ARNs granted symmetric encryption/decryption operations."
  type        = list(string)
  default     = []
}

variable "hmac_crypto_user_arns" {
  description = "IAM principal ARNs granted HMAC generation/verification operations."
  type        = list(string)
  default     = []
}

variable "asymmetric_public_encrypt_user_arns" {
  description = "IAM principal ARNs granted asymmetric public-key encryption operations."
  type        = list(string)
  default     = []
}

variable "asymmetric_sign_verify_user_arns" {
  description = "IAM principal ARNs granted asymmetric sign/verify operations."
  type        = list(string)
  default     = []
}

variable "dnssec_hosted_zone_arn" {
  description = "ARN of the Route 53 hosted zone that grants DNSSEC signing access to the key. Leave null to disable."
  type        = string
  default     = null
}

variable "custom_policy_statements" {
  description = "Additional key policy statements appended to the generated document."

  type = list(object({
    sid        = optional(string)
    effect     = optional(string, "Allow")
    principals = optional(list(string), [])
    actions    = optional(list(string), [])
    resources  = optional(list(string), ["*"])
    conditions = optional(list(object({
      test     = string
      variable = string
      values   = list(string)
    })), [])
  }))

  default = []
}

variable "policy_override_json" {
  description = "Full JSON key policy that completely replaces the generated policy when non-null."
  type        = string
  default     = null
  sensitive   = true
}

###############################################################################
# Variables - Aliases & Grants
###############################################################################

variable "alias_names" {
  description = "Map of exact KMS alias names to create (key => unused identifier). Example: { \"alias/my-key\" = \"exact\" }."
  type        = map(string)
  default     = {}
}

variable "alias_name_prefixes" {
  description = "Map of KMS alias name prefixes to create. Terraform appends a unique suffix to each key."
  type        = map(string)
  default     = {}
}

variable "key_grants" {
  description = "Map of KMS grants to create. The map key is used as the grant name."

  type = map(object({
    grantee_principal         = string
    operations                = list(string)
    retiring_principal        = optional(string)
    encryption_context_subset = optional(map(string))
    encryption_context_equals = optional(map(string))
  }))

  default = {}
}

###############################################################################
# Locals - Validation & Active Key Resolution
###############################################################################

locals {
  # Local validation expression: the collection of enabled creation flags.
  create_flags = [
    var.create_standard_key,
    var.create_external_key,
    var.create_replica_key,
    var.create_replica_external_key,
  ]

  # True only when exactly one creation flag is enabled.
  exactly_one_key_enabled = length([for enabled in local.create_flags : enabled if enabled]) == 1

  # Resolve whichever key has actually been provisioned.
  active_key_id = try(
    aws_kms_key.standard[0].id,
    aws_kms_external_key.external[0].id,
    aws_kms_replica_key.replica[0].id,
    aws_kms_replica_external_key.replica_external[0].id,
    null
  )

  active_key_arn = try(
    aws_kms_key.standard[0].arn,
    aws_kms_external_key.external[0].arn,
    aws_kms_replica_key.replica[0].arn,
    aws_kms_replica_external_key.replica_external[0].arn,
    null
  )

  # Resource scope used inside the key policy. Falls back to "*" only if no key
  # is present, which the preconditions below prevent from ever being deployed.
  policy_key_arn = local.active_key_arn == null ? "*" : local.active_key_arn

  # Least-privilege action sets.
  key_admin_actions = [
    "kms:Create*",
    "kms:Describe*",
    "kms:Enable*",
    "kms:List*",
    "kms:Put*",
    "kms:Update*",
    "kms:Revoke*",
    "kms:Disable*",
    "kms:Get*",
    "kms:TagResource",
    "kms:UntagResource",
  ]

  key_user_actions = [
    "kms:Encrypt",
    "kms:Decrypt",
    "kms:ReEncrypt*",
    "kms:GenerateDataKey*",
    "kms:DescribeKey",
  ]

  hmac_actions = [
    "kms:GenerateMac",
    "kms:VerifyMac",
    "kms:DescribeKey",
  ]

  asymmetric_public_encrypt_actions = [
    "kms:Encrypt",
    "kms:DescribeKey",
  ]

  asymmetric_sign_verify_actions = [
    "kms:Sign",
    "kms:Verify",
    "kms:DescribeKey",
  ]

  dnssec_actions = [
    "kms:GetPublicKey",
    "kms:Sign",
    "kms:DescribeKey",
  ]

  account_root_arn = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"

  # Derive kms:ViaService style endpoints from the supplied service principals.
  service_via_service_endpoints = [
    for principal in var.service_user_principals :
    "${trimsuffix(principal, ".amazonaws.com")}.${data.aws_region.current.name}.amazonaws.com"
  ]
}

###############################################################################
# Input Validation (lifecycle preconditions)
###############################################################################

resource "null_resource" "validation" {
  lifecycle {
    precondition {
      condition     = local.exactly_one_key_enabled
      error_message = "Exactly one of create_standard_key, create_external_key, create_replica_key, or create_replica_external_key must be set to true."
    }

    precondition {
      condition     = !(var.create_external_key || var.create_replica_external_key) || var.key_material_base64 != null
      error_message = "key_material_base64 must be provided when create_external_key or create_replica_external_key is true."
    }

    precondition {
      condition     = !var.create_replica_key || var.primary_key_arn != null
      error_message = "primary_key_arn must be provided when create_replica_key is true."
    }

    precondition {
      condition     = !var.create_replica_external_key || var.primary_external_key_arn != null
      error_message = "primary_external_key_arn must be provided when create_replica_external_key is true."
    }

    precondition {
      condition     = length(var.alias_names) == 0 || length(var.alias_name_prefixes) == 0
      error_message = "Only one of alias_names or alias_name_prefixes may be non-empty."
    }
  }
}

###############################################################################
# KMS Keys
###############################################################################

resource "aws_kms_key" "standard" {
  count = var.create_standard_key ? 1 : 0

  description             = var.description
  deletion_window_in_days = var.deletion_window_in_days
  enable_key_rotation     = true
  multi_region            = var.multi_region
  tags                    = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_external_key" "external" {
  count = var.create_external_key ? 1 : 0

  description             = var.description
  deletion_window_in_days = var.deletion_window_in_days
  key_material_base64     = var.key_material_base64
  multi_region            = var.multi_region
  tags                    = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_replica_key" "replica" {
  count = var.create_replica_key ? 1 : 0

  description             = var.description
  deletion_window_in_days = var.deletion_window_in_days
  primary_key_arn         = var.primary_key_arn
  tags                    = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_replica_external_key" "replica_external" {
  count = var.create_replica_external_key ? 1 : 0

  description             = var.description
  deletion_window_in_days = var.deletion_window_in_days
  primary_key_arn         = var.primary_external_key_arn
  key_material_base64     = var.key_material_base64
  tags                    = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Key Policy Document
###############################################################################

data "aws_iam_policy_document" "key_policy" {
  # Default root policy - full control for the account root, which prevents the
  # key from becoming unmanageable.
  statement {
    sid    = "DefaultRootAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  # Key owners - account scoped administrative control.
  dynamic "statement" {
    for_each = length(var.key_owner_arns) > 0 ? [1] : []

    content {
      sid    = "KeyOwners"
      effect = "Allow"

      principals {
        type        = "AWS"
        identifiers = var.key_owner_arns
      }

      actions   = local.key_admin_actions
      resources = ["*"]

      condition {
        test     = "StringEquals"
        variable = "kms:CallerAccount"
        values   = [data.aws_caller_identity.current.account_id]
      }
    }
  }

  # Key administrators - same administrative actions, scoped to this key.
  dynamic "statement" {
    for_each = length(var.key_administrator_arns) > 0 ? [1] : []

    content {
      sid    = "KeyAdministrators"
      effect = "Allow"

      principals {
        type        = "AWS"
        identifiers = var.key_administrator_arns
      }

      actions   = local.key_admin_actions
      resources = [local.policy_key_arn]

      condition {
        test     = "StringEquals"
        variable = "kms:CallerAccount"
        values   = [data.aws_caller_identity.current.account_id]
      }
    }
  }

  # Standard key users.
  dynamic "statement" {
    for_each = length(var.standard_key_user_arns) > 0 ? [1] : []

    content {
      sid    = "StandardKeyUsers"
      effect = "Allow"

      principals {
        type        = "AWS"
        identifiers = var.standard_key_user_arns
      }

      actions   = local.key_user_actions
      resources = [local.policy_key_arn]
    }
  }

  # AWS service users - constrained by kms:ViaService and aws:SourceArn.
  dynamic "statement" {
    for_each = length(var.service_user_principals) > 0 ? [1] : []

    content {
      sid    = "ServiceUsers"
      effect = "Allow"

      principals {
        type        = "Service"
        identifiers = var.service_user_principals
      }

      actions   = local.key_user_actions
      resources = [local.policy_key_arn]

      condition {
        test     = "StringEquals"
        variable = "kms:ViaService"
        values   = local.service_via_service_endpoints
      }

      dynamic "condition" {
        for_each = length(var.service_user_source_arns) > 0 ? [1] : []

        content {
          test     = "StringEquals"
          variable = "aws:SourceArn"
          values   = var.service_user_source_arns
        }
      }
    }
  }

  # EC2 Auto Scaling service usage.
  dynamic "statement" {
    for_each = length(var.ec2_autoscaling_role_arns) > 0 ? [1] : []

    content {
      sid    = "EC2AutoScaling"
      effect = "Allow"

      principals {
        type        = "Service"
        identifiers = ["autoscaling.amazonaws.com"]
      }

      actions   = local.key_user_actions
      resources = [local.policy_key_arn]

      condition {
        test     = "StringEquals"
        variable = "aws:SourceArn"
        values   = var.ec2_autoscaling_role_arns
      }
    }
  }

  # Symmetric cryptographic users.
  dynamic "statement" {
    for_each = length(var.symmetric_crypto_user_arns) > 0 ? [1] : []

    content {
      sid    = "SymmetricCryptoUsers"
      effect = "Allow"

      principals {
        type        = "AWS"
        identifiers = var.symmetric_crypto_user_arns
      }

      actions   = local.key_user_actions
      resources = [local.policy_key_arn]
    }
  }

  # HMAC cryptographic users.
  dynamic "statement" {
    for_each = length(var.hmac_crypto_user_arns) > 0 ? [1] : []

    content {
      sid    = "HmacCryptoUsers"
      effect = "Allow"

      principals {
        type        = "AWS"
        identifiers = var.hmac_crypto_user_arns
      }

      actions   = local.hmac_actions
      resources = [local.policy_key_arn]
    }
  }

  # Asymmetric public encryption users.
  dynamic "statement" {
    for_each = length(var.asymmetric_public_encrypt_user_arns) > 0 ? [1] : []

    content {
      sid    = "AsymmetricPublicEncryptUsers"
      effect = "Allow"

      principals {
        type        = "AWS"
        identifiers = var.asymmetric_public_encrypt_user_arns
      }

      actions   = local.asymmetric_public_encrypt_actions
      resources = [local.policy_key_arn]
    }
  }

  # Asymmetric sign / verify users.
  dynamic "statement" {
    for_each = length(var.asymmetric_sign_verify_user_arns) > 0 ? [1] : []

    content {
      sid    = "AsymmetricSignVerifyUsers"
      effect = "Allow"

      principals {
        type        = "AWS"
        identifiers = var.asymmetric_sign_verify_user_arns
      }

      actions   = local.asymmetric_sign_verify_actions
      resources = [local.policy_key_arn]
    }
  }

  # Route 53 DNSSEC signing.
  dynamic "statement" {
    for_each = var.dnssec_hosted_zone_arn != null && var.dnssec_hosted_zone_arn != "" ? [1] : []

    content {
      sid    = "Route53DnssecSigning"
      effect = "Allow"

      principals {
        type        = "Service"
        identifiers = ["dnssec-route53.amazonaws.com"]
      }

      actions   = local.dnssec_actions
      resources = [local.policy_key_arn]

      condition {
        test     = "StringEquals"
        variable = "aws:SourceArn"
        values   = [var.dnssec_hosted_zone_arn]
      }
    }
  }

  # Caller supplied custom statements.
  dynamic "statement" {
    for_each = { for idx, stmt in var.custom_policy_statements : tostring(idx) => stmt }

    content {
      sid    = statement.value.sid
      effect = statement.value.effect

      dynamic "principals" {
        for_each = length(statement.value.principals) > 0 ? [1] : []

        content {
          type        = "AWS"
          identifiers = statement.value.principals
        }
      }

      actions   = statement.value.actions
      resources = statement.value.resources

      dynamic "condition" {
        for_each = statement.value.conditions

        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

locals {
  # A full override policy wins over the generated document when supplied.
  effective_policy_json = var.policy_override_json != null ? var.policy_override_json : data.aws_iam_policy_document.key_policy.json
}

###############################################################################
# Key Policies
###############################################################################

resource "aws_kms_key_policy" "standard" {
  count = var.create_standard_key ? 1 : 0

  key_id = aws_kms_key.standard[0].id
  policy = local.effective_policy_json
}

resource "aws_kms_key_policy" "external" {
  count = var.create_external_key ? 1 : 0

  key_id = aws_kms_external_key.external[0].id
  policy = local.effective_policy_json
}

resource "aws_kms_key_policy" "replica" {
  count = var.create_replica_key ? 1 : 0

  key_id = aws_kms_replica_key.replica[0].id
  policy = local.effective_policy_json
}

resource "aws_kms_key_policy" "replica_external" {
  count = var.create_replica_external_key ? 1 : 0

  key_id = aws_kms_replica_external_key.replica_external[0].id
  policy = local.effective_policy_json
}

###############################################################################
# Aliases
###############################################################################

resource "aws_kms_alias" "exact" {
  for_each = var.alias_names

  name          = each.key
  target_key_id = local.active_key_id
}

resource "aws_kms_alias" "prefix" {
  for_each = var.alias_name_prefixes

  name_prefix   = each.key
  target_key_id = local.active_key_id
}

###############################################################################
# Grants
###############################################################################

resource "aws_kms_grant" "grants" {
  for_each = var.key_grants

  name               = each.key
  key_id             = local.active_key_id
  grantee_principal  = each.value.grantee_principal
  operations         = each.value.operations
  retiring_principal = each.value.retiring_principal

  dynamic "constraints" {
    for_each = (
      each.value.encryption_context_subset != null || each.value.encryption_context_equals != null
    ) ? [1] : []

    content {
      encryption_context_subset = each.value.encryption_context_subset
      encryption_context_equals = each.value.encryption_context_equals
    }
  }
}

###############################################################################
# Outputs
###############################################################################

output "key_arn" {
  description = "ARN of the provisioned KMS key."
  value       = local.active_key_arn
}

output "key_id" {
  description = "ID of the provisioned KMS key."
  value       = local.active_key_id
}

output "alias_names" {
  description = "Names of all KMS aliases created by this module."
  value = sort(concat(
    [for alias in aws_kms_alias.exact : alias.name],
    [for alias in aws_kms_alias.prefix : alias.name],
  ))
}

output "alias_arns" {
  description = "ARNs of all KMS aliases created by this module."
  value = sort(concat(
    [for alias in aws_kms_alias.exact : alias.arn],
    [for alias in aws_kms_alias.prefix : alias.arn],
  ))
}

output "grant_ids" {
  description = "Map of grant names to their KMS grant IDs."
  value       = { for name, grant in aws_kms_grant.grants : name => grant.grant_id }
}

output "key_policy_json" {
  description = "Effective JSON key policy applied to the KMS key."
  value       = local.effective_policy_json
  sensitive   = true
}

output "key_material_base64" {
  description = "Base64-encoded external key material supplied to the module."
  value       = var.key_material_base64
  sensitive   = true
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

################################################################################
# Variables
################################################################################

variable "vpc_name" {
  description = "Name to be used for the VPC and as the value of the Blueprint tag on all resources"
  type        = string
  default     = "blueprint-eks"
}

################################################################################
# Availability Zones
################################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

################################################################################
# Locals
################################################################################

locals {
  tags = {
    Blueprint  = var.vpc_name
    GithubRepo = "github.com/aws-ia/terraform-aws-eks-blueprints"
  }
}

################################################################################
# VPC
# - CIDR 10.0.0.0/16
# - 3 private subnets: /20 (prefix extension 4) at netnums 0, 1, 2
# - 3 public subnets:  /24 (prefix extension 8) at netnums 48, 49, 50
# - Single NAT gateway shared by all private subnets
################################################################################

module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "~> 5.0"

  name = var.vpc_name
  cidr = "10.0.0.0/16"

  azs = slice(data.aws_availability_zones.available.names, 0, 3)

  private_subnets = [
    cidrsubnet("10.0.0.0/16", 4, 0),
    cidrsubnet("10.0.0.0/16", 4, 1),
    cidrsubnet("10.0.0.0/16", 4, 2),
  ]

  public_subnets = [
    cidrsubnet("10.0.0.0/16", 8, 48),
    cidrsubnet("10.0.0.0/16", 8, 49),
    cidrsubnet("10.0.0.0/16", 8, 50),
  ]

  enable_dns_hostnames = true
  enable_dns_support   = true

  enable_nat_gateway     = true
  single_nat_gateway     = true
  one_nat_gateway_per_az = false

  public_subnet_tags = {
    "kubernetes.io/role/elb" = "1"
  }

  private_subnet_tags = {
    "kubernetes.io/role/internal-elb" = "1"
  }

  tags = local.tags
}

################################################################################
# Dedicated cross-cluster security groups
################################################################################

resource "aws_security_group" "cluster1_additional_sg" {
  name        = "cluster1_additional_sg"
  description = "Additional security group for cluster1 allowing reciprocal all-protocol traffic with cluster2"
  vpc_id      = module.vpc.vpc_id

  tags = merge(local.tags, { Name = "cluster1_additional_sg" })
}

resource "aws_security_group" "cluster2_additional_sg" {
  name        = "cluster2_additional_sg"
  description = "Additional security group for cluster2 allowing reciprocal all-protocol traffic with cluster1"
  vpc_id      = module.vpc.vpc_id

  tags = merge(local.tags, { Name = "cluster2_additional_sg" })
}

################################################################################
# Cross-cluster rules (SG-to-SG only, no CIDR based access)
################################################################################

# cluster1 ingress from cluster2
resource "aws_vpc_security_group_ingress_rule" "cluster1_ingress_from_cluster2" {
  security_group_id            = aws_security_group.cluster1_additional_sg.id
  description                  = "Allow all inbound traffic from cluster2 additional security group"
  ip_protocol                  = "-1"
  from_port                    = 0
  to_port                      = 0
  referenced_security_group_id = aws_security_group.cluster2_additional_sg.id

  tags = merge(local.tags, { Name = "cluster1-ingress-from-cluster2" })
}

# cluster1 egress to cluster2
resource "aws_vpc_security_group_egress_rule" "cluster1_egress_to_cluster2" {
  security_group_id            = aws_security_group.cluster1_additional_sg.id
  description                  = "Allow all outbound traffic to cluster2 additional security group"
  ip_protocol                  = "-1"
  from_port                    = 0
  to_port                      = 0
  referenced_security_group_id = aws_security_group.cluster2_additional_sg.id

  tags = merge(local.tags, { Name = "cluster1-egress-to-cluster2" })
}

# cluster2 ingress from cluster1
resource "aws_vpc_security_group_ingress_rule" "cluster2_ingress_from_cluster1" {
  security_group_id            = aws_security_group.cluster2_additional_sg.id
  description                  = "Allow all inbound traffic from cluster1 additional security group"
  ip_protocol                  = "-1"
  from_port                    = 0
  to_port                      = 0
  referenced_security_group_id = aws_security_group.cluster1_additional_sg.id

  tags = merge(local.tags, { Name = "cluster2-ingress-from-cluster1" })
}

# cluster2 egress to cluster1
resource "aws_vpc_security_group_egress_rule" "cluster2_egress_to_cluster1" {
  security_group_id            = aws_security_group.cluster2_additional_sg.id
  description                  = "Allow all outbound traffic to cluster1 additional security group"
  ip_protocol                  = "-1"
  from_port                    = 0
  to_port                      = 0
  referenced_security_group_id = aws_security_group.cluster1_additional_sg.id

  tags = merge(local.tags, { Name = "cluster2-egress-to-cluster1" })
}

################################################################################
# Outputs
################################################################################

output "vpc_id" {
  description = "ID of the VPC"
  value       = module.vpc.vpc_id
}

output "vpc_cidr_block" {
  description = "CIDR block of the VPC"
  value       = module.vpc.vpc_cidr_block
}

output "availability_zones" {
  description = "Availability zones used by the VPC subnets"
  value       = slice(data.aws_availability_zones.available.names, 0, 3)
}

output "private_subnets" {
  description = "List of private subnet IDs"
  value       = module.vpc.private_subnets
}

output "public_subnets" {
  description = "List of public subnet IDs"
  value       = module.vpc.public_subnets
}

output "nat_gateway_ids" {
  description = "List of NAT gateway IDs (single shared NAT gateway)"
  value       = module.vpc.natgw_ids
}

output "cluster1_additional_sg_id" {
  description = "ID of the additional security group for cluster1"
  value       = aws_security_group.cluster1_additional_sg.id
}

output "cluster2_additional_sg_id" {
  description = "ID of the additional security group for cluster2"
  value       = aws_security_group.cluster2_additional_sg.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

################################################################################
# Input variables
################################################################################

variable "tags" {
  description = "Tags applied to every resource that supports tagging."
  type        = map(string)
  default     = {}
}

# --- User pool core -----------------------------------------------------------

variable "pool_name" {
  description = "Name of the Cognito User Pool."
  type        = string
  default     = "Pool name"
}

variable "alias_attributes" {
  description = "Attributes that can be used as aliases when signing in."
  type        = list(string)
  default     = ["email", "phone_number"]
}

variable "auto_verified_attributes" {
  description = "Attributes that Cognito verifies automatically."
  type        = list(string)
  default     = []
}

variable "email_verification_message" {
  description = "Verification message sent by e-mail."
  type        = string
  default     = "Some message {####}"
}

variable "email_verification_subject" {
  description = "Subject used for verification e-mails."
  type        = string
  default     = "Some subject"
}

variable "mfa_configuration" {
  description = "Multi-factor authentication configuration (OFF, ON or OPTIONAL)."
  type        = string
  default     = "OPTIONAL"
}

variable "sms_authentication_message" {
  description = "SMS message sent for MFA challenges."
  type        = string
  default     = "SMS authentication message {####}"
}

variable "sms_verification_message" {
  description = "SMS message sent for verification."
  type        = string
  default     = "SMS verification message {####}"
}

variable "verification_message_template_by_link" {
  description = "Map describing the by-link e-mail verification template."
  type        = map(string)
  default = {
    default_email_option  = "CONFIRM_WITH_LINK"
    email_subject_by_link = "Some subject by link"
    email_message_by_link = "Some message by link {##Verify Email##}"
  }
}

variable "sms_configuration" {
  description = "SMS configuration for the user pool (external_id + sns_caller_arn)."
  type        = map(string)
  default = {
    external_id    = ""
    sns_caller_arn = ""
  }
}

variable "account_recovery_setting" {
  description = "Account recovery mechanisms expressed as name => priority."
  type        = map(number)
  default = {
    verified_email        = 2
    verified_phone_number = 1
  }
}

variable "invite_message_template" {
  description = "Invitation messages sent to users created by an administrator."
  type        = map(string)
  default = {
    email_subject = "Your temporary password"
    email_message = "Your username is {username} and temporary password is {####}"
    sms_message   = "Your username is {username} and temporary password is {####}"
  }
}

variable "admin_create_user_only" {
  description = "When true only administrators can create users."
  type        = bool
  default     = false
}

variable "enable_software_token_mfa" {
  description = "Enable TOTP software token MFA."
  type        = bool
  default     = true
}

variable "username_case_sensitivity" {
  description = "Whether usernames are case sensitive. Null omits the block."
  type        = bool
  default     = null
}

variable "device_configuration" {
  description = "Device tracking configuration. Null omits the block."
  type        = map(bool)
  default     = null
}

variable "lambda_config" {
  description = "Map of Lambda triggers to attach to the user pool."
  type        = any
  default     = {}
}

variable "schema" {
  description = "Attribute schema definitions (with or without min/max constraints)."
  type        = list(any)
  default = [
    {
      name                = "email"
      attribute_data_type = "String"
      required            = true
      mutable             = true
    }
  ]
}

# --- User pool clients --------------------------------------------------------

variable "client_names" {
  description = "List of user pool client names to create."
  type        = list(string)
  default     = []
}

variable "client_generate_secret" {
  description = "Whether a client secret is generated for the clients."
  type        = bool
  default     = false
}

variable "client_access_token_validity" {
  description = "Access token validity."
  type        = number
  default     = 120
}

variable "client_id_token_validity" {
  description = "ID token validity."
  type        = number
  default     = 120
}

variable "client_refresh_token_validity" {
  description = "Refresh token validity."
  type        = number
  default     = 7
}

variable "client_token_validity_units" {
  description = "Units paired with the token validity values."
  type        = map(string)
  default = {
    access_token  = "minutes"
    id_token      = "minutes"
    refresh_token = "days"
  }
}

variable "client_allowed_oauth" {
  description = "Whether the clients are allowed to use OAuth flows."
  type        = bool
  default     = false
}

variable "client_enable_token_revocation" {
  description = "Whether token revocation is enabled for the clients."
  type        = bool
  default     = true
}

variable "client_explicit_auth_flows" {
  description = "Explicit authentication flows allowed for the clients."
  type        = list(string)
  default     = ["ALLOW_REFRESH_TOKEN_AUTH", "ALLOW_USER_PASSWORD_AUTH", "ALLOW_USER_SRP_AUTH"]
}

variable "client_prevent_user_existence_errors" {
  description = "How the clients handle user existence errors."
  type        = string
  default     = "LEGACY"
}

variable "read_attributes" {
  description = "Attributes the clients are allowed to read."
  type        = list(string)
  default     = ["email"]
}

variable "write_attributes" {
  description = "Attributes the clients are allowed to write."
  type        = list(string)
  default     = ["email"]
}

variable "callback_urls" {
  description = "Callback URLs registered for the clients."
  type        = list(string)
  default     = []
}

variable "logout_urls" {
  description = "Logout URLs registered for the clients."
  type        = list(string)
  default     = []
}

variable "allowed_oauth_flows" {
  description = "OAuth flows enabled for the clients."
  type        = list(string)
  default     = []
}

variable "allowed_oauth_scopes" {
  description = "OAuth scopes enabled for the clients."
  type        = list(string)
  default     = []
}

variable "supported_identity_providers" {
  description = "Identity providers supported by the clients."
  type        = list(string)
  default     = ["COGNITO"]
}

# --- User group ---------------------------------------------------------------

variable "group_name" {
  description = "Name of the Cognito user group. Empty string disables the group."
  type        = string
  default     = ""
}

variable "group_precedence" {
  description = "Precedence of the Cognito user group."
  type        = number
  default     = 0
}

variable "group_role_arn" {
  description = "Optional IAM role ARN associated with the user group."
  type        = string
  default     = null
}

# --- Domain & DNS -------------------------------------------------------------

variable "domain_name" {
  description = "Cognito user pool domain. Empty string disables the domain."
  type        = string
  default     = ""
}

variable "domain_certificate_arn" {
  description = "Optional ACM certificate ARN for a custom domain."
  type        = string
  default     = null
}

variable "create_route53_record" {
  description = "Whether to create a Route 53 alias record for the Cognito domain."
  type        = bool
  default     = false
}

variable "route53_zone_id" {
  description = "Route 53 hosted zone ID used for the alias record."
  type        = string
  default     = ""
}

################################################################################
# Locals
################################################################################

locals {
  # CloudFront hosted zone ID used by Cognito custom domains (fixed by AWS).
  cloudfront_hosted_zone_id = "Z2FDTNDATAQYW2"

  sms_configuration_enabled = (
    try(length(var.sms_configuration), 0) > 0 &&
    try(var.sms_configuration["external_id"], "") != "" &&
    try(var.sms_configuration["sns_caller_arn"], "") != ""
  )

  create_user_group   = var.group_name != ""
  create_user_domain  = var.domain_name != ""
  create_alias_record = var.create_route53_record && var.route53_zone_id != "" && var.domain_name != ""
}

################################################################################
# Cognito User Pool
################################################################################

resource "aws_cognito_user_pool" "this" {
  name                     = var.pool_name
  alias_attributes         = var.alias_attributes
  auto_verified_attributes = var.auto_verified_attributes
  mfa_configuration        = var.mfa_configuration

  sms_authentication_message = var.sms_authentication_message
  sms_verification_message   = var.sms_verification_message

  # verification_message_template is the single source of truth for the
  # email verification copy (the deprecated top-level
  # email_verification_message / email_verification_subject arguments are
  # mutually exclusive with this block and must not be set).
  verification_message_template {
    default_email_option  = try(var.verification_message_template_by_link["default_email_option"], "CONFIRM_WITH_LINK")
    email_subject         = var.email_verification_subject
    email_message         = var.email_verification_message
    email_subject_by_link = lookup(var.verification_message_template_by_link, "email_subject_by_link", null)
    email_message_by_link = lookup(var.verification_message_template_by_link, "email_message_by_link", null)
  }

  dynamic "sms_configuration" {
    for_each = local.sms_configuration_enabled ? [1] : []
    content {
      external_id    = var.sms_configuration["external_id"]
      sns_caller_arn = var.sms_configuration["sns_caller_arn"]
      sns_region     = lookup(var.sms_configuration, "sns_region", null)
    }
  }

  dynamic "software_token_mfa_configuration" {
    for_each = var.enable_software_token_mfa ? [1] : []
    content {
      enabled = true
    }
  }

  dynamic "username_configuration" {
    for_each = var.username_case_sensitivity != null ? [1] : []
    content {
      case_sensitive = var.username_case_sensitivity
    }
  }

  dynamic "device_configuration" {
    for_each = var.device_configuration != null ? [1] : []
    content {
      challenge_required_on_new_device      = lookup(var.device_configuration, "challenge_required_on_new_device", null)
      device_only_remembered_on_user_prompt = lookup(var.device_configuration, "device_only_remembered_on_user_prompt", null)
    }
  }

  dynamic "lambda_config" {
    for_each = length(var.lambda_config) > 0 ? [1] : []
    content {
      create_auth_challenge          = lookup(var.lambda_config, "create_auth_challenge", null)
      custom_message                 = lookup(var.lambda_config, "custom_message", null)
      define_auth_challenge          = lookup(var.lambda_config, "define_auth_challenge", null)
      post_authentication            = lookup(var.lambda_config, "post_authentication", null)
      post_confirmation              = lookup(var.lambda_config, "post_confirmation", null)
      pre_authentication             = lookup(var.lambda_config, "pre_authentication", null)
      pre_sign_up                    = lookup(var.lambda_config, "pre_sign_up", null)
      pre_token_generation           = lookup(var.lambda_config, "pre_token_generation", null)
      user_migration                 = lookup(var.lambda_config, "user_migration", null)
      verify_auth_challenge_response = lookup(var.lambda_config, "verify_auth_challenge_response", null)
      kms_key_id                     = lookup(var.lambda_config, "kms_key_id", null)

      dynamic "custom_email_sender" {
        for_each = try(var.lambda_config["custom_email_sender"], null) != null ? [var.lambda_config["custom_email_sender"]] : []
        content {
          lambda_arn     = custom_email_sender.value["lambda_arn"]
          lambda_version = custom_email_sender.value["lambda_version"]
        }
      }

      dynamic "custom_sms_sender" {
        for_each = try(var.lambda_config["custom_sms_sender"], null) != null ? [var.lambda_config["custom_sms_sender"]] : []
        content {
          lambda_arn     = custom_sms_sender.value["lambda_arn"]
          lambda_version = custom_sms_sender.value["lambda_version"]
        }
      }
    }
  }

  dynamic "schema" {
    for_each = var.schema
    content {
      name                     = schema.value["name"]
      attribute_data_type      = schema.value["attribute_data_type"]
      developer_only_attribute = lookup(schema.value, "developer_only_attribute", null)
      mutable                  = lookup(schema.value, "mutable", null)
      required                 = lookup(schema.value, "required", null)

      string_attribute_constraints {
        min_length = try(schema.value["string_attribute_constraints"]["min_length"], null)
        max_length = try(schema.value["string_attribute_constraints"]["max_length"], null)
      }

      dynamic "number_attribute_constraints" {
        for_each = lookup(schema.value, "number_attribute_constraints", null) != null ? [schema.value["number_attribute_constraints"]] : []
        content {
          min_value = lookup(number_attribute_constraints.value, "min_value", null)
          max_value = lookup(number_attribute_constraints.value, "max_value", null)
        }
      }
    }
  }

  dynamic "account_recovery_setting" {
    for_each = length(var.account_recovery_setting) > 0 ? [var.account_recovery_setting] : []
    content {
      dynamic "recovery_mechanism" {
        for_each = [for k, v in account_recovery_setting.value : { name = k, priority = v }]
        content {
          name     = recovery_mechanism.value.name
          priority = recovery_mechanism.value.priority
        }
      }
    }
  }

  admin_create_user_config {
    allow_admin_create_user_only = var.admin_create_user_only

    dynamic "invite_message_template" {
      for_each = length(var.invite_message_template) > 0 ? [var.invite_message_template] : []
      content {
        email_subject = lookup(invite_message_template.value, "email_subject", null)
        email_message = lookup(invite_message_template.value, "email_message", null)
        sms_message   = lookup(invite_message_template.value, "sms_message", null)
      }
    }
  }

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

################################################################################
# Cognito User Pool Clients
################################################################################

resource "aws_cognito_user_pool_client" "this" {
  for_each = toset(var.client_names)

  name         = each.value
  user_pool_id = aws_cognito_user_pool.this.id

  generate_secret        = var.client_generate_secret
  access_token_validity  = var.client_access_token_validity
  id_token_validity      = var.client_id_token_validity
  refresh_token_validity = var.client_refresh_token_validity

  token_validity_units {
    access_token  = try(var.client_token_validity_units["access_token"], "minutes")
    id_token      = try(var.client_token_validity_units["id_token"], "minutes")
    refresh_token = try(var.client_token_validity_units["refresh_token"], "days")
  }

  allowed_oauth_flows_user_pool_client = var.client_allowed_oauth
  enable_token_revocation              = var.client_enable_token_revocation
  explicit_auth_flows                  = var.client_explicit_auth_flows
  prevent_user_existence_errors        = var.client_prevent_user_existence_errors

  read_attributes  = var.read_attributes
  write_attributes = var.write_attributes

  callback_urls                = var.callback_urls
  logout_urls                  = var.logout_urls
  allowed_oauth_flows          = var.allowed_oauth_flows
  allowed_oauth_scopes         = var.allowed_oauth_scopes
  supported_identity_providers = var.supported_identity_providers
}

################################################################################
# Cognito User Group
################################################################################

resource "aws_cognito_user_group" "this" {
  count = local.create_user_group ? 1 : 0

  name         = var.group_name
  user_pool_id = aws_cognito_user_pool.this.id
  precedence   = var.group_precedence
  role_arn     = var.group_role_arn
}

################################################################################
# Cognito User Pool Domain
################################################################################

resource "aws_cognito_user_pool_domain" "this" {
  count = local.create_user_domain ? 1 : 0

  domain          = var.domain_name
  user_pool_id    = aws_cognito_user_pool.this.id
  certificate_arn = var.domain_certificate_arn
}

################################################################################
# Route 53 alias record pointing at the Cognito CloudFront distribution
################################################################################

resource "aws_route53_record" "cognito_alias" {
  count = local.create_alias_record ? 1 : 0

  zone_id = var.route53_zone_id
  name    = var.domain_name
  type    = "A"

  alias {
    name                   = aws_cognito_user_pool_domain.this[0].cloudfront_distribution_arn
    zone_id                = local.cloudfront_hosted_zone_id
    evaluate_target_health = false
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

################################################################################
# Static provider metadata (no pre-existing infrastructure is looked up)
################################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

################################################################################
# Input variables
################################################################################

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "vpc_name" {
  description = "Name tag applied to the VPC."
  type        = string
  default     = "DevOps-Project-VPC"
}

variable "igw_name" {
  description = "Name tag applied to the Internet Gateway."
  type        = string
  default     = "devops-project-igw"
}

variable "route_table_name" {
  description = "Name tag applied to the public route table."
  type        = string
  default     = "DevOps-project-RT"
}

variable "public_subnet_identifier_name" {
  description = "Logical identifier of the public subnet associated with the public route table."
  type        = string
  default     = "subnet_a"
}

variable "nat_gateway_name" {
  description = "Name tag applied to the NAT gateway and its Elastic IP."
  type        = string
  default     = "DevOps-NAT-GW"
}

variable "public_ipv4_pool_name" {
  description = "Name of the public IPv4 address pool used to allocate the NAT gateway Elastic IP."
  type        = string
  default     = "amazon"
}

variable "subnet_a_cidr" {
  description = "CIDR block for Subnet A."
  type        = string
  default     = "10.0.1.0/24"
}

variable "subnet_a_az" {
  description = "Availability zone for Subnet A. Defaults to the first available AZ in the region."
  type        = string
  default     = null
}

variable "subnet_a_map_public_ip" {
  description = "Whether instances launched into Subnet A are automatically assigned a public IP address."
  type        = bool
  default     = false
}

variable "subnet_a_name" {
  description = "Name tag applied to Subnet A."
  type        = string
  default     = "Subnet-A-Public"
}

variable "subnet_b_cidr" {
  description = "CIDR block for Subnet B."
  type        = string
  default     = "10.0.2.0/24"
}

variable "subnet_b_az" {
  description = "Availability zone for Subnet B. Defaults to the second available AZ in the region."
  type        = string
  default     = null
}

variable "subnet_b_map_public_ip" {
  description = "Whether instances launched into Subnet B are automatically assigned a public IP address."
  type        = bool
  default     = false
}

variable "subnet_b_name" {
  description = "Name tag applied to Subnet B."
  type        = string
  default     = "Subnet-B-Private"
}

variable "subnet_c_cidr" {
  description = "CIDR block for Subnet C."
  type        = string
  default     = "10.0.3.0/24"
}

variable "subnet_c_az" {
  description = "Availability zone for Subnet C. Defaults to the third distinct available AZ in the region."
  type        = string
  default     = null
}

variable "subnet_c_map_public_ip" {
  description = "Whether instances launched into Subnet C are automatically assigned a public IP address."
  type        = bool
  default     = false
}

variable "subnet_c_name" {
  description = "Name tag applied to Subnet C."
  type        = string
  default     = "Subnet-C-Private"
}

################################################################################
# Local values
################################################################################

locals {
  default_security_group_name = "DefaultSecurityGroup"

  # Resolve each subnet AZ from the caller-provided override, falling back to a
  # distinct availability zone discovered from the provider metadata.
  subnet_a_az = var.subnet_a_az != null ? var.subnet_a_az : data.aws_availability_zones.available.names[0]
  subnet_b_az = var.subnet_b_az != null ? var.subnet_b_az : data.aws_availability_zones.available.names[1]
  subnet_c_az = var.subnet_c_az != null ? var.subnet_c_az : data.aws_availability_zones.available.names[2]
}

################################################################################
# Networking
################################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = var.igw_name
  }
}

resource "aws_subnet" "subnet_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_a_cidr
  availability_zone       = local.subnet_a_az
  map_public_ip_on_launch = var.subnet_a_map_public_ip

  tags = {
    Name = var.subnet_a_name
  }
}

resource "aws_subnet" "subnet_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_b_cidr
  availability_zone       = local.subnet_b_az
  map_public_ip_on_launch = var.subnet_b_map_public_ip

  tags = {
    Name = var.subnet_b_name
  }
}

resource "aws_subnet" "subnet_c" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_c_cidr
  availability_zone       = local.subnet_c_az
  map_public_ip_on_launch = var.subnet_c_map_public_ip

  tags = {
    Name = var.subnet_c_name
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = var.route_table_name
  }
}

resource "aws_route" "internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.igw.id
}

# Only Subnet A (the logical public subnet identified by
# var.public_subnet_identifier_name) is associated with the public route table.
resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.subnet_a.id
  route_table_id = aws_route_table.public.id
}

################################################################################
# NAT gateway
################################################################################

resource "aws_eip" "nat" {
  domain           = "vpc"
  public_ipv4_pool = var.public_ipv4_pool_name

  tags = {
    Name = var.nat_gateway_name
  }

  depends_on = [aws_internet_gateway.igw]
}

resource "aws_nat_gateway" "nat" {
  allocation_id     = aws_eip.nat.id
  subnet_id         = aws_subnet.subnet_b.id
  connectivity_type = "public"

  tags = {
    Name = var.nat_gateway_name
  }

  depends_on = [aws_internet_gateway.igw]
}

################################################################################
# Default security group (no ingress, VPC-internal egress only)
################################################################################

resource "aws_security_group" "default" {
  name        = local.default_security_group_name
  description = "Default security group for VPC-internal egress only."
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow all outbound traffic within the VPC CIDR only."
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = local.default_security_group_name
  }
}

################################################################################
# Outputs
################################################################################

output "nat_gateway_public_ip" {
  description = "Public IP address of the NAT gateway."
  value       = aws_nat_gateway.nat.public_ip
}

output "public_subnet_identifier_name" {
  description = "Logical identifier of the subnet associated with the public route table."
  value       = var.public_subnet_identifier_name
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "create" {
  description = "Controls whether a new Transit Gateway is created (true) or an existing one is looked up (false)."
  type        = bool
  default     = true
}

variable "name" {
  description = "Name of the main Transit Gateway resource, used as a fallback for naming and tags."
  type        = string
  default     = "tgw"
}

variable "tags" {
  description = "A map of global tags applied to all taggable resources."
  type        = map(string)
  default     = {}
}

variable "transit_gateway_id" {
  description = "ID of an existing Transit Gateway to look up when create = false."
  type        = string
  default     = null
}

variable "transit_gateway_name_tag" {
  description = "Value of the tag:Name filter to look up an existing Transit Gateway when create = false and no id is provided."
  type        = string
  default     = null
}

variable "amazon_side_asn" {
  description = "BGP ASN for the Transit Gateway (private ASN range)."
  type        = number
  default     = 65200
}

variable "auto_accept_shared_attachments" {
  description = "Whether to automatically accept cross-account VPC attachments that are shared via AWS RAM. Valid values: enable, disable."
  type        = string
  default     = "disable"
}

variable "dns_support" {
  description = "Whether DNS support is enabled for the Transit Gateway. Valid values: enable, disable."
  type        = string
  default     = "enable"
}

variable "vpn_ecmp_support" {
  description = "Whether Equal Cost Multipath (ECMP) support is enabled for VPN attachments. Valid values: enable, disable."
  type        = string
  default     = "enable"
}

variable "transit_gateway_cidr_blocks" {
  description = "One or more IPv4 or IPv6 CIDR blocks to assign to the Transit Gateway."
  type        = list(string)
  default     = []

  validation {
    condition = alltrue([
      for cidr in var.transit_gateway_cidr_blocks : can(cidrhost(cidr, 0))
    ])
    error_message = "Every entry in transit_gateway_cidr_blocks must be a valid IPv4 or IPv6 CIDR block."
  }
}

variable "route_tables" {
  description = "Map of Transit Gateway route tables to create or look up. Keyed by an arbitrary logical name."
  type = map(object({
    create     = optional(bool, true)
    name       = optional(string, null)
    name_tag   = optional(string, null)
    local_tags = optional(map(string), {})
  }))
  default = {}
}

variable "shared_principals" {
  description = "Map of principals (account IDs, principal ARNs, or OU ARNs) to associate with the AWS RAM resource share."
  type        = map(string)
  default     = {}
}

variable "ram_resource_share_name" {
  description = "Name of the AWS RAM resource share. Defaults to var.name when null."
  type        = string
  default     = null
}

###############################################################################
# Locals
###############################################################################

locals {
  # Partitioned route tables by whether they must be created or looked up.
  create_route_tables   = { for k, v in var.route_tables : k => v if v.create }
  existing_route_tables = { for k, v in var.route_tables : k => v if !v.create }

  # Resolved Transit Gateway identity regardless of create/lookup path.
  transit_gateway_id = one(concat(
    aws_ec2_transit_gateway.this[*].id,
    data.aws_ec2_transit_gateway.this[*].id,
  ))

  transit_gateway_arn = one(concat(
    aws_ec2_transit_gateway.this[*].arn,
    data.aws_ec2_transit_gateway.this[*].arn,
  ))

  ram_share_name = coalesce(var.ram_resource_share_name, var.name)
}

###############################################################################
# Transit Gateway (create)
###############################################################################

resource "aws_ec2_transit_gateway" "this" {
  count = var.create ? 1 : 0

  amazon_side_asn                = var.amazon_side_asn
  auto_accept_shared_attachments = var.auto_accept_shared_attachments
  dns_support                    = var.dns_support
  vpn_ecmp_support               = var.vpn_ecmp_support
  transit_gateway_cidr_blocks    = var.transit_gateway_cidr_blocks

  default_route_table_association = "disable"
  default_route_table_propagation = "disable"

  tags = merge(var.tags, { Name = var.name })
}

###############################################################################
# Transit Gateway (lookup by id or tag:Name)
###############################################################################

data "aws_ec2_transit_gateway" "this" {
  count = var.create ? 0 : 1

  id = var.transit_gateway_id

  dynamic "filter" {
    for_each = var.transit_gateway_id == null ? { "tag:Name" = var.transit_gateway_name_tag } : {}
    content {
      name   = filter.key
      values = [filter.value]
    }
  }
}

###############################################################################
# Transit Gateway Route Tables (create)
###############################################################################

resource "aws_ec2_transit_gateway_route_table" "this" {
  for_each = local.create_route_tables

  transit_gateway_id = local.transit_gateway_id

  tags = merge(
    var.tags,
    each.value.local_tags,
    { Name = coalesce(each.value.name_tag, each.key, var.name) },
  )
}

###############################################################################
# Transit Gateway Route Tables (lookup)
###############################################################################

data "aws_ec2_transit_gateway_route_table" "this" {
  for_each = local.existing_route_tables

  filter {
    name   = "transit-gateway-id"
    values = [local.transit_gateway_id]
  }

  filter {
    name   = "tag:Name"
    values = [coalesce(each.value.name_tag, each.key)]
  }
}

###############################################################################
# RAM Resource Share
###############################################################################

resource "aws_ram_resource_share" "this" {
  count = length(var.shared_principals) > 0 ? 1 : 0

  name                      = local.ram_share_name
  allow_external_principals = true

  tags = merge(var.tags, { Name = local.ram_share_name })
}

resource "aws_ram_resource_association" "this" {
  count = length(var.shared_principals) > 0 ? 1 : 0

  resource_arn       = local.transit_gateway_arn
  resource_share_arn = aws_ram_resource_share.this[0].arn
}

resource "aws_ram_principal_association" "this" {
  for_each = var.shared_principals

  principal          = each.value
  resource_share_arn = aws_ram_resource_share.this[0].arn
}

###############################################################################
# Outputs
###############################################################################

output "transit_gateway_id" {
  description = "ID of the created or looked-up Transit Gateway."
  value       = local.transit_gateway_id
}

output "transit_gateway_arn" {
  description = "ARN of the created or looked-up Transit Gateway."
  value       = local.transit_gateway_arn
}

output "transit_gateway_route_table_ids" {
  description = "Map of logical route table name to Transit Gateway route table ID, combining created and looked-up route tables."
  value = merge(
    { for k, rt in aws_ec2_transit_gateway_route_table.this : k => rt.id },
    { for k, rt in data.aws_ec2_transit_gateway_route_table.this : k => rt.id },
  )
}

output "ram_resource_share_arn" {
  description = "ARN of the AWS RAM resource share, or null when no principals are shared."
  value       = one(aws_ram_resource_share.this[*].arn)
}

terraform {
  required_version = ">= 1.4.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

###############################################################################
# Data sources (pure/static lookups only)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

###############################################################################
# Variables
###############################################################################

variable "bucket_name" {
  description = "Optional explicit S3 bucket name. When null a name is generated from 'corebucket-<random hex>'."
  type        = string
  default     = null

  validation {
    condition     = var.bucket_name == null || can(regex("^[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]$", var.bucket_name))
    error_message = "bucket_name must be a valid S3 bucket name (lowercase, 3-63 characters)."
  }
}

variable "prefix" {
  description = "When true, append an additional random suffix to the resolved bucket name."
  type        = bool
  default     = false
}

variable "environment" {
  description = "Environment name used for the standard tag map."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Additional tags applied to every taggable resource created by this module."
  type        = map(string)
  default     = {}
}

variable "request_payer" {
  description = "S3 Requester Pays configuration. One of BucketOwner or Requester."
  type        = string
  default     = "BucketOwner"

  validation {
    condition     = contains(["BucketOwner", "Requester"], var.request_payer)
    error_message = "request_payer must be either BucketOwner or Requester."
  }
}

variable "encryption" {
  description = "Whether server-side encryption should be enabled on the bucket (always aws:kms)."
  type        = bool
  default     = true
}

variable "kms_key" {
  description = "Optional customer-managed KMS key ARN. When empty a rotating customer-managed key is created."
  type        = string
  default     = ""

  validation {
    condition     = var.kms_key == "" || can(regex("^arn:[^:]+:kms:[^:]+:[0-9]{12}:key/.+$", var.kms_key))
    error_message = "kms_key must be empty or a valid KMS key ARN (arn:*:kms:*)."
  }
}

variable "kms_deletion_window_in_days" {
  description = "Waiting period (days) before a module-created KMS key is deleted."
  type        = number
  default     = 30

  validation {
    condition     = var.kms_deletion_window_in_days >= 7 && var.kms_deletion_window_in_days <= 30
    error_message = "kms_deletion_window_in_days must be between 7 and 30 days."
  }
}

variable "versioning" {
  description = "Enable bucket versioning."
  type        = bool
  default     = false
}

variable "mfa_delete" {
  description = "Enable MFA delete (only meaningful when versioning is enabled)."
  type        = bool
  default     = false
}

variable "force_destroy" {
  description = "Allow the bucket to be destroyed even when it contains objects."
  type        = bool
  default     = false
}

variable "policy" {
  description = "Optional JSON bucket policy, supplied as an HCL object that will be jsonencoded. Must be least privilege."
  type        = any
  default     = null
}

variable "transfer_acceleration_status" {
  description = "Optional transfer acceleration status. One of Enabled or Suspended. Null disables the feature."
  type        = string
  default     = null

  validation {
    condition     = var.transfer_acceleration_status == null || contains(["Enabled", "Suspended"], var.transfer_acceleration_status)
    error_message = "transfer_acceleration_status must be null, Enabled or Suspended."
  }
}

variable "logging" {
  description = "Optional access logging configuration. The target bucket is created and managed by this module."
  type = object({
    target_bucket = optional(string)
    prefix        = optional(string, "s3-access-logs/")
  })
  default = null
}

variable "website" {
  description = "Optional static website configuration. Configure exactly one of index/error documents or redirect_all_requests_to."
  type = object({
    index_document = optional(string)
    error_document = optional(string)
    routing_rules  = optional(string)
    redirect_all_requests_to = optional(object({
      host_name = string
      protocol  = optional(string)
    }))
  })
  default = null

  validation {
    condition = var.website == null || (
      (var.website.redirect_all_requests_to == null) != (var.website.index_document == null)
    )
    error_message = "The website configuration must set exactly one of index_document or redirect_all_requests_to."
  }
}

variable "cors_rules" {
  description = "List of CORS rules for the bucket."
  type = list(object({
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "lifecycle_rules" {
  description = "List of lifecycle rules for the bucket."
  type = list(object({
    id     = string
    status = optional(string, "Enabled")
    filter = optional(object({
      prefix = optional(string)
      tags   = optional(map(string))
    }))
    expiration = optional(object({
      days                         = optional(number)
      expired_object_delete_marker = optional(bool)
    }))
    noncurrent_version_expiration = optional(object({
      noncurrent_days = number
    }))
    transitions = optional(list(object({
      days          = optional(number)
      storage_class = string
    })), [])
    abort_incomplete_multipart_upload_days = optional(number)
  }))
  default = []
}

variable "noncurrent_version_expiration_days" {
  description = "Retention (days) for noncurrent object versions when versioning is enabled and no explicit rule is supplied."
  type        = number
  default     = 30

  validation {
    condition     = var.noncurrent_version_expiration_days > 0
    error_message = "noncurrent_version_expiration_days must be greater than zero."
  }
}

variable "object_lock_enabled" {
  description = "Enable S3 Object Lock on the bucket (forces versioning on)."
  type        = bool
  default     = false
}

variable "object_lock_mode" {
  description = "Default object lock retention mode. One of GOVERNANCE or COMPLIANCE."
  type        = string
  default     = "GOVERNANCE"

  validation {
    condition     = contains(["GOVERNANCE", "COMPLIANCE"], var.object_lock_mode)
    error_message = "object_lock_mode must be either GOVERNANCE or COMPLIANCE."
  }
}

variable "object_lock_days" {
  description = "Default object lock retention period in days (mutually exclusive with object_lock_years)."
  type        = number
  default     = null

  validation {
    condition     = var.object_lock_days == null || var.object_lock_days > 0
    error_message = "object_lock_days must be greater than zero when set."
  }
}

variable "object_lock_years" {
  description = "Default object lock retention period in years (mutually exclusive with object_lock_days)."
  type        = number
  default     = null

  validation {
    condition     = var.object_lock_years == null || var.object_lock_years > 0
    error_message = "object_lock_years must be greater than zero when set."
  }
}

variable "replication_role" {
  description = "Optional external IAM role ARN used for replication. When null a dedicated role is created."
  type        = string
  default     = null
}

variable "replication_rules" {
  description = "List of cross-region replication rules. The destination bucket is created and managed by this module."
  type = list(object({
    id                        = string
    priority                  = optional(number)
    status                    = optional(string, "Enabled")
    filter_prefix             = optional(string)
    destination_storage_class = optional(string, "STANDARD")
    delete_marker_replication = optional(bool, false)
  }))
  default = []
}

###############################################################################
# Locals
###############################################################################

locals {
  tags = merge(var.tags, {
    ManagedBy   = "terraform"
    Environment = var.environment
  })

  # Stable, always non-empty keeper value used to drive random_id change
  # detection. `coalesce` discards null and empty strings, so a literal
  # fallback is required here (var.bucket_name defaults to null).
  bucket_name_keeper = coalesce(var.bucket_name, "corebucket-auto")

  prefix_suffix        = try(random_id.prefix_suffix[0].hex, "")
  base_bucket_name     = coalesce(var.bucket_name, "corebucket-${random_id.bucket_suffix.hex}")
  resolved_bucket_name = var.prefix ? "${local.base_bucket_name}-${local.prefix_suffix}" : local.base_bucket_name

  create_kms_key = var.encryption && var.kms_key == ""

  encryption_key_arn = var.kms_key != "" ? var.kms_key : try(aws_kms_key.s3[0].arn, null)

  versioning_enabled = var.versioning || var.object_lock_enabled

  lifecycle_rules_has_noncurrent = anytrue([
    for r in var.lifecycle_rules : r.noncurrent_version_expiration != null
  ])

  default_noncurrent_rule = {
    id      = "corebucket-noncurrent-version-expiration"
    status  = "Enabled"
    filter  = null
    expiration = null
    noncurrent_version_expiration = {
      noncurrent_days = var.noncurrent_version_expiration_days
    }
    transitions                            = []
    abort_incomplete_multipart_upload_days = null
  }

  effective_lifecycle_rules = concat(
    var.lifecycle_rules,
    (local.versioning_enabled && !local.lifecycle_rules_has_noncurrent) ? [local.default_noncurrent_rule] : []
  )

  create_replication_role = length(var.replication_rules) > 0 && var.replication_role == null

  replication_role_arn = var.replication_role != null ? var.replication_role : try(aws_iam_role.replication[0].arn, null)
}

###############################################################################
# Random naming
###############################################################################

resource "random_id" "bucket_suffix" {
  byte_length = 4

  keepers = {
    bucket_name = local.bucket_name_keeper
  }
}

resource "random_id" "prefix_suffix" {
  count       = var.prefix ? 1 : 0
  byte_length = 4

  keepers = {
    bucket_name = local.bucket_name_keeper
  }
}

resource "random_id" "log_suffix" {
  count       = var.logging != null ? 1 : 0
  byte_length = 4

  keepers = {
    bucket_name = local.bucket_name_keeper
  }
}

resource "random_id" "replica_suffix" {
  count       = length(var.replication_rules) > 0 ? 1 : 0
  byte_length = 4

  keepers = {
    bucket_name = local.bucket_name_keeper
  }
}

###############################################################################
# Primary bucket
###############################################################################

resource "aws_s3_bucket" "this" {
  bucket              = local.resolved_bucket_name
  force_destroy       = var.force_destroy
  object_lock_enabled = var.object_lock_enabled
  tags                = merge(local.tags, { Name = local.resolved_bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status     = local.versioning_enabled ? "Enabled" : "Suspended"
    mfa_delete = (local.versioning_enabled && var.mfa_delete) ? "Enabled" : "Disabled"
  }
}

resource "aws_s3_bucket_request_payment_configuration" "this" {
  bucket = aws_s3_bucket.this.id
  payer  = var.request_payer
}

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count = var.transfer_acceleration_status != null ? 1 : 0

  bucket = aws_s3_bucket.this.id
  status = var.transfer_acceleration_status
}

###############################################################################
# KMS key (module managed) + encryption configuration
###############################################################################

data "aws_iam_policy_document" "kms" {
  count = local.create_kms_key ? 1 : 0

  statement {
    sid    = "EnableRootAccountAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowS3ServiceUsage"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["s3.${data.aws_region.current.name}.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_kms_key" "s3" {
  count = local.create_kms_key ? 1 : 0

  description             = "Customer managed KMS key for S3 bucket ${local.resolved_bucket_name}"
  deletion_window_in_days = var.kms_deletion_window_in_days
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms[0].json
  tags                    = local.tags
}

resource "aws_kms_alias" "s3" {
  count = local.create_kms_key ? 1 : 0

  name          = "alias/corebucket-${local.resolved_bucket_name}"
  target_key_id = aws_kms_key.s3[0].key_id
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count = var.encryption ? 1 : 0

  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = local.encryption_key_arn
    }

    bucket_key_enabled = true
  }
}

###############################################################################
# Bucket policy
###############################################################################

resource "aws_s3_bucket_policy" "this" {
  count = var.policy != null ? 1 : 0

  bucket = aws_s3_bucket.this.id
  policy = jsonencode(var.policy)

  depends_on = [aws_s3_bucket_public_access_block.this]
}

###############################################################################
# Static website hosting
###############################################################################

resource "aws_s3_bucket_website_configuration" "this" {
  count = var.website != null ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "index_document" {
    for_each = try(var.website.index_document, null) != null ? [var.website.index_document] : []

    content {
      suffix = index_document.value
    }
  }

  dynamic "error_document" {
    for_each = try(var.website.error_document, null) != null ? [var.website.error_document] : []

    content {
      key = error_document.value
    }
  }

  routing_rules = try(var.website.routing_rules, null)

  dynamic "redirect_all_requests_to" {
    for_each = try(var.website.redirect_all_requests_to, null) != null ? [var.website.redirect_all_requests_to] : []

    content {
      host_name = redirect_all_requests_to.value.host_name
      protocol  = redirect_all_requests_to.value.protocol
    }
  }
}

###############################################################################
# CORS
###############################################################################

resource "aws_s3_bucket_cors_configuration" "this" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules

    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

###############################################################################
# Lifecycle
###############################################################################

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = length(local.effective_lifecycle_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = local.effective_lifecycle_rules

    content {
      id     = rule.value.id
      status = rule.value.status

      filter {
        prefix = try(rule.value.filter.prefix, null)

        dynamic "tag" {
          for_each = try(rule.value.filter.tags, {})

          content {
            key   = tag.key
            value = tag.value
          }
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration != null ? [rule.value.expiration] : []

        content {
          days                         = expiration.value.days
          expired_object_delete_marker = expiration.value.expired_object_delete_marker
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration != null ? [rule.value.noncurrent_version_expiration] : []

        content {
          noncurrent_days = noncurrent_version_expiration.value.noncurrent_days
        }
      }

      dynamic "transition" {
        for_each = rule.value.transitions

        content {
          days          = transition.value.days
          storage_class = transition.value.storage_class
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload_days != null ? [rule.value.abort_incomplete_multipart_upload_days] : []

        content {
          days_after_initiation = abort_incomplete_multipart_upload.value
        }
      }
    }
  }
}

###############################################################################
# Access logging target bucket
###############################################################################

resource "aws_s3_bucket" "log_target" {
  count = var.logging != null ? 1 : 0

  bucket        = "${local.resolved_bucket_name}-logs-${random_id.log_suffix[0].hex}"
  force_destroy = var.force_destroy
  tags          = merge(local.tags, { Name = "${local.resolved_bucket_name}-logs" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "log_target" {
  count = var.logging != null ? 1 : 0

  bucket = aws_s3_bucket.log_target[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "log_target" {
  count = var.logging != null ? 1 : 0

  bucket = aws_s3_bucket.log_target[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.encryption ? "aws:kms" : "AES256"
      kms_master_key_id = var.encryption ? local.encryption_key_arn : null
    }

    bucket_key_enabled = var.encryption
  }
}

resource "aws_s3_bucket_logging" "this" {
  count = var.logging != null ? 1 : 0

  bucket        = aws_s3_bucket.this.id
  target_bucket = aws_s3_bucket.log_target[0].id
  target_prefix = var.logging.prefix
}

###############################################################################
# Object Lock
###############################################################################

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = var.object_lock_enabled ? 1 : 0

  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode  = var.object_lock_mode
      days  = var.object_lock_days
      years = var.object_lock_years
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]

  lifecycle {
    precondition {
      condition     = (var.object_lock_days == null) != (var.object_lock_years == null)
      error_message = "Object lock requires exactly one of object_lock_days or object_lock_years."
    }
  }
}

###############################################################################
# Cross-region replication destination bucket
###############################################################################

resource "aws_s3_bucket" "replica" {
  count = length(var.replication_rules) > 0 ? 1 : 0

  bucket        = "${local.resolved_bucket_name}-replica-${random_id.replica_suffix[0].hex}"
  force_destroy = var.force_destroy
  tags          = merge(local.tags, { Name = "${local.resolved_bucket_name}-replica" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  count = length(var.replication_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.replica[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "replica" {
  count = length(var.replication_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.replica[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  count = length(var.replication_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.replica[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.encryption ? "aws:kms" : "AES256"
      kms_master_key_id = var.encryption ? local.encryption_key_arn : null
    }

    bucket_key_enabled = var.encryption
  }
}

###############################################################################
# Replication IAM role / policy
###############################################################################

data "aws_iam_policy_document" "replication_assume" {
  count = local.create_replication_role ? 1 : 0

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "replication" {
  count = local.create_replication_role ? 1 : 0

  statement {
    sid    = "SourceBucketLevelPermissions"
    effect = "Allow"

    actions = [
      "s3:ListBucket",
      "s3:GetReplicationConfiguration",
      "s3:GetBucketVersioning",
      "s3:PutReplicationConfiguration",
    ]

    resources = [aws_s3_bucket.this.arn]
  }

  statement {
    sid    = "SourceObjectLevelPermissions"
    effect = "Allow"

    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
    ]

    resources = ["${aws_s3_bucket.this.arn}/*"]
  }

  statement {
    sid    = "DestinationObjectLevelPermissions"
    effect = "Allow"

    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
    ]

    resources = ["${try(aws_s3_bucket.replica[0].arn, "")}/*"]
  }
}

resource "aws_iam_role" "replication" {
  count = local.create_replication_role ? 1 : 0

  name               = "CoreS3ReplicationRole_${local.resolved_bucket_name}"
  assume_role_policy = data.aws_iam_policy_document.replication_assume[0].json
  tags               = local.tags
}

resource "aws_iam_policy" "replication" {
  count = local.create_replication_role ? 1 : 0

  name   = "CoreS3ReplicationPolicy_${local.resolved_bucket_name}"
  policy = data.aws_iam_policy_document.replication[0].json
  tags   = local.tags
}

resource "aws_iam_role_policy_attachment" "replication" {
  count = local.create_replication_role ? 1 : 0

  role       = aws_iam_role.replication[0].name
  policy_arn = aws_iam_policy.replication[0].arn
}

###############################################################################
# Replication configuration
###############################################################################

resource "aws_s3_bucket_replication_configuration" "this" {
  count = length(var.replication_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id
  role   = local.replication_role_arn

  dynamic "rule" {
    for_each = var.replication_rules

    content {
      id       = rule.value.id
      status   = rule.value.status
      priority = coalesce(rule.value.priority, rule.key + 1)

      filter {
        prefix = rule.value.filter_prefix
      }

      destination {
        bucket        = aws_s3_bucket.replica[0].arn
        storage_class = rule.value.destination_storage_class
      }

      dynamic "delete_marker_replication" {
        for_each = rule.value.delete_marker_replication ? [1] : []

        content {
          status = "Enabled"
        }
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.this,
    aws_s3_bucket_versioning.replica,
    aws_iam_role_policy_attachment.replication,
  ]
}

###############################################################################
# Outputs
###############################################################################

output "bucket_id" {
  description = "The name of the primary S3 bucket."
  value       = aws_s3_bucket.this.id
}

output "bucket_arn" {
  description = "The ARN of the primary S3 bucket."
  value       = aws_s3_bucket.this.arn
}

output "bucket_regional_domain_name" {
  description = "The region specific domain name of the primary S3 bucket."
  value       = aws_s3_bucket.this.bucket_regional_domain_name
}

output "website_endpoint" {
  description = "The static website endpoint of the primary S3 bucket (when configured)."
  value       = try(aws_s3_bucket_website_configuration.this[0].website_endpoint, null)
}

output "kms_key_arn" {
  description = "The ARN of the KMS key used for server-side encryption."
  value       = local.encryption_key_arn
}

output "replication_role_arn" {
  description = "The ARN of the IAM role used for replication."
  value       = local.replication_role_arn
}

output "replication_role_name" {
  description = "The name of the module-managed IAM replication role (when created)."
  value       = try(aws_iam_role.replication[0].name, null)
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "awsRegion" {
  description = "AWS region in which the network stack is deployed."
  type        = string
  default     = "us-east-1"
}

variable "projectPrefix" {
  description = "Prefix used for naming and tagging resources."
  type        = string
  default     = "f5-dcec"
}

variable "resourceOwner" {
  description = "Owner tag applied to all resources."
  type        = string
  default     = "f5-user"
}

variable "buildSuffix" {
  description = "Suffix used for tagging build generations."
  type        = string
  default     = "YY"
}

variable "map_public_ip_on_launch" {
  description = "Automatically assign public IP addresses to instances launched in the public subnets."
  type        = bool
  default     = false
}

variable "vpcMainCidr" {
  description = "CIDR block for the main VPC."
  type        = string
  default     = "10.1.0.0/16"
}

variable "vpcMainSubPubACidr" {
  description = "CIDR block for the first public subnet."
  type        = string
  default     = "10.1.10.0/24"
}

variable "vpcMainSubPubBCidr" {
  description = "CIDR block for the second public subnet."
  type        = string
  default     = "10.1.110.0/24"
}

variable "vpcMainSubMgmtACidr" {
  description = "CIDR block for the first management subnet."
  type        = string
  default     = "10.1.1.0/24"
}

variable "vpcMainSubMgmtBCidr" {
  description = "CIDR block for the second management subnet."
  type        = string
  default     = "10.1.101.0/24"
}

variable "vpcMainSubPrivACidr" {
  description = "CIDR block for the first private subnet."
  type        = string
  default     = "10.1.20.0/24"
}

variable "vpcMainSubPrivBCidr" {
  description = "CIDR block for the second private subnet."
  type        = string
  default     = "10.1.120.0/24"
}

variable "awsAz1" {
  description = "Optional first availability zone; defaults to the first available AZ in the region."
  type        = string
  default     = null
}

variable "awsAz2" {
  description = "Optional second availability zone; defaults to awsAz1 when set, otherwise the second available AZ in the region."
  type        = string
  default     = null
}

###############################################################################
# Data sources
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Locals
###############################################################################

locals {
  az1 = coalesce(var.awsAz1, data.aws_availability_zones.available.names[0])
  az2 = coalesce(
    var.awsAz2,
    try(var.awsAz1, null) != null ? var.awsAz1 : data.aws_availability_zones.available.names[1]
  )

  common_tags = {
    Project     = var.projectPrefix
    Owner       = var.resourceOwner
    BuildSuffix = var.buildSuffix
  }
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpcMainCidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-vpc"
  })
}

###############################################################################
# Public subnets
###############################################################################

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPubACidr
  availability_zone       = local.az1
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-subnet-public-a"
    Tier = "public"
  })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPubBCidr
  availability_zone       = local.az2
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-subnet-public-b"
    Tier = "public"
  })
}

###############################################################################
# Management subnets
###############################################################################

resource "aws_subnet" "mgmt_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubMgmtACidr
  availability_zone = local.az1

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-subnet-mgmt-a"
    Tier = "management"
  })
}

resource "aws_subnet" "mgmt_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubMgmtBCidr
  availability_zone = local.az2

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-subnet-mgmt-b"
    Tier = "management"
  })
}

###############################################################################
# Private subnets
###############################################################################

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPrivACidr
  availability_zone       = local.az1
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-subnet-private-a"
    Tier = "private"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPrivBCidr
  availability_zone       = local.az2
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-subnet-private-b"
    Tier = "private"
  })
}

###############################################################################
# Internet gateway
###############################################################################

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-igw"
  })
}

###############################################################################
# Route table and default route
###############################################################################

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-rtb-public"
  })
}

resource "aws_main_route_table_association" "main" {
  vpc_id         = aws_vpc.main.id
  route_table_id = aws_route_table.public.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  type    = string
  default = "us-east-1"
}

variable "name" {
  type    = string
  default = "benchmark"
}

variable "rule_count" {
  type    = number
  default = 1
}

locals {
  common_tags = {
    Name        = var.name
    Environment = var.name
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = local.common_tags
}

resource "aws_subnet" "main" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, {
    Name = var.name
  })
}

resource "aws_security_group" "alb" {
  name        = var.name
  description = "Internal ALB security group allowing all traffic within the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "All traffic within the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "All traffic within the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = local.common_tags
}

resource "aws_lb" "this" {
  name                       = var.name
  internal                   = true
  load_balancer_type         = "application"
  subnets                    = aws_subnet.main[*].id
  security_groups            = [aws_security_group.alb.id]
  drop_invalid_header_fields = true

  tags = local.common_tags
}

resource "aws_lb_target_group" "this" {
  name     = var.name
  port     = 8080
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    enabled             = true
    port                = "8081"
    path                = "/health"
    interval            = 60
    timeout             = 3
    matcher             = "200-299"
    healthy_threshold   = 3
    unhealthy_threshold = 3
  }

  tags = local.common_tags
}

resource "tls_private_key" "this" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "this" {
  private_key_pem = tls_private_key.this.private_key_pem

  subject {
    common_name  = var.name
    organization = var.name
  }

  validity_period_hours = 8760

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "this" {
  certificate_body  = tls_self_signed_cert.this.cert_pem
  private_key       = tls_private_key.this.private_key_pem
  certificate_chain = tls_self_signed_cert.this.cert_pem

  tags = local.common_tags
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.this.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.this.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.this.arn
  }

  tags = local.common_tags
}

resource "aws_lb_listener_rule" "static" {
  count        = var.rule_count
  listener_arn = aws_lb_listener.https.arn
  priority     = 100 + count.index

  action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.this.arn
  }

  condition {
    path_pattern {
      values = ["/static-${count.index}/*"]
    }
  }

  tags = local.common_tags
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------

variable "region" {
  description = "AWS region in which to deploy the isolated VPC networking stack."
  type        = string
  default     = "us-east-1"
}

variable "name_prefix" {
  description = "Prefix applied to the Name tag of every resource in the stack."
  type        = string
  default     = "tfm-aws"
}

variable "vpc_cidr" {
  description = "Main CIDR block assigned to the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "instance_tenancy" {
  description = "Tenancy option for instances launched into the VPC."
  type        = string
  default     = "default"
}

variable "private_subnets" {
  description = "List of CIDR blocks used for the private subnets."
  type        = list(string)
  default     = ["10.0.2.0/24", "10.0.3.0/24"]
}

variable "public_inbound_acl_rules" {
  description = "Inbound (ingress) rules for the shared network ACL. Default permits only ephemeral return traffic."
  type        = list(map(string))
  default = [
    {
      rule_number = "100"
      protocol    = "tcp"
      from_port   = "1024"
      to_port     = "65535"
      cidr_block  = "0.0.0.0/0"
    }
  ]
}

variable "public_outbound_acl_rules" {
  description = "Outbound (egress) rules for the shared network ACL. Default permits only HTTPS."
  type        = list(map(string))
  default = [
    {
      rule_number = "100"
      protocol    = "tcp"
      from_port   = "443"
      to_port     = "443"
      cidr_block  = "0.0.0.0/0"
    }
  ]
}

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------

locals {
  vpc_name            = "${var.name_prefix}-vpc"
  private_subnet_name = "${var.name_prefix}-private-subnet"
  private_rt_name     = "${var.name_prefix}-private-rt"
  private_nacl_name   = "${var.name_prefix}-private-nacl"
  s3_endpoint_name    = "${var.name_prefix}-s3-endpoint"
}

# ---------------------------------------------------------------------------
# Data sources (static provider metadata only)
# ---------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_partition" "current" {}

# ---------------------------------------------------------------------------
# VPC (fully isolated: no IGW, no NAT, no EIP, no public subnets)
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  instance_tenancy     = var.instance_tenancy

  tags = {
    Name = local.vpc_name
  }
}

# ---------------------------------------------------------------------------
# Private subnets (one per CIDR, first two AZs from the region)
# ---------------------------------------------------------------------------

resource "aws_subnet" "private" {
  count = length(var.private_subnets)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnets[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.private_subnet_name}-${count.index + 1}"
    Tier = "private"
  }
}

# ---------------------------------------------------------------------------
# One dedicated private route table per private subnet
# ---------------------------------------------------------------------------

resource "aws_route_table" "private" {
  count = length(var.private_subnets)

  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.private_rt_name}-${data.aws_availability_zones.available.names[count.index]}"
    Tier = "private"
  }
}

resource "aws_route_table_association" "private" {
  count = length(var.private_subnets)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# ---------------------------------------------------------------------------
# S3 VPC Gateway Endpoint associated with BOTH private route tables
# ---------------------------------------------------------------------------

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  vpc_endpoint_type = "Gateway"
  service_name      = "com.amazonaws.${var.region}.s3"
  route_table_ids   = aws_route_table.private[*].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowListBucket"
        Effect    = "Allow"
        Principal = "*"
        Action = [
          "s3:ListBucket",
          "s3:GetBucketLocation"
        ]
        Resource = "arn:${data.aws_partition.current.partition}:s3:::*"
      },
      {
        Sid       = "AllowObjectAccess"
        Effect    = "Allow"
        Principal = "*"
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Resource = "arn:${data.aws_partition.current.partition}:s3:::*/*"
      }
    ]
  })

  tags = {
    Name = local.s3_endpoint_name
  }
}

# ---------------------------------------------------------------------------
# Shared network ACL for both private subnets
# ---------------------------------------------------------------------------

resource "aws_network_acl" "private" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = local.private_nacl_name
  }
}

resource "aws_network_acl_rule" "private_inbound" {
  for_each = { for idx, rule in var.public_inbound_acl_rules : tostring(idx) => rule }

  network_acl_id = aws_network_acl.private.id
  rule_number    = each.value.rule_number
  egress         = false
  protocol       = each.value.protocol
  rule_action    = "allow"
  cidr_block     = each.value.cidr_block
  from_port      = each.value.from_port
  to_port        = each.value.to_port
}

resource "aws_network_acl_rule" "private_outbound" {
  for_each = { for idx, rule in var.public_outbound_acl_rules : tostring(idx) => rule }

  network_acl_id = aws_network_acl.private.id
  rule_number    = each.value.rule_number
  egress         = true
  protocol       = each.value.protocol
  rule_action    = "allow"
  cidr_block     = each.value.cidr_block
  from_port      = each.value.from_port
  to_port        = each.value.to_port
}

terraform {
  required_version = ">= 1.9.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

variable "create" {
  description = "Controls whether the primary SQS queue is created."
  type        = bool
  default     = true
}

variable "name" {
  description = "Name of the SQS queue. Cannot be used with name_prefix."
  type        = string
  default     = ""
}

variable "name_prefix" {
  description = "Prefix for the SQS queue name. Cannot be used with name. Must not end in .fifo."
  type        = string
  default     = ""

  validation {
    condition     = !(var.name != "" && var.name_prefix != "")
    error_message = "Only one of name or name_prefix may be specified, not both."
  }

  validation {
    condition     = var.name_prefix == "" || !endswith(var.name_prefix, ".fifo")
    error_message = "The name_prefix must not end with '.fifo'; SQS appends this suffix automatically for FIFO queues."
  }
}

variable "default_name_prefix" {
  description = "Fallback queue name prefix used to synthesize a queue name when neither name nor name_prefix is supplied."
  type        = string
  default     = "sqs-queue-"
}

variable "fifo_queue" {
  description = "Whether the queue is a FIFO queue."
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enables content-based deduplication for FIFO queues."
  type        = bool
  default     = false
}

variable "deduplication_scope" {
  description = "Specifies whether message deduplication occurs at the message group or queue level."
  type        = string
  default     = "queue"

  validation {
    condition     = contains(["queue", "messageGroup"], var.deduplication_scope)
    error_message = "deduplication_scope must be one of: queue, messageGroup."
  }
}

variable "fifo_throughput_limit" {
  description = "Specifies whether the FIFO queue throughput quota applies to the entire queue or per message group."
  type        = string
  default     = "perQueue"

  validation {
    condition     = contains(["perQueue", "perMessageGroupId"], var.fifo_throughput_limit)
    error_message = "fifo_throughput_limit must be one of: perQueue, perMessageGroupId."
  }
}

variable "delay_seconds" {
  description = "The time in seconds that the delivery of all messages in the queue is delayed."
  type        = number
  default     = 0
}

variable "max_message_size" {
  description = "The limit of how many bytes a message can contain before Amazon SQS rejects it."
  type        = number
  default     = 262144
}

variable "message_retention_seconds" {
  description = "The number of seconds Amazon SQS retains a message."
  type        = number
  default     = 345600
}

variable "receive_wait_time_seconds" {
  description = "The time for which a ReceiveMessage call will wait for a message to arrive."
  type        = number
  default     = 0
}

variable "visibility_timeout_seconds" {
  description = "The visibility timeout for the queue."
  type        = number
  default     = 30
}

variable "sqs_managed_sse_enabled" {
  description = "Whether SQS-managed server-side encryption is enabled when no custom KMS key is configured."
  type        = bool
  default     = true
}

variable "kms_master_key_id" {
  description = "The ID of an AWS-managed customer master key (CMK) for SQS or a custom CMK."
  type        = string
  default     = ""
}

variable "kms_data_key_reuse_period_seconds" {
  description = "The length of time, in seconds, for which Amazon SQS can reuse a data key to encrypt or decrypt messages."
  type        = number
  default     = 300
}

variable "create_kms_key" {
  description = "Controls whether a customer-managed KMS key is created for the queue."
  type        = bool
  default     = false
}

variable "create_queue_policy" {
  description = "Controls whether an SQS queue policy is created."
  type        = bool
  default     = false
}

variable "queue_policy_source" {
  description = "JSON policy document to merge into the generated queue policy."
  type        = string
  default     = ""
}

variable "queue_policy_override" {
  description = "JSON policy document to override the generated queue policy."
  type        = string
  default     = ""
}

variable "queue_policy_statements" {
  description = "List of additional policy statements to add to the queue policy."
  type        = list(any)
  default     = []

  validation {
    condition = alltrue([
      for s in var.queue_policy_statements :
      !(
        try(contains(s.actions, "*"), false) &&
        try(contains(s.resources, "*"), false)
      )
    ])
    error_message = "Each policy statement must not use Action = \"*\" together with Resource = \"*\"."
  }
}

variable "create_dlq" {
  description = "Controls whether a dead-letter queue is created and associated with the primary queue."
  type        = bool
  default     = false
}

variable "dlq_name" {
  description = "Optional name for the dead-letter queue. Overrides the default name."
  type        = string
  default     = ""
}

variable "dlq_name_prefix" {
  description = "Optional prefix for the dead-letter queue name. Overrides the default prefix."
  type        = string
  default     = ""
}

variable "max_receive_count" {
  description = "The number of times a message is delivered to the source queue before being moved to the dead-letter queue."
  type        = number
  default     = 5
}

variable "create_dlq_redrive_allow_policy" {
  description = "Controls whether a redrive allow policy is created for the dead-letter queue."
  type        = bool
  default     = true
}

variable "redrive_allow_permission" {
  description = "The permission type for the redrive allow policy."
  type        = string
  default     = "byQueue"

  validation {
    condition     = contains(["byQueue", "allowAll", "denyAll"], var.redrive_allow_permission)
    error_message = "redrive_allow_permission must be one of: byQueue, allowAll, denyAll."
  }
}

variable "tags" {
  description = "A map of tags to apply to all resources."
  type        = map(string)
  default     = {}
}

locals {
  name_provided        = var.name != ""
  name_prefix_provided = var.name_prefix != ""

  effective_name_prefix = local.name_provided ? null : (
    local.name_prefix_provided ? var.name_prefix : var.default_name_prefix
  )

  main_name_base = trimsuffix(var.name, ".fifo")
  main_name = var.create && local.name_provided ? (
    var.fifo_queue ? "${local.main_name_base}.fifo" : local.main_name_base
  ) : null
  main_name_prefix = var.create ? local.effective_name_prefix : null

  main_display_name = coalesce(local.main_name, local.main_name_prefix, "sqs")

  tags = merge(var.tags, {
    Name = local.main_display_name
  })

  kms_key_arn             = var.create_kms_key ? try(aws_kms_key.sqs[0].arn, null) : null
  effective_kms_key_id    = var.kms_master_key_id != "" ? var.kms_master_key_id : local.kms_key_arn
  sqs_managed_sse_enabled = local.effective_kms_key_id == null ? var.sqs_managed_sse_enabled : false

  dlq_name_override        = var.dlq_name != ""
  dlq_name_prefix_override = var.dlq_name_prefix != ""

  dlq_use_name = local.dlq_name_override || (
    !local.dlq_name_prefix_override && local.name_provided
  )
  dlq_use_name_prefix = !local.dlq_use_name

  dlq_name_base = local.dlq_name_override ? trimsuffix(var.dlq_name, ".fifo") : (
    local.name_provided ? "${local.main_name_base}-dlq" : "dlq"
  )
  dlq_name_max_base_length = 80 - (var.fifo_queue ? 5 : 0)
  dlq_name_base_trimmed = substr(
    local.dlq_name_base,
    0,
    min(length(local.dlq_name_base), local.dlq_name_max_base_length)
  )
  dlq_name = var.create && var.create_dlq && local.dlq_use_name ? (
    var.fifo_queue ? "${local.dlq_name_base_trimmed}.fifo" : local.dlq_name_base_trimmed
  ) : null

  dlq_prefix_base = trimsuffix(
    coalesce(local.effective_name_prefix, var.default_name_prefix),
    "-"
  )
  dlq_name_prefix_value = local.dlq_name_prefix_override ? var.dlq_name_prefix : (
    "${local.dlq_prefix_base}-dlq"
  )
  dlq_name_prefix = var.create && var.create_dlq && local.dlq_use_name_prefix ? local.dlq_name_prefix_value : null

  dlq_display_name = coalesce(local.dlq_name, local.dlq_name_prefix, "dlq")
  dlq_tags = merge(var.tags, {
    Name = local.dlq_display_name
  })
}

resource "aws_kms_key" "sqs" {
  count = var.create && var.create_kms_key ? 1 : 0

  description             = "KMS key for SQS queue ${local.main_display_name}"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "sqs" {
  count = var.create && var.create_kms_key ? 1 : 0

  name          = "alias/${replace(local.main_display_name, ".", "-")}"
  target_key_id = aws_kms_key.sqs[0].key_id
}

resource "aws_kms_key_policy" "sqs" {
  count = var.create && var.create_kms_key ? 1 : 0

  key_id = aws_kms_key.sqs[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowSQSService"
        Effect    = "Allow"
        Principal = { Service = "sqs.amazonaws.com" }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = aws_kms_key.sqs[0].arn
      },
      {
        Sid       = "AllowAccountRoot"
        Effect    = "Allow"
        Principal = { AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root" }
        Action    = "kms:*"
        Resource  = aws_kms_key.sqs[0].arn
      }
    ]
  })
}

resource "aws_sqs_queue" "main" {
  count = var.create ? 1 : 0

  name        = local.main_name
  name_prefix = local.main_name_prefix

  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? var.content_based_deduplication : null
  deduplication_scope         = var.fifo_queue ? var.deduplication_scope : null
  fifo_throughput_limit       = var.fifo_queue ? var.fifo_throughput_limit : null

  delay_seconds              = var.delay_seconds
  max_message_size           = var.max_message_size
  message_retention_seconds  = var.message_retention_seconds
  receive_wait_time_seconds  = var.receive_wait_time_seconds
  visibility_timeout_seconds = var.visibility_timeout_seconds

  kms_master_key_id                 = local.effective_kms_key_id
  kms_data_key_reuse_period_seconds = local.effective_kms_key_id != null ? var.kms_data_key_reuse_period_seconds : null
  sqs_managed_sse_enabled           = local.sqs_managed_sse_enabled

  redrive_policy = var.create_dlq ? jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq[0].arn
    maxReceiveCount     = var.max_receive_count
  }) : null

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sqs_queue" "dlq" {
  count = var.create && var.create_dlq ? 1 : 0

  name        = local.dlq_name
  name_prefix = local.dlq_name_prefix

  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? var.content_based_deduplication : null
  deduplication_scope         = var.fifo_queue ? var.deduplication_scope : null
  fifo_throughput_limit       = var.fifo_queue ? var.fifo_throughput_limit : null

  delay_seconds              = var.delay_seconds
  max_message_size           = var.max_message_size
  message_retention_seconds  = var.message_retention_seconds
  receive_wait_time_seconds  = var.receive_wait_time_seconds
  visibility_timeout_seconds = var.visibility_timeout_seconds

  kms_master_key_id                 = local.effective_kms_key_id
  kms_data_key_reuse_period_seconds = local.effective_kms_key_id != null ? var.kms_data_key_reuse_period_seconds : null
  sqs_managed_sse_enabled           = local.sqs_managed_sse_enabled

  tags = local.dlq_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sqs_queue_redrive_allow_policy" "dlq" {
  count = var.create && var.create_dlq && var.create_dlq_redrive_allow_policy ? 1 : 0

  queue_url = aws_sqs_queue.dlq[0].id

  redrive_allow_policy = jsonencode(merge(
    {
      redrivePermission = var.redrive_allow_permission
    },
    var.redrive_allow_permission == "byQueue" ? {
      sourceQueueArns = [aws_sqs_queue.main[0].arn]
    } : {}
  ))
}

data "aws_iam_policy_document" "queue_policy" {
  count = var.create && var.create_queue_policy ? 1 : 0

  source_policy_documents   = var.queue_policy_source != "" ? [var.queue_policy_source] : []
  override_policy_documents = var.queue_policy_override != "" ? [var.queue_policy_override] : []

  dynamic "statement" {
    for_each = var.queue_policy_statements
    content {
      sid    = try(statement.value.sid, null)
      effect = try(statement.value.effect, "Allow")

      actions = length(try(statement.value.actions, [])) > 0 ? statement.value.actions : [
        "sqs:SendMessage",
        "sqs:ReceiveMessage",
        "sqs:GetQueueAttributes"
      ]

      resources = length(try(statement.value.resources, [])) > 0 ? statement.value.resources : [
        try(aws_sqs_queue.main[0].arn, null)
      ]

      dynamic "principals" {
        for_each = try(statement.value.principals, null) != null ? [statement.value.principals] : []
        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = try(statement.value.conditions, [])
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

resource "aws_sqs_queue_policy" "main" {
  count = var.create && var.create_queue_policy ? 1 : 0

  queue_url = aws_sqs_queue.main[0].id
  policy    = data.aws_iam_policy_document.queue_policy[0].json
}

output "queue_id" {
  value = one(aws_sqs_queue.main[*].id)
}

output "queue_arn" {
  value = one(aws_sqs_queue.main[*].arn)
}

output "queue_url" {
  value = one(aws_sqs_queue.main[*].url)
}

output "queue_name" {
  value = one(aws_sqs_queue.main[*].name)
}

output "fifo_queue" {
  value = var.fifo_queue
}

output "dlq_arn" {
  value = one(aws_sqs_queue.dlq[*].arn)
}

output "dlq_url" {
  value = one(aws_sqs_queue.dlq[*].url)
}

output "redrive_policy_json" {
  value = one(aws_sqs_queue.main[*].redrive_policy)
}

output "queue_policy_json" {
  value = one(data.aws_iam_policy_document.queue_policy[*].json)
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "backup_name" {
  type        = string
  description = "Name of the AWS Backup vault (and base name for the backup plan)."
  default     = "backup"
}

variable "account_type" {
  type        = string
  description = "Account pattern type. Use \"workload\" to provision the backup plan and IAM role, or \"backup\" for a centralized backup vault account."
  default     = "workload"

  validation {
    condition     = var.account_type == "workload" || var.account_type == "backup"
    error_message = "The account_type must be exactly either \"workload\" or \"backup\"."
  }
}

variable "kms_key_arn" {
  type        = string
  description = "Optional customer-managed KMS key ARN used to encrypt recovery points in the vault."
  default     = null
}

variable "vault_policy" {
  type        = string
  description = "Optional JSON vault access policy to attach to the vault."
  default     = null
}

variable "min_retention_days" {
  type        = number
  description = "Optional minimum retention in days. When set, a vault lock configuration is created."
  default     = null
}

variable "max_retention_days" {
  type        = number
  description = "Optional maximum retention in days applied within the vault lock configuration."
  default     = null
}

variable "changeable_for_days" {
  type        = number
  description = "Optional number of days the vault lock remains changeable."
  default     = null
}

variable "enable_aws_backup_vault_notifications" {
  type        = bool
  description = "Whether to create SNS failure notifications for the backup vault."
  default     = false
}

variable "backup_vault_events" {
  type        = list(string)
  description = "List of backup vault events routed to the SNS topic."
  default     = ["BACKUP_JOB_FAILED", "COPY_JOB_FAILED"]
}

variable "sns_topic_arn" {
  type        = string
  description = "SNS topic ARN used as the destination for vault notifications."
  default     = null
}

variable "backup_rule_schedule" {
  type        = string
  description = "Cron expression defining the backup rule schedule."
  default     = "cron(0 5 * * ? *)"
}

variable "copy_action_destination_vault_arns" {
  type        = list(string)
  description = "Destination vault ARNs used to generate cross-region / cross-account copy actions."
  default     = []
}

variable "selection_resources" {
  type        = list(string)
  description = "Explicit resource ARNs used for an additional resource-based backup selection."
  default     = []
}

###############################################################################
# Locals
###############################################################################

locals {
  create_workload_resources = var.account_type == "workload"
  backup_plan_name          = "plan-${var.backup_name}-backup"
  backup_role_name          = "${var.backup_name}-backup-role"
  common_tags = {
    Environment = var.account_type
  }
}

###############################################################################
# Backup Vault
###############################################################################

resource "aws_backup_vault" "this" {
  name        = var.backup_name
  kms_key_arn = var.kms_key_arn

  tags = merge(local.common_tags, {
    Name = var.backup_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault_lock_configuration" "this" {
  count = var.min_retention_days != null ? 1 : 0

  backup_vault_name   = aws_backup_vault.this.name
  min_retention_days  = var.min_retention_days
  max_retention_days  = var.max_retention_days
  changeable_for_days = var.changeable_for_days
}

resource "aws_backup_vault_notifications" "this" {
  count = var.enable_aws_backup_vault_notifications ? 1 : 0

  backup_vault_name   = aws_backup_vault.this.name
  sns_topic_arn       = var.sns_topic_arn
  backup_vault_events = var.backup_vault_events
}

resource "aws_backup_vault_policy" "this" {
  count = var.vault_policy != null && var.vault_policy != "" ? 1 : 0

  backup_vault_name = aws_backup_vault.this.name
  policy            = var.vault_policy
}

###############################################################################
# IAM (workload accounts only)
###############################################################################

data "aws_iam_policy_document" "backup_assume_role" {
  statement {
    sid     = "AllowBackupServiceAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "this" {
  count = local.create_workload_resources ? 1 : 0

  name_prefix        = "aws-backup-"
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role.json

  tags = merge(local.common_tags, {
    Name = local.backup_role_name
  })
}

resource "aws_iam_role_policy_attachment" "backup_service_role" {
  count = local.create_workload_resources ? 1 : 0

  role       = aws_iam_role.this[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

###############################################################################
# Backup Plan (workload accounts only)
###############################################################################

resource "aws_backup_plan" "this" {
  count = local.create_workload_resources ? 1 : 0

  name = local.backup_plan_name

  rule {
    rule_name         = "${local.backup_plan_name}-rule"
    target_vault_name = aws_backup_vault.this.name
    schedule          = var.backup_rule_schedule
    start_window      = 60
    completion_window = 120

    lifecycle {
      cold_storage_after = 30
      delete_after       = 120
    }

    recovery_point_tags = merge(local.common_tags, {
      Backup = "true"
    })

    dynamic "copy_action" {
      for_each = var.copy_action_destination_vault_arns
      content {
        destination_vault_arn = copy_action.value

        lifecycle {
          cold_storage_after = 30
          delete_after       = 120
        }
      }
    }
  }

  tags = merge(local.common_tags, {
    Name = local.backup_plan_name
  })
}

###############################################################################
# Backup Selections (workload accounts only)
###############################################################################

resource "aws_backup_selection" "tags" {
  count = local.create_workload_resources ? 1 : 0

  name         = "${local.backup_plan_name}-selection-tags"
  plan_id      = aws_backup_plan.this[0].id
  iam_role_arn = aws_iam_role.this[0].arn

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "true"
  }
}

resource "aws_backup_selection" "resources" {
  count = local.create_workload_resources && length(var.selection_resources) > 0 ? 1 : 0

  name         = "${local.backup_plan_name}-selection-resources"
  plan_id      = aws_backup_plan.this[0].id
  iam_role_arn = aws_iam_role.this[0].arn
  resources    = var.selection_resources
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }

  # NOTE: no backend block - remote state is configured by the deployment harness.
  # NOTE: no provider block - the AWS provider is injected by the deployment harness.
}

###############################################################################
# Static provider metadata (account/partition only - no pre-existing infra lookup)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Inputs
###############################################################################

variable "name" {
  description = "Name used for the AWS Config resources. When null or empty a petname-based name is generated (\"config\" prefix + random pet suffix)."
  type        = string
  default     = null

  validation {
    condition     = var.name == null ? true : (trimspace(var.name) == "" ? true : length(var.name) <= 64)
    error_message = "The name must be null, empty, or at most 64 characters long (AWS IAM role and SNS topic name limit)."
  }
}

variable "tags" {
  description = "Tags applied to every taggable resource in this stack."
  type        = map(string)

  default = {
    "terraform.io" = "true"
    "environment"  = "sandbox"
  }
}

###############################################################################
# Naming convention: provided name wins, otherwise "config-<petname>"
###############################################################################

resource "random_pet" "name" {
  length    = 2
  separator = "-"
}

resource "random_id" "bucket_suffix" {
  byte_length = 4
}

locals {
  # Null-safe / empty-safe selection: guard the null comparison BEFORE any
  # string function (trimspace) is called, so a null var.name resolves to the
  # petname fallback instead of raising an evaluation error. try() adds a final
  # defensive layer for any unexpected evaluation failure.
  name = try(
    var.name != null && trimspace(var.name) != "" ? var.name : "config-${random_pet.name.id}",
    "config-${random_pet.name.id}"
  )

  tags = merge(
    {
      "terraform.io" = "true"
      "environment"  = "sandbox"
    },
    var.tags,
  )

  snapshots_prefix = "awsconfig/records"
}

###############################################################################
# Dedicated customer managed KMS key for the Config SNS topic / snapshot data
###############################################################################

resource "aws_kms_key" "config" {
  description             = "Customer managed key used to encrypt AWS Config notifications and snapshot data (${local.name})"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  tags = local.tags
}

resource "aws_kms_alias" "config" {
  name          = "alias/${local.name}-config"
  target_key_id = aws_kms_key.config.key_id
}

###############################################################################
# SNS topic (named after the generated resource name) encrypted with the CMK
###############################################################################

resource "aws_sns_topic" "config" {
  name              = local.name
  kms_master_key_id = aws_kms_key.config.arn

  tags = local.tags
}

data "aws_iam_policy_document" "sns_topic" {
  statement {
    sid    = "AllowConfigServicePublish"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }

    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.config.arn]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_sns_topic_policy" "config" {
  arn    = aws_sns_topic.config.arn
  policy = data.aws_iam_policy_document.sns_topic.json
}

###############################################################################
# S3 snapshot storage bucket
###############################################################################

resource "aws_s3_bucket" "config_snapshots" {
  bucket        = "${local.name}-config-${random_id.bucket_suffix.hex}"
  force_destroy = true

  tags = merge(local.tags, { Name = "${local.name}-config-snapshots" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "config_snapshots" {
  bucket = aws_s3_bucket.config_snapshots.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "config_snapshots" {
  bucket = aws_s3_bucket.config_snapshots.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.config.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "config_snapshots" {
  bucket = aws_s3_bucket.config_snapshots.id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "config_snapshots_bucket" {
  statement {
    sid    = "AllowConfigBucketAclCheck"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }

    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.config_snapshots.arn]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }

  statement {
    sid    = "AllowConfigSnapshotDelivery"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.config_snapshots.arn}/${local.snapshots_prefix}/*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

resource "aws_s3_bucket_policy" "config_snapshots" {
  bucket = aws_s3_bucket.config_snapshots.id
  policy = data.aws_iam_policy_document.config_snapshots_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.config_snapshots]
}

###############################################################################
# IAM role used by AWS Config
###############################################################################

data "aws_iam_policy_document" "config_assume_role" {
  statement {
    sid     = "AllowConfigServiceAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_iam_role" "config" {
  name               = local.name
  description        = "IAM role assumed by AWS Config to record resource configurations and deliver snapshots"
  assume_role_policy = data.aws_iam_policy_document.config_assume_role.json

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "config_managed" {
  role       = aws_iam_role.config.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWS_ConfigRole"
}

data "aws_iam_policy_document" "config_sns" {
  statement {
    sid       = "AllowPublishToConfigTopic"
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.config.arn]
  }
}

resource "aws_iam_role_policy" "config_sns" {
  name   = "${local.name}-sns"
  role   = aws_iam_role.config.id
  policy = data.aws_iam_policy_document.config_sns.json
}

data "aws_iam_policy_document" "config_s3" {
  statement {
    sid       = "AllowBucketAclCheckAndList"
    effect    = "Allow"
    actions   = ["s3:GetBucketAcl", "s3:ListBucket"]
    resources = [aws_s3_bucket.config_snapshots.arn]
  }

  statement {
    sid       = "AllowSnapshotObjectWrite"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.config_snapshots.arn}/${local.snapshots_prefix}/*"]
  }
}

resource "aws_iam_role_policy" "config_s3" {
  name   = "${local.name}-s3"
  role   = aws_iam_role.config.id
  policy = data.aws_iam_policy_document.config_s3.json
}

data "aws_iam_policy_document" "config_kms" {
  statement {
    sid    = "AllowUseOfConfigKmsKey"
    effect = "Allow"
    actions = [
      "kms:DescribeKey",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:Decrypt",
    ]
    resources = [aws_kms_key.config.arn]
  }
}

resource "aws_iam_role_policy" "config_kms" {
  name   = "${local.name}-kms"
  role   = aws_iam_role.config.id
  policy = data.aws_iam_policy_document.config_kms.json
}

###############################################################################
# AWS Config recorder / delivery channel / enablement
###############################################################################

resource "aws_config_configuration_recorder" "main" {
  name     = local.name
  role_arn = aws_iam_role.config.arn

  recording_group {
    all_supported                 = true
    include_global_resource_types = true
  }
}

resource "aws_config_delivery_channel" "main" {
  name           = local.name
  s3_bucket_name = aws_s3_bucket.config_snapshots.id
  s3_key_prefix  = local.snapshots_prefix
  s3_kms_key_arn = aws_kms_key.config.arn
  sns_topic_arn  = aws_sns_topic.config.arn

  snapshot_delivery_properties {
    delivery_frequency = "TwentyFour_Hours"
  }
}

resource "aws_config_configuration_recorder_status" "main" {
  name       = aws_config_configuration_recorder.main.name
  is_enabled = true

  depends_on = [
    aws_config_delivery_channel.main,
    aws_s3_bucket_policy.config_snapshots,
    aws_sns_topic_policy.config,
    aws_iam_role_policy_attachment.config_managed,
    aws_iam_role_policy.config_sns,
    aws_iam_role_policy.config_s3,
    aws_iam_role_policy.config_kms,
  ]
}

###############################################################################
# Managed AWS Config rules (evaluated on configuration change + every 24 hours)
###############################################################################

resource "aws_config_config_rule" "cloudtrail_enabled" {
  name                        = "cloudtrail-enabled"
  description                 = "Checks whether AWS CloudTrail is enabled in the account."
  maximum_execution_frequency = "TwentyFour_Hours"

  source {
    owner             = "AWS"
    source_identifier = "CLOUD_TRAIL_ENABLED"
  }

  tags = local.tags
}

resource "aws_config_config_rule" "iam_pw_policy" {
  name                        = "iam-pw-policy"
  description                 = "Checks that the account password policy meets the specified requirements."
  maximum_execution_frequency = "TwentyFour_Hours"

  source {
    owner             = "AWS"
    source_identifier = "IAM_PASSWORD_POLICY"
  }

  tags = local.tags
}

resource "aws_config_config_rule" "ec2_vpc" {
  name                        = "ec2-vpc"
  description                 = "Checks whether all EC2 instances are launched inside a VPC."
  maximum_execution_frequency = "TwentyFour_Hours"

  source {
    owner             = "AWS"
    source_identifier = "INSTANCES_IN_VPC"
  }

  tags = local.tags
}

resource "aws_config_config_rule" "root_mfa_enabled" {
  name                        = "root-mfa-enabled"
  description                 = "Checks whether MFA is enabled for the root user of the account."
  maximum_execution_frequency = "TwentyFour_Hours"

  source {
    owner             = "AWS"
    source_identifier = "ROOT_ACCOUNT_MFA_ENABLED"
  }

  tags = local.tags
}

resource "aws_config_config_rule" "acm_expiration_check" {
  name                        = "acm-expiration-check"
  description                 = "Checks whether ACM certificates are in the specified number of days before expiration."
  maximum_execution_frequency = "TwentyFour_Hours"

  source {
    owner             = "AWS"
    source_identifier = "ACM_CERTIFICATE_EXPIRATION_CHECK"
  }

  tags = local.tags
}

resource "aws_config_config_rule" "ebs_inuse_check" {
  name                        = "ebs-inuse-check"
  description                 = "Checks whether EBS volumes are attached to EC2 instances."
  maximum_execution_frequency = "TwentyFour_Hours"

  source {
    owner             = "AWS"
    source_identifier = "EC2_VOLUME_INUSE_CHECK"
  }

  tags = local.tags
}

resource "aws_config_config_rule" "ec2_imdsv2_check" {
  name                        = "ec2-imdsv2-check"
  description                 = "Checks whether the EC2 instance metadata service is configured to require IMDSv2 (HttpTokens = required)."
  maximum_execution_frequency = "TwentyFour_Hours"

  source {
    owner             = "AWS"
    source_identifier = "EC2_IMDSV2_CHECK"
  }

  tags = local.tags
}

resource "aws_config_config_rule" "rds_encrypted" {
  name                        = "rds-encrypted"
  description                 = "Checks whether RDS DB instances and clusters have storage encryption enabled."
  maximum_execution_frequency = "TwentyFour_Hours"

  source {
    owner             = "AWS"
    source_identifier = "RDS_STORAGE_ENCRYPTED"
  }

  tags = local.tags
}

resource "aws_config_config_rule" "rds_private" {
  name                        = "rds-private"
  description                 = "Checks whether RDS DB instances are configured with public access disabled."
  maximum_execution_frequency = "TwentyFour_Hours"

  source {
    owner             = "AWS"
    source_identifier = "RDS_INSTANCE_PUBLIC_ACCESS_CHECK"
  }

  tags = local.tags
}

resource "aws_config_config_rule" "rds_private_snapshots" {
  name                        = "rds-private-snapshots"
  description                 = "Checks whether RDS snapshots are prohibited from being public."
  maximum_execution_frequency = "TwentyFour_Hours"

  source {
    owner             = "AWS"
    source_identifier = "RDS_SNAPSHOTS_PUBLIC_PROHIBITED"
  }

  tags = local.tags
}

resource "aws_config_config_rule" "required_tags" {
  name                        = "required-tags"
  description                 = "Checks whether S3 buckets carry the required tags (terraform.io, environment)."
  maximum_execution_frequency = "TwentyFour_Hours"

  source {
    owner             = "AWS"
    source_identifier = "REQUIRED_TAGS"
  }

  input_parameters = jsonencode({
    tag1Key = "terraform.io"
    tag2Key = "environment"
  })

  scope {
    compliance_resource_types = ["S3::Bucket"]
  }

  tags = local.tags
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
  required_version = ">= 1.5.0"
}

###############################################################################
# Variables (metadata only - never secrets, never resource attributes)
###############################################################################

variable "aws_region" {
  description = "AWS region used to scope the DRS baseline metadata."
  type        = string
  default     = "us-east-1"
}

variable "tags" {
  description = "Shared tag map applied to every resource in the DRS baseline."
  type        = map(string)
  default = {
    Environment = "production"
    Owner       = "drs-baseline"
    ManagedBy   = "terraform"
  }
}

###############################################################################
# Static provider metadata / caller identity (no pre-existing infrastructure)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# AWS-owned managed policies (immutable, referenced - never created)
###############################################################################

data "aws_iam_policy" "drs_agent_policy" {
  name = "AWSElasticDisasterRecoveryAgentPolicy"
}

data "aws_iam_policy" "drs_failback_policy" {
  name = "AWSElasticDisasterRecoveryFailbackPolicy"
}

data "aws_iam_policy" "drs_conversion_server_policy" {
  name = "AWSElasticDisasterRecoveryConversionServerPolicy"
}

data "aws_iam_policy" "drs_recovery_instance_policy" {
  name = "AWSElasticDisasterRecoveryRecoveryInstancePolicy"
}

data "aws_iam_policy" "drs_replication_server_policy" {
  name = "AWSElasticDisasterRecoveryReplicationServerPolicy"
}

data "aws_iam_policy" "ssm_managed_instance_core" {
  name = "AmazonSSMManagedInstanceCore"
}

###############################################################################
# Locals
###############################################################################

locals {
  service_role_path = "/service-role/"

  drs_principal = "drs.amazonaws.com"
  ec2_principal = "ec2.amazonaws.com"

  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
}

###############################################################################
# Service role 1: AWSElasticDisasterRecoveryAgentRole (DRS, source identity s-*)
###############################################################################

resource "aws_iam_role" "drs_agent" {
  name = "AWSElasticDisasterRecoveryAgentRole"
  path = local.service_role_path

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowDrsAgentAssumeRole"
        Effect    = "Allow"
        Principal = { Service = local.drs_principal }
        Action    = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
          StringLike = {
            "sts:SourceIdentity" = "s-*"
          }
        }
      }
    ]
  })

  tags = merge(var.tags, { Name = "AWSElasticDisasterRecoveryAgentRole" })
}

###############################################################################
# Service role 2: AWSElasticDisasterRecoveryFailbackRole (DRS, identity i-*)
###############################################################################

resource "aws_iam_role" "drs_failback" {
  name = "AWSElasticDisasterRecoveryFailbackRole"
  path = local.service_role_path

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowDrsFailbackAssumeRole"
        Effect    = "Allow"
        Principal = { Service = local.drs_principal }
        Action    = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
          StringLike = {
            "sts:SourceIdentity" = "i-*"
          }
        }
      }
    ]
  })

  tags = merge(var.tags, { Name = "AWSElasticDisasterRecoveryFailbackRole" })
}

###############################################################################
# Service role 3: AWSElasticDisasterRecoveryConversionServerRole (EC2)
###############################################################################

resource "aws_iam_role" "drs_conversion_server" {
  name = "AWSElasticDisasterRecoveryConversionServerRole"
  path = local.service_role_path

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowEc2ConversionServerAssumeRole"
        Effect    = "Allow"
        Principal = { Service = local.ec2_principal }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(var.tags, { Name = "AWSElasticDisasterRecoveryConversionServerRole" })
}

###############################################################################
# Service role 4: AWSElasticDisasterRecoveryRecoveryInstanceRole (EC2)
###############################################################################

resource "aws_iam_role" "drs_recovery_instance" {
  name = "AWSElasticDisasterRecoveryRecoveryInstanceRole"
  path = local.service_role_path

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowEc2RecoveryInstanceAssumeRole"
        Effect    = "Allow"
        Principal = { Service = local.ec2_principal }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(var.tags, { Name = "AWSElasticDisasterRecoveryRecoveryInstanceRole" })
}

###############################################################################
# Service role 5: AWSElasticDisasterRecoveryReplicationServerRole (EC2)
###############################################################################

resource "aws_iam_role" "drs_replication_server" {
  name = "AWSElasticDisasterRecoveryReplicationServerRole"
  path = local.service_role_path

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowEc2ReplicationServerAssumeRole"
        Effect    = "Allow"
        Principal = { Service = local.ec2_principal }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(var.tags, { Name = "AWSElasticDisasterRecoveryReplicationServerRole" })
}

###############################################################################
# Service role 6: ...RecoveryInstanceWithLaunchActionsRole (EC2)
###############################################################################

resource "aws_iam_role" "drs_recovery_instance_with_launch_actions" {
  name = "AWSElasticDisasterRecoveryRecoveryInstanceWithLaunchActionsRole"
  path = local.service_role_path

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowEc2RecoveryInstanceWithLaunchActionsAssumeRole"
        Effect    = "Allow"
        Principal = { Service = local.ec2_principal }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(var.tags, { Name = "AWSElasticDisasterRecoveryRecoveryInstanceWithLaunchActionsRole" })
}

###############################################################################
# Instance profiles (required for EC2-assumable service roles)
###############################################################################

resource "aws_iam_instance_profile" "conversion_server" {
  name = "AWSElasticDisasterRecoveryConversionServerProfile"
  path = local.service_role_path
  role = aws_iam_role.drs_conversion_server.name

  tags = merge(var.tags, { Name = "AWSElasticDisasterRecoveryConversionServerProfile" })
}

resource "aws_iam_instance_profile" "replication_server" {
  name = "AWSElasticDisasterRecoveryReplicationServerProfile"
  path = local.service_role_path
  role = aws_iam_role.drs_replication_server.name

  tags = merge(var.tags, { Name = "AWSElasticDisasterRecoveryReplicationServerProfile" })
}

resource "aws_iam_instance_profile" "recovery_instance" {
  name = "AWSElasticDisasterRecoveryRecoveryInstanceProfile"
  path = local.service_role_path
  role = aws_iam_role.drs_recovery_instance.name

  tags = merge(var.tags, { Name = "AWSElasticDisasterRecoveryRecoveryInstanceProfile" })
}

resource "aws_iam_instance_profile" "recovery_instance_with_launch_actions" {
  name = "AWSElasticDisasterRecoveryRecoveryInstanceWithLaunchActionsProfile"
  path = local.service_role_path
  role = aws_iam_role.drs_recovery_instance_with_launch_actions.name

  tags = merge(var.tags, { Name = "AWSElasticDisasterRecoveryRecoveryInstanceWithLaunchActionsProfile" })
}

###############################################################################
# Managed policy attachments
###############################################################################

resource "aws_iam_role_policy_attachment" "drs_agent_policy" {
  role       = aws_iam_role.drs_agent.name
  policy_arn = data.aws_iam_policy.drs_agent_policy.arn
}

resource "aws_iam_role_policy_attachment" "drs_failback_policy" {
  role       = aws_iam_role.drs_failback.name
  policy_arn = data.aws_iam_policy.drs_failback_policy.arn
}

resource "aws_iam_role_policy_attachment" "drs_conversion_server_policy" {
  role       = aws_iam_role.drs_conversion_server.name
  policy_arn = data.aws_iam_policy.drs_conversion_server_policy.arn
}

resource "aws_iam_role_policy_attachment" "drs_recovery_instance_policy" {
  role       = aws_iam_role.drs_recovery_instance.name
  policy_arn = data.aws_iam_policy.drs_recovery_instance_policy.arn
}

resource "aws_iam_role_policy_attachment" "drs_replication_server_policy" {
  role       = aws_iam_role.drs_replication_server.name
  policy_arn = data.aws_iam_policy.drs_replication_server_policy.arn
}

resource "aws_iam_role_policy_attachment" "drs_recovery_instance_with_launch_actions_policy" {
  role       = aws_iam_role.drs_recovery_instance_with_launch_actions.name
  policy_arn = data.aws_iam_policy.drs_recovery_instance_policy.arn
}

resource "aws_iam_role_policy_attachment" "drs_recovery_instance_with_launch_actions_ssm" {
  role       = aws_iam_role.drs_recovery_instance_with_launch_actions.name
  policy_arn = data.aws_iam_policy.ssm_managed_instance_core.arn
}

###############################################################################
# Initializer role (root path) - assumable only by the current calling identity
###############################################################################

resource "aws_iam_role" "drs_initializer" {
  name = "AWSElasticDisasterRecoveryInitializerRole"
  path = "/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowCallingIdentityAssumeRole"
        Effect    = "Allow"
        Principal = { AWS = data.aws_caller_identity.current.arn }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(var.tags, { Name = "AWSElasticDisasterRecoveryInitializerRole" })
}

###############################################################################
# Customer-managed InitializePolicy (least privilege, scoped to DRS bootstrap)
###############################################################################

resource "aws_iam_policy" "initialize_policy" {
  name        = "InitializePolicy"
  description = "Bootstrap policy enabling AWS Elastic Disaster Recovery service initialization."
  path        = "/"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "DrsServiceInitialization"
        Effect = "Allow"
        Action = [
          "drs:InitializeService",
          "drs:DescribeSourceServers",
          "drs:DescribeReplicationConfigurationTemplates",
          "drs:ListTagsForResource"
        ]
        Resource = "*"
      },
      {
        Sid    = "InstanceProfileManagement"
        Effect = "Allow"
        Action = [
          "iam:CreateInstanceProfile",
          "iam:GetInstanceProfile",
          "iam:AddRoleToInstanceProfile",
          "iam:RemoveRoleFromInstanceProfile",
          "iam:DeleteInstanceProfile",
          "iam:TagInstanceProfile"
        ]
        Resource = [
          aws_iam_instance_profile.conversion_server.arn,
          aws_iam_instance_profile.replication_server.arn,
          aws_iam_instance_profile.recovery_instance.arn,
          aws_iam_instance_profile.recovery_instance_with_launch_actions.arn
        ]
      },
      {
        Sid    = "PassRoleToDrsAndEc2"
        Effect = "Allow"
        Action = "iam:PassRole"
        Resource = [
          aws_iam_role.drs_agent.arn,
          aws_iam_role.drs_failback.arn,
          aws_iam_role.drs_conversion_server.arn,
          aws_iam_role.drs_recovery_instance.arn,
          aws_iam_role.drs_replication_server.arn,
          aws_iam_role.drs_recovery_instance_with_launch_actions.arn
        ]
        Condition = {
          StringEquals = {
            "iam:PassedToService" = [
              "ec2.amazonaws.com",
              "drs.amazonaws.com"
            ]
          }
        }
      },
      {
        Sid    = "CreateDrsServiceLinkedRole"
        Effect = "Allow"
        Action = "iam:CreateServiceLinkedRole"
        Resource = [
          "arn:${local.partition}:iam::${local.account_id}:role/aws-service-role/drs.amazonaws.com/AWSServiceRoleForElasticDisasterRecovery"
        ]
        Condition = {
          StringEquals = {
            "iam:AWSServiceName" = "drs.amazonaws.com"
          }
        }
      },
      {
        Sid    = "Ec2InitializationActions"
        Effect = "Allow"
        Action = [
          "ec2:CreateSecurityGroup",
          "ec2:AuthorizeSecurityGroupIngress",
          "ec2:AuthorizeSecurityGroupEgress",
          "ec2:CreateTags",
          "ec2:DescribeAvailabilityZones",
          "ec2:DescribeAccountAttributes",
          "ec2:DescribeImages",
          "ec2:DescribeInstanceTypes",
          "ec2:DescribeInstances",
          "ec2:DescribeInstanceStatus",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSubnets",
          "ec2:DescribeVpcs",
          "ec2:DescribeLaunchTemplates",
          "ec2:DescribeLaunchTemplateVersions",
          "ec2:RunInstances",
          "ec2:StartInstances",
          "ec2:StopInstances",
          "ec2:TerminateInstances",
          "ec2:CreateLaunchTemplate",
          "ec2:CreateLaunchTemplateVersion",
          "ec2:DeleteLaunchTemplate",
          "ec2:DeleteLaunchTemplateVersions",
          "ec2:ModifyLaunchTemplate"
        ]
        Resource = "*"
      },
      {
        Sid    = "AttachDrsManagedPoliciesOnly"
        Effect = "Allow"
        Action = [
          "iam:AttachRolePolicy",
          "iam:DetachRolePolicy"
        ]
        Resource = [
          aws_iam_role.drs_agent.arn,
          aws_iam_role.drs_failback.arn,
          aws_iam_role.drs_conversion_server.arn,
          aws_iam_role.drs_recovery_instance.arn,
          aws_iam_role.drs_replication_server.arn,
          aws_iam_role.drs_recovery_instance_with_launch_actions.arn
        ]
        Condition = {
          StringEquals = {
            "iam:PolicyARN" = [
              data.aws_iam_policy.drs_agent_policy.arn,
              data.aws_iam_policy.drs_failback_policy.arn,
              data.aws_iam_policy.drs_conversion_server_policy.arn,
              data.aws_iam_policy.drs_recovery_instance_policy.arn,
              data.aws_iam_policy.drs_replication_server_policy.arn
            ]
          }
        }
      }
    ]
  })

  tags = merge(var.tags, { Name = "InitializePolicy" })
}

resource "aws_iam_role_policy_attachment" "drs_initializer_initialize_policy" {
  role       = aws_iam_role.drs_initializer.name
  policy_arn = aws_iam_policy.initialize_policy.arn
}

###############################################################################
# Outputs
###############################################################################

output "drs_agent_role_arn" {
  description = "ARN of the AWS Elastic Disaster Recovery agent service role."
  value       = aws_iam_role.drs_agent.arn
}

output "drs_failback_role_arn" {
  description = "ARN of the AWS Elastic Disaster Recovery failback service role."
  value       = aws_iam_role.drs_failback.arn
}

output "drs_conversion_server_role_arn" {
  description = "ARN of the AWS Elastic Disaster Recovery conversion server role."
  value       = aws_iam_role.drs_conversion_server.arn
}

output "drs_recovery_instance_role_arn" {
  description = "ARN of the AWS Elastic Disaster Recovery recovery instance role."
  value       = aws_iam_role.drs_recovery_instance.arn
}

output "drs_replication_server_role_arn" {
  description = "ARN of the AWS Elastic Disaster Recovery replication server role."
  value       = aws_iam_role.drs_replication_server.arn
}

output "drs_recovery_instance_with_launch_actions_role_arn" {
  description = "ARN of the AWS Elastic Disaster Recovery recovery instance with launch actions role."
  value       = aws_iam_role.drs_recovery_instance_with_launch_actions.arn
}

output "drs_initializer_role_arn" {
  description = "ARN of the AWS Elastic Disaster Recovery initializer role."
  value       = aws_iam_role.drs_initializer.arn
}

output "drs_instance_profile_names" {
  description = "Names of the instance profiles bound to the EC2-assumable DRS service roles."
  value = {
    conversion_server                    = aws_iam_instance_profile.conversion_server.name
    replication_server                   = aws_iam_instance_profile.replication_server.name
    recovery_instance                    = aws_iam_instance_profile.recovery_instance.name
    recovery_instance_with_launch_actions = aws_iam_instance_profile.recovery_instance_with_launch_actions.name
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

locals {
  environment = "prod"
}

data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------
# External VPC (public-facing tier)
# ---------------------------------------------------------------------------

resource "aws_vpc" "external" {
  cidr_block           = "10.41.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "Production External"
    purpose     = "Production External VPC"
    environment = local.environment
  }
}

resource "aws_default_security_group" "external" {
  vpc_id = aws_vpc.external.id

  tags = {
    Name = "Production External Default SG"
  }
}

resource "aws_subnet" "external_subnet_0" {
  vpc_id            = aws_vpc.external.id
  cidr_block        = "10.41.0.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "Subnet0-1a"
  }
}

resource "aws_subnet" "external_subnet_1" {
  vpc_id            = aws_vpc.external.id
  cidr_block        = "10.41.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name = "Subnet1-1b"
  }
}

resource "aws_subnet" "external_subnet_2" {
  vpc_id            = aws_vpc.external.id
  cidr_block        = "10.41.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[2]

  tags = {
    Name = "Subnet2-1c"
  }
}

resource "aws_subnet" "external_subnet_3" {
  vpc_id            = aws_vpc.external.id
  cidr_block        = "10.41.3.0/24"
  availability_zone = data.aws_availability_zones.available.names[3]

  tags = {
    Name = "Subnet3-1d"
  }
}

resource "aws_internet_gateway" "external" {
  vpc_id = aws_vpc.external.id

  tags = {
    Name = "External GW"
  }
}

resource "aws_route_table" "external" {
  vpc_id = aws_vpc.external.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.external.id
  }

  tags = {
    Name = "Production External Route Table"
  }
}

resource "aws_main_route_table_association" "external" {
  vpc_id         = aws_vpc.external.id
  route_table_id = aws_route_table.external.id
}

resource "aws_route_table_association" "external_subnet_0" {
  subnet_id      = aws_subnet.external_subnet_0.id
  route_table_id = aws_route_table.external.id
}

resource "aws_route_table_association" "external_subnet_1" {
  subnet_id      = aws_subnet.external_subnet_1.id
  route_table_id = aws_route_table.external.id
}

resource "aws_route_table_association" "external_subnet_2" {
  subnet_id      = aws_subnet.external_subnet_2.id
  route_table_id = aws_route_table.external.id
}

resource "aws_route_table_association" "external_subnet_3" {
  subnet_id      = aws_subnet.external_subnet_3.id
  route_table_id = aws_route_table.external.id
}

resource "aws_default_network_acl" "external" {
  default_network_acl_id = aws_vpc.external.default_network_acl_id

  egress {
    protocol   = "icmp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  egress {
    protocol   = "-1"
    rule_no    = 150
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  ingress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = {
    Name = "Production External Default NACL"
  }
}

# ---------------------------------------------------------------------------
# Internal VPC (isolated tier)
# ---------------------------------------------------------------------------

resource "aws_vpc" "internal" {
  cidr_block           = "10.40.0.0/16"
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "Production Internal"
    purpose     = "Production Internal VPC"
    environment = local.environment
  }
}

resource "aws_default_security_group" "internal" {
  vpc_id = aws_vpc.internal.id

  tags = {
    Name = "Production Internal Default SG"
  }
}

resource "aws_subnet" "internal_subnet_0" {
  vpc_id            = aws_vpc.internal.id
  cidr_block        = "10.40.0.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "Subnet0-1a"
  }
}

resource "aws_subnet" "internal_subnet_1" {
  vpc_id            = aws_vpc.internal.id
  cidr_block        = "10.40.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name = "Subnet1-1b"
  }
}

resource "aws_subnet" "internal_subnet_2" {
  vpc_id            = aws_vpc.internal.id
  cidr_block        = "10.40.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[2]

  tags = {
    Name = "Subnet2-1c"
  }
}

resource "aws_subnet" "internal_subnet_3" {
  vpc_id            = aws_vpc.internal.id
  cidr_block        = "10.40.3.0/24"
  availability_zone = data.aws_availability_zones.available.names[3]

  tags = {
    Name = "Subnet3-1d"
  }
}

resource "aws_default_network_acl" "internal" {
  default_network_acl_id = aws_vpc.internal.default_network_acl_id

  subnet_ids = [
    aws_subnet.internal_subnet_0.id,
    aws_subnet.internal_subnet_1.id,
    aws_subnet.internal_subnet_2.id,
    aws_subnet.internal_subnet_3.id,
  ]

  egress {
    protocol   = "icmp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  egress {
    protocol   = "-1"
    rule_no    = 150
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  ingress {
    protocol   = "icmp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = {
    Name = "Production Internal Default NACL"
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

variable "resource_prefix" {
  description = "Prefix used for naming all resources."
  type        = string
  default     = "n8n"
}

variable "certificate_arn" {
  description = "Optional ACM certificate ARN for the HTTPS listener. When null, a self-signed certificate is generated and imported."
  type        = string
  default     = null
}

variable "url" {
  description = "Optional public webhook URL override for n8n."
  type        = string
  default     = null
}

variable "desired_count" {
  description = "Desired number of ECS tasks."
  type        = number
  default     = 1
}

variable "container_image" {
  description = "Container image for n8n."
  type        = string
  default     = "n8nio/n8n:1.4.0"
}

variable "fargate_type" {
  description = "Fargate capacity provider type (FARGATE or FARGATE_SPOT)."
  type        = string
  default     = "FARGATE_SPOT"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  common_tags = {
    Project     = var.resource_prefix
    Environment = "production"
    ManagedBy   = "Terraform"
  }

  private_subnet_cidrs = [
    "10.0.0.0/24",
    "10.0.1.0/24",
    "10.0.2.0/24"
  ]

  public_subnet_cidrs = [
    "10.0.4.0/24",
    "10.0.5.0/24",
    "10.0.6.0/24"
  ]

  certificate_arn = coalesce(var.certificate_arn, one(aws_acm_certificate.main[*].arn))
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-vpc"
  })
}

resource "aws_subnet" "private" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-private-${count.index + 1}"
    Tier = "private"
  })
}

resource "aws_subnet" "public" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-public-${count.index + 1}"
    Tier = "public"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "alb" {
  name_prefix = "${var.resource_prefix}-alb-"
  description = "Security group for the internal n8n application load balancer"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow HTTP from anywhere to the ALB entry point"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "Allow HTTPS from anywhere to the ALB entry point"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Restrict ALB egress to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-alb-sg"
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group" "tasks" {
  name_prefix = "${var.resource_prefix}-tasks-"
  description = "Security group for n8n ECS tasks"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "Allow n8n traffic only from the load balancer"
    from_port       = 5678
    to_port         = 5678
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "Restrict task egress to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-tasks-sg"
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group" "efs" {
  name_prefix = "${var.resource_prefix}-efs-"
  description = "Security group for n8n EFS mount targets"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow NFS from the VPC CIDR"
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Restrict EFS egress to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-efs-sg"
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_lb" "main" {
  name                       = "${var.resource_prefix}-alb"
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = aws_subnet.public[*].id
  drop_invalid_header_fields = true

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-alb"
  })
}

resource "aws_lb_target_group" "main" {
  name                 = "${var.resource_prefix}-tg"
  port                 = 80
  protocol             = "HTTP"
  vpc_id               = aws_vpc.main.id
  target_type          = "ip"
  deregistration_delay = 30

  health_check {
    enabled             = true
    healthy_threshold   = 2
    unhealthy_threshold = 2
    timeout             = 3
    interval            = 30
    path                = "/healthz"
    protocol            = "HTTP"
    matcher             = "200"
  }

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-tg"
  })
}

resource "tls_private_key" "main" {
  count = var.certificate_arn == null ? 1 : 0

  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "main" {
  count = var.certificate_arn == null ? 1 : 0

  private_key_pem       = tls_private_key.main[0].private_key_pem
  validity_period_hours = 8760

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth"
  ]

  subject {
    common_name  = aws_lb.main.dns_name
    organization = var.resource_prefix
  }

  dns_names = [aws_lb.main.dns_name]
}

resource "aws_acm_certificate" "main" {
  count = var.certificate_arn == null ? 1 : 0

  certificate_body = tls_self_signed_cert.main[0].cert_pem
  private_key      = tls_private_key.main[0].private_key_pem

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-cert"
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.main.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = local.certificate_arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }

  depends_on = [aws_acm_certificate.main]
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }
}

resource "aws_efs_file_system" "main" {
  creation_token = "${var.resource_prefix}-efs"
  encrypted      = true

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-efs"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_efs_mount_target" "private" {
  count = 3

  file_system_id  = aws_efs_file_system.main.id
  subnet_id       = aws_subnet.private[count.index].id
  security_groups = [aws_security_group.efs.id]
}

resource "aws_efs_access_point" "main" {
  file_system_id = aws_efs_file_system.main.id

  posix_user {
    uid = 1000
    gid = 1000
  }

  root_directory {
    path = "/n8n"

    creation_info {
      owner_uid   = 1000
      owner_gid   = 1000
      permissions = "777"
    }
  }

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-efs-ap"
  })
}

resource "aws_ecs_cluster" "main" {
  name = "${var.resource_prefix}-cluster"

  setting {
    name  = "containerInsights"
    value = "disabled"
  }

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-cluster"
  })
}

resource "aws_ecs_cluster_capacity_providers" "main" {
  cluster_name       = aws_ecs_cluster.main.name
  capacity_providers = [var.fargate_type]

  default_capacity_provider_strategy {
    capacity_provider = var.fargate_type
    base              = 1
    weight            = 100
  }
}

resource "aws_cloudwatch_log_group" "main" {
  name              = "${var.resource_prefix}-logs"
  retention_in_days = 1

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-logs"
  })
}

resource "aws_iam_role" "ecs_task_execution" {
  name = "${var.resource_prefix}-ecs-task-execution"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-ecs-task-execution"
  })
}

resource "aws_iam_role" "ecs_task" {
  name = "${var.resource_prefix}-ecs-task"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-ecs-task"
  })
}

resource "aws_iam_role_policy" "ecs_task_execution_logs" {
  name = "${var.resource_prefix}-ecs-task-execution-logs"
  role = aws_iam_role.ecs_task_execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = [
          aws_cloudwatch_log_group.main.arn,
          "${aws_cloudwatch_log_group.main.arn}:*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy" "ecs_task" {
  name = "${var.resource_prefix}-ecs-task"
  role = aws_iam_role.ecs_task.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = [
          aws_cloudwatch_log_group.main.arn,
          "${aws_cloudwatch_log_group.main.arn}:*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "elasticfilesystem:ClientMount",
          "elasticfilesystem:ClientWrite",
          "elasticfilesystem:ClientRootAccess"
        ]
        Resource = [
          aws_efs_file_system.main.arn
        ]
      }
    ]
  })
}

resource "aws_ecs_task_definition" "main" {
  family                   = "${var.resource_prefix}-task"
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                      = 256
  memory                   = 512
  execution_role_arn       = aws_iam_role.ecs_task_execution.arn
  task_role_arn            = aws_iam_role.ecs_task.arn

  volume {
    name = "n8n-data"

    efs_volume_configuration {
      file_system_id     = aws_efs_file_system.main.id
      transit_encryption = "ENABLED"

      authorization_config {
        access_point_id = aws_efs_access_point.main.id
        iam             = "ENABLED"
      }
    }
  }

  container_definitions = jsonencode([
    {
      name      = "n8n"
      image     = var.container_image
      essential = true

      portMappings = [
        {
          containerPort = 5678
          hostPort      = 5678
          protocol      = "tcp"
        }
      ]

      mountPoints = [
        {
          sourceVolume  = "n8n-data"
          containerPath = "/home/node/.n8n"
          readOnly      = false
        }
      ]

      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.main.name
          "awslogs-region"        = "us-east-1"
          "awslogs-stream-prefix" = var.resource_prefix
        }
      }

      environment = [
        {
          name  = "N8N_SKIP_WEBHOOK_DEREGISTRATION_SHUTDOWN"
          value = "true"
        },
        {
          name  = "WEBHOOK_URL"
          value = var.url != null ? var.url : "https://${aws_lb.main.dns_name}"
        }
      ]
    }
  ])

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-task"
  })
}

resource "aws_ecs_service" "main" {
  name            = "${var.resource_prefix}-service"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.main.arn
  desired_count   = var.desired_count

  capacity_provider_strategy {
    capacity_provider = var.fargate_type
    base              = 1
    weight            = 100
  }

  network_configuration {
    subnets          = aws_subnet.public[*].id
    assign_public_ip = true
    security_groups  = [aws_security_group.tasks.id]
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.main.arn
    container_name   = "n8n"
    container_port   = 5678
  }

  depends_on = [
    aws_lb_listener.https,
    aws_efs_mount_target.private,
    aws_ecs_cluster_capacity_providers.main,
    aws_iam_role_policy.ecs_task_execution_logs,
    aws_iam_role_policy.ecs_task
  ]

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-service"
  })
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.99.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  common_tags = {
    Application = "dosomething-quasar"
    Environment = "production"
    Stack       = "data"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.255.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "Quasar"
  })
}

resource "aws_subnet" "rds_1a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.255.100.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, {
    Name = "Quasar RDS - 1A"
  })
}

resource "aws_subnet" "rds_1e" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.255.101.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.common_tags, {
    Name = "Quasar RDS - 1E"
  })
}

resource "aws_security_group" "bastion" {
  name        = "Quasar-Bastion"
  description = "Bastion host - SSH access from admin range only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from admin range"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["203.0.113.0/24"]
  }

  egress {
    description = "Egress restricted to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-Bastion"
  })
}

resource "aws_security_group" "ha_proxy" {
  name        = "Quasar-HA-Proxy"
  description = "HA proxy load balancer - HTTP/HTTPS from internet (accepted-risk), SSH from bastion"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from everywhere (accepted risk - intended public load balancer)"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from everywhere (accepted risk - intended public load balancer)"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description     = "SSH from bastion"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.bastion.id]
  }

  egress {
    description = "Egress restricted to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-HA-Proxy"
  })
}

resource "aws_security_group" "jenkins" {
  name        = "Quasar-Jenkins"
  description = "Jenkins CI - SSH from bastion, HTTP 8080 from HA proxy"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "SSH from bastion"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.bastion.id]
  }

  ingress {
    description     = "Jenkins UI from HA proxy"
    from_port       = 8080
    to_port         = 8080
    protocol        = "tcp"
    security_groups = [aws_security_group.ha_proxy.id]
  }

  egress {
    description = "Egress restricted to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-Jenkins"
  })
}

resource "aws_security_group" "etl" {
  name        = "Quasar-ETL"
  description = "ETL compute nodes - SSH from bastion and Jenkins"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "SSH from bastion"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.bastion.id]
  }

  ingress {
    description     = "SSH from Jenkins"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.jenkins.id]
  }

  egress {
    description = "Egress restricted to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-ETL"
  })
}

resource "aws_security_group" "postgres" {
  name        = "Quasar-PostgreSQL"
  description = "PostgreSQL database - access from ETL and (accepted-risk) everywhere"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL from everywhere (accepted risk - narrow before production)"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description     = "PostgreSQL from ETL"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.etl.id]
  }

  egress {
    description = "Egress restricted to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-PostgreSQL"
  })
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.0"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.0"
    }
  }
}

###############################################################################
# Global creation control
###############################################################################

variable "create" {
  description = "Global creation guard. When false, no resources are created."
  type        = bool
  default     = true
}

###############################################################################
# Deployment target inputs
###############################################################################

variable "function_name" {
  description = "Name of the Lambda function that is the blue/green deployment target."
  type        = string
  default     = "bluegreen-demo-function"
}

variable "alias_name" {
  description = "Lambda alias that CodeDeploy shifts traffic to."
  type        = string
  default     = "live"
}

variable "current_version" {
  description = "Lambda version that currently receives traffic. Empty string falls back to the Terraform-managed published version."
  type        = string
  default     = ""
}

variable "target_version" {
  description = "Lambda version that traffic is shifted to. Empty string falls back to the Terraform-managed published version."
  type        = string
  default     = ""
}

variable "lambda_runtime" {
  description = "Runtime for the deployment target Lambda function."
  type        = string
  default     = "python3.12"

  validation {
    condition     = contains(["python3.12", "nodejs22.x", "python3.11", "nodejs20.x"], var.lambda_runtime)
    error_message = "lambda_runtime must be one of: python3.12, nodejs22.x, python3.11, nodejs20.x."
  }
}

variable "before_allow_traffic_hook_arn" {
  description = "Optional Lambda ARN invoked by CodeDeploy before traffic is allowed."
  type        = string
  default     = ""
}

variable "after_allow_traffic_hook_arn" {
  description = "Optional Lambda ARN invoked by CodeDeploy after traffic is allowed."
  type        = string
  default     = ""
}

###############################################################################
# CodeDeploy application / deployment group inputs
###############################################################################

variable "app_name" {
  description = "Name of the CodeDeploy application (Lambda compute platform)."
  type        = string
  default     = "bluegreen-demo-app"
}

variable "deployment_group_name" {
  description = "Name of the CodeDeploy deployment group."
  type        = string
  default     = "bluegreen-demo-dg"
}

variable "deployment_config_name" {
  description = "CodeDeploy deployment configuration used for the blue/green deployment group."
  type        = string
  default     = "CodeDeployDefault.LambdaAllAtOnce"
}

variable "create_app" {
  description = "Create a new CodeDeploy application."
  type        = bool
  default     = false
}

variable "use_existing_app" {
  description = "Reuse an existing CodeDeploy application instead of creating one."
  type        = bool
  default     = false
}

variable "create_deployment_group" {
  description = "Create a new CodeDeploy deployment group."
  type        = bool
  default     = false
}

variable "use_existing_deployment_group" {
  description = "Reuse an existing CodeDeploy deployment group instead of creating one."
  type        = bool
  default     = false
}

variable "auto_rollback_enabled" {
  description = "Enable automatic rollbacks on the deployment group."
  type        = bool
  default     = true
}

variable "auto_rollback_events" {
  description = "Deployment events that trigger an automatic rollback."
  type        = list(string)
  default     = ["DEPLOYMENT_STOP_ON_ALARM"]
}

variable "alarm_configuration_enabled" {
  description = "Enable CloudWatch alarm monitoring for the deployment group."
  type        = bool
  default     = false
}

variable "alarm_names" {
  description = "CloudWatch alarm names monitored by the deployment group."
  type        = list(string)
  default     = []
}

variable "notification_triggers" {
  description = "SNS notification triggers for the deployment group."
  type = list(object({
    trigger_name       = string
    trigger_target_arn = string
    trigger_events     = list(string)
  }))
  default = []
}

###############################################################################
# IAM inputs
###############################################################################

variable "create_codedeploy_role" {
  description = "Create the CodeDeploy service role and attach the Lambda deployment managed policy."
  type        = bool
  default     = true
}

variable "codedeploy_service_principals" {
  description = "Service principals allowed to assume the CodeDeploy service role."
  type        = list(string)
  default     = ["codedeploy.amazonaws.com"]
}

variable "codedeploy_service_role_arn" {
  description = "Existing CodeDeploy service role ARN used when create_codedeploy_role is false."
  type        = string
  default     = ""
}

variable "attach_hooks_policy" {
  description = "Attach an inline policy granting lambda:InvokeFunction for the allow-traffic hooks."
  type        = bool
  default     = true
}

variable "attach_triggers_policy" {
  description = "Attach an inline policy granting sns:Publish for the configured notification triggers."
  type        = bool
  default     = false
}

###############################################################################
# Deployment execution inputs
###############################################################################

variable "create_deployment" {
  description = "Generate the AppSpec JSON and shell script used to create the blue/green deployment."
  type        = bool
  default     = false
}

variable "aws_cli_command" {
  description = "AWS CLI executable used by the generated deployment script."
  type        = string
  default     = "aws"
}

variable "get_deployment_sleep_timer" {
  description = "Seconds to sleep between get-deployment status polls."
  type        = number
  default     = 5
}

variable "monitor_deployment" {
  description = "Poll the CodeDeploy deployment status until it reaches a terminal state."
  type        = bool
  default     = true
}

variable "save_deploy_script" {
  description = "Persist the generated deployment script and AppSpec locally."
  type        = bool
  default     = false
}

variable "run_deployment" {
  description = "Execute the generated deployment script via a local-exec provisioner."
  type        = bool
  default     = false
}

variable "force_deploy" {
  description = "Optional value used to force re-execution of the deployment. When empty a uuid() is generated."
  type        = string
  default     = ""
}

###############################################################################
# Locals
###############################################################################

locals {
  create_app              = var.create && var.create_app && !var.use_existing_app
  create_deployment_group = var.create && var.create_deployment_group && !var.use_existing_deployment_group
  create_codedeploy_role  = var.create && var.create_codedeploy_role
  create_deployment       = var.create && var.create_deployment

  create_hooks_policy    = local.create_codedeploy_role && var.attach_hooks_policy
  create_triggers_policy = local.create_codedeploy_role && var.attach_triggers_policy

  generated_dir      = "${path.module}/generated"
  appspec_path       = "${local.generated_dir}/appspec.json"
  revision_path      = "${local.generated_dir}/revision.json"
  deploy_script_path = "${local.generated_dir}/deploy.sh"

  codedeploy_app_name   = try(coalesce(one(aws_codedeploy_app.app[*].name), var.app_name), var.app_name)
  codedeploy_group_name = try(coalesce(one(aws_codedeploy_deployment_group.this[*].deployment_group_name), var.deployment_group_name), var.deployment_group_name)
  codedeploy_role_arn   = try(coalesce(one(aws_iam_role.codedeploy[*].arn), var.codedeploy_service_role_arn), "")

  lambda_function_arn = one(aws_lambda_function.app[*].arn)
  lambda_alias_arn    = one(aws_lambda_alias.live[*].arn)
  lambda_version      = one(aws_lambda_function.app[*].version)

  current_version = coalesce(var.current_version, local.lambda_version, "0")
  target_version  = coalesce(var.target_version, local.lambda_version, "0")

  provided_hook_arns = compact([
    var.before_allow_traffic_hook_arn,
    var.after_allow_traffic_hook_arn,
  ])

  hook_policy_arns = length(local.provided_hook_arns) > 0 ? local.provided_hook_arns : compact([local.lambda_alias_arn])

  trigger_topic_arns = distinct([for trigger in var.notification_triggers : trigger.trigger_target_arn])

  appspec_hooks = concat(
    var.before_allow_traffic_hook_arn != "" ? [{ BeforeAllowTraffic = var.before_allow_traffic_hook_arn }] : [],
    var.after_allow_traffic_hook_arn != "" ? [{ AfterAllowTraffic = var.after_allow_traffic_hook_arn }] : [],
  )

  appspec = merge(
    {
      version = "0.0"
      Resources = [
        {
          BlueGreenFunction = {
            Type = "AWS::Lambda::Function"
            Properties = {
              Name           = var.function_name
              Alias          = var.alias_name
              CurrentVersion = local.current_version
              TargetVersion  = local.target_version
            }
          }
        }
      ]
    },
    length(local.appspec_hooks) > 0 ? { Hooks = local.appspec_hooks } : {}
  )

  appspec_json = jsonencode(local.appspec)

  revision_json = jsonencode({
    revisionType = "AppSpecContent"
    appSpecContent = {
      content = local.appspec_json
    }
  })

  deploy_script = <<-EOT
    #!/usr/bin/env bash
    set -euo pipefail

    AWS_CLI_COMMAND="${var.aws_cli_command}"
    APPLICATION_NAME="${local.codedeploy_app_name}"
    DEPLOYMENT_GROUP_NAME="${local.codedeploy_group_name}"
    REVISION_FILE="${local.revision_path}"
    SLEEP_TIMER="${var.get_deployment_sleep_timer}"
    MONITOR_DEPLOYMENT="${var.monitor_deployment}"

    echo "Creating CodeDeploy blue/green deployment for $APPLICATION_NAME ($DEPLOYMENT_GROUP_NAME)"

    DEPLOYMENT_ID=$($AWS_CLI_COMMAND deploy create-deployment \
      --application-name "$APPLICATION_NAME" \
      --deployment-group-name "$DEPLOYMENT_GROUP_NAME" \
      --revision "file://$REVISION_FILE" \
      --query 'deploymentId' \
      --output text)

    echo "Deployment created: $DEPLOYMENT_ID"

    if [ "$MONITOR_DEPLOYMENT" = "true" ]; then
      while true; do
        STATUS=$($AWS_CLI_COMMAND deploy get-deployment \
          --deployment-id "$DEPLOYMENT_ID" \
          --query 'deploymentInfo.status' \
          --output text)

        echo "Deployment status: $STATUS"

        case "$STATUS" in
          Succeeded)
            echo "Deployment $DEPLOYMENT_ID succeeded"
            break
            ;;
          Failed|Stopped|Skipped)
            echo "Deployment $DEPLOYMENT_ID finished with status $STATUS" >&2
            exit 1
            ;;
        esac

        sleep "$SLEEP_TIMER"
      done
    fi
  EOT
}

###############################################################################
# Deployment target Lambda function
###############################################################################

data "archive_file" "lambda" {
  count       = var.create ? 1 : 0
  type        = "zip"
  output_path = "${path.module}/build/function.zip"

  source {
    filename = "index.py"
    content  = <<-PY
      import json


      def lambda_handler(event, context):
          return {
              "statusCode": 200,
              "headers": {"Content-Type": "application/json"},
              "body": json.dumps({"message": "blue/green deployment target"}),
          }
    PY
  }
}

data "aws_iam_policy_document" "lambda_assume" {
  count = var.create ? 1 : 0

  statement {
    sid     = "LambdaAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "lambda_exec" {
  count              = var.create ? 1 : 0
  name               = "${var.function_name}-exec-role"
  description        = "Execution role for the blue/green deployment target Lambda function."
  assume_role_policy = data.aws_iam_policy_document.lambda_assume[0].json
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  count      = var.create ? 1 : 0
  role       = aws_iam_role.lambda_exec[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_lambda_function" "app" {
  count = var.create ? 1 : 0

  function_name = var.function_name
  description   = "Blue/green deployment target function managed alongside its CodeDeploy pipeline."
  role          = aws_iam_role.lambda_exec[0].arn
  handler       = "index.lambda_handler"
  runtime       = var.lambda_runtime
  publish       = true
  timeout       = 30
  memory_size   = 128

  filename         = data.archive_file.lambda[0].output_path
  source_code_hash = data.archive_file.lambda[0].output_base64sha256

  depends_on = [aws_iam_role_policy_attachment.lambda_basic_execution]
}

resource "aws_lambda_alias" "live" {
  count = var.create ? 1 : 0

  name             = var.alias_name
  description      = "Alias used by CodeDeploy for blue/green traffic shifting."
  function_name    = aws_lambda_function.app[0].function_name
  function_version = aws_lambda_function.app[0].version
}

###############################################################################
# CodeDeploy application
###############################################################################

resource "aws_codedeploy_app" "app" {
  count            = local.create_app ? 1 : 0
  name             = var.app_name
  compute_platform = "Lambda"
}

###############################################################################
# CodeDeploy service role
###############################################################################

data "aws_iam_policy_document" "codedeploy_assume" {
  count = local.create_codedeploy_role ? 1 : 0

  statement {
    sid     = "CodeDeployAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = var.codedeploy_service_principals
    }
  }
}

resource "aws_iam_role" "codedeploy" {
  count              = local.create_codedeploy_role ? 1 : 0
  name               = "${var.app_name}-codedeploy-role"
  description        = "Service role assumed by CodeDeploy to perform Lambda blue/green deployments."
  assume_role_policy = data.aws_iam_policy_document.codedeploy_assume[0].json
}

resource "aws_iam_role_policy_attachment" "codedeploy_lambda" {
  count      = local.create_codedeploy_role ? 1 : 0
  role       = aws_iam_role.codedeploy[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSCodeDeployRoleForLambda"
}

data "aws_iam_policy_document" "hooks" {
  count = local.create_hooks_policy ? 1 : 0

  statement {
    sid       = "InvokeAllowTrafficHooks"
    effect    = "Allow"
    actions   = ["lambda:InvokeFunction"]
    resources = local.hook_policy_arns
  }
}

resource "aws_iam_role_policy" "hooks" {
  count = local.create_hooks_policy ? 1 : 0

  name   = "${var.app_name}-codedeploy-hooks-policy"
  role   = aws_iam_role.codedeploy[0].id
  policy = data.aws_iam_policy_document.hooks[0].json
}

data "aws_iam_policy_document" "triggers" {
  count = local.create_triggers_policy && length(local.trigger_topic_arns) > 0 ? 1 : 0

  statement {
    sid       = "PublishDeploymentNotifications"
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = local.trigger_topic_arns
  }
}

resource "aws_iam_role_policy" "triggers" {
  count = local.create_triggers_policy && length(local.trigger_topic_arns) > 0 ? 1 : 0

  name   = "${var.app_name}-codedeploy-triggers-policy"
  role   = aws_iam_role.codedeploy[0].id
  policy = data.aws_iam_policy_document.triggers[0].json
}

###############################################################################
# CodeDeploy deployment group (Lambda blue/green)
###############################################################################

resource "aws_codedeploy_deployment_group" "this" {
  count = local.create_deployment_group ? 1 : 0

  app_name               = local.codedeploy_app_name
  deployment_group_name  = var.deployment_group_name
  service_role_arn       = local.codedeploy_role_arn
  deployment_config_name = var.deployment_config_name

  deployment_style {
    deployment_option = "WITH_TRAFFIC_CONTROL"
    deployment_type   = "BLUE_GREEN"
  }

  auto_rollback_configuration {
    enabled = var.auto_rollback_enabled
    events  = var.auto_rollback_events
  }

  dynamic "alarm_configuration" {
    for_each = var.alarm_configuration_enabled ? [1] : []
    content {
      enabled = true
      alarms  = var.alarm_names
    }
  }

  dynamic "trigger_configuration" {
    for_each = var.notification_triggers
    content {
      trigger_name       = trigger_configuration.value.trigger_name
      trigger_target_arn = trigger_configuration.value.trigger_target_arn
      trigger_events     = trigger_configuration.value.trigger_events
    }
  }

  depends_on = [
    aws_iam_role_policy_attachment.codedeploy_lambda,
    aws_lambda_alias.live,
  ]
}

###############################################################################
# Generated blue/green revision artifacts and deployment script
###############################################################################

resource "local_file" "appspec" {
  count    = local.create_deployment ? 1 : 0
  filename = local.appspec_path
  content  = local.appspec_json

  file_permission = "0644"
}

resource "local_file" "revision" {
  count    = local.create_deployment ? 1 : 0
  filename = local.revision_path
  content  = local.revision_json

  file_permission = "0644"
}

resource "local_file" "deploy_script" {
  count    = local.create_deployment && (var.save_deploy_script || var.run_deployment) ? 1 : 0
  filename = local.deploy_script_path
  content  = local.deploy_script

  file_permission = "0755"
}

resource "null_resource" "run_deployment" {
  count = local.create_deployment && var.run_deployment ? 1 : 0

  triggers = {
    force_deploy  = var.force_deploy != "" ? var.force_deploy : uuid()
    revision_hash = sha256(local.revision_json)
    function_name = var.function_name
    alias_name    = var.alias_name
  }

  provisioner "local-exec" {
    command = "bash ${local.deploy_script_path}"
  }

  depends_on = [
    local_file.appspec,
    local_file.revision,
    local_file.deploy_script,
    aws_codedeploy_deployment_group.this,
  ]
}

###############################################################################
# Outputs for downstream CLI execution
###############################################################################

output "codedeploy_app_name" {
  description = "Name of the CodeDeploy application used by the pipeline."
  value       = local.codedeploy_app_name
}

output "codedeploy_deployment_group_name" {
  description = "Name of the CodeDeploy deployment group bound to the pipeline."
  value       = local.codedeploy_group_name
}

output "codedeploy_role_arn" {
  description = "ARN of the CodeDeploy service role used for Lambda deployments."
  value       = local.codedeploy_role_arn
}

output "appspec_path" {
  description = "Local path of the generated AppSpec JSON artifact."
  value       = local.appspec_path
}

output "revision_path" {
  description = "Local path of the generated CodeDeploy revision JSON artifact."
  value       = local.revision_path
}

output "deployment_script_path" {
  description = "Local path of the generated deployment shell script."
  value       = local.deploy_script_path
}

output "deployment_config_name" {
  description = "CodeDeploy deployment configuration used by the deployment group."
  value       = var.deployment_config_name
}

output "lambda_function_name" {
  description = "Name of the blue/green deployment target Lambda function."
  value       = var.function_name
}

output "lambda_function_arn" {
  description = "ARN of the blue/green deployment target Lambda function."
  value       = local.lambda_function_arn
}

output "lambda_alias_arn" {
  description = "ARN of the Lambda alias used for the blue/green traffic shift."
  value       = local.lambda_alias_arn
}

terraform {
  required_version = ">= 1.3"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "internal_domain" {
  description = "Internal DNS domain name for the private Route 53 zone and DHCP options."
  type        = string
  default     = "internal"
}

variable "public_dns_server" {
  description = "Additional public DNS resolver used by the VPC DHCP option set."
  type        = string
  default     = "8.8.8.8"
}

variable "admin_cidrs" {
  description = "List of administrator CIDR blocks allowed to SSH into the Home SSH security group."
  type        = list(string)
  default     = ["203.0.113.0/24"]
}

variable "tags" {
  description = "Additional tags to apply to all taggable resources."
  type        = map(string)
  default     = {}
}

locals {
  common_tags = merge(
    {
      Environment = "dev"
      ManagedBy   = "Terraform"
    },
    var.tags
  )
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "main"
  })
}

resource "aws_internet_gateway" "ig" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
