# -----------------------------------------------------------------------------
# Security Groups
# -----------------------------------------------------------------------------

resource "aws_security_group" "home_ssh" {
  name        = "Home SSH"
  description = "Allow SSH access from administrative CIDRs and self."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from self"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    self        = true
  }

  dynamic "ingress" {
    for_each = var.admin_cidrs
    content {
      description = "SSH from administrative CIDR ${ingress.value}"
      from_port   = 22
      to_port     = 22
      protocol    = "tcp"
      cidr_blocks = [ingress.value]
    }
  }

  egress {
    description = "Restrict all egress to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "Home SSH"
  })
}

resource "aws_security_group" "packer_ssh" {
  name        = "Packer SSH"
  description = "Allow SSH access from the VPC CIDR and self."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from self"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    self        = true
  }

  ingress {
    description = "SSH from the VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Restrict all egress to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "Packer SSH"
  })
}

terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.100.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "3.7.2"
    }
  }
}

variable "base_bucket_name" {
  description = "Base name for the S3 bucket."
  type        = string
  default     = "benchmark-bucket-tf5x"

  validation {
    condition     = length(var.base_bucket_name) >= 3 && length(var.base_bucket_name) <= 63 && can(regex("^[a-z0-9][a-z0-9.-]*[a-z0-9]$", var.base_bucket_name))
    error_message = "The base bucket name must be between 3 and 63 characters, lowercase, and DNS-compliant."
  }
}

variable "use_account_alias_prefix" {
  description = "Prefix the bucket name with the AWS IAM account alias."
  type        = bool
  default     = false
}

variable "use_random_suffix" {
  description = "Prefix the bucket name with a random suffix."
  type        = bool
  default     = false
}

variable "custom_bucket_policy" {
  description = "Optional custom JSON bucket policy to merge with the managed policy."
  type        = string
  default     = null

  validation {
    condition     = var.custom_bucket_policy == null ? true : can(jsondecode(var.custom_bucket_policy).Statement)
    error_message = "custom_bucket_policy must be null or a valid JSON policy document containing a Statement element."
  }
}

variable "enable_s3_public_access_block" {
  description = "Enable all S3 public access block settings."
  type        = bool
  default     = true
}

variable "kms_master_key_id" {
  description = "Optional KMS key ID or ARN for SSE-KMS encryption."
  type        = string
  default     = null
}

variable "bucket_key_enabled" {
  description = "Enable S3 Bucket Keys for SSE-KMS."
  type        = bool
  default     = false
}

variable "versioning_status" {
  description = "Versioning status for the bucket."
  type        = string
  default     = "Enabled"

  validation {
    condition     = contains(["Enabled", "Suspended"], var.versioning_status)
    error_message = "versioning_status must be one of Enabled or Suspended."
  }
}

variable "force_destroy" {
  description = "Allow the bucket to be destroyed even if it contains objects."
  type        = bool
  default     = false
}

variable "enable_analytics" {
  description = "Enable S3 Storage Class Analytics."
  type        = bool
  default     = true
}

variable "enable_bucket_inventory" {
  description = "Enable S3 Bucket Inventory."
  type        = bool
  default     = false
}

variable "logging_bucket" {
  description = "Optional name for a dedicated S3 server access logging bucket. When set, logging is enabled."
  type        = string
  default     = null

  validation {
    condition     = var.logging_bucket == null ? true : (length(var.logging_bucket) >= 3 && length(var.logging_bucket) <= 63 && can(regex("^[a-z0-9][a-z0-9.-]*[a-z0-9]$", var.logging_bucket)))
    error_message = "logging_bucket must be null or a valid DNS-compliant S3 bucket name between 3 and 63 characters."
  }
}

variable "transfer_acceleration" {
  description = "Optional S3 transfer acceleration status. Valid values: Enabled, Suspended."
  type        = string
  default     = null

  validation {
    condition     = var.transfer_acceleration == null ? true : contains(["Enabled", "Suspended"], var.transfer_acceleration)
    error_message = "transfer_acceleration must be null, Enabled, or Suspended."
  }
}

variable "s3_bucket_acl" {
  description = "Optional canned ACL for the bucket. Deprecated; prefer bucket policies and public access block."
  type        = string
  default     = null

  validation {
    condition = var.s3_bucket_acl == null ? true : contains([
      "private",
      "public-read",
      "public-read-write",
      "authenticated-read",
      "aws-exec-read",
      "bucket-owner-read",
      "bucket-owner-full-control"
    ], var.s3_bucket_acl)
    error_message = "s3_bucket_acl must be null or a valid canned ACL."
  }
}

variable "cors_rules" {
  description = "List of CORS rules to apply to the bucket."
  type        = list(any)
  default     = []
}

variable "environment" {
  description = "Environment tag value."
  type        = string
  default     = "dev"
}

locals {
  account_alias_prefix = var.use_account_alias_prefix ? "${lower(data.aws_iam_account_alias.current[0].account_alias)}-" : ""
  random_suffix_prefix = var.use_random_suffix ? "${random_id.suffix[0].hex}-" : ""

  bucket_name = trim(
    replace(
      replace(
        lower("${local.account_alias_prefix}${local.random_suffix_prefix}${var.base_bucket_name}"),
        "/[^a-z0-9.-]/",
        ""
      ),
      "/\\.{2,}/",
      "."
    ),
    "-."
  )

  tags = {
    Project     = "benchmark-bucket-tf5x"
    ManagedBy   = "Terraform"
    Environment = var.environment
  }
}

data "aws_iam_account_alias" "current" {
  count = var.use_account_alias_prefix ? 1 : 0
}

resource "random_id" "suffix" {
  count       = var.use_random_suffix ? 1 : 0
  byte_length = 4
}

data "aws_iam_policy_document" "main" {
  statement {
    sid    = "DenyNonTLS"
    effect = "Deny"

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.main.arn,
      "${aws_s3_bucket.main.arn}/*"
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid    = "AllowS3ServiceInventoryAnalyticsWrites"
    effect = "Allow"

    actions = ["s3:PutObject"]

    resources = [
      "${aws_s3_bucket.main.arn}/_AWSBucketInventory/*",
      "${aws_s3_bucket.main.arn}/_AWSBucketAnalytics/*"
    ]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }

  source_policy_documents = var.custom_bucket_policy != null ? [jsonencode(jsondecode(var.custom_bucket_policy))] : []
}

resource "aws_s3_bucket" "main" {
  bucket        = local.bucket_name
  force_destroy = var.force_destroy

  tags = local.tags

  lifecycle {
    prevent_destroy = true

    precondition {
      condition     = length(local.bucket_name) >= 3 && length(local.bucket_name) <= 63 && can(regex("^[a-z0-9][a-z0-9.-]*[a-z0-9]$", local.bucket_name))
      error_message = "The computed bucket name must be a valid DNS-compliant S3 bucket name between 3 and 63 characters."
    }
  }
}

resource "aws_s3_bucket_public_access_block" "main" {
  count = var.enable_s3_public_access_block ? 1 : 0

  bucket = aws_s3_bucket.main.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.kms_master_key_id != null ? "aws:kms" : "AES256"
      kms_master_key_id = var.kms_master_key_id
    }

    bucket_key_enabled = var.bucket_key_enabled
  }
}

resource "aws_s3_bucket_versioning" "main" {
  bucket = aws_s3_bucket.main.id

  versioning_configuration {
    status = var.versioning_status
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "main" {
  bucket = aws_s3_bucket.main.id

  transition_default_minimum_object_size = "all_storage_classes_128K"

  rule {
    id     = "abort-incomplete-multipart-uploads"
    status = "Enabled"

    abort_incomplete_multipart_upload {
      days_after_initiation = 14
    }
  }

  rule {
    id     = "noncurrent-version-management"
    status = "Enabled"

    noncurrent_version_transition {
      noncurrent_days = 30
      storage_class   = "STANDARD_IA"
    }

    noncurrent_version_expiration {
      noncurrent_days = 365
    }
  }

  dynamic "rule" {
    for_each = var.enable_analytics ? [1] : []

    content {
      id     = "expire-analytics-exports"
      status = "Enabled"

      filter {
        prefix = "_AWSBucketAnalytics/"
      }

      expiration {
        days = 30
      }
    }
  }

  dynamic "rule" {
    for_each = var.enable_bucket_inventory ? [1] : []

    content {
      id     = "expire-inventory-reports"
      status = "Enabled"

      filter {
        prefix = "_AWSBucketInventory/"
      }

      expiration {
        days = 14
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.main]
}

resource "aws_s3_bucket_policy" "main" {
  bucket = aws_s3_bucket.main.id
  policy = data.aws_iam_policy_document.main.json

  depends_on = [aws_s3_bucket_public_access_block.main]
}

resource "aws_s3_bucket_analytics_configuration" "main" {
  count = var.enable_analytics ? 1 : 0

  bucket = aws_s3_bucket.main.id
  name   = "main-analytics"

  filter {
    prefix = "_AWSBucketAnalytics/"
  }

  storage_class_analysis {
    data_export {
      output_schema_version = "V_1"

      destination {
        s3_bucket_destination {
          bucket_arn = aws_s3_bucket.main.arn
          format     = "CSV"
          prefix     = "_AWSBucketAnalytics/"
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_policy.main]
}

resource "aws_s3_bucket_inventory" "main" {
  count = var.enable_bucket_inventory ? 1 : 0

  bucket = aws_s3_bucket.main.id
  name   = "main-inventory"

  included_object_versions = "All"

  schedule {
    frequency = "Weekly"
  }

  destination {
    bucket {
      format     = "ORC"
      bucket_arn = aws_s3_bucket.main.arn
      prefix     = "_AWSBucketInventory/"
    }
  }

  depends_on = [aws_s3_bucket_policy.main]
}

resource "aws_s3_bucket" "logging" {
  count = var.logging_bucket != null ? 1 : 0

  bucket        = var.logging_bucket
  force_destroy = var.force_destroy

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "logging" {
  count = var.logging_bucket != null && var.enable_s3_public_access_block ? 1 : 0

  bucket = aws_s3_bucket.logging[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logging" {
  count = var.logging_bucket != null ? 1 : 0

  bucket = aws_s3_bucket.logging[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.kms_master_key_id != null ? "aws:kms" : "AES256"
      kms_master_key_id = var.kms_master_key_id
    }

    bucket_key_enabled = var.bucket_key_enabled
  }
}

resource "aws_s3_bucket_versioning" "logging" {
  count = var.logging_bucket != null ? 1 : 0

  bucket = aws_s3_bucket.logging[0].id

  versioning_configuration {
    status = var.versioning_status
  }
}

resource "aws_s3_bucket_logging" "main" {
  count = var.logging_bucket != null ? 1 : 0

  bucket        = aws_s3_bucket.main.id
  target_bucket = aws_s3_bucket.logging[0].id
  target_prefix = "s3/${aws_s3_bucket.main.id}/"
}

resource "aws_s3_bucket_accelerate_configuration" "main" {
  count = var.transfer_acceleration != null ? 1 : 0

  bucket = aws_s3_bucket.main.id
  status = var.transfer_acceleration
}

resource "aws_s3_bucket_acl" "main" {
  count = var.s3_bucket_acl != null ? 1 : 0

  bucket = aws_s3_bucket.main.id
  acl    = var.s3_bucket_acl
}

resource "aws_s3_bucket_cors_configuration" "main" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.main.id

  dynamic "cors_rule" {
    for_each = var.cors_rules

    content {
      allowed_headers = try(cors_rule.value.allowed_headers, null)
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Providers
# The primary provider hosts the source bucket, the aliased provider hosts the
# replication destination bucket in a different region.
###############################################################################

provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "replica"
  region = var.replication_region
}

###############################################################################
# Static provider metadata (no pre-existing infrastructure is discovered)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Variables
###############################################################################

variable "environment" {
  description = "Environment name used for tagging and resource naming."
  type        = string
  default     = "dev"

  validation {
    condition     = length(var.environment) > 0
    error_message = "environment must not be empty."
  }
}

variable "owner" {
  description = "Team or individual accountable for the resources."
  type        = string
  default     = "platform-team"
}

variable "tags" {
  description = "Additional tags merged onto every taggable resource."
  type        = map(string)
  default     = {}
}

variable "replication_region" {
  description = "Region hosting the cross-region replication destination bucket."
  type        = string
  default     = "us-west-2"
}

variable "bucket_name" {
  description = "Globally unique name for the primary bucket (maximum 63 characters)."
  type        = string
  default     = null

  validation {
    condition     = var.bucket_name == null || (length(var.bucket_name) <= 63 && length(var.bucket_name) >= 3)
    error_message = "bucket_name must be null or between 3 and 63 characters long."
  }
}

variable "bucket_name_prefix" {
  description = "Prefix used by S3 to generate a unique bucket name (maximum 37 characters)."
  type        = string
  default     = "enterprise-s3-"

  validation {
    condition     = var.bucket_name_prefix == null || length(var.bucket_name_prefix) <= 37
    error_message = "bucket_name_prefix must be null or at most 37 characters long."
  }

  validation {
    condition     = var.bucket_name != null || var.bucket_name_prefix != null
    error_message = "At least one of bucket_name or bucket_name_prefix must be provided."
  }
}

variable "force_destroy" {
  description = "Allow destruction of a non-empty bucket. Defaults to false."
  type        = bool
  default     = false
}

variable "object_ownership" {
  description = "S3 object ownership mode for the primary bucket."
  type        = string
  default     = "BucketOwnerEnforced"

  validation {
    condition     = contains(["BucketOwnerEnforced", "ObjectWriter", "BucketOwnerPreferred"], var.object_ownership)
    error_message = "object_ownership must be one of BucketOwnerEnforced, ObjectWriter or BucketOwnerPreferred."
  }
}

variable "block_public_acls" {
  description = "Block public ACLs on the bucket."
  type        = bool
  default     = true
}

variable "block_public_policy" {
  description = "Block public bucket policies."
  type        = bool
  default     = true
}

variable "ignore_public_acls" {
  description = "Ignore public ACLs placed on the bucket."
  type        = bool
  default     = true
}

variable "restrict_public_buckets" {
  description = "Restrict public bucket policies."
  type        = bool
  default     = true
}

variable "kms_key_arn" {
  description = "Optional customer managed KMS key ARN. When null an AES256 default is used and a dedicated key is created for reference."
  type        = string
  default     = null

  validation {
    condition     = var.kms_key_arn == null || can(regex("^arn:[a-z0-9-]+:kms:", var.kms_key_arn))
    error_message = "kms_key_arn must be null or a valid KMS key ARN."
  }
}

variable "versioning_enabled" {
  description = "Enable bucket versioning. Defaults to false (Suspended)."
  type        = bool
  default     = false
}

variable "object_lock_enabled" {
  description = "Enable S3 Object Lock on the bucket. Requires versioning."
  type        = bool
  default     = false
}

variable "object_lock_retention" {
  description = "Default object lock retention applied to the bucket when object_lock_enabled is true."
  type = object({
    mode  = optional(string, "GOVERNANCE")
    days  = optional(number, 30)
    years = optional(number, null)
  })
  default = {
    mode  = "GOVERNANCE"
    days  = 30
    years = null
  }

  validation {
    condition     = contains(["GOVERNANCE", "COMPLIANCE"], var.object_lock_retention.mode)
    error_message = "object_lock_retention.mode must be GOVERNANCE or COMPLIANCE."
  }

  validation {
    condition     = var.object_lock_retention.days == null || (var.object_lock_retention.days >= 1 && var.object_lock_retention.days <= 36500)
    error_message = "object_lock_retention.days must be between 1 and 36500 when set."
  }

  validation {
    condition     = var.object_lock_retention.years == null || (var.object_lock_retention.years >= 1 && var.object_lock_retention.years <= 100)
    error_message = "object_lock_retention.years must be between 1 and 100 when set."
  }

  validation {
    condition     = !(var.object_lock_retention.days != null && var.object_lock_retention.years != null)
    error_message = "object_lock_retention may only define one of days or years."
  }
}

variable "custom_bucket_policy_json" {
  description = "Optional additional bucket policy JSON merged with the enforced statements."
  type        = string
  default     = null

  validation {
    condition     = var.custom_bucket_policy_json == null || can(jsondecode(var.custom_bucket_policy_json))
    error_message = "custom_bucket_policy_json must be null or valid JSON."
  }
}

variable "logging_source_bucket_arns" {
  description = "Source bucket ARNs allowed to deliver server access logs to this bucket."
  type        = list(string)
  default     = []
}

variable "enable_eventbridge_notifications" {
  description = "Enable EventBridge notifications for the bucket."
  type        = bool
  default     = false
}

variable "access_logging" {
  description = "Server access logging configuration for the primary bucket."
  type = object({
    enabled       = optional(bool, false)
    target_prefix = optional(string, "access-logs/")
  })
  default = {
    enabled       = false
    target_prefix = "access-logs/"
  }
}

variable "replication_rules" {
  description = "Cross-region replication rules applied to the source bucket."
  type = list(object({
    id                               = string
    priority                         = optional(number, null)
    status                           = optional(string, "Enabled")
    prefix                           = optional(string, null)
    tags                             = optional(map(string), {})
    storage_class                    = optional(string, "STANDARD")
    replica_kms_key_id               = optional(string, null)
    replication_time_minutes         = optional(number, 15)
    metrics_status                   = optional(string, "Enabled")
    delete_marker_replication_status = optional(string, "Enabled")
  }))
  default = []

  validation {
    condition     = alltrue([for rule in var.replication_rules : contains(["Enabled", "Disabled"], rule.status)])
    error_message = "replication_rules[*].status must be Enabled or Disabled."
  }

  validation {
    condition     = length(distinct([for rule in var.replication_rules : tostring(coalesce(rule.priority, 0))])) == length(var.replication_rules)
    error_message = "replication_rules[*].priority must be unique across all rules."
  }

  validation {
    condition     = alltrue([for rule in var.replication_rules : rule.replication_time_minutes >= 15])
    error_message = "replication_rules[*].replication_time_minutes must be at least 15."
  }

  validation {
    condition     = alltrue([for rule in var.replication_rules : contains(["Enabled", "Disabled"], rule.delete_marker_replication_status)])
    error_message = "replication_rules[*].delete_marker_replication_status must be Enabled or Disabled."
  }
}

variable "inventory_configurations" {
  description = "S3 Inventory configurations written to the primary bucket."
  type = list(object({
    name                     = string
    frequency                = optional(string, "Daily")
    included_object_versions = optional(string, "All")
    format                   = optional(string, "Parquet")
    prefix                   = optional(string, null)
    destination_prefix       = optional(string, null)
    optional_fields          = optional(list(string), null)
    encryption_type          = optional(string, "sse_s3")
    kms_key_id               = optional(string, null)
  }))
  default = []

  validation {
    condition     = alltrue([for config in var.inventory_configurations : contains(["Daily", "Weekly"], config.frequency)])
    error_message = "inventory_configurations[*].frequency must be Daily or Weekly."
  }

  validation {
    condition     = alltrue([for config in var.inventory_configurations : contains(["CSV", "Parquet"], config.format)])
    error_message = "inventory_configurations[*].format must be CSV or Parquet."
  }

  validation {
    condition     = alltrue([for config in var.inventory_configurations : contains(["All", "Current"], config.included_object_versions)])
    error_message = "inventory_configurations[*].included_object_versions must be All or Current."
  }

  validation {
    condition     = alltrue([for config in var.inventory_configurations : contains(["sse_s3", "sse_kms"], config.encryption_type)])
    error_message = "inventory_configurations[*].encryption_type must be sse_s3 or sse_kms."
  }

  validation {
    condition     = alltrue([for config in var.inventory_configurations : config.encryption_type != "sse_kms" || config.kms_key_id != null])
    error_message = "inventory_configurations[*].kms_key_id is required when encryption_type is sse_kms."
  }
}

variable "cors_rules" {
  description = "CORS rules applied to the primary bucket."
  type = list(object({
    allowed_methods = list(string)
    allowed_origins = list(string)
    allowed_headers = optional(list(string), null)
    expose_headers  = optional(list(string), null)
    max_age_seconds = optional(number, 3000)
  }))
  default = []

  validation {
    condition = alltrue([
      for rule in var.cors_rules :
      !contains(rule.allowed_origins, "*") || !contains(coalesce(rule.allowed_headers, []), "Authorization")
    ])
    error_message = "Wildcard origins are only permitted together with non-credentialed CORS rules."
  }
}

variable "lifecycle_rules" {
  description = "Lifecycle rules applied to the primary bucket."
  type = list(object({
    id     = string
    status = optional(string, "Enabled")
    prefix = optional(string, null)
    tags   = optional(map(string), {})
    expiration = optional(object({
      days                         = optional(number, null)
      date                         = optional(string, null)
      expired_object_delete_marker = optional(bool, null)
    }), null)
    transitions = optional(list(object({
      days          = optional(number, null)
      date          = optional(string, null)
      storage_class = string
    })), [])
    noncurrent_version_expiration = optional(object({
      noncurrent_days = number
    }), null)
    noncurrent_version_transitions = optional(list(object({
      noncurrent_days = number
      storage_class   = string
    })), [])
    abort_incomplete_multipart_upload_days = optional(number, null)
  }))
  default = []

  validation {
    condition     = alltrue([for rule in var.lifecycle_rules : contains(["Enabled", "Disabled"], rule.status)])
    error_message = "lifecycle_rules[*].status must be Enabled or Disabled."
  }

  validation {
    condition     = length(distinct([for rule in var.lifecycle_rules : rule.id])) == length(var.lifecycle_rules)
    error_message = "lifecycle_rules[*].id must be unique."
  }

  validation {
    condition     = alltrue([for rule in var.lifecycle_rules : rule.expiration == null || !(rule.expiration.days != null && rule.expiration.date != null)])
    error_message = "lifecycle_rules[*].expiration may only define one of days or date."
  }
}

###############################################################################
# Locals
###############################################################################

locals {
  common_tags = {
    Environment = var.environment
    Owner       = var.owner
    ManagedBy   = "terraform"
  }

  tags = merge(var.tags, local.common_tags)

  bucket_name_base = coalesce(var.bucket_name, var.bucket_name_prefix, "enterprise-s3")

  sse_algorithm = var.kms_key_arn == null ? "AES256" : "aws:kms"

  effective_kms_key_arn = coalesce(var.kms_key_arn, aws_kms_key.s3.arn)

  inventory_configurations = {
    for configuration in var.inventory_configurations : configuration.name => configuration
  }
}

###############################################################################
# KMS keys
###############################################################################

data "aws_iam_policy_document" "kms" {
  statement {
    sid    = "EnableAccountRootPermissions"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowS3ReplicationRole"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.replication.arn]
    }

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:Encrypt",
      "kms:GenerateDataKey*",
      "kms:ReEncrypt*",
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key" "s3" {
  description             = "Customer managed key protecting the ${local.bucket_name_base} S3 bucket"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms.json

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "s3" {
  name          = "alias/s3-data-encryption"
  target_key_id = aws_kms_key.s3.key_id
}

data "aws_iam_policy_document" "kms_replica" {
  statement {
    sid    = "EnableAccountRootPermissions"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowS3ReplicationRole"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.replication.arn]
    }

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:Encrypt",
      "kms:GenerateDataKey*",
      "kms:ReEncrypt*",
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key" "replica" {
  provider = aws.replica

  description             = "Customer managed key protecting the replication destination bucket"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_replica.json

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "replica" {
  provider = aws.replica

  name          = "alias/s3-replica-data-encryption"
  target_key_id = aws_kms_key.replica.key_id
}

###############################################################################
# IAM role used by S3 replication
###############################################################################

data "aws_iam_policy_document" "replication_assume_role" {
  statement {
    sid     = "AllowS3ServiceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_iam_role" "replication" {
  name_prefix        = "s3-replication-"
  description        = "Allows S3 to replicate objects between the source and destination buckets"
  assume_role_policy = data.aws_iam_policy_document.replication_assume_role.json

  tags = local.tags
}

data "aws_iam_policy_document" "replication" {
  statement {
    sid    = "SourceBucketReadPermissions"
    effect = "Allow"

    actions = [
      "s3:GetReplicationConfiguration",
      "s3:GetBucketVersioning",
      "s3:ListBucket",
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
      "s3:GetObjectLegalHold",
      "s3:GetObjectRetention",
    ]

    resources = [
      aws_s3_bucket.this.arn,
      "${aws_s3_bucket.this.arn}/*",
    ]
  }

  statement {
    sid    = "DestinationBucketWritePermissions"
    effect = "Allow"

    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
      "s3:ObjectOwnerOverrideToBucketOwner",
    ]

    resources = [
      aws_s3_bucket.replica.arn,
      "${aws_s3_bucket.replica.arn}/*",
    ]
  }

  statement {
    sid    = "ReplicationKeyPermissions"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
    ]

    resources = [
      aws_kms_key.s3.arn,
      aws_kms_key.replica.arn,
    ]
  }
}

resource "aws_iam_role_policy" "replication" {
  name   = "s3-replication-least-privilege"
  role   = aws_iam_role.replication.id
  policy = data.aws_iam_policy_document.replication.json
}

###############################################################################
# Primary bucket
###############################################################################

resource "aws_s3_bucket" "this" {
  bucket              = var.bucket_name
  bucket_prefix       = var.bucket_name != null ? null : var.bucket_name_prefix
  force_destroy       = var.force_destroy
  object_lock_enabled = var.object_lock_enabled

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = var.object_ownership
  }
}

resource "aws_s3_bucket_acl" "this" {
  count = var.object_ownership == "ObjectWriter" ? 1 : 0

  bucket = aws_s3_bucket.this.id
  acl    = "private"

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = local.sse_algorithm
      kms_master_key_id = var.kms_key_arn == null ? null : local.effective_kms_key_arn
    }

    bucket_key_enabled = var.kms_key_arn == null ? null : true
  }
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = var.versioning_enabled ? "Enabled" : "Suspended"
  }

  lifecycle {
    precondition {
      condition     = !(length(var.replication_rules) > 0 || var.object_lock_enabled) || var.versioning_enabled
      error_message = "versioning_enabled must be true when replication rules or object lock retention are configured."
    }
  }
}

data "aws_iam_policy_document" "bucket" {
  source_policy_documents = var.custom_bucket_policy_json != null ? [var.custom_bucket_policy_json] : []

  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.this.arn,
      "${aws_s3_bucket.this.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid    = "DenyRequestsOutsideBucketRegion"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.this.arn,
      "${aws_s3_bucket.this.arn}/*",
    ]

    condition {
      test     = "Null"
      variable = "aws:RequestedRegion"
      values   = ["false"]
    }

    condition {
      test     = "StringNotEquals"
      variable = "aws:RequestedRegion"
      values   = [data.aws_region.current.name]
    }
  }

  dynamic "statement" {
    for_each = length(var.logging_source_bucket_arns) > 0 ? [1] : []

    content {
      sid    = "AllowS3ServerAccessLogging"
      effect = "Allow"

      principals {
        type        = "Service"
        identifiers = ["logging.s3.amazonaws.com"]
      }

      actions   = ["s3:PutObject"]
      resources = ["${aws_s3_bucket.this.arn}/*"]

      condition {
        test     = "StringEquals"
        variable = "aws:SourceAccount"
        values   = [data.aws_caller_identity.current.account_id]
      }

      condition {
        test     = "ArnLike"
        variable = "aws:SourceArn"
        values   = var.logging_source_bucket_arns
      }
    }
  }

  dynamic "statement" {
    for_each = length(var.inventory_configurations) > 0 ? [1] : []

    content {
      sid    = "AllowS3InventoryDelivery"
      effect = "Allow"

      principals {
        type        = "Service"
        identifiers = ["s3.amazonaws.com"]
      }

      actions   = ["s3:PutObject"]
      resources = ["${aws_s3_bucket.this.arn}/*"]

      condition {
        test     = "StringEquals"
        variable = "aws:SourceAccount"
        values   = [data.aws_caller_identity.current.account_id]
      }

      condition {
        test     = "ArnLike"
        variable = "aws:SourceArn"
        values   = [aws_s3_bucket.this.arn]
      }
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = data.aws_iam_policy_document.bucket.json

  depends_on = [aws_s3_bucket_public_access_block.this]
}

resource "aws_s3_bucket_notification" "this" {
  count = var.enable_eventbridge_notifications ? 1 : 0

  bucket      = aws_s3_bucket.this.id
  eventbridge = true
}

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = var.object_lock_enabled ? 1 : 0

  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode  = var.object_lock_retention.mode
      days  = var.object_lock_retention.years == null ? var.object_lock_retention.days : null
      years = var.object_lock_retention.years
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]

  lifecycle {
    precondition {
      condition     = !var.access_logging.enabled
      error_message = "Object Lock cannot be combined with server access logging on the same bucket."
    }
  }
}

###############################################################################
# Server access logging target bucket
###############################################################################

resource "aws_s3_bucket" "log_bucket" {
  bucket_prefix = "s3-access-logs-"
  force_destroy = var.force_destroy

  tags = merge(local.tags, { Name = "s3-access-logs" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "log_bucket" {
  bucket = aws_s3_bucket.log_bucket.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "log_bucket" {
  bucket = aws_s3_bucket.log_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "log_bucket" {
  bucket = aws_s3_bucket.log_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "log_bucket" {
  bucket = aws_s3_bucket.log_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "log_bucket" {
  statement {
    sid    = "AllowS3ServerAccessLoggingWrite"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logging.s3.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.log_bucket.arn}/*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = [aws_s3_bucket.this.arn]
    }
  }

  statement {
    sid    = "AllowS3ServerAccessLoggingReadAcl"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logging.s3.amazonaws.com"]
    }

    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.log_bucket.arn]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_s3_bucket_policy" "log_bucket" {
  bucket = aws_s3_bucket.log_bucket.id
  policy = data.aws_iam_policy_document.log_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.log_bucket]
}

resource "aws_s3_bucket_logging" "this" {
  count = var.access_logging.enabled ? 1 : 0

  bucket        = aws_s3_bucket.this.id
  target_bucket = aws_s3_bucket.log_bucket.id
  target_prefix = var.access_logging.target_prefix

  lifecycle {
    precondition {
      condition     = !var.object_lock_enabled
      error_message = "Server access logging cannot be combined with object locking on the same bucket."
    }
  }
}

###############################################################################
# Replication destination bucket
###############################################################################

resource "aws_s3_bucket" "replica" {
  provider = aws.replica

  bucket_prefix = "s3-replica-"
  force_destroy = var.force_destroy

  tags = merge(local.tags, { Name = "s3-replica" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "replica" {
  provider = aws.replica

  bucket = aws_s3_bucket.replica.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  provider = aws.replica

  bucket = aws_s3_bucket.replica.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  provider = aws.replica

  bucket = aws_s3_bucket.replica.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.replica.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "replica" {
  provider = aws.replica

  bucket = aws_s3_bucket.replica.id

  versioning_configuration {
    status = "Enabled"
  }
}

###############################################################################
# Cross-region replication
###############################################################################

resource "aws_s3_bucket_replication_configuration" "this" {
  count = length(var.replication_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id
  role   = aws_iam_role.replication.arn

  dynamic "rule" {
    for_each = var.replication_rules

    content {
      id       = rule.value.id
      priority = rule.value.priority
      status   = rule.value.status

      filter {
        prefix = rule.value.prefix

        dynamic "tag" {
          for_each = rule.value.tags

          content {
            key   = tag.key
            value = tag.value
          }
        }
      }

      delete_marker_replication {
        status = rule.value.delete_marker_replication_status
      }

      source_selection_criteria {
        sse_kms_encrypted_objects {
          status = "Enabled"
        }
      }

      destination {
        bucket        = aws_s3_bucket.replica.arn
        storage_class = rule.value.storage_class
        account       = data.aws_caller_identity.current.account_id

        encryption_configuration {
          replica_kms_key_id = coalesce(rule.value.replica_kms_key_id, aws_kms_key.replica.arn)
        }

        replication_time {
          status = "Enabled"

          time {
            minutes = rule.value.replication_time_minutes
          }
        }

        metrics {
          status = rule.value.metrics_status
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]

  lifecycle {
    precondition {
      condition     = var.versioning_enabled
      error_message = "versioning_enabled must be true to configure cross-region replication."
    }
  }
}

###############################################################################
# Inventory configuration
###############################################################################

resource "aws_s3_bucket_inventory" "this" {
  for_each = local.inventory_configurations

  bucket                   = aws_s3_bucket.this.id
  name                     = each.value.name
  included_object_versions = each.value.included_object_versions
  optional_fields          = each.value.optional_fields

  schedule {
    frequency = each.value.frequency
  }

  dynamic "filter" {
    for_each = each.value.prefix != null ? [each.value.prefix] : []

    content {
      prefix = filter.value
    }
  }

  destination {
    bucket {
      format     = each.value.format
      bucket_arn = aws_s3_bucket.this.arn
      prefix     = each.value.destination_prefix

      dynamic "encryption" {
        for_each = each.value.encryption_type == "sse_kms" ? [1] : []

        content {
          sse_kms {
            key_id = coalesce(each.value.kms_key_id, aws_kms_key.s3.arn)
          }
        }
      }

      dynamic "encryption" {
        for_each = each.value.encryption_type == "sse_s3" ? [1] : []

        content {
          sse_s3 {}
        }
      }
    }
  }
}

###############################################################################
# CORS configuration
###############################################################################

resource "aws_s3_bucket_cors_configuration" "this" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules

    content {
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      allowed_headers = cors_rule.value.allowed_headers
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

###############################################################################
# Lifecycle configuration
###############################################################################

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = length(var.lifecycle_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = var.lifecycle_rules

    content {
      id     = rule.value.id
      status = rule.value.status

      filter {
        prefix = rule.value.prefix

        dynamic "tag" {
          for_each = rule.value.tags

          content {
            key   = tag.key
            value = tag.value
          }
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration != null ? [rule.value.expiration] : []

        content {
          days                         = expiration.value.days
          date                         = expiration.value.date
          expired_object_delete_marker = expiration.value.expired_object_delete_marker
        }
      }

      dynamic "transition" {
        for_each = rule.value.transitions

        content {
          days          = transition.value.days
          date          = transition.value.date
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration != null ? [rule.value.noncurrent_version_expiration] : []

        content {
          noncurrent_days = noncurrent_version_expiration.value.noncurrent_days
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transitions

        content {
          noncurrent_days = noncurrent_version_transition.value.noncurrent_days
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload_days != null ? [1] : []

        content {
          days_after_initiation = rule.value.abort_incomplete_multipart_upload_days
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "group_name_prefix" {
  type        = string
  default     = "app"
  description = "Prefix used for IAM developer and admin group names."
}

variable "aws_region" {
  type        = string
  default     = "us-east-1"
  description = "Designated AWS region for S3 bucket creation and regional access controls."
}

variable "tags" {
  type = map(string)
  default = {
    ManagedBy = "Terraform"
    Stack     = "security-baseline"
  }
  description = "Common tags applied to taggable resources."
}

data "aws_caller_identity" "current" {}

locals {
  common_tags              = var.tags
  remote_state_bucket_name = "tf-remote-state-${data.aws_caller_identity.current.account_id}-${var.aws_region}"
}

resource "aws_iam_account_password_policy" "this" {
  minimum_password_length        = 12
  require_uppercase_characters   = true
  require_lowercase_characters   = true
  require_numbers                = true
  require_symbols                = true
  allow_users_to_change_password = true
  password_reuse_prevention      = 24
  max_password_age               = 90
}

resource "aws_s3_account_public_access_block" "this" {
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_kms_key" "remote_state" {
  description             = "Customer managed key for encrypting Terraform remote state objects."
  deletion_window_in_days = 30
  enable_key_rotation     = true
  key_usage               = "ENCRYPT_DECRYPT"
  customer_master_key_spec = "SYMMETRIC_DEFAULT"
  tags                    = local.common_tags
}

resource "aws_kms_alias" "remote_state" {
  name          = "alias/${var.group_name_prefix}-remote-state"
  target_key_id = aws_kms_key.remote_state.key_id
}

resource "aws_s3_bucket" "remote_state" {
  bucket = local.remote_state_bucket_name
  tags   = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "remote_state" {
  bucket = aws_s3_bucket.remote_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "remote_state" {
  bucket = aws_s3_bucket.remote_state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.remote_state.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "remote_state" {
  bucket = aws_s3_bucket.remote_state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_iam_group" "developer" {
  name = "${var.group_name_prefix}_developer"
}

resource "aws_iam_group" "admin" {
  name = "${var.group_name_prefix}_admin"
}

data "aws_iam_policy_document" "developer_self_service_access_keys" {
  statement {
    sid    = "AllowManageOwnAccessKeys"
    effect = "Allow"

    actions = [
      "iam:ListAccessKeys",
      "iam:CreateAccessKey",
      "iam:UpdateAccessKey",
      "iam:DeleteAccessKey"
    ]

    resources = [
      "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}"
    ]
  }
}

data "aws_iam_policy_document" "developer_virtual_mfa" {
  statement {
    sid    = "AllowManageOwnVirtualMFADevice"
    effect = "Allow"

    actions = [
      "iam:CreateVirtualMFADevice",
      "iam:ListVirtualMFADevices",
      "iam:EnableMFADevice",
      "iam:ResyncMFADevice"
    ]

    resources = [
      "arn:aws:iam::${data.aws_caller_identity.current.account_id}:mfa/*",
      "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}"
    ]
  }

  statement {
    sid    = "RequireMFAForMFADeviceDeactivation"
    effect = "Allow"

    actions = [
      "iam:DeactivateMFADevice",
      "iam:DeleteVirtualMFADevice"
    ]

    resources = [
      "arn:aws:iam::${data.aws_caller_identity.current.account_id}:mfa/$${aws:username}",
      "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}"
    ]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

data "aws_iam_policy_document" "developer_s3" {
  statement {
    sid    = "DenyS3CreateBucketOutsideDesignatedRegion"
    effect = "Deny"

    actions   = ["s3:CreateBucket"]
    resources = ["*"]

    condition {
      test     = "StringNotEquals"
      variable = "aws:RequestedRegion"
      values   = [var.aws_region]
    }
  }

  statement {
    sid    = "DenyRemoteStateS3AccessWithoutMFA"
    effect = "Deny"

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.remote_state.arn,
      "${aws_s3_bucket.remote_state.arn}/*"
    ]

    condition {
      test     = "BoolIfExists"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["false"]
    }
  }
}

data "aws_iam_policy_document" "developer_mfa_required_services" {
  statement {
    sid    = "DenyRegionalServicesWithoutMFA"
    effect = "Deny"

    actions = [
      "ec2:*",
      "elasticloadbalancing:*",
      "cloudwatch:*",
      "autoscaling:*"
    ]

    resources = ["*"]

    condition {
      test     = "BoolIfExists"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["false"]
    }
  }

  statement {
    sid    = "DenyPassRoleToServiceLinkedRolesWithoutMFA"
    effect = "Deny"

    actions = ["iam:PassRole"]

    resources = [
      "arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/aws-service-role/autoscaling.amazonaws.com/AWSServiceRoleForAutoScaling",
      "arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/aws-service-role/ec2.amazonaws.com/AWSServiceRoleForEC2SpotFleet"
    ]

    condition {
      test     = "BoolIfExists"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["false"]
    }
  }
}

resource "aws_iam_policy" "developer_self_service_access_keys" {
  name        = "${var.group_name_prefix}_developer_self_service_access_keys"
  description = "Allows developers to manage their own IAM access keys."
  policy      = data.aws_iam_policy_document.developer_self_service_access_keys.json
  tags        = local.common_tags
}

resource "aws_iam_group_policy_attachment" "developer_self_service_access_keys" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_self_service_access_keys.arn
}

resource "aws_iam_policy" "developer_virtual_mfa" {
  name        = "${var.group_name_prefix}_developer_virtual_mfa"
  description = "Allows developers to manage their own virtual MFA devices with MFA protection for deactivation."
  policy      = data.aws_iam_policy_document.developer_virtual_mfa.json
  tags        = local.common_tags
}

resource "aws_iam_group_policy_attachment" "developer_virtual_mfa" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_virtual_mfa.arn
}

resource "aws_iam_policy" "developer_s3" {
  name        = "${var.group_name_prefix}_developer_s3"
  description = "Restricts S3 bucket creation and protects remote state S3 access with MFA."
  policy      = data.aws_iam_policy_document.developer_s3.json
  tags        = local.common_tags
}

resource "aws_iam_group_policy_attachment" "developer_s3" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_s3.arn
}

resource "aws_iam_policy" "developer_mfa_required_services" {
  name        = "${var.group_name_prefix}_developer_mfa_required_services"
  description = "Requires MFA for EC2, ELB, CloudWatch, AutoScaling, and related service-linked role operations."
  policy      = data.aws_iam_policy_document.developer_mfa_required_services.json
  tags        = local.common_tags
}

resource "aws_iam_group_policy_attachment" "developer_mfa_required_services" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_mfa_required_services.arn
}

resource "aws_iam_group_policy_attachment" "developer_iam_read_only" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:aws:iam::aws:policy/IAMReadOnlyAccess"
}

resource "aws_iam_group_policy_attachment" "developer_change_password" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:aws:iam::aws:policy/IAMUserChangePassword"
}

resource "aws_iam_group_policy_attachment" "developer_ssh_keys" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:aws:iam::aws:policy/IAMUserSSHKeys"
}

data "aws_iam_policy_document" "admin_assume_role" {
  statement {
    sid    = "AllowAccountRootToAssumeAdminRole"
    effect = "Allow"

    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }
}

resource "aws_iam_role" "admin" {
  name                 = "admin"
  description          = "Administrative role assumable by the account root principal."
  assume_role_policy   = data.aws_iam_policy_document.admin_assume_role.json
  max_session_duration = 3600
  tags                 = local.common_tags
}

data "aws_iam_policy_document" "admin_full_access" {
  statement {
    sid    = "AllowAdministratorAccessWithMFA"
    effect = "Allow"

    actions   = ["*"]
    resources = ["*"]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "admin_full_access" {
  name        = "${var.group_name_prefix}_admin_full_access"
  description = "Grants full administrative access when MFA is present."
  policy      = data.aws_iam_policy_document.admin_full_access.json
  tags        = local.common_tags
}

resource "aws_iam_role_policy_attachment" "admin_full_access" {
  role       = aws_iam_role.admin.name
  policy_arn = aws_iam_policy.admin_full_access.arn
}

data "aws_iam_policy_document" "admin_group_assume_role" {
  statement {
    sid    = "AllowAssumeAdminRoleWithMFA"
    effect = "Allow"

    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.admin.arn]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "admin_group_assume_role" {
  name        = "${var.group_name_prefix}_admin_assume_role"
  description = "Allows admin group members to assume the admin role when MFA is present."
  policy      = data.aws_iam_policy_document.admin_group_assume_role.json
  tags        = local.common_tags
}

resource "aws_iam_group_policy_attachment" "admin_group_assume_role" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.admin_group_assume_role.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "config" {
  description = "Inline YAML document describing the data driven CI/CD orchestration framework."
  type        = string

  default = <<-YAML
    name_prefix: terrabits

    connections:
      github:
        provider_type: GitHub
      bitbucket:
        provider_type: Bitbucket

    repositories:
      app_repo:
        description: "Application source repository managed by Terraform"

    build_cache:
      expiration_days: 30

    codepipeline:
      create_default_role: true

    pipelines:
      app_pipeline:
        use_default_role: false
        role_arn: ""
        trigger:
          type: codecommit_branch
          repository: app_repo
          reference_name: main
          enabled: true
        stages:
          - name: Source
            actions:
              - name: Source
                category: Source
                owner: AWS
                provider: CodeCommit
                version: "1"
                repository: app_repo
                output_artifacts:
                  - source_output
                configuration:
                  RepositoryName: app_repo
                  BranchName: main
                  PollForSourceChanges: "false"
          - name: Build
            actions:
              - name: Build
                category: Build
                owner: AWS
                provider: CodeBuild
                version: "1"
                input_artifacts:
                  - source_output
                output_artifacts:
                  - build_output
                build:
                  compute_type: BUILD_GENERAL1_SMALL
                  image: aws/codebuild/amazonlinux2-x86_64-standard:5.0
                  buildspec: |
                    version: 0.2
                    phases:
                      install:
                        runtime-versions:
                          python: "3.12"
                      build:
                        commands:
                          - echo "Building application"
          - name: Approval
            actions:
              - name: ManualApproval
                category: Approval
                owner: AWS
                provider: Manual
                version: "1"
                configuration:
                  CustomData: "Please review and approve this release"
          - name: Notify
            actions:
              - name: Notify
                category: Invoke
                owner: AWS
                provider: Lambda
                version: "1"
                input_artifacts:
                  - build_output
                lambda:
                  runtime: python3.12
                  handler: index.handler
                  code: |
                    import json

                    def handler(event, context):
                        print(json.dumps(event))
                        return {"statusCode": 200}

      web_pipeline:
        use_default_role: true
        role_arn: ""
        trigger:
          type: schedule
          schedule_expression: "cron(0 12 * * ? *)"
          enabled: true
        stages:
          - name: Source
            actions:
              - name: Source
                category: Source
                owner: AWS
                provider: CodeStarSourceConnection
                version: "1"
                connection: github
                output_artifacts:
                  - source_output
                configuration:
                  FullRepositoryId: example-org/web-app
                  BranchName: main
          - name: Build
            actions:
              - name: Build
                category: Build
                owner: AWS
                provider: CodeBuild
                version: "1"
                input_artifacts:
                  - source_output
                output_artifacts:
                  - build_output
                build:
                  compute_type: BUILD_GENERAL1_SMALL
                  image: aws/codebuild/amazonlinux2-x86_64-standard:5.0
                  buildspec: |
                    version: 0.2
                    phases:
                      build:
                        commands:
                          - echo "Building web application"

      release_pipeline:
        use_default_role: false
        role_arn: ""
        trigger:
          type: codecommit_tag
          repository: app_repo
          reference_name: release
          enabled: true
        stages:
          - name: Source
            actions:
              - name: Source
                category: Source
                owner: AWS
                provider: CodeCommit
                version: "1"
                repository: app_repo
                output_artifacts:
                  - source_output
                configuration:
                  RepositoryName: app_repo
                  BranchName: main
                  PollForSourceChanges: "false"
          - name: Build
            actions:
              - name: Build
                category: Build
                owner: AWS
                provider: CodeBuild
                version: "1"
                input_artifacts:
                  - source_output
                output_artifacts:
                  - build_output
                build:
                  compute_type: BUILD_GENERAL1_SMALL
                  image: aws/codebuild/amazonlinux2-x86_64-standard:5.0
                  buildspec: |
                    version: 0.2
                    phases:
                      build:
                        commands:
                          - echo "Packaging release"
    YAML
}

variable "tags" {
  description = "Tags applied to every taggable resource created by this configuration."
  type        = map(string)

  default = {
    Project = "terraforest"
  }
}

###############################################################################
# Provider metadata (static lookups only)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

###############################################################################
# Parsed configuration and derived maps
###############################################################################

locals {
  cfg = yamldecode(var.config)

  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
  partition  = data.aws_partition.current.partition

  name_prefix = try(local.cfg.name_prefix, "terrabits")

  create_default_codepipeline_role = try(local.cfg.codepipeline.create_default_role, true)
  build_cache_expiration_days      = try(local.cfg.build_cache.expiration_days, 30)

  repositories = {
    for name, repository in try(local.cfg.repositories, {}) : name => {
      description = try(repository.description, "Source repository managed by Terraform")
    }
  }

  connections = {
    for name, connection in try(local.cfg.connections, {}) : name => {
      provider_type = connection.provider_type
    }
  }

  pipelines = {
    for name, pipeline in try(local.cfg.pipelines, {}) : name => {
      role_arn         = try(pipeline.role_arn, "")
      use_default_role = try(pipeline.use_default_role, false)
      stages           = try(pipeline.stages, [])
      trigger = merge(
        {
          type                = "none"
          enabled             = true
          repository          = ""
          reference_name      = ""
          schedule_expression = ""
          event_pattern       = {}
        },
        try(pipeline.trigger, {}),
      )
    }
  }

  pipeline_names = {
    for name, pipeline in local.pipelines : name => "${local.name_prefix}-${name}"
  }

  # Constructed ARNs are required inside role policies because the pipeline
  # itself consumes those roles (using aws_codepipeline.*.arn would be cyclic).
  pipeline_arns = {
    for name, pipeline in local.pipelines : name => format(
      "arn:%s:codepipeline:%s:%s:%s",
      local.partition,
      local.region,
      local.account_id,
      local.pipeline_names[name],
    )
  }

  stages = merge([
    for name, pipeline in local.pipelines : {
      for stage in pipeline.stages : "${name}/${stage.name}" => {
        pipeline = name
        name     = stage.name
        actions  = try(stage.actions, [])
      }
    }
  ]...)

  actions = merge([
    for stage_key, stage in local.stages : {
      for action in stage.actions : "${stage_key}/${action.name}" => {
        pipeline         = stage.pipeline
        stage            = stage.name
        name             = action.name
        category         = action.category
        owner            = try(action.owner, "AWS")
        provider         = action.provider
        version          = tostring(try(action.version, "1"))
        run_order        = try(action.run_order, null)
        input_artifacts  = try(action.input_artifacts, [])
        output_artifacts = try(action.output_artifacts, [])
        configuration    = try(action.configuration, {})
        build            = try(action.build, {})
        lambda           = try(action.lambda, {})
        connection       = try(action.connection, "")
        repository       = try(action.repository, "")
        ecr_repository   = try(action.ecr_repository, "")
      }
    }
  ]...)

  codebuild_actions = {
    for key, action in local.actions : key => action if action.provider == "CodeBuild"
  }

  lambda_actions = {
    for key, action in local.actions : key => action if action.provider == "Lambda"
  }

  ecr_repository_arns = distinct([
    for key, action in local.actions :
    format(
      "arn:%s:ecr:%s:%s:repository/%s",
      local.partition,
      local.region,
      local.account_id,
      action.ecr_repository,
    )
    if action.ecr_repository != ""
  ])

  # ---------------------------------------------------------------------------
  # IAM role ARNs constructed from deterministic names.
  # Derived purely from naming so the artifact bucket policy does not have to
  # wait on the IAM role graph to finish.
  # ---------------------------------------------------------------------------
  iam_role_arn_prefix = "arn:${local.partition}:iam::${local.account_id}:role/terraforest"

  codepipeline_default_role_arn = "${local.iam_role_arn_prefix}/${local.name_prefix}-codepipeline-default"

  pipeline_role_arns = {
    for name, pipeline in local.pipelines : name => "${local.iam_role_arn_prefix}/${local.pipeline_names[name]}-role"
  }

  codebuild_role_arns = {
    for key, action in local.codebuild_actions : key => "${local.iam_role_arn_prefix}/${local.name_prefix}-${replace(key, "/", "-")}-codebuild"
  }

  artifact_bucket_policy_principals = distinct(concat(
    local.create_default_codepipeline_role ? [local.codepipeline_default_role_arn] : [],
    [for name, pipeline in local.pipelines : local.pipeline_role_arns[name]],
    [for key, action in local.codebuild_actions : local.codebuild_role_arns[key]],
  ))

  # Resource derived maps (safe to use with lookup() so no invalid index errors)
  repository_arns = {
    for name, repo in aws_codecommit_repository.repository : name => repo.arn
  }

  repository_names = {
    for name, repo in aws_codecommit_repository.repository : name => repo.repository_name
  }

  connection_arns = {
    for name, conn in aws_codestarconnections_connection.connection : name => conn.arn
  }

  codebuild_project_arns = {
    for key, project in aws_codebuild_project.build : key => project.arn
  }

  codebuild_project_names = {
    for key, project in aws_codebuild_project.build : key => project.name
  }

  lambda_function_arns = {
    for key, function in aws_lambda_function.invoke : key => function.arn
  }

  lambda_function_names = {
    for key, function in aws_lambda_function.invoke : key => function.function_name
  }

  # Per pipeline scoped resource collections
  pipeline_repository_arns = {
    for name, pipeline in local.pipelines : name => distinct(compact([
      for key, action in local.actions : lookup(local.repository_arns, action.repository, "")
      if action.pipeline == name && action.repository != ""
    ]))
  }

  pipeline_codebuild_arns = {
    for name, pipeline in local.pipelines : name => distinct(compact([
      for key, action in local.codebuild_actions : lookup(local.codebuild_project_arns, key, "")
      if action.pipeline == name
    ]))
  }

  pipeline_lambda_arns = {
    for name, pipeline in local.pipelines : name => distinct(compact([
      for key, action in local.lambda_actions : lookup(local.lambda_function_arns, key, "")
      if action.pipeline == name
    ]))
  }

  pipeline_connection_arns = {
    for name, pipeline in local.pipelines : name => distinct(compact([
      for key, action in local.actions : lookup(local.connection_arns, action.connection, "")
      if action.pipeline == name && action.connection != ""
    ]))
  }

  pipeline_ecr_repository_arns = {
    for name, pipeline in local.pipelines : name => distinct([
      for key, action in local.actions :
      format(
        "arn:%s:ecr:%s:%s:repository/%s",
        local.partition,
        local.region,
        local.account_id,
        action.ecr_repository,
      )
      if action.pipeline == name && action.ecr_repository != ""
    ])
  }

  # Account wide collections used by the shared default CodePipeline role
  all_repository_arns = [for key, repo in aws_codecommit_repository.repository : repo.arn]
  all_codebuild_arns  = [for key, project in aws_codebuild_project.build : project.arn]
  all_lambda_arns     = [for key, function in aws_lambda_function.invoke : function.arn]
  all_connection_arns = [for key, conn in aws_codestarconnections_connection.connection : conn.arn]
  all_pipeline_arns   = [for name, pipeline in local.pipelines : local.pipeline_arns[name]]

  # EventBridge trigger descriptions (one per pipeline that enables a trigger)
  pipeline_event_configs = {
    for name, pipeline in local.pipelines : name => {
      schedule_expression = pipeline.trigger.type == "schedule" ? pipeline.trigger.schedule_expression : null

      event_pattern = (
        pipeline.trigger.type == "schedule" ? null :
        pipeline.trigger.type == "custom" ? jsonencode(try(pipeline.trigger.event_pattern, {})) :
        pipeline.trigger.type == "codecommit_branch" || pipeline.trigger.type == "codecommit_tag" ? jsonencode({
          source      = ["aws.codecommit"]
          detail-type = ["CodeCommit Repository State Change"]
          resources   = [lookup(local.repository_arns, pipeline.trigger.repository, "")]
          detail = {
            event         = ["referenceCreated", "referenceUpdated"]
            referenceType = [pipeline.trigger.type == "codecommit_tag" ? "tag" : "branch"]
            referenceName = [pipeline.trigger.reference_name]
          }
        }) : null
      )
    }
    if pipeline.trigger.enabled && pipeline.trigger.type != "none"
  }

  # Runtime helpers for inline Lambda actions
  lambda_runtimes = {
    for key, action in local.lambda_actions : key => lookup(action.lambda, "runtime", "python3.12")
  }

  lambda_default_code = {
    "python3.12" = <<-PY
      import json

      def handler(event, context):
          print(json.dumps(event))
          return {"statusCode": 200}
      PY
    "nodejs22.x" = <<-JS
      exports.handler = async (event) => {
        console.log(JSON.stringify(event));
        return { statusCode: 200 };
      };
      JS
  }
}

###############################################################################
# Customer managed key for pipeline artifacts and the CodeBuild cache.
# The key policy explicitly authorizes the S3 service principal to use the key
# so S3 SSE validation calls are not denied, and grants the account principal
# key administration.
###############################################################################

data "aws_iam_policy_document" "pipeline_artifacts_key" {
  statement {
    sid    = "EnableAccountKeyAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions = [
      "kms:Create*",
      "kms:Describe*",
      "kms:Enable*",
      "kms:List*",
      "kms:Put*",
      "kms:Update*",
      "kms:Revoke*",
      "kms:Disable*",
      "kms:Get*",
      "kms:Delete*",
      "kms:TagResource",
      "kms:UntagResource",
      "kms:ScheduleKeyDeletion",
      "kms:CancelKeyDeletion",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowAccountKeyUsage"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions = [
      "kms:Decrypt",
      "kms:Encrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowS3ServiceUse"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:DescribeKey",
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key" "pipeline_artifacts" {
  description             = "Customer managed key for ${local.name_prefix} CodePipeline artifacts and CodeBuild cache"
  deletion_window_in_days = 7
  policy                  = data.aws_iam_policy_document.pipeline_artifacts_key.json
}

###############################################################################
# Artifact bucket (SSE-KMS using the customer managed key)
###############################################################################

resource "aws_s3_bucket" "artifacts" {
  bucket = "${local.name_prefix}-${local.account_id}-${local.region}-artifacts"
  tags   = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.pipeline_artifacts.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "artifacts_bucket_policy" {
  statement {
    sid    = "AllowCodePipelineArtifactAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = local.artifact_bucket_policy_principals
    }

    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:ListBucket",
      "s3:GetBucketLocation",
    ]

    resources = [
      aws_s3_bucket.artifacts.arn,
      "${aws_s3_bucket.artifacts.arn}/*",
    ]
  }

  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.artifacts.arn,
      "${aws_s3_bucket.artifacts.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id
  policy = data.aws_iam_policy_document.artifacts_bucket_policy.json

  depends_on = [aws_s3_bucket_public_access_block.artifacts]
}

###############################################################################
# Build cache bucket (SSE-KMS using the customer managed key)
###############################################################################

resource "aws_s3_bucket" "build_cache" {
  bucket = "${local.name_prefix}-${local.account_id}-${local.region}-build-cache"
  tags   = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "build_cache" {
  bucket = aws_s3_bucket.build_cache.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "build_cache" {
  bucket = aws_s3_bucket.build_cache.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.pipeline_artifacts.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "build_cache" {
  bucket = aws_s3_bucket.build_cache.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "build_cache" {
  bucket = aws_s3_bucket.build_cache.id

  rule {
    id     = "expire-build-cache"
    status = "Enabled"

    filter {
      prefix = ""
    }

    expiration {
      days = local.build_cache_expiration_days
    }

    noncurrent_version_expiration {
      noncurrent_days = 7
    }
  }
}

data "aws_iam_policy_document" "build_cache_bucket_policy" {
  statement {
    sid    = "AllowCodeBuildCacheAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [for key, action in local.codebuild_actions : local.codebuild_role_arns[key]]
    }

    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:ListBucket",
      "s3:GetBucketLocation",
    ]

    resources = [
      aws_s3_bucket.build_cache.arn,
      "${aws_s3_bucket.build_cache.arn}/*",
    ]
  }

  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.build_cache.arn,
      "${aws_s3_bucket.build_cache.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "build_cache" {
  bucket = aws_s3_bucket.build_cache.id
  policy = data.aws_iam_policy_document.build_cache_bucket_policy.json

  depends_on = [aws_s3_bucket_public_access_block.build_cache]
}

###############################################################################
# CodeCommit repositories
###############################################################################

resource "aws_codecommit_repository" "repository" {
  for_each = local.repositories

  repository_name = each.key
  description     = each.value.description

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# CodeStar connections (Bitbucket / GitHub)
###############################################################################

resource "aws_codestarconnections_connection" "connection" {
  for_each = local.connections

  name          = "${local.name_prefix}-${each.key}-connection"
  provider_type = each.value.provider_type

  tags = var.tags
}

###############################################################################
# Assume role policies
###############################################################################

data "aws_iam_policy_document" "codepipeline_assume_role" {
  statement {
    sid     = "AllowCodePipelineServiceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["codepipeline.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "codebuild_assume_role" {
  statement {
    sid     = "AllowCodeBuildServiceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["codebuild.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    sid     = "AllowLambdaServiceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "eventbridge_assume_role" {
  statement {
    sid     = "AllowEventBridgeServiceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }
  }
}

###############################################################################
# Default (shared) CodePipeline role
###############################################################################

resource "aws_iam_role" "codepipeline_default" {
  count = local.create_default_codepipeline_role ? 1 : 0

  name               = "${local.name_prefix}-codepipeline-default"
  description        = "Shared default CodePipeline execution role"
  path               = "/terraforest/"
  assume_role_policy = data.aws_iam_policy_document.codepipeline_assume_role.json

  tags = var.tags
}

data "aws_iam_policy_document" "codepipeline_default_policy" {
  statement {
    sid    = "ArtifactStoreAccess"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:ListBucket",
      "s3:GetBucketLocation",
    ]

    resources = [
      aws_s3_bucket.artifacts.arn,
      "${aws_s3_bucket.artifacts.arn}/*",
    ]
  }

  statement {
    sid    = "ArtifactStoreEncryption"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]

    resources = [aws_kms_key.pipeline_artifacts.arn]
  }

  statement {
    sid       = "StartPipelineExecution"
    effect    = "Allow"
    actions   = ["codepipeline:StartPipelineExecution"]
    resources = local.all_pipeline_arns
  }

  dynamic "statement" {
    for_each = length(local.all_repository_arns) > 0 ? [local.all_repository_arns] : []

    content {
      sid    = "CodeCommitSourceAccess"
      effect = "Allow"

      actions = [
        "codecommit:GetBranch",
        "codecommit:GetCommit",
        "codecommit:GetRepository",
        "codecommit:UploadArchive",
        "codecommit:GetUploadArchiveStatus",
        "codecommit:CancelUploadArchive",
      ]

      resources = statement.value
    }
  }

  dynamic "statement" {
    for_each = length(local.all_codebuild_arns) > 0 ? [local.all_codebuild_arns] : []

    content {
      sid    = "CodeBuildActionAccess"
      effect = "Allow"

      actions = [
        "codebuild:BatchGetBuilds",
        "codebuild:StartBuild",
        "codebuild:StopBuild",
        "codebuild:BatchGetBuildBatches",
        "codebuild:StartBuildBatch",
        "codebuild:StopBuildBatch",
      ]

      resources = statement.value
    }
  }

  dynamic "statement" {
    for_each = length(local.all_lambda_arns) > 0 ? [local.all_lambda_arns] : []

    content {
      sid       = "LambdaInvokeAccess"
      effect    = "Allow"
      actions   = ["lambda:InvokeFunction"]
      resources = statement.value
    }
  }

  dynamic "statement" {
    for_each = length(local.all_connection_arns) > 0 ? [local.all_connection_arns] : []

    content {
      sid       = "CodeStarConnectionAccess"
      effect    = "Allow"
      actions   = ["codestar-connections:UseConnection"]
      resources = statement.value
    }
  }

  dynamic "statement" {
    for_each = length(local.ecr_repository_arns) > 0 ? [local.ecr_repository_arns] : []

    content {
      sid    = "EcrSourceAccess"
      effect = "Allow"

      actions = [
        "ecr:GetAuthorizationToken",
        "ecr:BatchCheckLayerAvailability",
        "ecr:GetDownloadUrlForLayer",
        "ecr:BatchGetImage",
        "ecr:DescribeImages",
      ]

      resources = concat(["*"], statement.value)
    }
  }
}

resource "aws_iam_role_policy" "codepipeline_default" {
  count = local.create_default_codepipeline_role ? 1 : 0

  name   = "codepipeline-default-permissions"
  role   = aws_iam_role.codepipeline_default[0].id
  policy = data.aws_iam_policy_document.codepipeline_default_policy.json
}

###############################################################################
# Per pipeline CodePipeline roles
###############################################################################

resource "aws_iam_role" "pipeline" {
  for_each = local.pipelines

  name               = "${local.pipeline_names[each.key]}-role"
  description        = "Execution role for the ${each.key} CodePipeline pipeline"
  path               = "/terraforest/"
  assume_role_policy = data.aws_iam_policy_document.codepipeline_assume_role.json

  tags = var.tags
}

data "aws_iam_policy_document" "pipeline_policy" {
  for_each = local.pipelines

  statement {
    sid    = "ArtifactStoreAccess"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:ListBucket",
      "s3:GetBucketLocation",
    ]

    resources = [
      aws_s3_bucket.artifacts.arn,
      "${aws_s3_bucket.artifacts.arn}/*",
    ]
  }

  statement {
    sid    = "ArtifactStoreEncryption"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]

    resources = [aws_kms_key.pipeline_artifacts.arn]
  }

  statement {
    sid       = "StartOwnPipelineExecution"
    effect    = "Allow"
    actions   = ["codepipeline:StartPipelineExecution"]
    resources = [local.pipeline_arns[each.key]]
  }

  dynamic "statement" {
    for_each = length(local.pipeline_repository_arns[each.key]) > 0 ? [local.pipeline_repository_arns[each.key]] : []

    content {
      sid    = "CodeCommitSourceAccess"
      effect = "Allow"

      actions = [
        "codecommit:GetBranch",
        "codecommit:GetCommit",
        "codecommit:GetRepository",
        "codecommit:UploadArchive",
        "codecommit:GetUploadArchiveStatus",
        "codecommit:CancelUploadArchive",
      ]

      resources = statement.value
    }
  }

  dynamic "statement" {
    for_each = length(local.pipeline_codebuild_arns[each.key]) > 0 ? [local.pipeline_codebuild_arns[each.key]] : []

    content {
      sid    = "CodeBuildActionAccess"
      effect = "Allow"

      actions = [
        "codebuild:BatchGetBuilds",
        "codebuild:StartBuild",
        "codebuild:StopBuild",
        "codebuild:BatchGetBuildBatches",
        "codebuild:StartBuildBatch",
        "codebuild:StopBuildBatch",
      ]

      resources = statement.value
    }
  }

  dynamic "statement" {
    for_each = length(local.pipeline_lambda_arns[each.key]) > 0 ? [local.pipeline_lambda_arns[each.key]] : []

    content {
      sid       = "LambdaInvokeAccess"
      effect    = "Allow"
      actions   = ["lambda:InvokeFunction"]
      resources = statement.value
    }
  }

  dynamic "statement" {
    for_each = length(local.pipeline_connection_arns[each.key]) > 0 ? [local.pipeline_connection_arns[each.key]] : []

    content {
      sid       = "CodeStarConnectionAccess"
      effect    = "Allow"
      actions   = ["codestar-connections:UseConnection"]
      resources = statement.value
    }
  }

  dynamic "statement" {
    for_each = length(local.pipeline_ecr_repository_arns[each.key]) > 0 ? [local.pipeline_ecr_repository_arns[each.key]] : []

    content {
      sid    = "EcrSourceAccess"
      effect = "Allow"

      actions = [
        "ecr:GetAuthorizationToken",
        "ecr:BatchCheckLayerAvailability",
        "ecr:GetDownloadUrlForLayer",
        "ecr:BatchGetImage",
        "ecr:DescribeImages",
      ]

      resources = concat(["*"], statement.value)
    }
  }
}

resource "aws_iam_role_policy" "pipeline" {
  for_each = local.pipelines

  name   = "pipeline-execution-permissions"
  role   = aws_iam_role.pipeline[each.key].id
  policy = data.aws_iam_policy_document.pipeline_policy[each.key].json
}

###############################################################################
# CodeBuild projects (inline, not external modules)
###############################################################################

resource "aws_iam_role" "codebuild" {
  for_each = local.codebuild_actions

  name               = "${local.name_prefix}-${replace(each.key, "/", "-")}-codebuild"
  description        = "CodeBuild service role for ${each.key}"
  path               = "/terraforest/"
  assume_role_policy = data.aws_iam_policy_document.codebuild_assume_role.json

  tags = var.tags
}

data "aws_iam_policy_document" "codebuild_policy" {
  for_each = local.codebuild_actions

  statement {
    sid    = "ArtifactAndCacheAccess"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:ListBucket",
      "s3:GetBucketLocation",
    ]

    resources = [
      aws_s3_bucket.artifacts.arn,
      "${aws_s3_bucket.artifacts.arn}/*",
      aws_s3_bucket.build_cache.arn,
      "${aws_s3_bucket.build_cache.arn}/*",
    ]
  }

  statement {
    sid    = "ArtifactAndCacheEncryption"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]

    resources = [aws_kms_key.pipeline_artifacts.arn]
  }

  statement {
    sid    = "LogGroupAccess"
    effect = "Allow"

    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = [
      "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:/aws/codebuild/*",
      "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:/aws/codebuild/*:*",
    ]
  }
}

resource "aws_iam_role_policy" "codebuild" {
  for_each = local.codebuild_actions

  name   = "codebuild-permissions"
  role   = aws_iam_role.codebuild[each.key].id
  policy = data.aws_iam_policy_document.codebuild_policy[each.key].json
}

resource "aws_codebuild_project" "build" {
  for_each = local.codebuild_actions

  name          = "${local.name_prefix}-${replace(each.key, "/", "-")}-project"
  description   = "CodeBuild project backing the ${each.key} pipeline action"
  service_role  = aws_iam_role.codebuild[each.key].arn
  build_timeout = 60

  artifacts {
    type = "CODEPIPELINE"
  }

  environment {
    compute_type    = lookup(each.value.build, "compute_type", "BUILD_GENERAL1_SMALL")
    image           = lookup(each.value.build, "image", "aws/codebuild/amazonlinux2-x86_64-standard:5.0")
    type            = "LINUX_CONTAINER"
    privileged_mode = false
  }

  source {
    type      = "CODEPIPELINE"
    buildspec = lookup(each.value.build, "buildspec", null)
  }

  cache {
    type     = "S3"
    location = aws_s3_bucket.build_cache.bucket
  }

  tags = var.tags
}

###############################################################################
# Lambda functions (inline invoke actions, not external modules)
###############################################################################

data "archive_file" "lambda_code" {
  for_each = local.lambda_actions

  type        = "zip"
  output_path = "${path.module}/lambda-${replace(each.key, "/", "-")}.zip"

  source {
    filename = startswith(local.lambda_runtimes[each.key], "nodejs") ? "index.mjs" : "index.py"
    content = lookup(
      each.value.lambda,
      "code",
      lookup(local.lambda_default_code, local.lambda_runtimes[each.key], local.lambda_default_code["python3.12"]),
    )
  }
}

resource "aws_iam_role" "lambda" {
  for_each = local.lambda_actions

  name               = "${local.name_prefix}-${replace(each.key, "/", "-")}-lambda"
  description        = "Lambda execution role for ${each.key}"
  path               = "/terraforest/"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json

  tags = var.tags
}

data "aws_iam_policy_document" "lambda_policy" {
  for_each = local.lambda_actions

  statement {
    sid    = "LogGroupAccess"
    effect = "Allow"

    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = [
      "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:/aws/lambda/*",
      "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:/aws/lambda/*:*",
    ]
  }
}

resource "aws_iam_role_policy" "lambda" {
  for_each = local.lambda_actions

  name   = "lambda-permissions"
  role   = aws_iam_role.lambda[each.key].id
  policy = data.aws_iam_policy_document.lambda_policy[each.key].json
}

resource "aws_lambda_function" "invoke" {
  for_each = local.lambda_actions

  function_name    = "${local.name_prefix}-${replace(each.key, "/", "-")}-function"
  description      = "CodePipeline invoke action backing ${each.key}"
  role             = aws_iam_role.lambda[each.key].arn
  handler          = lookup(each.value.lambda, "handler", "index.handler")
  runtime          = local.lambda_runtimes[each.key]
  filename         = data.archive_file.lambda_code[each.key].output_path
  source_code_hash = data.archive_file.lambda_code[each.key].output_base64sha256
  timeout          = lookup(each.value.lambda, "timeout", 30)
  memory_size      = lookup(each.value.lambda, "memory_size", 128)

  timeouts {
    create = "10m"
    update = "10m"
    delete = "10m"
  }

  tags = var.tags
}

resource "aws_lambda_permission" "codepipeline" {
  for_each = local.lambda_actions

  statement_id  = "AllowExecutionFromCodePipeline"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.invoke[each.key].function_name
  principal     = "codepipeline.amazonaws.com"
  source_arn    = local.pipeline_arns[each.value.pipeline]
}

###############################################################################
# Pipelines
###############################################################################

resource "aws_codepipeline" "pipeline" {
  for_each = local.pipelines

  name = local.pipeline_names[each.key]

  role_arn = (
    each.value.role_arn != "" ? each.value.role_arn :
    each.value.use_default_role && local.create_default_codepipeline_role ?
      one(aws_iam_role.codepipeline_default[*].arn) :
      aws_iam_role.pipeline[each.key].arn
  )

  artifact_store {
    location = aws_s3_bucket.artifacts.bucket
    type     = "S3"

    encryption_key {
      id   = aws_kms_key.pipeline_artifacts.arn
      type = "KMS"
    }
  }

  dynamic "stage" {
    for_each = each.value.stages

    content {
      name = stage.value.name

      dynamic "action" {
        for_each = try(stage.value.actions, [])

        content {
          name             = action.value.name
          category         = action.value.category
          owner            = try(action.value.owner, "AWS")
          provider         = action.value.provider
          version          = tostring(try(action.value.version, "1"))
          run_order        = try(action.value.run_order, null)
          input_artifacts  = try(action.value.input_artifacts, [])
          output_artifacts = try(action.value.output_artifacts, [])

          configuration = merge(
            { for key, value in try(action.value.configuration, {}) : key => tostring(value) },

            action.value.provider == "CodeCommit" && try(action.value.repository, "") != "" ? {
              RepositoryName = lookup(
                local.repository_names,
                action.value.repository,
                action.value.repository,
              )
            } : {},

            action.value.provider == "CodeStarSourceConnection" && try(action.value.connection, "") != "" ? {
              ConnectionArn = lookup(local.connection_arns, action.value.connection, "")
            } : {},

            action.value.provider == "CodeBuild" ? {
              ProjectName = lookup(
                local.codebuild_project_names,
                "${each.key}/${stage.value.name}/${action.value.name}",
                "",
              )
            } : {},

            action.value.provider == "Lambda" ? {
              FunctionName = lookup(
                local.lambda_function_names,
                "${each.key}/${stage.value.name}/${action.value.name}",
                "",
              )
              UserParameters = lookup(try(action.value.configuration, {}), "UserParameters", "{}")
            } : {},
          )
        }
      }
    }
  }

  tags = var.tags
}

###############################################################################
# EventBridge triggers
###############################################################################

resource "aws_iam_role" "eventbridge_trigger" {
  for_each = local.pipeline_event_configs

  name               = "${local.name_prefix}-${each.key}"
  description        = "EventBridge role allowed to start the ${each.key} pipeline"
  path               = "/terraforest/"
  assume_role_policy = data.aws_iam_policy_document.eventbridge_assume_role.json

  tags = var.tags
}

data "aws_iam_policy_document" "eventbridge_policy" {
  for_each = local.pipeline_event_configs

  statement {
    sid       = "StartPipelineExecution"
    effect    = "Allow"
    actions   = ["codepipeline:StartPipelineExecution"]
    resources = [aws_codepipeline.pipeline[each.key].arn]
  }
}

resource "aws_iam_role_policy" "eventbridge_trigger" {
  for_each = local.pipeline_event_configs

  name   = "eventbridge-trigger-permissions"
  role   = aws_iam_role.eventbridge_trigger[each.key].id
  policy = data.aws_iam_policy_document.eventbridge_policy[each.key].json
}

resource "aws_cloudwatch_event_rule" "pipeline_trigger" {
  for_each = local.pipeline_event_configs

  name                = "${local.name_prefix}-${each.key}-trigger"
  description         = "Trigger rule for the ${each.key} CodePipeline pipeline"
  schedule_expression = each.value.schedule_expression
  event_pattern       = each.value.event_pattern

  tags = var.tags
}

resource "aws_cloudwatch_event_target" "pipeline_trigger" {
  for_each = local.pipeline_event_configs

  rule      = aws_cloudwatch_event_rule.pipeline_trigger[each.key].name
  target_id = "${local.name_prefix}-${each.key}"
  arn       = aws_codepipeline.pipeline[each.key].arn
  role_arn  = aws_iam_role.eventbridge_trigger[each.key].arn
}

###############################################################################
# Outputs
###############################################################################

output "pipeline_names" {
  description = "Map of pipeline key to CodePipeline name."
  value       = { for key, pipeline in aws_codepipeline.pipeline : key => pipeline.name }
}

output "pipeline_arns" {
  description = "Map of pipeline key to CodePipeline ARN."
  value       = { for key, pipeline in aws_codepipeline.pipeline : key => pipeline.arn }
}

output "codestar_connection_arns" {
  description = "Map of connection key to CodeStar connection ARN."
  value       = { for key, conn in aws_codestarconnections_connection.connection : key => conn.arn }
}

output "codecommit_repository_arns" {
  description = "Map of repository key to CodeCommit repository ARN."
  value       = { for key, repo in aws_codecommit_repository.repository : key => repo.arn }
}

output "artifact_bucket_name" {
  description = "Name of the CodePipeline artifact bucket."
  value       = aws_s3_bucket.artifacts.bucket
}

output "artifact_bucket_arn" {
  description = "ARN of the CodePipeline artifact bucket."
  value       = aws_s3_bucket.artifacts.arn
}

output "build_cache_bucket_name" {
  description = "Name of the CodeBuild cache bucket."
  value       = aws_s3_bucket.build_cache.bucket
}

output "build_cache_bucket_arn" {
  description = "ARN of the CodeBuild cache bucket."
  value       = aws_s3_bucket.build_cache.arn
}

output "artifact_kms_key_arn" {
  description = "ARN of the customer managed KMS key used for pipeline artifacts and the build cache."
  value       = aws_kms_key.pipeline_artifacts.arn
}

terraform {
  required_version = ">= 1.4.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Module controls
###############################################################################

variable "create" {
  description = "Master toggle. When false, the module creates nothing."
  type        = bool
  default     = true
}

variable "create_new" {
  description = "When true, create a new security group. When false, manage rules on existing_security_group_id."
  type        = bool
  default     = true
}

variable "vpc_id" {
  description = "Target VPC ID. When empty, a new VPC is created and used."
  type        = string
  default     = ""
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC created when vpc_id is empty."
  type        = string
  default     = "10.0.0.0/16"
}

variable "existing_security_group_id" {
  description = "Existing security group ID to attach rules to when create_new is false."
  type        = string
  default     = ""
}

variable "create_before_destroy" {
  description = "Toggle for the create-before-destroy lifecycle on the newly created security group."
  type        = bool
  default     = true
}

variable "revoke_rules_on_delete" {
  description = "Revoke all ingress and egress rules when the created security group is deleted."
  type        = bool
  default     = false
}

variable "name" {
  description = "Explicit name for the new security group. Takes precedence over name_prefix."
  type        = string
  default     = ""
}

variable "name_prefix" {
  description = "Name prefix for the new security group (used only when name is empty)."
  type        = string
  default     = ""
}

variable "description" {
  description = "Description for the new security group."
  type        = string
  default     = "Security group managed by Terraform"
}

variable "tags" {
  description = "Tags applied to all created resources."
  type        = map(string)
  default     = {}
}

###############################################################################
# Rule inputs (new security group path)
###############################################################################

variable "new_ingress_rules" {
  description = "Ingress rules for the newly created security group. Empty by default (no inbound exposure)."
  type = list(object({
    cidr_ipv4                    = optional(string)
    cidr_ipv6                    = optional(string)
    referenced_security_group_id = optional(string)
    prefix_list_id               = optional(string)
    ip_protocol                  = string
    from_port                    = optional(number)
    to_port                      = optional(number)
    description                  = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for r in var.new_ingress_rules : length(compact([
        r.cidr_ipv4 != null ? r.cidr_ipv4 : "",
        r.cidr_ipv6 != null ? r.cidr_ipv6 : "",
        r.referenced_security_group_id != null ? r.referenced_security_group_id : "",
        r.prefix_list_id != null ? r.prefix_list_id : "",
      ])) == 1
    ])
    error_message = "Each ingress rule must set exactly one of: cidr_ipv4, cidr_ipv6, referenced_security_group_id, prefix_list_id."
  }

  validation {
    condition = alltrue([
      for r in var.new_ingress_rules : r.ip_protocol == "-1" || (r.from_port != null && r.to_port != null)
    ])
    error_message = "from_port and to_port are required unless ip_protocol is \"-1\"."
  }
}

variable "new_egress_rules" {
  description = "Egress rules for the newly created security group. Defaults to allowing all outbound IPv4 traffic."
  type = list(object({
    cidr_ipv4                    = optional(string)
    cidr_ipv6                    = optional(string)
    referenced_security_group_id = optional(string)
    prefix_list_id               = optional(string)
    ip_protocol                  = string
    from_port                    = optional(number)
    to_port                      = optional(number)
    description                  = optional(string)
  }))
  default = [
    {
      cidr_ipv4   = "0.0.0.0/0"
      ip_protocol = "-1"
      description = "Allow all outbound IPv4 traffic"
    }
  ]

  validation {
    condition = alltrue([
      for r in var.new_egress_rules : length(compact([
        r.cidr_ipv4 != null ? r.cidr_ipv4 : "",
        r.cidr_ipv6 != null ? r.cidr_ipv6 : "",
        r.referenced_security_group_id != null ? r.referenced_security_group_id : "",
        r.prefix_list_id != null ? r.prefix_list_id : "",
      ])) == 1
    ])
    error_message = "Each egress rule must set exactly one of: cidr_ipv4, cidr_ipv6, referenced_security_group_id, prefix_list_id."
  }

  validation {
    condition = alltrue([
      for r in var.new_egress_rules : r.ip_protocol == "-1" || (r.from_port != null && r.to_port != null)
    ])
    error_message = "from_port and to_port are required unless ip_protocol is \"-1\"."
  }
}

###############################################################################
# Rule inputs (existing security group path)
###############################################################################

variable "existing_ingress_rules" {
  description = "Ingress rules to attach to existing_security_group_id. Empty by default."
  type = list(object({
    cidr_ipv4                    = optional(string)
    cidr_ipv6                    = optional(string)
    referenced_security_group_id = optional(string)
    prefix_list_id               = optional(string)
    ip_protocol                  = string
    from_port                    = optional(number)
    to_port                      = optional(number)
    description                  = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for r in var.existing_ingress_rules : length(compact([
        r.cidr_ipv4 != null ? r.cidr_ipv4 : "",
        r.cidr_ipv6 != null ? r.cidr_ipv6 : "",
        r.referenced_security_group_id != null ? r.referenced_security_group_id : "",
        r.prefix_list_id != null ? r.prefix_list_id : "",
      ])) == 1
    ])
    error_message = "Each ingress rule must set exactly one of: cidr_ipv4, cidr_ipv6, referenced_security_group_id, prefix_list_id."
  }

  validation {
    condition = alltrue([
      for r in var.existing_ingress_rules : r.ip_protocol == "-1" || (r.from_port != null && r.to_port != null)
    ])
    error_message = "from_port and to_port are required unless ip_protocol is \"-1\"."
  }
}

variable "existing_egress_rules" {
  description = "Egress rules to attach to existing_security_group_id. Empty by default."
  type = list(object({
    cidr_ipv4                    = optional(string)
    cidr_ipv6                    = optional(string)
    referenced_security_group_id = optional(string)
    prefix_list_id               = optional(string)
    ip_protocol                  = string
    from_port                    = optional(number)
    to_port                      = optional(number)
    description                  = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for r in var.existing_egress_rules : length(compact([
        r.cidr_ipv4 != null ? r.cidr_ipv4 : "",
        r.cidr_ipv6 != null ? r.cidr_ipv6 : "",
        r.referenced_security_group_id != null ? r.referenced_security_group_id : "",
        r.prefix_list_id != null ? r.prefix_list_id : "",
      ])) == 1
    ])
    error_message = "Each egress rule must set exactly one of: cidr_ipv4, cidr_ipv6, referenced_security_group_id, prefix_list_id."
  }

  validation {
    condition = alltrue([
      for r in var.existing_egress_rules : r.ip_protocol == "-1" || (r.from_port != null && r.to_port != null)
    ])
    error_message = "from_port and to_port are required unless ip_protocol is \"-1\"."
  }
}

###############################################################################
# Managed prefix list inputs
###############################################################################

variable "prefix_list_create" {
  description = "When true (and no existing prefix list IDs are supplied), create a customer-managed EC2 prefix list."
  type        = bool
  default     = false
}

variable "existing_prefix_list_ids" {
  description = "Existing managed prefix list IDs. When non-empty, no prefix list is created and rules may reference these IDs."
  type        = list(string)
  default     = []
}

variable "prefix_list_address_family" {
  description = "Address family of the created prefix list (IPv4 or IPv6)."
  type        = string
  default     = "IPv4"

  validation {
    condition     = contains(["IPv4", "IPv6"], var.prefix_list_address_family)
    error_message = "prefix_list_address_family must be either \"IPv4\" or \"IPv6\"."
  }
}

variable "prefix_list_max_entries" {
  description = "Maximum number of entries allowed in the created prefix list."
  type        = number
  default     = 10
}

variable "prefix_list_entries" {
  description = "CIDR entries used to populate the created prefix list."
  type        = list(string)
  default     = []
}

###############################################################################
# Locals
###############################################################################

locals {
  name_base = var.name != "" ? var.name : (var.name_prefix != "" ? var.name_prefix : "managed-sg")

  # aws_security_group accepts either name or name_prefix, never both.
  sg_name        = var.name != "" ? var.name : null
  sg_name_prefix = var.name == "" && var.name_prefix != "" ? var.name_prefix : null

  # VPC: use the supplied VPC when provided, otherwise fall back to the one we create.
  vpc_id = var.vpc_id != "" ? var.vpc_id : one(aws_vpc.this[*].id)

  # Effective security group id: newly created (either lifecycle variant) or the existing one.
  new_sg_id         = one(concat(aws_security_group.new[*].id, aws_security_group.new_no_cbd[*].id))
  security_group_id = var.create_new ? local.new_sg_id : var.existing_security_group_id

  # Shared rule sets so the new-SG and existing-SG paths render through the same logic.
  effective_ingress_rules = var.create ? (var.create_new ? var.new_ingress_rules : var.existing_ingress_rules) : []
  effective_egress_rules  = var.create ? (var.create_new ? var.new_egress_rules : var.existing_egress_rules) : []

  # Stable composite keys so rule reordering never produces spurious diffs.
  ingress_rules = {
    for r in local.effective_ingress_rules : join("|", [
      r.cidr_ipv4 != null ? r.cidr_ipv4 : "",
      r.cidr_ipv6 != null ? r.cidr_ipv6 : "",
      r.referenced_security_group_id != null ? r.referenced_security_group_id : "",
      r.prefix_list_id != null ? r.prefix_list_id : "",
      r.ip_protocol,
      r.from_port == null ? "" : tostring(r.from_port),
      r.to_port == null ? "" : tostring(r.to_port),
      r.description != null ? r.description : "",
    ]) => r
  }

  egress_rules = {
    for r in local.effective_egress_rules : join("|", [
      r.cidr_ipv4 != null ? r.cidr_ipv4 : "",
      r.cidr_ipv6 != null ? r.cidr_ipv6 : "",
      r.referenced_security_group_id != null ? r.referenced_security_group_id : "",
      r.prefix_list_id != null ? r.prefix_list_id : "",
      r.ip_protocol,
      r.from_port == null ? "" : tostring(r.from_port),
      r.to_port == null ? "" : tostring(r.to_port),
      r.description != null ? r.description : "",
    ]) => r
  }

  created_prefix_list_ids    = aws_ec2_managed_prefix_list.this[*].id
  effective_prefix_list_ids  = length(var.existing_prefix_list_ids) > 0 ? var.existing_prefix_list_ids : local.created_prefix_list_ids
}

###############################################################################
# Supporting VPC (only built when the caller does not supply one)
###############################################################################

resource "aws_vpc" "this" {
  count = var.create && var.create_new && var.vpc_id == "" ? 1 : 0

  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.tags, { Name = "${local.name_base}-vpc" })
}

###############################################################################
# New security group - two mutually exclusive lifecycle variants
###############################################################################

resource "aws_security_group" "new" {
  count = var.create && var.create_new && var.create_before_destroy ? 1 : 0

  name        = local.sg_name
  name_prefix = local.sg_name_prefix
  description = var.description
  vpc_id      = local.vpc_id

  revoke_rules_on_delete = var.revoke_rules_on_delete

  tags = merge(var.tags, { Name = local.name_base })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group" "new_no_cbd" {
  count = var.create && var.create_new && !var.create_before_destroy ? 1 : 0

  name        = local.sg_name
  name_prefix = local.sg_name_prefix
  description = var.description
  vpc_id      = local.vpc_id

  revoke_rules_on_delete = var.revoke_rules_on_delete

  tags = merge(var.tags, { Name = local.name_base })

  lifecycle {
    create_before_destroy = false
  }
}

###############################################################################
# Guard: existing security group path requires an existing group id
###############################################################################

resource "terraform_data" "validate_existing_sg" {
  count = var.create && !var.create_new ? 1 : 0

  lifecycle {
    precondition {
      condition     = var.existing_security_group_id != ""
      error_message = "existing_security_group_id must be provided when create = true and create_new = false."
    }
  }
}

###############################################################################
# Rules - rendered identically for new and existing security groups
###############################################################################

resource "aws_vpc_security_group_ingress_rule" "this" {
  for_each = local.ingress_rules

  security_group_id            = local.security_group_id
  cidr_ipv4                    = try(each.value.cidr_ipv4, null)
  cidr_ipv6                    = try(each.value.cidr_ipv6, null)
  referenced_security_group_id = try(each.value.referenced_security_group_id, null)
  prefix_list_id               = try(each.value.prefix_list_id, null)
  ip_protocol                  = each.value.ip_protocol
  from_port                    = try(each.value.from_port, null)
  to_port                      = try(each.value.to_port, null)
  description                  = try(each.value.description, null)
}

resource "aws_vpc_security_group_egress_rule" "this" {
  for_each = local.egress_rules

  security_group_id            = local.security_group_id
  cidr_ipv4                    = try(each.value.cidr_ipv4, null)
  cidr_ipv6                    = try(each.value.cidr_ipv6, null)
  referenced_security_group_id = try(each.value.referenced_security_group_id, null)
  prefix_list_id               = try(each.value.prefix_list_id, null)
  ip_protocol                  = each.value.ip_protocol
  from_port                    = try(each.value.from_port, null)
  to_port                      = try(each.value.to_port, null)
  description                  = try(each.value.description, null)
}

###############################################################################
# Optional customer-managed EC2 prefix list
###############################################################################

resource "aws_ec2_managed_prefix_list" "this" {
  count = var.create && var.prefix_list_create && length(var.existing_prefix_list_ids) == 0 ? 1 : 0

  name           = "${local.name_base}-prefix-list"
  address_family = var.prefix_list_address_family
  max_entries    = var.prefix_list_max_entries

  dynamic "entry" {
    for_each = var.prefix_list_entries
    content {
      cidr        = entry.value
      description = "Managed by Terraform"
    }
  }

  tags = merge(var.tags, { Name = "${local.name_base}-prefix-list" })
}

###############################################################################
# Outputs
###############################################################################

output "security_group_id" {
  description = "ID of the created security group, or the supplied existing security group ID."
  value       = local.security_group_id
}

output "managed_prefix_list_id" {
  description = "ID of the created managed prefix list, or null when none was created."
  value       = one(aws_ec2_managed_prefix_list.this[*].id)
}

output "managed_prefix_list_arn" {
  description = "ARN of the created managed prefix list, or null when none was created."
  value       = one(aws_ec2_managed_prefix_list.this[*].arn)
}

output "prefix_list_ids" {
  description = "Effective prefix list IDs: the supplied existing IDs or the created prefix list ID."
  value       = local.effective_prefix_list_ids
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "environment" {
  description = "Deployment environment name used for tagging."
  type        = string
  default     = "dev"

  validation {
    condition     = length(trimspace(var.environment)) > 0
    error_message = "The environment value must be a non-empty string."
  }
}

locals {
  common_tags = {
    Environment = var.environment
  }
}

