terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

################################################################################
# Data sources (static provider metadata / locally generated documents only)
################################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

################################################################################
# Variables
################################################################################

variable "name" {
  description = "Name of the AWS Transfer Family server. When empty a random two-word hyphenated pet name is generated."
  type        = string
  default     = ""
}

variable "protocols" {
  description = "Transfer protocols enabled on the server (subset of SFTP, FTPS, FTP)."
  type        = list(string)
  default     = ["SFTP"]

  validation {
    condition     = length(var.protocols) > 0 && alltrue([for p in var.protocols : contains(["SFTP", "FTPS", "FTP"], p)])
    error_message = "protocols must be a non-empty subset of [\"SFTP\", \"FTPS\", \"FTP\"]."
  }
}

variable "endpoint_type" {
  description = "Endpoint type of the Transfer server. One of PUBLIC, VPC or VPC_ENDPOINT."
  type        = string
  default     = "PUBLIC"

  validation {
    condition     = contains(["PUBLIC", "VPC", "VPC_ENDPOINT"], var.endpoint_type)
    error_message = "endpoint_type must be one of \"PUBLIC\", \"VPC\" or \"VPC_ENDPOINT\"."
  }
}

variable "security_policy_name" {
  description = "Name of the AWS Transfer Family security policy applied to the server."
  type        = string
  default     = "TransferSecurityPolicy-2023-05"
}

variable "sub_domain" {
  description = "Sub-domain label used for the optional Route 53 CNAME record."
  type        = string
  default     = "sftp"
}

variable "domain_name" {
  description = "DNS domain name used to build the optional Route 53 CNAME record (e.g. example.com)."
  type        = string
  default     = null
}

variable "hosted_zone_id" {
  description = "Route 53 hosted zone ID in which to create the optional CNAME record. No record is created when null."
  type        = string
  default     = null
}

variable "certificate_arn" {
  description = "ACM certificate ARN used for FTPS/AS2 protocols. Required when protocols include FTPS or AS2."
  type        = string
  default     = null
}

variable "logging_role_arn" {
  description = "IAM role ARN used by the Transfer server for CloudWatch logging. When null a role is created and AWSTransferLoggingAccess is attached."
  type        = string
  default     = null
}

variable "api_gateway_auth" {
  description = "When true the server uses API_GATEWAY as identity provider and the supporting IAM role, secret and log permissions are provisioned."
  type        = bool
  default     = false
}

variable "host_key" {
  description = "Optional SSH host key (PEM) for the server. When null Transfer Family generates and manages the host key."
  type        = string
  default     = null
}

variable "subnet_ids" {
  description = "Subnet IDs used for VPC hosted endpoints. When empty and vpc_id is null a dedicated VPC is created."
  type        = list(string)
  default     = []
}

variable "security_group_ids" {
  description = "Security group IDs used for VPC hosted endpoints. When empty a dedicated security group is created."
  type        = list(string)
  default     = []
}

variable "vpc_id" {
  description = "VPC ID used for VPC hosted endpoints. When null a dedicated VPC is created."
  type        = string
  default     = null
}

variable "vpc_cidr" {
  description = "CIDR block for the dedicated VPC created when no VPC is supplied."
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_count" {
  description = "Number of subnets (and Elastic IP addresses) created in the dedicated VPC."
  type        = number
  default     = 2

  validation {
    condition     = var.subnet_count >= 1 && var.subnet_count <= 6
    error_message = "subnet_count must be between 1 and 6."
  }
}

variable "log_retention_in_days" {
  description = "Retention for the dedicated Transfer Family CloudWatch log group."
  type        = number
  default     = 90
}

variable "as2_transports" {
  description = "Optional AS2 transport message security modes passed through protocol_details."
  type        = set(string)
  default     = null
}

variable "passive_ip" {
  description = "Optional passive IP address advertised for PASV sessions."
  type        = string
  default     = null
}

variable "set_stat_option" {
  description = "Optional value for the STAT command option (DEFAULT, ENABLE or DISABLE)."
  type        = string
  default     = null

  validation {
    condition     = var.set_stat_option == null ? true : contains(["DEFAULT", "ENABLE", "DISABLE"], var.set_stat_option)
    error_message = "set_stat_option must be one of DEFAULT, ENABLE or DISABLE."
  }
}

variable "tls_session_resumption_mode" {
  description = "Optional TLS session resumption mode (DISABLED, ENABLED or ENFORCED)."
  type        = string
  default     = null

  validation {
    condition     = var.tls_session_resumption_mode == null ? true : contains(["DISABLED", "ENABLED", "ENFORCED"], var.tls_session_resumption_mode)
    error_message = "tls_session_resumption_mode must be one of DISABLED, ENABLED or ENFORCED."
  }
}

variable "users" {
  description = "Map of SFTP users. The key is the user name; home_directory is the path prefix inside the user's dedicated home bucket (for example \"/uploads\")."
  type = map(object({
    home_directory = string
  }))
  default = {}
}

variable "user_keys" {
  description = "Map of user name to a list of SSH public keys authorized for that user. Entries for unknown users are ignored."
  type        = map(list(string))
  default     = {}
}

variable "tags" {
  description = "Additional tags applied to every taggable resource."
  type        = map(string)
  default     = {}
}

################################################################################
# Locals
################################################################################

locals {
  server_name = var.name != "" ? var.name : random_pet.server_name.id

  tags = merge(var.tags, {
    Name = local.server_name
  })

  is_vpc_hosted = contains(["VPC", "VPC_ENDPOINT"], var.endpoint_type)

  create_network = local.is_vpc_hosted && var.vpc_id == null && length(var.subnet_ids) == 0

  vpc_id = var.vpc_id != null ? var.vpc_id : try(aws_vpc.main[0].id, null)

  subnet_count = local.create_network ? var.subnet_count : 0

  subnet_ids = length(var.subnet_ids) > 0 ? var.subnet_ids : aws_subnet.private[*].id

  create_security_group = local.is_vpc_hosted && length(var.security_group_ids) == 0

  security_group_ids = length(var.security_group_ids) > 0 ? var.security_group_ids : aws_security_group.transfer[*].id

  eip_count = var.endpoint_type == "VPC" ? (length(var.subnet_ids) > 0 ? length(var.subnet_ids) : local.subnet_count) : 0

  protocol_details_enabled = (
    var.as2_transports != null ||
    var.passive_ip != null ||
    var.set_stat_option != null ||
    var.tls_session_resumption_mode != null
  )

  user_bucket_name = {
    for user_name in keys(var.users) :
    user_name => "${local.server_name}-${replace(lower(user_name), "/[^a-z0-9-]/", "-")}-home"
  }

  user_home_prefix = {
    for user_name, user in var.users :
    user_name => trimsuffix(
      startswith(user.home_directory, "/") ? user.home_directory : "/${user.home_directory}",
      "/"
    )
  }

  user_home_directory = {
    for user_name in keys(var.users) :
    user_name => "/${local.user_bucket_name[user_name]}${local.user_home_prefix[user_name]}"
  }

  user_ssh_keys = merge([
    for user_name, public_keys in var.user_keys : {
      for idx, public_key in public_keys :
      "${user_name}-${idx}" => {
        user       = user_name
        public_key = public_key
      }
    } if contains(keys(var.users), user_name)
  ]...)
}

################################################################################
# Server name
################################################################################

resource "random_pet" "server_name" {
  length    = 2
  separator = "-"
}

################################################################################
# Dedicated network (VPC endpoints without pre-existing network resources)
################################################################################

resource "aws_vpc" "main" {
  count = local.create_network ? 1 : 0

  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, {
    Name = "${local.server_name}-vpc"
  })
}

resource "aws_subnet" "private" {
  count = local.create_network ? var.subnet_count : 0

  vpc_id                  = aws_vpc.main[0].id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.tags, {
    Name = "${local.server_name}-subnet-${count.index}"
  })
}

resource "aws_internet_gateway" "main" {
  count = local.create_network ? 1 : 0

  vpc_id = aws_vpc.main[0].id

  tags = merge(local.tags, {
    Name = "${local.server_name}-igw"
  })
}

resource "aws_route_table" "public" {
  count = local.create_network ? 1 : 0

  vpc_id = aws_vpc.main[0].id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main[0].id
  }

  tags = merge(local.tags, {
    Name = "${local.server_name}-route-table"
  })
}

resource "aws_route_table_association" "public" {
  count = local.create_network ? var.subnet_count : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.public[0].id
}

################################################################################
# Security group for VPC hosted SFTP endpoints
################################################################################

resource "aws_security_group" "transfer" {
  count = local.create_security_group ? 1 : 0

  name        = "${local.server_name}-transfer-sftp"
  description = "Security group controlling access to the ${local.server_name} AWS Transfer Family SFTP endpoint"
  vpc_id      = local.vpc_id

  # Ingress on port 22 from 0.0.0.0/0 is intentional: SFTP clients connect
  # directly from the internet to the Transfer Family endpoint addresses that
  # are bound to these Elastic IPs, so the endpoint addresses must be publicly
  # reachable. Restrict the CIDRs at the client/network layer if private
  # connectivity is required instead (use endpoint_type = "VPC_ENDPOINT").
  ingress {
    description = "SFTP from the internet - required for public SFTP reachability"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic required by the Transfer Family service"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = local.tags
}

################################################################################
# Elastic IP addresses (one per subnet for VPC hosted endpoints)
################################################################################

resource "aws_eip" "transfer" {
  count = local.eip_count

  domain = "vpc"

  tags = merge(local.tags, {
    Name = "${local.server_name}-eip-${count.index}"
  })

  lifecycle {
    prevent_destroy = true
  }
}

################################################################################
# VPC endpoint for VPC_ENDPOINT endpoint type
################################################################################

resource "aws_vpc_endpoint" "transfer" {
  count = var.endpoint_type == "VPC_ENDPOINT" ? 1 : 0

  vpc_id              = local.vpc_id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.transfer"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = local.subnet_ids
  security_group_ids  = local.security_group_ids
  private_dns_enabled = false

  tags = local.tags
}

################################################################################
# CloudWatch logging
################################################################################

resource "aws_cloudwatch_log_group" "transfer" {
  name              = "/aws/transfer/${local.server_name}"
  retention_in_days = var.log_retention_in_days

  tags = local.tags
}

data "aws_iam_policy_document" "transfer_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["transfer.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "transfer_logging" {
  count = var.logging_role_arn == null ? 1 : 0

  name               = "${local.server_name}-transfer-logging"
  assume_role_policy = data.aws_iam_policy_document.transfer_assume_role.json

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "transfer_logging" {
  count = var.logging_role_arn == null ? 1 : 0

  role       = aws_iam_role.transfer_logging[0].name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSTransferLoggingAccess"
}

################################################################################
# API Gateway authorization / CloudWatch logging role
################################################################################

data "aws_iam_policy_document" "api_gateway_assume_role" {
  count = var.api_gateway_auth ? 1 : 0

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["apigateway.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "api_gateway_cloudwatch" {
  count = var.api_gateway_auth ? 1 : 0

  name               = "${local.server_name}-apigw-cloudwatch"
  assume_role_policy = data.aws_iam_policy_document.api_gateway_assume_role[0].json

  tags = local.tags
}

data "aws_iam_policy_document" "api_gateway_cloudwatch" {
  count = var.api_gateway_auth ? 1 : 0

  statement {
    sid    = "TransferCloudWatchLogs"
    effect = "Allow"

    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = [
      aws_cloudwatch_log_group.transfer.arn,
      "${aws_cloudwatch_log_group.transfer.arn}:*",
    ]
  }

  statement {
    sid    = "ApiGatewayAuthorizationSecret"
    effect = "Allow"

    actions = [
      "secretsmanager:GetSecretValue",
      "secretsmanager:DescribeSecret",
    ]

    resources = [aws_secretsmanager_secret.api_gateway_auth[0].arn]
  }
}

resource "aws_iam_role_policy" "api_gateway_cloudwatch" {
  count = var.api_gateway_auth ? 1 : 0

  name   = "${local.server_name}-apigw-cloudwatch"
  role   = aws_iam_role.api_gateway_cloudwatch[0].id
  policy = data.aws_iam_policy_document.api_gateway_cloudwatch[0].json
}

################################################################################
# API Gateway authorization credentials (never stored in plain text)
################################################################################

resource "random_password" "api_gateway_key" {
  count = var.api_gateway_auth ? 1 : 0

  length  = 32
  special = false
}

resource "aws_secretsmanager_secret" "api_gateway_auth" {
  count = var.api_gateway_auth ? 1 : 0

  name                    = "${local.server_name}-api-gateway-auth"
  description             = "API Gateway authorization credentials for the ${local.server_name} AWS Transfer Family server"
  recovery_window_in_days = 7

  tags = local.tags
}

resource "aws_secretsmanager_secret_version" "api_gateway_auth" {
  count = var.api_gateway_auth ? 1 : 0

  secret_id = aws_secretsmanager_secret.api_gateway_auth[0].id
  secret_string = jsonencode({
    apiKey = random_password.api_gateway_key[0].result
  })
}

################################################################################
# Transfer Family server
################################################################################

resource "aws_transfer_server" "this" {
  identity_provider_type = var.api_gateway_auth ? "API_GATEWAY" : "SERVICE_MANAGED"
  endpoint_type          = var.endpoint_type
  protocols              = var.protocols
  security_policy_name   = var.security_policy_name
  certificate            = var.certificate_arn
  host_key               = var.host_key

  logging_role                = var.logging_role_arn != null ? var.logging_role_arn : try(aws_iam_role.transfer_logging[0].arn, null)
  structured_log_destinations = [aws_cloudwatch_log_group.transfer.arn]

  dynamic "endpoint_details" {
    for_each = var.endpoint_type == "PUBLIC" ? [] : [1]

    content {
      vpc_id                 = var.endpoint_type == "VPC" ? local.vpc_id : null
      subnet_ids             = var.endpoint_type == "VPC" ? local.subnet_ids : null
      security_group_ids     = var.endpoint_type == "VPC" ? local.security_group_ids : null
      address_allocation_ids = var.endpoint_type == "VPC" ? aws_eip.transfer[*].id : null
      vpc_endpoint_id        = var.endpoint_type == "VPC_ENDPOINT" ? try(aws_vpc_endpoint.transfer[0].id, null) : null
    }
  }

  dynamic "protocol_details" {
    for_each = local.protocol_details_enabled ? [1] : []

    content {
      passive_ip                  = var.passive_ip
      set_stat_option             = var.set_stat_option
      tls_session_resumption_mode = var.tls_session_resumption_mode
      as2_transports              = var.as2_transports
    }
  }

  tags = local.tags
}

################################################################################
# Optional Route 53 CNAME record
################################################################################

resource "aws_route53_record" "sftp" {
  count = var.hosted_zone_id != null ? 1 : 0

  zone_id = var.hosted_zone_id
  name    = var.domain_name != null ? "${var.sub_domain}.${var.domain_name}" : var.sub_domain
  type    = "CNAME"
  ttl     = 300
  records = [aws_transfer_server.this.endpoint]
}

################################################################################
# Per-user home bucket
################################################################################

resource "aws_s3_bucket" "home" {
  for_each = var.users

  bucket = local.user_bucket_name[each.key]

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "home" {
  for_each = var.users

  bucket = aws_s3_bucket.home[each.key].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "home" {
  for_each = var.users

  bucket = aws_s3_bucket.home[each.key].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "home" {
  for_each = var.users

  bucket = aws_s3_bucket.home[each.key].id

  versioning_configuration {
    status = "Enabled"
  }
}

################################################################################
# Per-user IAM role, policy and Transfer user
################################################################################

data "aws_iam_policy_document" "sftp_user_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["transfer.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }

    condition {
      test     = "ArnEquals"
      variable = "aws:SourceArn"
      values   = [aws_transfer_server.this.arn]
    }
  }
}

resource "aws_iam_role" "sftp_user" {
  for_each = var.users

  name               = "${local.server_name}-${replace(each.key, "/[^a-zA-Z0-9+=,.@_-]/", "-")}-sftp-role"
  assume_role_policy = data.aws_iam_policy_document.sftp_user_assume_role.json

  tags = local.tags
}

data "aws_iam_policy_document" "sftp_user" {
  for_each = var.users

  statement {
    sid    = "ListUserHomeBucket"
    effect = "Allow"

    actions = [
      "s3:ListBucket",
      "s3:GetBucketLocation",
    ]

    resources = [aws_s3_bucket.home[each.key].arn]
  }

  statement {
    sid    = "AccessUserHomeDirectory"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:GetObjectVersion",
      "s3:DeleteObjectVersion",
    ]

    resources = ["${aws_s3_bucket.home[each.key].arn}${local.user_home_prefix[each.key]}/*"]
  }
}

resource "aws_iam_policy" "sftp_user" {
  for_each = var.users

  name        = "${local.server_name}-${replace(each.key, "/[^a-zA-Z0-9+=,.@_-]/", "-")}-sftp-policy"
  description = "Least privilege access to the ${each.key} home directory in bucket ${local.user_bucket_name[each.key]}"
  policy      = data.aws_iam_policy_document.sftp_user[each.key].json

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "sftp_user" {
  for_each = var.users

  role       = aws_iam_role.sftp_user[each.key].name
  policy_arn = aws_iam_policy.sftp_user[each.key].arn
}

data "aws_iam_policy_document" "sftp_user_session" {
  for_each = var.users

  statement {
    sid    = "SessionListUserHomeBucket"
    effect = "Allow"

    actions   = ["s3:ListBucket"]
    resources = [aws_s3_bucket.home[each.key].arn]
  }

  statement {
    sid    = "SessionAccessUserHomeDirectory"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
    ]

    resources = ["${aws_s3_bucket.home[each.key].arn}${local.user_home_prefix[each.key]}/*"]
  }
}

resource "aws_transfer_user" "this" {
  for_each = var.users

  server_id           = aws_transfer_server.this.id
  user_name           = each.key
  role                = aws_iam_role.sftp_user[each.key].arn
  home_directory      = local.user_home_directory[each.key]
  home_directory_type = "PATH"
  policy              = data.aws_iam_policy_document.sftp_user_session[each.key].json

  tags = local.tags
}

################################################################################
# SSH public keys for Transfer users
################################################################################

resource "aws_transfer_ssh_key" "this" {
  for_each = local.user_ssh_keys

  server_id = aws_transfer_server.this.id
  user_name = aws_transfer_user.this[each.value.user].user_name
  body      = trimspace(each.value.public_key)
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which the network stack is provisioned."
  type        = string
  default     = "us-east-1"
}

variable "vpc_name" {
  description = "Name applied to the VPC and used as the prefix for all network resources."
  type        = string
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  description = "CIDR block assigned to the VPC."
  type        = string
  default     = "10.0.0.0/18"
}

variable "az_count" {
  description = "Number of availability zones to consume. Null uses every available AZ in the region."
  type        = number
  default     = null

  validation {
    condition     = var.az_count == null || var.az_count > 0
    error_message = "az_count must be null (use all available AZs) or a positive integer."
  }
}

variable "create_public_subnets" {
  description = "Whether to create public subnets, their route table, and the public network ACL."
  type        = bool
  default     = true
}

variable "create_private_subnets" {
  description = "Whether to create private subnets, their route tables, and the private network ACL."
  type        = bool
  default     = true
}

variable "create_nat_gateway" {
  description = "Whether to create NAT gateways (one per AZ) for private subnet egress."
  type        = bool
  default     = true
}

variable "environment" {
  description = "Environment identifier applied to all resources as a tag."
  type        = string
  default     = "dev"
}

###############################################################################
# Data Sources
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Locals
###############################################################################

locals {
  available_az_count = length(data.aws_availability_zones.available.names)

  az_count_effective = var.az_count != null ? min(var.az_count, local.available_az_count) : local.available_az_count

  azs = slice(data.aws_availability_zones.available.names, 0, local.az_count_effective)

  public_subnet_count  = var.create_public_subnets ? length(local.azs) : 0
  private_subnet_count = var.create_private_subnets ? length(local.azs) : 0
  nat_gateway_count    = var.create_nat_gateway && var.create_public_subnets ? length(local.azs) : 0
  private_nat_routes   = var.create_nat_gateway && var.create_public_subnets && var.create_private_subnets ? length(local.azs) : 0

  common_tags = {
    Environment = var.environment
    Project     = var.vpc_name
    Region      = var.aws_region
    ManagedBy   = "terraform"
  }
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = var.vpc_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Subnets
###############################################################################

resource "aws_subnet" "public" {
  count = local.public_subnet_count

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-public-${local.azs[count.index]}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  count = local.private_subnet_count

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, count.index + 64)
  availability_zone = local.azs[count.index]

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-private-${local.azs[count.index]}"
    Tier = "private"
  })
}

###############################################################################
# Internet Gateway
###############################################################################

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-igw"
  })
}

###############################################################################
# NAT Gateways (Elastic IP + gateway per AZ)
###############################################################################

resource "aws_eip" "nat" {
  count = local.nat_gateway_count

  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-nat-eip-${local.azs[count.index]}"
    Tier = "public"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  count = local.nat_gateway_count

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-nat-${local.azs[count.index]}"
  })

  depends_on = [aws_internet_gateway.main]
}

###############################################################################
# Public Routing
###############################################################################

resource "aws_route_table" "public" {
  count = var.create_public_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-public-rt"
    Tier = "public"
  })
}

resource "aws_route" "public_internet" {
  count = var.create_public_subnets ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count = local.public_subnet_count

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = one(aws_route_table.public[*].id)
}

###############################################################################
# Private Routing
###############################################################################

resource "aws_route_table" "private" {
  count = local.private_subnet_count

  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-private-rt-${local.azs[count.index]}"
    Tier = "private"
  })
}

resource "aws_route" "private_nat" {
  count = local.private_nat_routes

  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main[count.index].id
}

resource "aws_route_table_association" "private" {
  count = local.private_subnet_count

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

###############################################################################
# Network ACLs
###############################################################################

resource "aws_network_acl" "public" {
  count = var.create_public_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-public-nacl"
    Tier = "public"
  })

  ingress {
    rule_no    = 100
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 80
    to_port    = 80
  }

  ingress {
    rule_no    = 110
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 443
    to_port    = 443
  }

  ingress {
    rule_no    = 120
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 1024
    to_port    = 65535
  }

  ingress {
    rule_no    = 32766
    protocol   = "-1"
    action     = "deny"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  egress {
    rule_no    = 100
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 80
    to_port    = 80
  }

  egress {
    rule_no    = 110
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 443
    to_port    = 443
  }

  egress {
    rule_no    = 120
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 1024
    to_port    = 65535
  }

  egress {
    rule_no    = 130
    protocol   = "tcp"
    action     = "allow"
    cidr_block = var.vpc_cidr
    from_port  = 0
    to_port    = 65535
  }

  egress {
    rule_no    = 32766
    protocol   = "-1"
    action     = "deny"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }
}

resource "aws_network_acl_association" "public" {
  count = local.public_subnet_count

  network_acl_id = one(aws_network_acl.public[*].id)
  subnet_id      = aws_subnet.public[count.index].id
}

resource "aws_network_acl" "private" {
  count = var.create_private_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-private-nacl"
    Tier = "private"
  })

  ingress {
    rule_no    = 100
    protocol   = "-1"
    action     = "allow"
    cidr_block = var.vpc_cidr
    from_port  = 0
    to_port    = 0
  }

  ingress {
    rule_no    = 110
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 1024
    to_port    = 65535
  }

  ingress {
    rule_no    = 32766
    protocol   = "-1"
    action     = "deny"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  egress {
    rule_no    = 100
    protocol   = "-1"
    action     = "allow"
    cidr_block = var.vpc_cidr
    from_port  = 0
    to_port    = 0
  }

  egress {
    rule_no    = 110
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 80
    to_port    = 80
  }

  egress {
    rule_no    = 120
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 443
    to_port    = 443
  }

  egress {
    rule_no    = 130
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 1024
    to_port    = 65535
  }

  egress {
    rule_no    = 32766
    protocol   = "-1"
    action     = "deny"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }
}

resource "aws_network_acl_association" "private" {
  count = local.private_subnet_count

  network_acl_id = one(aws_network_acl.private[*].id)
  subnet_id      = aws_subnet.private[count.index].id
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "Identifier of the created VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr" {
  description = "CIDR block assigned to the VPC."
  value       = aws_vpc.main.cidr_block
}

output "availability_zones" {
  description = "Availability zones used by the deployment."
  value       = local.azs
}

output "public_subnet_ids" {
  description = "Identifiers of the public subnets."
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "Identifiers of the private subnets."
  value       = aws_subnet.private[*].id
}

output "nat_gateway_ids" {
  description = "Identifiers of the NAT gateways."
  value       = aws_nat_gateway.main[*].id
}

output "internet_gateway_id" {
  description = "Identifier of the internet gateway attached to the VPC."
  value       = aws_internet_gateway.main.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.100.0"
    }
  }
}

variable "is_ipv6_enabled" {
  description = "Controls whether an Amazon-provided IPv6 CIDR block is assigned to the VPC and whether subnets receive IPv6 addresses on creation."
  type        = bool
  default     = true
}

variable "sn_details" {
  description = "Subnet definitions: logical name, index into the available AZ list, and whether the subnet is public."
  type = list(object({
    name     = string
    az_index = number
    public   = bool
  }))
  default = [
    { name = "web-1", az_index = 0, public = true },
    { name = "web-2", az_index = 1, public = true },
    { name = "web-3", az_index = 2, public = true },
    { name = "app-1", az_index = 0, public = false },
    { name = "app-2", az_index = 1, public = false },
    { name = "app-3", az_index = 2, public = false },
    { name = "database-1", az_index = 0, public = false },
    { name = "database-2", az_index = 1, public = false },
    { name = "database-3", az_index = 2, public = false },
    { name = "reserved-1", az_index = 0, public = false },
    { name = "reserved-2", az_index = 1, public = false },
    { name = "reserved-3", az_index = 2, public = false },
  ]
}

locals {
  environment = "prod"

  sn_map = { for entry in var.sn_details : entry.name => entry }

  public_sn_map = {
    for entry in var.sn_details : entry.name => entry
    if entry.public
  }

  common_tags = {
    Environment = local.environment
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block                       = "10.16.0.0/16"
  assign_generated_ipv6_cidr_block = var.is_ipv6_enabled
  instance_tenancy                 = "default"
  enable_dns_support               = true
  enable_dns_hostnames             = true

  tags = merge(local.common_tags, {
    Name = "main-vpc"
    Tier = "network"
  })
}

module "subnets_ipv4" {
  source  = "hashicorp/subnets/cidr"
  version = "1.0.0"

  base_cidr_block = aws_vpc.main.cidr_block
  networks = [
    for entry in var.sn_details : {
      name     = entry.name
      new_bits = 4
    }
  ]
}

module "subnets_ipv6" {
  source  = "hashicorp/subnets/cidr"
  version = "1.0.0"

  base_cidr_block = aws_vpc.main.ipv6_cidr_block
  networks = [
    for entry in var.sn_details : {
      name     = entry.name
      new_bits = 8
    }
  ]
}

resource "aws_subnet" "main" {
  for_each = local.sn_map

  vpc_id                          = aws_vpc.main.id
  cidr_block                      = module.subnets_ipv4.network_cidr_blocks[each.key]
  ipv6_cidr_block                 = module.subnets_ipv6.network_cidr_blocks[each.key]
  availability_zone               = data.aws_availability_zones.available.names[each.value.az_index]
  assign_ipv6_address_on_creation = var.is_ipv6_enabled
  map_public_ip_on_launch         = false

  tags = merge(local.common_tags, {
    Name   = each.key
    Tier   = split("-", each.key)[0]
    Public = each.value.public ? "true" : "false"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "main-igw-vpc-${aws_vpc.main.id}"
    Tier = "public"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "public-rt-web"
    Tier = "public"
  })
}

resource "aws_route" "public_ipv4" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route" "public_ipv6" {
  route_table_id              = aws_route_table.public.id
  destination_ipv6_cidr_block = "::/0"
  gateway_id                  = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  for_each = local.public_sn_map

  subnet_id      = aws_subnet.main[each.key].id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "web_sg" {
  name        = "web-sg"
  description = "Web tier security group: public TLS ingress, administrative SSH from within the VPC, TLS egress to the app tier"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "web-sg"
    Tier = "web"
  })
}

resource "aws_security_group" "app_sg" {
  name        = "app-sg"
  description = "Application tier security group: TLS ingress from the web tier, TLS egress to the database tier"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "app-sg"
    Tier = "app"
  })
}

resource "aws_security_group" "db_sg" {
  name        = "db-sg"
  description = "Database tier security group: TLS ingress from the application tier only, no egress rules"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "db-sg"
    Tier = "database"
  })
}

resource "aws_vpc_security_group_ingress_rule" "web_https_public" {
  security_group_id = aws_security_group.web_sg.id
  description       = "Allow HTTPS (TLS) from the internet"
  cidr_ipv4         = "0.0.0.0/0"
  ip_protocol       = "tcp"
  from_port         = 443
  to_port           = 443

  tags = merge(local.common_tags, {
    Name = "web-sg-ingress-443-public"
    Tier = "web"
  })
}

resource "aws_vpc_security_group_ingress_rule" "web_ssh_vpc" {
  security_group_id = aws_security_group.web_sg.id
  description       = "Allow SSH from within the VPC IPv4 CIDR block"
  cidr_ipv4         = aws_vpc.main.cidr_block
  ip_protocol       = "tcp"
  from_port         = 22
  to_port           = 22

  tags = merge(local.common_tags, {
    Name = "web-sg-ingress-22-vpc"
    Tier = "web"
  })
}

resource "aws_vpc_security_group_egress_rule" "web_to_app_https" {
  security_group_id            = aws_security_group.web_sg.id
  description                  = "Allow HTTPS to the application tier"
  referenced_security_group_id = aws_security_group.app_sg.id
  ip_protocol                  = "tcp"
  from_port                    = 443
  to_port                      = 443

  tags = merge(local.common_tags, {
    Name = "web-sg-egress-443-app"
    Tier = "web"
  })
}

resource "aws_vpc_security_group_ingress_rule" "app_from_web_https" {
  security_group_id            = aws_security_group.app_sg.id
  description                  = "Allow HTTPS from the web tier"
  referenced_security_group_id = aws_security_group.web_sg.id
  ip_protocol                  = "tcp"
  from_port                    = 443
  to_port                      = 443

  tags = merge(local.common_tags, {
    Name = "app-sg-ingress-443-web"
    Tier = "app"
  })
}

resource "aws_vpc_security_group_egress_rule" "app_to_db_https" {
  security_group_id            = aws_security_group.app_sg.id
  description                  = "Allow HTTPS to the database tier"
  referenced_security_group_id = aws_security_group.db_sg.id
  ip_protocol                  = "tcp"
  from_port                    = 443
  to_port                      = 443

  tags = merge(local.common_tags, {
    Name = "app-sg-egress-443-db"
    Tier = "app"
  })
}

resource "aws_vpc_security_group_ingress_rule" "db_from_app_https" {
  security_group_id            = aws_security_group.db_sg.id
  description                  = "Allow HTTPS from the application tier only"
  referenced_security_group_id = aws_security_group.app_sg.id
  ip_protocol                  = "tcp"
  from_port                    = 443
  to_port                      = 443

  tags = merge(local.common_tags, {
    Name = "db-sg-ingress-443-app"
    Tier = "database"
  })
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

################################################################################
# Variables
################################################################################

variable "create_vpc" {
  description = "Master toggle that controls whether the VPC and all of its dependent resources are created"
  type        = bool
  default     = true
}

variable "vpc_cidr" {
  description = "The CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "enable_dns_support" {
  description = "A boolean flag to enable/disable DNS support in the VPC"
  type        = bool
  default     = true
}

variable "enable_dns_hostnames" {
  description = "A boolean flag to enable/disable DNS hostnames in the VPC"
  type        = bool
  default     = true
}

variable "public_subnets" {
  description = "A list of public subnets CIDR blocks inside the VPC"
  type        = list(string)
  default     = []
}

variable "private_subnets" {
  description = "A list of private subnets CIDR blocks inside the VPC"
  type        = list(string)
  default     = []
}

variable "intra_subnets" {
  description = "A list of intra (fully isolated) subnets CIDR blocks inside the VPC"
  type        = list(string)
  default     = []
}

variable "azs" {
  description = "A list of availability zone names or IDs in the region; the subnet CIDR lists are mapped across it by index"
  type        = list(string)
  default     = []
}

variable "public_subnet_suffix" {
  description = "Suffix to append to public subnets name"
  type        = string
  default     = "public"
}

variable "private_subnet_suffix" {
  description = "Suffix to append to private subnets name"
  type        = string
  default     = "private"
}

variable "intra_subnet_suffix" {
  description = "Suffix to append to intra subnets name"
  type        = string
  default     = "intra"
}

variable "public_subnet_names" {
  description = "Explicit list of public subnet names; overrides the auto-generated '<suffix>-<az>' names when supplied"
  type        = list(string)
  default     = []
}

variable "private_subnet_names" {
  description = "Explicit list of private subnet names; overrides the auto-generated '<suffix>-<az>' names when supplied"
  type        = list(string)
  default     = []
}

variable "intra_subnet_names" {
  description = "Explicit list of intra subnet names; overrides the auto-generated '<suffix>-<az>' names when supplied"
  type        = list(string)
  default     = []
}

variable "map_public_ip_on_launch" {
  description = "Specify true to indicate that instances launched into the public subnets should be assigned a public IP address"
  type        = bool
  default     = false
}

variable "create_igw" {
  description = "Controls if an Internet Gateway is created for public subnets and the related routes that connect them"
  type        = bool
  default     = true
}

variable "enable_nat_gateway" {
  description = "Controls if Elastic IPs and NAT Gateways (plus private routes to them) should be created"
  type        = bool
  default     = false
}

variable "tags" {
  description = "A map of tags to add to all resources created by this configuration"
  type        = map(string)
  default = {
    Environment = "dev"
  }
}

################################################################################
# Locals
################################################################################

locals {
  # Availability zones explicitly provided by the caller, falling back to all
  # available AZs advertised by the AWS provider for the current region.
  effective_azs = coalescelist(var.azs, data.aws_availability_zones.available.names)

  vpc_name = format("vpc-%s", replace(var.vpc_cidr, "/", "-"))

  # Subnet definitions keyed by index so that for_each can be used safely.
  public_subnet_map  = { for i, cidr in var.public_subnets : tostring(i) => cidr }
  private_subnet_map = { for i, cidr in var.private_subnets : tostring(i) => cidr }
  intra_subnet_map   = { for i, cidr in var.intra_subnets : tostring(i) => cidr }

  # Per-tier slice of the effective AZ list, mapped across the CIDR lists by index.
  public_subnet_azs  = slice(local.effective_azs, 0, min(length(var.public_subnets), length(local.effective_azs)))
  private_subnet_azs = slice(local.effective_azs, 0, min(length(var.private_subnets), length(local.effective_azs)))
  intra_subnet_azs   = slice(local.effective_azs, 0, min(length(var.intra_subnets), length(local.effective_azs)))

  # Generated Name tags: "<tier-suffix>-<az-identifier>", unless an explicit name is supplied.
  public_subnet_names_map = {
    for i, cidr in var.public_subnets :
    tostring(i) => coalesce(
      try(var.public_subnet_names[i], null),
      format("%s-%s", var.public_subnet_suffix, element(local.public_subnet_azs, i % length(local.public_subnet_azs)))
    )
  }

  private_subnet_names_map = {
    for i, cidr in var.private_subnets :
    tostring(i) => coalesce(
      try(var.private_subnet_names[i], null),
      format("%s-%s", var.private_subnet_suffix, element(local.private_subnet_azs, i % length(local.private_subnet_azs)))
    )
  }

  intra_subnet_names_map = {
    for i, cidr in var.intra_subnets :
    tostring(i) => coalesce(
      try(var.intra_subnet_names[i], null),
      format("%s-%s", var.intra_subnet_suffix, element(local.intra_subnet_azs, i % length(local.intra_subnet_azs)))
    )
  }

  # Public networking (IGW + public route table) is only created when requested.
  create_public_networking = var.create_vpc && var.create_igw && length(var.public_subnets) > 0

  # One NAT gateway per public/private subnet pair, capped at the smallest tier.
  nat_gateway_count = (
    var.create_vpc
    && var.enable_nat_gateway
    && var.create_igw
    && length(var.public_subnets) > 0
    && length(var.private_subnets) > 0
  ) ? min(length(var.public_subnets), length(var.private_subnets)) : 0
}

################################################################################
# VPC
################################################################################

resource "aws_vpc" "main" {
  count = var.create_vpc ? 1 : 0

  cidr_block           = var.vpc_cidr
  enable_dns_support   = var.enable_dns_support
  enable_dns_hostnames = var.enable_dns_hostnames

  tags = merge(
    var.tags,
    {
      Name = local.vpc_name
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

################################################################################
# Subnets
################################################################################

resource "aws_subnet" "public" {
  for_each = var.create_vpc ? local.public_subnet_map : {}

  vpc_id                  = aws_vpc.main[0].id
  cidr_block              = each.value
  availability_zone       = element(local.public_subnet_azs, tonumber(each.key) % length(local.public_subnet_azs))
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(
    var.tags,
    {
      Name = local.public_subnet_names_map[each.key]
      Tier = var.public_subnet_suffix
    }
  )
}

resource "aws_subnet" "private" {
  for_each = var.create_vpc ? local.private_subnet_map : {}

  vpc_id            = aws_vpc.main[0].id
  cidr_block        = each.value
  availability_zone = element(local.private_subnet_azs, tonumber(each.key) % length(local.private_subnet_azs))

  tags = merge(
    var.tags,
    {
      Name = local.private_subnet_names_map[each.key]
      Tier = var.private_subnet_suffix
    }
  )
}

resource "aws_subnet" "intra" {
  for_each = var.create_vpc ? local.intra_subnet_map : {}

  vpc_id            = aws_vpc.main[0].id
  cidr_block        = each.value
  availability_zone = element(local.intra_subnet_azs, tonumber(each.key) % length(local.intra_subnet_azs))

  tags = merge(
    var.tags,
    {
      Name = local.intra_subnet_names_map[each.key]
      Tier = var.intra_subnet_suffix
    }
  )
}

################################################################################
# Internet Gateway and public routing
################################################################################

resource "aws_internet_gateway" "main" {
  count = local.create_public_networking ? 1 : 0

  vpc_id = aws_vpc.main[0].id

  tags = merge(
    var.tags,
    {
      Name = format("%s-igw", local.vpc_name)
    }
  )
}

resource "aws_route_table" "public" {
  count = local.create_public_networking ? 1 : 0

  vpc_id = aws_vpc.main[0].id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main[0].id
  }

  tags = merge(
    var.tags,
    {
      Name = format("%s-%s-rt", local.vpc_name, var.public_subnet_suffix)
      Tier = var.public_subnet_suffix
    }
  )
}

resource "aws_route_table_association" "public" {
  for_each = local.create_public_networking ? local.public_subnet_map : {}

  subnet_id      = aws_subnet.public[each.key].id
  route_table_id = aws_route_table.public[0].id
}

################################################################################
# NAT Gateways (Elastic IPs)
################################################################################

resource "aws_eip" "nat" {
  count = local.nat_gateway_count

  domain = "vpc"

  tags = merge(
    var.tags,
    {
      Name = format("%s-nat-eip-%s", local.vpc_name, element(local.public_subnet_azs, count.index % length(local.public_subnet_azs)))
    }
  )

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  count = local.nat_gateway_count

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[tostring(count.index)].id

  tags = merge(
    var.tags,
    {
      Name = format("%s-nat-%s", local.vpc_name, element(local.public_subnet_azs, count.index % length(local.public_subnet_azs)))
    }
  )

  depends_on = [aws_internet_gateway.main]
}

################################################################################
# Private routing (one route table per private subnet, each routed to a NAT gateway)
################################################################################

resource "aws_route_table" "private" {
  count = local.nat_gateway_count > 0 ? length(var.private_subnets) : 0

  vpc_id = aws_vpc.main[0].id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index % local.nat_gateway_count].id
  }

  tags = merge(
    var.tags,
    {
      Name = format("%s-rt", local.private_subnet_names_map[tostring(count.index)])
      Tier = var.private_subnet_suffix
    }
  )
}

resource "aws_route_table_association" "private" {
  for_each = local.nat_gateway_count > 0 ? local.private_subnet_map : {}

  subnet_id      = aws_subnet.private[each.key].id
  route_table_id = aws_route_table.private[tonumber(each.key)].id
}

################################################################################
# Intra routing (fully isolated - no 0.0.0.0/0 route, no NAT/IGW target)
################################################################################

resource "aws_route_table" "intra" {
  count = var.create_vpc && length(var.intra_subnets) > 0 ? length(var.intra_subnets) : 0

  vpc_id = aws_vpc.main[0].id

  tags = merge(
    var.tags,
    {
      Name = format("%s-rt", local.intra_subnet_names_map[tostring(count.index)])
      Tier = var.intra_subnet_suffix
    }
  )
}

resource "aws_route_table_association" "intra" {
  for_each = var.create_vpc && length(var.intra_subnets) > 0 ? local.intra_subnet_map : {}

  subnet_id      = aws_subnet.intra[each.key].id
  route_table_id = aws_route_table.intra[tonumber(each.key)].id
}

################################################################################
# Outputs
################################################################################

output "vpc_id" {
  description = "The ID of the VPC (empty when the VPC is not created)"
  value       = try(aws_vpc.main[0].id, "")
}

output "vpc_cidr_block" {
  description = "The CIDR block of the VPC (empty when the VPC is not created)"
  value       = try(aws_vpc.main[0].cidr_block, "")
}

output "public_subnet_ids" {
  description = "List of IDs of the public subnets"
  value       = [for subnet in aws_subnet.public : subnet.id]
}

output "private_subnet_ids" {
  description = "List of IDs of the private subnets"
  value       = [for subnet in aws_subnet.private : subnet.id]
}

output "intra_subnet_ids" {
  description = "List of IDs of the intra subnets"
  value       = [for subnet in aws_subnet.intra : subnet.id]
}

output "internet_gateway_id" {
  description = "The ID of the Internet Gateway (empty when it is not created)"
  value       = try(aws_internet_gateway.main[0].id, "")
}

output "nat_gateway_ids" {
  description = "List of IDs of the NAT Gateways (empty when NAT gateways are disabled)"
  value       = aws_nat_gateway.main[*].id
}

output "public_route_table_id" {
  description = "The ID of the public route table (empty when it is not created)"
  value       = try(aws_route_table.public[0].id, "")
}

output "private_route_table_ids" {
  description = "List of IDs of the private route tables (empty when NAT gateways are disabled)"
  value       = aws_route_table.private[*].id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = local.common_tags
  }
}

###############################################################################
# Data sources (static / provider metadata only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Input variables (all with defaults so `terraform apply` runs unattended)
###############################################################################

variable "api_type" {
  description = "API Gateway flavour to provision: 'http' (v2) or 'rest' (v1)."
  type        = string
  default     = "http"

  validation {
    condition     = contains(["http", "rest"], var.api_type)
    error_message = "api_type must be either 'http' or 'rest'."
  }
}

variable "api_name" {
  description = "Name of the API Gateway and associated resources."
  type        = string
  default     = "benchmark-api"
}

variable "environment" {
  description = "Environment name, also used as the stage prefix."
  type        = string
  default     = "dev"
}

variable "vpc_link_enabled" {
  description = "Whether to provision a VPC link for the API."
  type        = bool
  default     = false
}

variable "vpc_link_port" {
  description = "TCP port used by the VPC link stack (NLB target group / listeners)."
  type        = number
  default     = 443
}

variable "custom_domain_name" {
  description = "Custom domain name to attach to the API (empty disables the feature)."
  type        = string
  default     = ""
}

variable "create_custom_domain" {
  description = "Whether to build the custom domain (ACM + domain name + mapping)."
  type        = bool
  default     = false
}

variable "create_route53_alias" {
  description = "Whether to create a Route 53 public zone and alias A record for the custom domain."
  type        = bool
  default     = false
}

variable "enable_ip_restriction" {
  description = "Whether to attach an IP restriction resource policy to the REST API."
  type        = bool
  default     = false
}

variable "allowed_ip_cidrs" {
  description = "CIDR ranges allowed to invoke the REST API when IP restriction is enabled."
  type        = list(string)
  default     = []
}

variable "authorizer_name" {
  description = "Name of the custom Lambda authorizer(s)."
  type        = string
  default     = "benchmark-authorizer"
}

variable "authorizer_result_ttl_seconds" {
  description = "Caching TTL for authorizer results."
  type        = number
  default     = 300
}

variable "enable_token_authorizer" {
  description = "Whether to also create a TOKEN type authorizer variant."
  type        = bool
  default     = false
}

variable "usage_plan_name" {
  description = "Name of the REST API usage plan."
  type        = string
  default     = "benchmark-usage-plan"
}

variable "usage_plan_throttle_rate_limit" {
  description = "Steady-state request rate limit for the usage plan."
  type        = number
  default     = 100
}

variable "usage_plan_throttle_burst_limit" {
  description = "Burst request limit for the usage plan."
  type        = number
  default     = 200
}

variable "usage_plan_quota_limit" {
  description = "Maximum number of requests allowed per quota period."
  type        = number
  default     = 10000
}

variable "usage_plan_quota_period" {
  description = "Quota period (DAY, WEEK or MONTH)."
  type        = string
  default     = "MONTH"
}

variable "log_retention_in_days" {
  description = "Retention for every CloudWatch log group created by this module."
  type        = number
  default     = 30
}

variable "vpc_cidr" {
  description = "CIDR block for the greenfield VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for the private subnets (one per subnet, AZs taken from data.aws_availability_zones)."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "http_routes" {
  description = "Map of HTTP API route key -> handler identifier used to drive dynamic route creation."
  type        = map(string)
  default = {
    "GET /"           = "list"
    "GET /items"      = "list"
    "GET /items/{id}" = "get"
    "POST /items"     = "create"
  }
}

variable "rest_resources" {
  description = "Map of logical resource key -> { path_part, parent } used to build the REST path tree."
  type = map(object({
    path_part = string
    parent    = string
  }))
  default = {
    items = {
      path_part = "items"
      parent    = "root"
    }
    item = {
      path_part = "{id}"
      parent    = "items"
    }
  }
}

variable "rest_methods" {
  description = "Map of logical method key -> { resource_key, http_method, authorization, request_parameters }."
  type = map(object({
    resource_key       = string
    http_method        = string
    authorization      = string
    request_parameters = map(bool)
  }))
  default = {
    list_items = {
      resource_key       = "items"
      http_method        = "GET"
      authorization      = "NONE"
      request_parameters = {}
    }
    get_item = {
      resource_key       = "item"
      http_method        = "GET"
      authorization      = "NONE"
      request_parameters = { "method.request.path.id" = true }
    }
  }
}

###############################################################################
# Locals
###############################################################################

locals {
  is_http = var.api_type == "http"
  is_rest = var.api_type == "rest"

  http_vpc_link = local.is_http && var.vpc_link_enabled
  rest_vpc_link = local.is_rest && var.vpc_link_enabled

  needs_zone = var.create_custom_domain || var.create_route53_alias

  common_tags = {
    Environment = var.environment
    Project     = var.api_name
  }

  stage_name   = "${var.environment}-stage"
  api_key_name = "${var.api_name}-key"

  ssm_parameter_name = "/${var.api_name}/${var.environment}/api-key"
  secret_name        = "${var.api_name}/api-key"
}

###############################################################################
# Greenfield networking foundation
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.api_name}-vpc"
  }
}

resource "aws_subnet" "private" {
  count             = length(var.private_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${var.api_name}-private-${count.index}"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.api_name}-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count          = length(aws_subnet.private)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

###############################################################################
# Security groups for VPC link traffic (no 0.0.0.0/0 unless on 80/443)
###############################################################################

resource "aws_security_group" "vpc_link" {
  name        = "${var.api_name}-vpc-link-sg"
  description = "Security group used by API Gateway VPC link ENIs"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "${var.api_name}-vpc-link-sg"
  }
}

resource "aws_security_group" "target" {
  name        = "${var.api_name}-target-sg"
  description = "Security group for the backend load balancers behind the VPC link"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "${var.api_name}-target-sg"
  }
}

resource "aws_security_group_rule" "vpc_link_ingress" {
  type              = "ingress"
  security_group_id = aws_security_group.vpc_link.id
  description       = "Allow VPC link traffic from within the VPC CIDR"
  from_port         = var.vpc_link_port
  to_port           = var.vpc_link_port
  protocol          = "tcp"
  cidr_blocks       = [var.vpc_cidr]
}

resource "aws_security_group_rule" "vpc_link_egress" {
  type                     = "egress"
  security_group_id        = aws_security_group.vpc_link.id
  description              = "Egress only toward the target security group"
  from_port                = var.vpc_link_port
  to_port                  = var.vpc_link_port
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.target.id
}

resource "aws_security_group_rule" "target_ingress" {
  type                     = "ingress"
  security_group_id        = aws_security_group.target.id
  description              = "Allow ingress from the VPC link security group"
  from_port                = var.vpc_link_port
  to_port                  = var.vpc_link_port
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.vpc_link.id
}

resource "aws_security_group_rule" "target_egress" {
  type              = "egress"
  security_group_id = aws_security_group.target.id
  description       = "Allow outbound HTTPS within the VPC"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = [var.vpc_cidr]
}

###############################################################################
# KMS + CloudWatch log groups (encrypted at rest)
###############################################################################

resource "aws_kms_key" "main" {
  description             = "KMS key protecting ${var.api_name} logs and secrets"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountAdmin"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowCloudWatchLogs"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt*",
          "kms:Decrypt*",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:Describe*"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "${var.api_name}-kms"
  }
}

resource "aws_kms_alias" "main" {
  name          = "alias/${var.api_name}-logs"
  target_key_id = aws_kms_key.main.key_id
}

resource "aws_cloudwatch_log_group" "api_access" {
  name              = "/aws/apigateway/${var.api_name}/access"
  retention_in_days = var.log_retention_in_days
  kms_key_id        = aws_kms_key.main.arn

  tags = {
    Name = "${var.api_name}-access-logs"
  }
}

resource "aws_cloudwatch_log_group" "lambda_route_handler" {
  name              = "/aws/lambda/${var.api_name}-route-handler"
  retention_in_days = var.log_retention_in_days
  kms_key_id        = aws_kms_key.main.arn

  tags = {
    Name = "${var.api_name}-route-handler-logs"
  }
}

resource "aws_cloudwatch_log_group" "lambda_authorizer" {
  name              = "/aws/lambda/${var.api_name}-authorizer"
  retention_in_days = var.log_retention_in_days
  kms_key_id        = aws_kms_key.main.arn

  tags = {
    Name = "${var.api_name}-authorizer-logs"
  }
}

###############################################################################
# Lambda packaging (code built locally, never from an external S3 object)
###############################################################################

data "archive_file" "route_handler" {
  type        = "zip"
  output_path = "${path.module}/build/route_handler.zip"

  source {
    filename = "index.py"
    content  = <<PY
import json


def handler(event, context):
    return {
        "statusCode": 200,
        "headers": {"Content-Type": "application/json"},
        "body": json.dumps({"message": "ok", "path": event.get("path", "/")}),
    }
PY
  }
}

data "archive_file" "authorizer" {
  type        = "zip"
  output_path = "${path.module}/build/authorizer.zip"

  source {
    filename = "index.js"
    content  = <<JS
exports.handler = async (event) => {
  return {
    principalId: "caller",
    policyDocument: {
      Version: "2012-10-17",
      Statement: [
        {
          Action: "execute-api:Invoke",
          Effect: "Allow",
          Resource: event.methodArn,
        },
      ],
    },
  };
};
JS
  }
}

###############################################################################
# Lambda execution roles (least privilege, logs only, scoped to own group)
###############################################################################

resource "aws_iam_role" "route_handler_lambda" {
  name = "${var.api_name}-route-handler-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "${var.api_name}-route-handler-role"
  }
}

resource "aws_iam_role_policy" "route_handler_lambda" {
  name = "${var.api_name}-route-handler-logs"
  role = aws_iam_role.route_handler_lambda.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.lambda_route_handler.arn}:*"
      }
    ]
  })
}

resource "aws_iam_role" "authorizer_lambda" {
  name = "${var.api_name}-authorizer-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "${var.api_name}-authorizer-role"
  }
}

resource "aws_iam_role_policy" "authorizer_lambda" {
  name = "${var.api_name}-authorizer-logs"
  role = aws_iam_role.authorizer_lambda.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.lambda_authorizer.arn}:*"
      }
    ]
  })
}

###############################################################################
# Lambda functions
###############################################################################

resource "aws_lambda_function" "route_handler" {
  function_name    = "${var.api_name}-route-handler"
  description      = "Handler backing the ${var.api_name} API integrations"
  filename         = data.archive_file.route_handler.output_path
  source_code_hash = data.archive_file.route_handler.output_base64sha256
  handler          = "index.handler"
  runtime          = "python3.12"
  role             = aws_iam_role.route_handler_lambda.arn
  timeout          = 30
  memory_size      = 256

  tracing_config {
    mode = "Active"
  }

  tags = {
    Name = "${var.api_name}-route-handler"
  }

  depends_on = [
    aws_iam_role_policy.route_handler_lambda,
    aws_cloudwatch_log_group.lambda_route_handler
  ]
}

resource "aws_lambda_function" "authorizer" {
  function_name    = "${var.api_name}-authorizer"
  description      = "Custom Lambda authorizer for the ${var.api_name} REST API"
  filename         = data.archive_file.authorizer.output_path
  source_code_hash = data.archive_file.authorizer.output_base64sha256
  handler          = "index.handler"
  runtime          = "nodejs22.x"
  role             = aws_iam_role.authorizer_lambda.arn
  timeout          = 10
  memory_size      = 128

  tags = {
    Name = "${var.api_name}-authorizer"
  }

  depends_on = [
    aws_iam_role_policy.authorizer_lambda,
    aws_cloudwatch_log_group.lambda_authorizer
  ]
}

###############################################################################
# HTTP API (v2)
###############################################################################

resource "aws_apigatewayv2_api" "http" {
  count         = local.is_http ? 1 : 0
  name          = var.api_name
  description   = "HTTP API (v2) managed by Terraform"
  protocol_type = "HTTP"

  cors_configuration {
    allow_origins = ["*"]
    allow_methods = ["GET", "POST", "PUT", "PATCH", "DELETE", "OPTIONS"]
    allow_headers = ["Content-Type", "Authorization", "X-Amz-Date", "X-Api-Key"]
    max_age       = 3600
  }

  tags = {
    Name = var.api_name
  }
}

resource "aws_apigatewayv2_integration" "http" {
  count                  = local.is_http ? 1 : 0
  api_id                 = aws_apigatewayv2_api.http[0].id
  integration_type       = "AWS_PROXY"
  integration_method     = "POST"
  integration_uri        = aws_lambda_function.route_handler.invoke_arn
  payload_format_version = "2.0"
  timeout_milliseconds   = 30000
}

resource "aws_apigatewayv2_route" "http" {
  for_each = local.is_http ? var.http_routes : {}

  api_id    = aws_apigatewayv2_api.http[0].id
  route_key = each.key
  target    = "integrations/${aws_apigatewayv2_integration.http[0].id}"
}

resource "aws_apigatewayv2_stage" "http" {
  count       = local.is_http ? 1 : 0
  api_id      = aws_apigatewayv2_api.http[0].id
  name        = local.stage_name
  auto_deploy = true

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.api_access.arn
    format = jsonencode({
      requestId      = "$context.requestId"
      ip             = "$context.identity.sourceIp"
      requestTime    = "$context.requestTime"
      httpMethod     = "$context.httpMethod"
      routeKey       = "$context.routeKey"
      status         = "$context.status"
      protocol       = "$context.protocol"
      responseLength = "$context.responseLength"
    })
  }

  tags = {
    Name = local.stage_name
  }
}

resource "aws_lambda_permission" "http_apigw" {
  count         = local.is_http ? 1 : 0
  statement_id  = "AllowHTTPAPIGatewayInvoke"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.route_handler.function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${aws_apigatewayv2_api.http[0].execution_arn}/*/*"
}

resource "aws_apigatewayv2_vpc_link" "http" {
  count              = local.http_vpc_link ? 1 : 0
  name               = var.api_name
  subnet_ids         = aws_subnet.private[*].id
  security_group_ids = [aws_security_group.vpc_link.id]

  tags = {
    Name = var.api_name
  }
}

###############################################################################
# REST API (v1)
###############################################################################

resource "aws_api_gateway_rest_api" "rest" {
  count       = local.is_rest ? 1 : 0
  name        = var.api_name
  description = "REST API (v1) managed by Terraform"

  endpoint_configuration {
    types = ["REGIONAL"]
  }

  tags = {
    Name = var.api_name
  }
}

resource "aws_api_gateway_rest_api_policy" "rest" {
  count       = local.is_rest && var.enable_ip_restriction ? 1 : 0
  rest_api_id = aws_api_gateway_rest_api.rest[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "IpRangeWhitelist"
        Effect    = "Allow"
        Principal = "*"
        Action    = "execute-api:Invoke"
        Resource  = "execute-api:/*"
        Condition = {
          IpAddress = {
            "aws:SourceIp" = var.allowed_ip_cidrs
          }
        }
      },
      {
        Sid       = "IpRangeBlacklist"
        Effect    = "Deny"
        Principal = "*"
        Action    = "execute-api:Invoke"
        Resource  = "execute-api:/*"
        Condition = {
          NotIpAddress = {
            "aws:SourceIp" = var.allowed_ip_cidrs
          }
        }
      }
    ]
  })
}

resource "aws_api_gateway_resource" "rest" {
  for_each = local.is_rest ? var.rest_resources : {}

  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  parent_id   = each.value.parent == "root" ? aws_api_gateway_rest_api.rest[0].root_resource_id : aws_api_gateway_resource.rest[each.value.parent].id
  path_part   = each.value.path_part
}

resource "aws_api_gateway_request_validator" "rest" {
  count                       = local.is_rest ? 1 : 0
  name                        = "${var.api_name}-validator"
  rest_api_id                 = aws_api_gateway_rest_api.rest[0].id
  validate_request_body       = false
  validate_request_parameters = true
}

resource "aws_api_gateway_method" "rest" {
  for_each = local.is_rest ? var.rest_methods : {}

  rest_api_id        = aws_api_gateway_rest_api.rest[0].id
  resource_id        = aws_api_gateway_resource.rest[each.value.resource_key].id
  http_method        = each.value.http_method
  authorization      = each.value.authorization
  authorizer_id      = each.value.authorization == "CUSTOM" ? aws_api_gateway_authorizer.rest[0].id : null
  request_validator_id = aws_api_gateway_request_validator.rest[0].id
  request_parameters   = each.value.request_parameters
}

resource "aws_api_gateway_integration" "rest" {
  for_each = local.is_rest ? var.rest_methods : {}

  rest_api_id             = aws_api_gateway_rest_api.rest[0].id
  resource_id             = aws_api_gateway_resource.rest[each.value.resource_key].id
  http_method             = aws_api_gateway_method.rest[each.key].http_method
  integration_http_method = "POST"
  type                    = "AWS_PROXY"
  uri                     = aws_lambda_function.route_handler.invoke_arn
}

resource "aws_lambda_permission" "rest_apigw" {
  count         = local.is_rest ? 1 : 0
  statement_id  = "AllowRESTAPIGatewayInvoke"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.route_handler.function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${aws_api_gateway_rest_api.rest[0].execution_arn}/*/*"
}

###############################################################################
# REST custom Lambda authorizers
###############################################################################

resource "aws_iam_role" "authorizer_invoke" {
  name = "${var.api_name}-authorizer-invoke-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "${var.api_name}-authorizer-invoke-role"
  }
}

resource "aws_iam_role_policy" "authorizer_invoke" {
  name = "${var.api_name}-authorizer-invoke-policy"
  role = aws_iam_role.authorizer_invoke.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "lambda:InvokeFunction"
        Resource = aws_lambda_function.authorizer.arn
      }
    ]
  })
}

resource "aws_api_gateway_authorizer" "rest" {
  count                            = local.is_rest ? 1 : 0
  name                             = var.authorizer_name
  rest_api_id                      = aws_api_gateway_rest_api.rest[0].id
  type                             = "REQUEST"
  identity_source                  = "method.request.header.Authorization"
  authorizer_uri                   = aws_lambda_function.authorizer.invoke_arn
  authorizer_result_ttl_in_seconds = var.authorizer_result_ttl_seconds
  authorizer_credentials           = aws_iam_role.authorizer_invoke.arn
}

resource "aws_api_gateway_authorizer" "token" {
  count                            = local.is_rest && var.enable_token_authorizer ? 1 : 0
  name                             = "${var.authorizer_name}-token"
  rest_api_id                      = aws_api_gateway_rest_api.rest[0].id
  type                             = "TOKEN"
  identity_source                  = "method.request.header.Authorization"
  authorizer_uri                   = aws_lambda_function.authorizer.invoke_arn
  authorizer_result_ttl_in_seconds = var.authorizer_result_ttl_seconds
  authorizer_credentials           = aws_iam_role.authorizer_invoke.arn
}

resource "aws_lambda_permission" "authorizer_apigw" {
  count         = local.is_rest ? 1 : 0
  statement_id  = "AllowRESTAPIGatewayInvokeAuthorizer"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.authorizer.function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${aws_api_gateway_rest_api.rest[0].execution_arn}/authorizers/*"
}

###############################################################################
# REST deployment / stage with automatic redeployment trigger
###############################################################################

resource "aws_api_gateway_deployment" "rest" {
  count       = local.is_rest ? 1 : 0
  rest_api_id = aws_api_gateway_rest_api.rest[0].id

  triggers = {
    redeployment = sha1(jsonencode({
      resources    = { for k, v in aws_api_gateway_resource.rest : k => v.id }
      methods      = { for k, v in aws_api_gateway_method.rest : k => v.id }
      integrations = { for k, v in aws_api_gateway_integration.rest : k => v.id }
      authorizers  = { for k, v in aws_api_gateway_authorizer.rest : k => v.id }
      resources_cfg = var.rest_resources
      methods_cfg   = var.rest_methods
    }))
  }

  lifecycle {
    create_before_destroy = true
  }

  depends_on = [
    aws_api_gateway_method.rest,
    aws_api_gateway_integration.rest
  ]
}

resource "aws_api_gateway_stage" "rest" {
  count         = local.is_rest ? 1 : 0
  rest_api_id   = aws_api_gateway_rest_api.rest[0].id
  stage_name    = local.stage_name
  deployment_id = aws_api_gateway_deployment.rest[0].id

  xray_tracing_enabled = true

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.api_access.arn
    format = jsonencode({
      requestId      = "$context.requestId"
      ip             = "$context.identity.sourceIp"
      requestTime    = "$context.requestTime"
      httpMethod     = "$context.httpMethod"
      resourcePath   = "$context.resourcePath"
      status         = "$context.status"
      responseLength = "$context.responseLength"
    })
  }

  tags = {
    Name = local.stage_name
  }

  depends_on = [aws_api_gateway_account.rest]
}

resource "aws_api_gateway_method_settings" "rest" {
  count       = local.is_rest ? 1 : 0
  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  stage_name  = aws_api_gateway_stage.rest[0].stage_name
  method_path = "*/*"

  settings {
    metrics_enabled        = true
    logging_level          = "INFO"
    data_trace_enabled     = false
    throttling_rate_limit  = var.usage_plan_throttle_rate_limit
    throttling_burst_limit = var.usage_plan_throttle_burst_limit
  }
}

###############################################################################
# REST usage plan + API key stack
###############################################################################

resource "random_password" "api_key" {
  length  = 40
  special = false

  keepers = {
    environment = var.environment
    api_name    = var.api_name
  }
}

resource "aws_api_gateway_usage_plan" "rest" {
  count = local.is_rest ? 1 : 0
  name  = var.usage_plan_name

  api_stages {
    api_id = aws_api_gateway_rest_api.rest[0].id
    stage  = aws_api_gateway_stage.rest[0].stage_name
  }

  throttle_settings {
    rate_limit  = var.usage_plan_throttle_rate_limit
    burst_limit = var.usage_plan_throttle_burst_limit
  }

  quota_settings {
    limit  = var.usage_plan_quota_limit
    period = var.usage_plan_quota_period
  }

  tags = {
    Name = var.usage_plan_name
  }
}

resource "aws_api_gateway_api_key" "rest" {
  count       = local.is_rest ? 1 : 0
  name        = local.api_key_name
  description = "API key for ${var.api_name}"
  value       = random_password.api_key.result
  enabled     = true

  tags = {
    Name = local.api_key_name
  }
}

resource "aws_api_gateway_usage_plan_key" "rest" {
  count         = local.is_rest ? 1 : 0
  key_id        = aws_api_gateway_api_key.rest[0].id
  key_type      = "API_KEY"
  usage_plan_id = aws_api_gateway_usage_plan.rest[0].id
}

resource "aws_ssm_parameter" "api_key" {
  count       = local.is_rest ? 1 : 0
  name        = local.ssm_parameter_name
  description = "SecureString API key for ${var.api_name}"
  type        = "SecureString"
  value       = random_password.api_key.result

  tags = {
    Name = local.ssm_parameter_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret" "api_key" {
  count       = local.is_rest ? 1 : 0
  name        = local.secret_name
  description = "API key for ${var.api_name}"
  kms_key_id  = aws_kms_key.main.arn

  tags = {
    Name = local.secret_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "api_key" {
  count         = local.is_rest ? 1 : 0
  secret_id     = aws_secretsmanager_secret.api_key[0].id
  secret_string = random_password.api_key.result
}

###############################################################################
# REST VPC link stack (NLB -> ALB)
###############################################################################

resource "aws_lb" "alb" {
  count              = local.rest_vpc_link ? 1 : 0
  name               = "${var.api_name}-alb"
  internal           = true
  load_balancer_type = "application"
  security_groups    = [aws_security_group.target.id]
  subnets            = aws_subnet.private[*].id

  tags = {
    Name = "${var.api_name}-alb"
  }
}

resource "aws_lb_target_group" "rest" {
  count       = local.rest_vpc_link ? 1 : 0
  name        = "${var.api_name}-tg"
  port        = var.vpc_link_port
  protocol    = "TCP"
  target_type = "alb"
  vpc_id      = aws_vpc.main.id

  health_check {
    protocol            = "HTTPS"
    port                = "traffic-port"
    path                = "/"
    matcher             = "200-399"
    interval            = 30
    timeout             = 10
    healthy_threshold   = 3
    unhealthy_threshold = 3
  }

  tags = {
    Name = "${var.api_name}-tg"
  }
}

resource "aws_lb_target_group_attachment" "rest" {
  count            = local.rest_vpc_link ? 1 : 0
  target_group_arn = aws_lb_target_group.rest[0].arn
  target_id        = aws_lb.alb[0].arn
  port             = var.vpc_link_port
}

resource "tls_private_key" "alb" {
  count     = local.rest_vpc_link ? 1 : 0
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "alb" {
  count           = local.rest_vpc_link ? 1 : 0
  private_key_pem = tls_private_key.alb[0].private_key_pem

  subject {
    common_name  = "${var.api_name}.internal"
    organization = "Terraform"
  }

  validity_period_hours = 8760

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth"
  ]

  dns_names = ["${var.api_name}.internal"]
}

resource "aws_acm_certificate" "alb" {
  count            = local.rest_vpc_link ? 1 : 0
  private_key      = tls_private_key.alb[0].private_key_pem
  certificate_body = tls_self_signed_cert.alb[0].cert_pem

  tags = {
    Name = "${var.api_name}-alb-cert"
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_lb_listener" "alb" {
  count             = local.rest_vpc_link ? 1 : 0
  load_balancer_arn = aws_lb.alb[0].arn
  port              = local.rest_vpc_link ? var.vpc_link_port : 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.alb[0].arn

  default_action {
    type = "fixed-response"

    fixed_response {
      content_type = "text/plain"
      message_body = "OK"
      status_code  = "200"
    }
  }
}

resource "aws_lb" "nlb" {
  count              = local.rest_vpc_link ? 1 : 0
  name               = "${var.api_name}-nlb"
  internal           = true
  load_balancer_type = "network"
  security_groups    = [aws_security_group.target.id]
  subnets            = aws_subnet.private[*].id

  tags = {
    Name = "${var.api_name}-nlb"
  }
}

resource "aws_lb_listener" "nlb" {
  count             = local.rest_vpc_link ? 1 : 0
  load_balancer_arn = aws_lb.nlb[0].arn
  port              = var.vpc_link_port
  protocol          = "TCP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.rest[0].arn
  }
}

resource "aws_api_gateway_vpc_link" "rest" {
  count       = local.rest_vpc_link ? 1 : 0
  name        = var.api_name
  description = "VPC link for ${var.api_name}"
  target_arns = [aws_lb.nlb[0].arn]

  tags = {
    Name = var.api_name
  }
}

###############################################################################
# API Gateway CloudWatch logging account role
###############################################################################

resource "aws_iam_role" "apigw_cloudwatch" {
  name = "${var.api_name}-apigw-cloudwatch-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "${var.api_name}-apigw-cloudwatch-role"
  }
}

resource "aws_iam_policy" "apigw_cloudwatch" {
  name        = "${var.api_name}-apigw-cloudwatch-policy"
  description = "Least privilege CloudWatch logging policy for API Gateway"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents",
          "logs:GetLogEvents",
          "logs:FilterLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.api_access.arn,
          "${aws_cloudwatch_log_group.api_access.arn}:*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "apigw_cloudwatch" {
  role       = aws_iam_role.apigw_cloudwatch.name
  policy_arn = aws_iam_policy.apigw_cloudwatch.arn
}

resource "aws_api_gateway_account" "rest" {
  count               = local.is_rest ? 1 : 0
  cloudwatch_role_arn = aws_iam_role.apigw_cloudwatch.arn

  depends_on = [aws_iam_role_policy_attachment.apigw_cloudwatch]
}

###############################################################################
# Route 53 hosted zone (greenfield)
###############################################################################

resource "aws_route53_zone" "main" {
  count = local.needs_zone ? 1 : 0
  name  = var.custom_domain_name

  tags = {
    Name = var.custom_domain_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# HTTP custom domain (ACM TLS 1.2 regional)
###############################################################################

resource "aws_acm_certificate" "http_domain" {
  count             = local.is_http && var.create_custom_domain ? 1 : 0
  domain_name       = var.custom_domain_name
  validation_method = "DNS"

  tags = {
    Name = var.custom_domain_name
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_route53_record" "http_domain_validation" {
  for_each = local.is_http && var.create_custom_domain ? {
    for dvo in aws_acm_certificate.http_domain[0].domain_validation_options : dvo.domain_name => {
      name   = dvo.resource_record_name
      record = dvo.resource_record_value
      type   = dvo.resource_record_type
    }
  } : {}

  allow_overwrite = true
  name            = each.value.name
  records         = [each.value.record]
  ttl             = 60
  type            = each.value.type
  zone_id         = aws_route53_zone.main[0].zone_id
}

resource "aws_acm_certificate_validation" "http_domain" {
  count                   = local.is_http && var.create_custom_domain ? 1 : 0
  certificate_arn         = aws_acm_certificate.http_domain[0].arn
  validation_record_fqdns = [for record in aws_route53_record.http_domain_validation : record.fqdn]
}

resource "aws_apigatewayv2_domain_name" "http" {
  count       = local.is_http && var.create_custom_domain ? 1 : 0
  domain_name = var.custom_domain_name

  domain_name_configuration {
    certificate_arn = aws_acm_certificate_validation.http_domain[0].certificate_arn
    endpoint_type   = "REGIONAL"
    security_policy = "TLS_1_2"
  }

  tags = {
    Name = var.custom_domain_name
  }
}

resource "aws_apigatewayv2_api_mapping" "http" {
  count       = local.is_http && var.create_custom_domain ? 1 : 0
  api_id      = aws_apigatewayv2_api.http[0].id
  domain_name = aws_apigatewayv2_domain_name.http[0].id
  stage       = aws_apigatewayv2_stage.http[0].name
}

resource "aws_route53_record" "http_alias" {
  count   = local.is_http && var.create_route53_alias ? 1 : 0
  zone_id = aws_route53_zone.main[0].zone_id
  name    = var.custom_domain_name
  type    = "A"

  alias {
    name                   = aws_apigatewayv2_domain_name.http[0].domain_name_configuration[0].target_domain_name
    zone_id                = aws_apigatewayv2_domain_name.http[0].domain_name_configuration[0].hosted_zone_id
    evaluate_target_health = false
  }
}

###############################################################################
# REST custom domain (ACM TLS 1.2 regional)
###############################################################################

resource "aws_acm_certificate" "rest_domain" {
  count             = local.is_rest && var.create_custom_domain ? 1 : 0
  domain_name       = var.custom_domain_name
  validation_method = "DNS"

  tags = {
    Name = var.custom_domain_name
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_route53_record" "rest_domain_validation" {
  for_each = local.is_rest && var.create_custom_domain ? {
    for dvo in aws_acm_certificate.rest_domain[0].domain_validation_options : dvo.domain_name => {
      name   = dvo.resource_record_name
      record = dvo.resource_record_value
      type   = dvo.resource_record_type
    }
  } : {}

  allow_overwrite = true
  name            = each.value.name
  records         = [each.value.record]
  ttl             = 60
  type            = each.value.type
  zone_id         = aws_route53_zone.main[0].zone_id
}

resource "aws_acm_certificate_validation" "rest_domain" {
  count                   = local.is_rest && var.create_custom_domain ? 1 : 0
  certificate_arn         = aws_acm_certificate.rest_domain[0].arn
  validation_record_fqdns = [for record in aws_route53_record.rest_domain_validation : record.fqdn]
}

resource "aws_api_gateway_domain_name" "rest" {
  count           = local.is_rest && var.create_custom_domain ? 1 : 0
  domain_name     = var.custom_domain_name
  certificate_arn = aws_acm_certificate_validation.rest_domain[0].certificate_arn
  security_policy = "TLS_1_2"

  endpoint_configuration {
    types = ["REGIONAL"]
  }

  tags = {
    Name = var.custom_domain_name
  }
}

resource "aws_api_gateway_base_path_mapping" "rest" {
  count       = local.is_rest && var.create_custom_domain ? 1 : 0
  api_id      = aws_api_gateway_rest_api.rest[0].id
  stage_name  = aws_api_gateway_stage.rest[0].stage_name
  domain_name = aws_api_gateway_domain_name.rest[0].domain_name
}

resource "aws_route53_record" "rest_alias" {
  count   = local.is_rest && var.create_route53_alias ? 1 : 0
  zone_id = aws_route53_zone.main[0].zone_id
  name    = var.custom_domain_name
  type    = "A"

  alias {
    name                   = aws_api_gateway_domain_name.rest[0].regional_domain_name
    zone_id                = aws_api_gateway_domain_name.rest[0].regional_zone_id
    evaluate_target_health = false
  }
}

###############################################################################
# Outputs
###############################################################################

output "api_type" {
  description = "The API flavour that was provisioned."
  value       = var.api_type
}

output "http_api_endpoint" {
  description = "Default endpoint of the HTTP API (if provisioned)."
  value       = one(aws_apigatewayv2_api.http[*].api_endpoint)
}

output "rest_api_invoke_url" {
  description = "Invoke URL of the REST API stage (if provisioned)."
  value       = one(aws_api_gateway_stage.rest[*].invoke_url)
}

output "api_stage_name" {
  description = "Name of the deployed stage."
  value       = local.stage_name
}

output "api_stage_arn" {
  description = "ARN of the deployed stage."
  value = one(concat(
    aws_apigatewayv2_stage.http[*].arn,
    aws_api_gateway_stage.rest[*].arn
  ))
}

output "api_key_id" {
  description = "ID of the generated REST API key."
  value       = one(aws_api_gateway_api_key.rest[*].id)
}

output "api_key_ssm_parameter_name" {
  description = "Name of the SSM SecureString parameter holding the API key."
  value       = one(aws_ssm_parameter.api_key[*].name)
}

output "api_key_ssm_parameter_arn" {
  description = "ARN of the SSM SecureString parameter holding the API key."
  value       = one(aws_ssm_parameter.api_key[*].arn)
}

output "api_key_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the API key."
  value       = one(aws_secretsmanager_secret.api_key[*].arn)
}

output "custom_domain_target_domain_name" {
  description = "Regional target domain name of the API Gateway custom domain."
  value = one(concat(
    [for cfg in aws_apigatewayv2_domain_name.http[*].domain_name_configuration : cfg[0].target_domain_name],
    aws_api_gateway_domain_name.rest[*].regional_domain_name
  ))
}

output "custom_domain_zone_id" {
  description = "Hosted zone ID of the API Gateway custom domain target."
  value = one(concat(
    [for cfg in aws_apigatewayv2_domain_name.http[*].domain_name_configuration : cfg[0].hosted_zone_id],
    aws_api_gateway_domain_name.rest[*].regional_zone_id
  ))
}

output "route53_zone_id" {
  description = "ID of the Route 53 public hosted zone (if created)."
  value       = one(aws_route53_zone.main[*].zone_id)
}

output "vpc_link_id" {
  description = "ID of the provisioned VPC link (HTTP or REST)."
  value = one(concat(
    aws_apigatewayv2_vpc_link.http[*].id,
    aws_api_gateway_vpc_link.rest[*].id
  ))
}

output "vpc_id" {
  description = "ID of the VPC created for this module."
  value       = aws_vpc.main.id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets used by the VPC link."
  value       = aws_subnet.private[*].id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

################################################################################
# Data sources (static provider / well-known lookups only)
################################################################################

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

################################################################################
# Random suffix for globally unique bucket naming
################################################################################

resource "random_string" "suffix" {
  length  = 8
  upper   = false
  lower   = true
  numeric = true
  special = false
}

################################################################################
# Variables
################################################################################

variable "trail_name" {
  description = "Name of the CloudTrail trail and prefix used for related resources."
  type        = string
  default     = "cloudtrail"
}

variable "bucket_name" {
  description = "Name of the S3 bucket used for CloudTrail log storage. When empty, a name is generated from the account ID, region and a random suffix."
  type        = string
  default     = ""
}

variable "s3_force_destroy" {
  description = "Whether to delete all objects in the CloudTrail S3 bucket when the bucket is destroyed."
  type        = bool
  default     = true
}

variable "s3_versioning_enabled" {
  description = "Whether versioning is enabled on the CloudTrail S3 bucket."
  type        = bool
  default     = false
}

variable "kms_key_alias" {
  description = "Alias name (without the 'alias/' prefix) for the CloudTrail KMS key."
  type        = string
  default     = "cloudtrail"
}

variable "kms_key_deletion_window_in_days" {
  description = "Number of days before the CloudTrail KMS key is deleted after destruction."
  type        = number
  default     = 30
}

variable "kms_key_rotation_enabled" {
  description = "Whether automatic annual rotation is enabled for the CloudTrail KMS key."
  type        = bool
  default     = true
}

variable "cloudtrail_kms_key_policy_role_arn" {
  description = "Optional IAM role ARN granted permission to decrypt CloudTrail logs with the CloudTrail KMS key."
  type        = string
  default     = ""
}

variable "cloudwatch_log_group_name" {
  description = "Name of the CloudWatch Log Group that receives CloudTrail logs. When empty, a name based on the trail name is used."
  type        = string
  default     = ""
}

variable "cloudwatch_log_retention_in_days" {
  description = "Retention period in days for the CloudTrail CloudWatch Log Group."
  type        = number
  default     = 90
}

variable "enable_log_file_validation" {
  description = "Whether CloudTrail log file validation (digest files) is enabled."
  type        = bool
  default     = true
}

variable "include_global_service_events" {
  description = "Whether global service events (for example IAM and STS) are included in the trail."
  type        = bool
  default     = true
}

variable "is_multi_region_trail" {
  description = "Whether the trail applies to all AWS regions."
  type        = bool
  default     = true
}

variable "enable_logging" {
  description = "Whether logging is enabled for the trail."
  type        = bool
  default     = true
}

variable "is_organization_trail" {
  description = "Whether the trail is an organization trail that applies to all accounts in the AWS Organization."
  type        = bool
  default     = false
}

variable "event_selector_read_write_type" {
  description = "Type of events the event selector applies to (All, ReadOnly or WriteOnly)."
  type        = string
  default     = "All"

  validation {
    condition     = contains(["All", "ReadOnly", "WriteOnly"], var.event_selector_read_write_type)
    error_message = "event_selector_read_write_type must be one of: All, ReadOnly, WriteOnly."
  }
}

variable "event_selector_include_management_events" {
  description = "Whether management events are included in the trail's event selector."
  type        = bool
  default     = true
}

variable "data_resource_selectors" {
  description = "List of data resource selectors for the trail (for example S3 objects or Lambda functions)."
  type = list(object({
    type   = string
    values = list(string)
  }))
  default = []
}

variable "insight_types" {
  description = "List of CloudTrail Insights event types to enable (for example ApiCallRateInsight or ApiErrorRateInsight)."
  type        = list(string)
  default     = []
}

variable "create_sns_topic" {
  description = "Whether to create an SNS topic used for CloudTrail log delivery notifications."
  type        = bool
  default     = false
}

variable "sns_topic_arn" {
  description = "Existing SNS topic ARN used for CloudTrail notifications when create_sns_topic is false."
  type        = string
  default     = ""
}

variable "tags" {
  description = "Tags applied to all taggable resources created by this configuration."
  type        = map(string)
  default = {
    Environment = "production"
    Project     = "cloudtrail-audit"
    ManagedBy   = "Terraform"
  }
}

################################################################################
# Locals
################################################################################

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
  partition  = data.aws_partition.current.partition

  trail_name = var.trail_name

  bucket_name = (
    var.bucket_name != ""
    ? var.bucket_name
    : "cloudtrail-${local.account_id}-${local.region}-${random_string.suffix.result}"
  )

  log_group_name = (
    var.cloudwatch_log_group_name != ""
    ? var.cloudwatch_log_group_name
    : "${local.trail_name}-logs"
  )

  kms_alias_name = "alias/${var.kms_key_alias}"

  sns_topic_arn = (
    var.create_sns_topic
    ? aws_sns_topic.cloudtrail[0].arn
    : (var.sns_topic_arn != "" ? var.sns_topic_arn : null)
  )
}

################################################################################
# S3 bucket for CloudTrail log storage
################################################################################

resource "aws_s3_bucket" "cloudtrail" {
  bucket        = local.bucket_name
  force_destroy = var.s3_force_destroy

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  versioning_configuration {
    status = var.s3_versioning_enabled ? "Enabled" : "Suspended"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.cloudtrail.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

################################################################################
# KMS key for CloudTrail log file encryption
################################################################################

data "aws_iam_policy_document" "cloudtrail_kms" {
  statement {
    sid    = "EnableRootAccountAdminAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudTrailToEncryptDecryptLogs"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt",
      "kms:DescribeKey",
    ]

    resources = ["*"]

    condition {
      test     = "StringLike"
      variable = "kms:EncryptionContext:aws:cloudtrail:arn"
      values   = ["arn:${local.partition}:cloudtrail:*:${local.account_id}:trail/*"]
    }
  }

  statement {
    sid    = "AllowCloudWatchLogsEncryption"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logs.${local.region}.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:Describe*",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = ["arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:${local.log_group_name}"]
    }
  }

  statement {
    sid    = "AllowS3BucketEncryption"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]

    resources = ["*"]
  }

  dynamic "statement" {
    for_each = var.cloudtrail_kms_key_policy_role_arn != "" ? [var.cloudtrail_kms_key_policy_role_arn] : []

    content {
      sid    = "AllowExternalRoleToDecryptLogs"
      effect = "Allow"

      principals {
        type        = "AWS"
        identifiers = [statement.value]
      }

      actions = [
        "kms:Decrypt",
        "kms:DescribeKey",
        "kms:GenerateDataKey*",
      ]

      resources = ["*"]
    }
  }
}

resource "aws_kms_key" "cloudtrail" {
  description             = "KMS key used to encrypt CloudTrail log files and CloudWatch Logs"
  deletion_window_in_days = var.kms_key_deletion_window_in_days
  enable_key_rotation     = var.kms_key_rotation_enabled
  policy                  = data.aws_iam_policy_document.cloudtrail_kms.json

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "cloudtrail" {
  name          = local.kms_alias_name
  target_key_id = aws_kms_key.cloudtrail.key_id
}

################################################################################
# CloudWatch Log Group for CloudTrail
################################################################################

resource "aws_cloudwatch_log_group" "cloudtrail" {
  name              = local.log_group_name
  retention_in_days = var.cloudwatch_log_retention_in_days
  kms_key_id        = aws_kms_key.cloudtrail.arn

  tags = var.tags
}

################################################################################
# IAM role and policy allowing CloudTrail to write to CloudWatch Logs
################################################################################

data "aws_iam_policy_document" "cloudtrail_assume_role" {
  statement {
    sid    = "AllowCloudTrailToAssumeRole"
    effect = "Allow"

    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "cloudtrail_cloudwatch" {
  name               = "${local.trail_name}-cloudwatch-logs-role"
  description        = "Role assumed by CloudTrail to deliver log events to CloudWatch Logs"
  assume_role_policy = data.aws_iam_policy_document.cloudtrail_assume_role.json

  tags = var.tags
}

data "aws_iam_policy_document" "cloudtrail_cloudwatch_logs" {
  statement {
    sid    = "AllowCloudTrailToCreateLogStreamAndPutLogEvents"
    effect = "Allow"

    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = ["${aws_cloudwatch_log_group.cloudtrail.arn}:*"]
  }
}

resource "aws_iam_policy" "cloudtrail_cloudwatch_logs" {
  name        = "${local.trail_name}-cloudwatch-logs-policy"
  description = "Least privilege policy allowing CloudTrail to write to the CloudTrail CloudWatch Log Group"
  policy      = data.aws_iam_policy_document.cloudtrail_cloudwatch_logs.json

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "cloudtrail_cloudwatch_logs" {
  role       = aws_iam_role.cloudtrail_cloudwatch.name
  policy_arn = aws_iam_policy.cloudtrail_cloudwatch_logs.arn
}

################################################################################
# S3 bucket policy allowing CloudTrail to deliver log files
# NOTE: S3 bucket policies may contain only s3: actions. KMS permissions for
# CloudTrail log encryption are granted in the dedicated KMS key policy above.
################################################################################

data "aws_iam_policy_document" "cloudtrail_bucket" {
  statement {
    sid    = "AWSCloudTrailAclCheck"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.cloudtrail.arn]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [aws_cloudtrail.cloudtrail.arn]
    }
  }

  statement {
    sid    = "AWSCloudTrailWrite"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.cloudtrail.arn}/*"]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [aws_cloudtrail.cloudtrail.arn]
    }
  }
}

resource "aws_s3_bucket_policy" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id
  policy = data.aws_iam_policy_document.cloudtrail_bucket.json
}

################################################################################
# Optional SNS topic for CloudTrail notifications
################################################################################

resource "aws_sns_topic" "cloudtrail" {
  count = var.create_sns_topic ? 1 : 0

  name = "${local.trail_name}-cloudtrail-alerts"

  tags = var.tags
}

data "aws_iam_policy_document" "cloudtrail_sns" {
  count = var.create_sns_topic ? 1 : 0

  statement {
    sid    = "AllowCloudTrailToPublish"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.cloudtrail[0].arn]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [aws_cloudtrail.cloudtrail.arn]
    }
  }
}

resource "aws_sns_topic_policy" "cloudtrail" {
  count = var.create_sns_topic ? 1 : 0

  arn    = aws_sns_topic.cloudtrail[0].arn
  policy = data.aws_iam_policy_document.cloudtrail_sns[0].json
}

################################################################################
# CloudTrail trail
################################################################################

resource "aws_cloudtrail" "cloudtrail" {
  name                          = local.trail_name
  s3_bucket_name                = aws_s3_bucket.cloudtrail.id
  kms_key_id                    = aws_kms_key.cloudtrail.arn
  cloud_watch_logs_group_arn    = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
  cloud_watch_logs_role_arn     = aws_iam_role.cloudtrail_cloudwatch.arn
  enable_log_file_validation    = var.enable_log_file_validation
  include_global_service_events = var.include_global_service_events
  is_multi_region_trail         = var.is_multi_region_trail
  enable_logging                = var.enable_logging
  is_organization_trail         = var.is_organization_trail
  sns_topic_name                = local.sns_topic_arn

  tags = var.tags

  event_selector {
    read_write_type           = var.event_selector_read_write_type
    include_management_events = var.event_selector_include_management_events

    dynamic "data_resource" {
      for_each = var.data_resource_selectors

      content {
        type   = data_resource.value.type
        values = data_resource.value.values
      }
    }
  }

  dynamic "insight_selector" {
    for_each = toset(var.insight_types)

    content {
      insight_type = insight_selector.value
    }
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "cluster_name" {
  type        = string
  description = "Name of the EKS cluster used as the suffix for all IAM resource names."
  default     = "legion"
}

locals {
  name_prefix = "tf-${var.cluster_name}"
  node_suffix = "${local.name_prefix}-node"
}

data "aws_iam_policy_document" "eks_cluster_assume_role" {
  statement {
    sid     = "EKSClusterAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "eks_node_assume_role" {
  statement {
    sid     = "EKSNodeAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "eks_worker_autoscaling" {
  statement {
    sid    = "ClusterAutoscalerDescribeActions"
    effect = "Allow"

    actions = [
      "autoscaling:DescribeAutoScalingGroups",
      "autoscaling:DescribeAutoScalingInstances",
      "autoscaling:DescribeLaunchConfigurations",
      "autoscaling:DescribeTags",
      "ec2:DescribeLaunchTemplateVersions",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "ClusterAutoscalerModifyActions"
    effect = "Allow"

    actions = [
      "autoscaling:SetDesiredCapacity",
      "autoscaling:TerminateInstanceInAutoScalingGroup",
      "autoscaling:UpdateAutoScalingGroup",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/kubernetes.io/cluster/${var.cluster_name}"
      values   = ["owned"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/k8s.io/cluster-autoscaler/enabled"
      values   = ["true"]
    }
  }
}

resource "aws_iam_role" "eks_cluster" {
  name        = local.name_prefix
  description = "IAM role for the ${var.cluster_name} EKS control plane."

  assume_role_policy = data.aws_iam_policy_document.eks_cluster_assume_role.json

  tags = {
    Name = local.name_prefix
  }
}

resource "aws_iam_role" "eks_node" {
  name        = local.node_suffix
  description = "IAM role for the ${var.cluster_name} EKS managed node group workers."

  assume_role_policy = data.aws_iam_policy_document.eks_node_assume_role.json

  tags = {
    Name = local.node_suffix
  }
}

resource "aws_iam_role_policy_attachment" "eks_cluster_amazon_eks_cluster_policy" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "eks_cluster_amazon_eks_service_policy" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSServicePolicy"
}

resource "aws_iam_role_policy_attachment" "eks_node_amazon_eks_worker_node_policy" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "eks_node_amazon_eks_cni_policy" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
}

resource "aws_iam_role_policy_attachment" "eks_node_amazon_ec2_container_registry_read_only" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

resource "aws_iam_policy" "eks_worker_autoscaling" {
  name        = "eks-worker-autoscaling-${var.cluster_name}"
  description = "Permissions for the Kubernetes Cluster Autoscaler running on the ${var.cluster_name} EKS worker nodes."
  policy      = data.aws_iam_policy_document.eks_worker_autoscaling.json

  tags = {
    Name = "eks-worker-autoscaling-${var.cluster_name}"
  }
}

resource "aws_iam_role_policy_attachment" "eks_node_worker_autoscaling" {
  role       = aws_iam_role.eks_node.name
  policy_arn = aws_iam_policy.eks_worker_autoscaling.arn
}

resource "aws_iam_instance_profile" "eks_node" {
  name = local.node_suffix
  role = aws_iam_role.eks_node.name

  tags = {
    Name = local.node_suffix
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

################################################################################
# Variables
################################################################################

variable "namespace" {
  type        = string
  description = "Namespace (organization/team name) used by the CloudPosse label module for standardized naming."
  default     = "acme"
}

variable "environment" {
  type        = string
  description = "Environment name (e.g. dev, staging, prod) used by the CloudPosse label module."
  default     = "dev"
}

variable "name" {
  type        = string
  description = "Base name used by the CloudPosse label module for the IAM access management framework."
  default     = "iam-access"
}

variable "tags" {
  type        = map(string)
  description = "Additional tags merged into the standardized CloudPosse tags for all resources."
  default     = {}
}

variable "attributes" {
  type        = list(string)
  description = "Additional attributes appended to the CloudPosse label ordering/identifier."
  default     = []
}

variable "admin_users" {
  type        = list(string)
  description = "List of admin IAM user names to create and add to the admin group. Empty list creates no users or membership."
  default     = []
}

variable "non_admin_users" {
  type        = list(string)
  description = "List of non-admin IAM user names to create and add to the non-admin group. Empty list creates no users or membership."
  default     = []
}

################################################################################
# CloudPosse standardized labels
################################################################################

module "admin_label" {
  source  = "cloudposse/label/null"
  version = "~> 0.25"

  namespace   = var.namespace
  environment = var.environment
  name        = var.name
  attributes  = concat(var.attributes, ["admin"])
  tags        = var.tags
}

module "non_admin_label" {
  source  = "cloudposse/label/null"
  version = "~> 0.25"

  namespace   = var.namespace
  environment = var.environment
  name        = var.name
  attributes  = concat(var.attributes, ["non-admin"])
  tags        = var.tags
}

locals {
  admin_tags     = merge(module.admin_label.tags, var.tags)
  non_admin_tags = merge(module.non_admin_label.tags, var.tags)
}

################################################################################
# IAM groups
# NOTE: aws_iam_group in the pinned AWS provider (~> 5.0) does not expose a
# `tags` argument, so no tags block is declared here. Naming is standardized
# via the CloudPosse label module outputs.
################################################################################

resource "aws_iam_group" "admin" {
  name = module.admin_label.id
  path = "/"
}

resource "aws_iam_group" "non_admin" {
  name = module.non_admin_label.id
  path = "/"
}

################################################################################
# IAM users
################################################################################

resource "aws_iam_user" "admin" {
  for_each = toset(var.admin_users)

  name = "${module.admin_label.id}-${each.key}"
  path = "/"

  tags = merge(local.admin_tags, { Name = "${module.admin_label.id}-${each.key}" })
}

resource "aws_iam_user" "non_admin" {
  for_each = toset(var.non_admin_users)

  name = "${module.non_admin_label.id}-${each.key}"
  path = "/"

  tags = merge(local.non_admin_tags, { Name = "${module.non_admin_label.id}-${each.key}" })
}

################################################################################
# Self-management policy (attached to BOTH groups)
################################################################################

data "aws_iam_policy_document" "self_management" {
  statement {
    sid    = "AllowViewAccountInfo"
    effect = "Allow"

    actions = [
      "iam:GetAccountPasswordPolicy",
      "iam:ListMFADevices",
      "iam:ListVirtualMFADevices",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowManageOwnPasswords"
    effect = "Allow"

    actions = [
      "iam:ChangePassword",
      "iam:GetUser",
    ]

    resources = [
      "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}",
    ]
  }

  statement {
    sid    = "AllowManageOwnAccessKeys"
    effect = "Allow"

    actions = [
      "iam:CreateAccessKey",
      "iam:UpdateAccessKey",
      "iam:DeleteAccessKey",
      "iam:ListAccessKeys",
    ]

    resources = [
      "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}",
    ]
  }

  statement {
    sid    = "AllowManageOwnVirtualMFADevice"
    effect = "Allow"

    actions = [
      "iam:CreateVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:ResyncMFADevice",
    ]

    resources = [
      "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:mfa/$${aws:username}",
      "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}",
    ]
  }

  statement {
    sid    = "AllowDeactivateOwnVirtualMFADeviceOnlyWithMFA"
    effect = "Allow"

    actions = [
      "iam:DeactivateMFADevice",
      "iam:DeleteVirtualMFADevice",
    ]

    resources = [
      "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:mfa/$${aws:username}",
      "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}",
    ]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "self_management" {
  name        = "${module.admin_label.id}-self-management"
  description = "Allows members to manage their own credentials, MFA devices, and read account password/MFA information. Deactivating an MFA device requires MFA."
  policy      = data.aws_iam_policy_document.self_management.json

  tags = local.admin_tags
}

resource "aws_iam_group_policy_attachment" "admin_self_management" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.self_management.arn
}

resource "aws_iam_group_policy_attachment" "non_admin_self_management" {
  group      = aws_iam_group.non_admin.name
  policy_arn = aws_iam_policy.self_management.arn
}

################################################################################
# Admin role and MFA-enforced assume-role policy
################################################################################

data "aws_iam_policy_document" "admin_role_trust" {
  statement {
    sid    = "AllowAccountRootAssumeRoleWithMFA"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions = ["sts:AssumeRole"]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_role" "admin" {
  name                 = "${module.admin_label.id}-role"
  description          = "Administrative role assumable only with MFA present."
  assume_role_policy   = data.aws_iam_policy_document.admin_role_trust.json
  max_session_duration = 3600

  tags = local.admin_tags
}

data "aws_iam_policy_document" "admin_assume_role" {
  statement {
    sid    = "AllowAssumeAdminRoleWithMFA"
    effect = "Allow"

    actions = ["sts:AssumeRole"]

    resources = [aws_iam_role.admin.arn]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "admin_assume_role" {
  name        = "${module.admin_label.id}-assume-role"
  description = "Allows admin group members to assume the dedicated admin role, requiring MFA to be present."
  policy      = data.aws_iam_policy_document.admin_assume_role.json

  tags = local.admin_tags
}

resource "aws_iam_group_policy_attachment" "admin_assume_role" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.admin_assume_role.arn
}

resource "aws_iam_role_policy_attachment" "admin_administrator_access" {
  role       = aws_iam_role.admin.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AdministratorAccess"
}

################################################################################
# Group memberships (conditional)
################################################################################

resource "aws_iam_group_membership" "admin" {
  count = length(var.admin_users) > 0 ? 1 : 0

  name  = "${module.admin_label.id}-membership"
  group = aws_iam_group.admin.name
  users = [for u in aws_iam_user.admin : u.name]
}

resource "aws_iam_group_membership" "non_admin" {
  count = length(var.non_admin_users) > 0 ? 1 : 0

  name  = "${module.non_admin_label.id}-membership"
  group = aws_iam_group.non_admin.name
  users = [for u in aws_iam_user.non_admin : u.name]
}

################################################################################
# Account password policy
################################################################################

resource "aws_iam_account_password_policy" "strict" {
  minimum_password_length        = 14
  require_lowercase_characters   = true
  require_uppercase_characters   = true
  require_numbers                = true
  require_symbols                = true
  allow_users_to_change_password = true
  password_reuse_prevention      = 24
  max_password_age               = 90

  lifecycle {
    prevent_destroy = true
  }
}

################################################################################
# Outputs
################################################################################

output "admin_role_arn" {
  description = "ARN of the administrative IAM role that requires MFA for assumption."
  value       = aws_iam_role.admin.arn
}

output "admin_role_name" {
  description = "Name of the administrative IAM role that requires MFA for assumption."
  value       = aws_iam_role.admin.name
}

output "admin_group_name" {
  description = "Name of the admin IAM group."
  value       = aws_iam_group.admin.name
}

output "non_admin_group_name" {
  description = "Name of the non-admin IAM group."
  value       = aws_iam_group.non_admin.name
}

output "self_management_policy_arn" {
  description = "ARN of the self-management policy attached to both groups."
  value       = aws_iam_policy.self_management.arn
}

output "admin_assume_role_policy_arn" {
  description = "ARN of the admin-only assume-role policy."
  value       = aws_iam_policy.admin_assume_role.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "enable" {
  description = "Enable or disable the entire module"
  type        = bool
  default     = true
}

variable "create_security_group" {
  description = "Whether to create a new security group or attach rules to an existing one"
  type        = bool
  default     = true
}

variable "existing_security_group_id" {
  description = "Existing security group ID to manage when create_security_group is false"
  type        = string
  default     = ""
}

variable "vpc_id" {
  description = "VPC ID to use for the new security group. If empty, a fallback VPC is created."
  type        = string
  default     = ""
}

variable "name" {
  description = "Name used by the labels module"
  type        = string
  default     = "app"
}

variable "environment" {
  description = "Environment used by the labels module"
  type        = string
  default     = "dev"
}

variable "namespace" {
  description = "Namespace used by the labels module, folded into the attributes input"
  type        = string
  default     = "example"
}

variable "attributes" {
  description = "Attributes used by the labels module"
  type        = list(string)
  default     = ["security"]
}

variable "tags" {
  description = "Additional tags to merge with module labels"
  type        = map(string)
  default     = {}
}

variable "create_prefix_list" {
  description = "Whether to create a managed prefix list when no prefix list IDs are supplied"
  type        = bool
  default     = false
}

variable "prefix_list_ids" {
  description = "Pre-existing managed prefix list IDs to use instead of creating a new one"
  type        = list(string)
  default     = []
}

variable "prefix_list_entries" {
  description = "CIDR entries for the managed prefix list (capped at prefix_list_max_entries)"
  type        = list(string)
  default     = []
}

variable "prefix_list_address_family" {
  description = "Address family for the managed prefix list"
  type        = string
  default     = "IPv4"

  validation {
    condition     = contains(["IPv4", "IPv6"], var.prefix_list_address_family)
    error_message = "prefix_list_address_family must be either IPv4 or IPv6."
  }
}

variable "prefix_list_max_entries" {
  description = "Maximum number of entries for the managed prefix list"
  type        = number
  default     = 5

  validation {
    condition     = var.prefix_list_max_entries > 0 && var.prefix_list_max_entries <= 5
    error_message = "prefix_list_max_entries must be between 1 and 5."
  }
}

variable "prefix_list_description" {
  description = "Description for managed prefix list entries"
  type        = string
  default     = "Managed prefix list entry"
}

variable "ingress_cidr_blocks" {
  description = "Ingress CIDR blocks"
  type        = list(string)
  default     = []
}

variable "ingress_self" {
  description = "Ingress self-referencing rule descriptions"
  type        = list(string)
  default     = []
}

variable "ingress_source_security_group_ids" {
  description = "Ingress source security group IDs"
  type        = list(string)
  default     = []
}

variable "ingress_prefix_list_ids" {
  description = "Ingress prefix list IDs. Defaults to the created or supplied prefix list IDs when empty."
  type        = list(string)
  default     = []
}

variable "ingress_ip_protocol" {
  description = "Ingress IP protocol"
  type        = string
  default     = "tcp"
}

variable "ingress_from_port" {
  description = "Ingress from port"
  type        = number
  default     = 443
}

variable "ingress_to_port" {
  description = "Ingress to port"
  type        = number
  default     = 443
}

variable "ingress_description" {
  description = "Ingress rule description"
  type        = string
  default     = "Managed ingress rule"
}

variable "egress_cidr_blocks" {
  description = "Egress CIDR blocks"
  type        = list(string)
  default     = []
}

variable "egress_self" {
  description = "Egress self-referencing rule descriptions"
  type        = list(string)
  default     = []
}

variable "egress_source_security_group_ids" {
  description = "Egress source security group IDs"
  type        = list(string)
  default     = []
}

variable "egress_prefix_list_ids" {
  description = "Egress prefix list IDs. Defaults to the created or supplied prefix list IDs when empty."
  type        = list(string)
  default     = []
}

variable "egress_ip_protocol" {
  description = "Egress IP protocol"
  type        = string
  default     = "-1"
}

variable "egress_from_port" {
  description = "Egress from port"
  type        = number
  default     = null
}

variable "egress_to_port" {
  description = "Egress to port"
  type        = number
  default     = null
}

variable "egress_description" {
  description = "Egress rule description"
  type        = string
  default     = "Managed egress rule"
}

module "labels" {
  source = "git::https://github.com/sohanyadav/terraform-aws-labels.git?ref=v1.0.0"

  name        = var.name
  environment = var.environment
  attributes  = distinct(concat(var.attributes, [var.namespace]))
}

locals {
  prefix_list_entries_capped = slice(
    var.prefix_list_entries,
    0,
    min(length(var.prefix_list_entries), var.prefix_list_max_entries)
  )

  tags = merge(module.labels.tags, var.tags)

  vpc_id = var.vpc_id != "" ? var.vpc_id : try(aws_vpc.fallback[0].id, "")

  security_group_id = var.create_security_group ? try(aws_security_group.this[0].id, "") : var.existing_security_group_id

  resolved_prefix_list_ids = length(var.prefix_list_ids) > 0 ? var.prefix_list_ids : try([aws_ec2_managed_prefix_list.this[0].id], [])

  ingress_prefix_list_ids = length(var.ingress_prefix_list_ids) > 0 ? var.ingress_prefix_list_ids : local.resolved_prefix_list_ids
  egress_prefix_list_ids  = length(var.egress_prefix_list_ids) > 0 ? var.egress_prefix_list_ids : local.resolved_prefix_list_ids

  ingress_cidr_rules = {
    for idx, cidr in var.ingress_cidr_blocks :
    "ingress_cidr_${idx}" => {
      cidr_ipv4                    = cidr
      cidr_ipv6                    = null
      description                  = var.ingress_description
      from_port                    = var.ingress_from_port
      ip_protocol                  = var.ingress_ip_protocol
      prefix_list_id               = null
      referenced_security_group_id = null
      to_port                      = var.ingress_to_port
      tags                         = local.tags
    }
  }

  ingress_self_rules = {
    for idx, desc in var.ingress_self :
    "ingress_self_${idx}" => {
      cidr_ipv4                    = null
      cidr_ipv6                    = null
      description                  = desc != "" ? desc : var.ingress_description
      from_port                    = var.ingress_from_port
      ip_protocol                  = var.ingress_ip_protocol
      prefix_list_id               = null
      referenced_security_group_id = local.security_group_id
      to_port                      = var.ingress_to_port
      tags                         = local.tags
    }
  }

  ingress_source_sg_rules = {
    for idx, sg_id in var.ingress_source_security_group_ids :
    "ingress_source_sg_${idx}" => {
      cidr_ipv4                    = null
      cidr_ipv6                    = null
      description                  = var.ingress_description
      from_port                    = var.ingress_from_port
      ip_protocol                  = var.ingress_ip_protocol
      prefix_list_id               = null
      referenced_security_group_id = sg_id
      to_port                      = var.ingress_to_port
      tags                         = local.tags
    }
  }

  ingress_prefix_list_rules = {
    for idx, pl_id in local.ingress_prefix_list_ids :
    "ingress_prefix_list_${idx}" => {
      cidr_ipv4                    = null
      cidr_ipv6                    = null
      description                  = var.ingress_description
      from_port                    = var.ingress_from_port
      ip_protocol                  = var.ingress_ip_protocol
      prefix_list_id               = pl_id
      referenced_security_group_id = null
      to_port                      = var.ingress_to_port
      tags                         = local.tags
    }
  }

  ingress_rules = merge(
    local.ingress_cidr_rules,
    local.ingress_self_rules,
    local.ingress_source_sg_rules,
    local.ingress_prefix_list_rules
  )

  egress_cidr_rules = {
    for idx, cidr in var.egress_cidr_blocks :
    "egress_cidr_${idx}" => {
      cidr_ipv4                    = cidr
      cidr_ipv6                    = null
      description                  = var.egress_description
      from_port                    = var.egress_from_port
      ip_protocol                  = var.egress_ip_protocol
      prefix_list_id               = null
      referenced_security_group_id = null
      to_port                      = var.egress_to_port
      tags                         = local.tags
    }
  }

  egress_self_rules = {
    for idx, desc in var.egress_self :
    "egress_self_${idx}" => {
      cidr_ipv4                    = null
      cidr_ipv6                    = null
      description                  = desc != "" ? desc : var.egress_description
      from_port                    = var.egress_from_port
      ip_protocol                  = var.egress_ip_protocol
      prefix_list_id               = null
      referenced_security_group_id = local.security_group_id
      to_port                      = var.egress_to_port
      tags                         = local.tags
    }
  }

  egress_source_sg_rules = {
    for idx, sg_id in var.egress_source_security_group_ids :
    "egress_source_sg_${idx}" => {
      cidr_ipv4                    = null
      cidr_ipv6                    = null
      description                  = var.egress_description
      from_port                    = var.egress_from_port
      ip_protocol                  = var.egress_ip_protocol
      prefix_list_id               = null
      referenced_security_group_id = sg_id
      to_port                      = var.egress_to_port
      tags                         = local.tags
    }
  }

  egress_prefix_list_rules = {
    for idx, pl_id in local.egress_prefix_list_ids :
    "egress_prefix_list_${idx}" => {
      cidr_ipv4                    = null
      cidr_ipv6                    = null
      description                  = var.egress_description
      from_port                    = var.egress_from_port
      ip_protocol                  = var.egress_ip_protocol
      prefix_list_id               = pl_id
      referenced_security_group_id = null
      to_port                      = var.egress_to_port
      tags                         = local.tags
    }
  }

  egress_rules = merge(
    local.egress_cidr_rules,
    local.egress_self_rules,
    local.egress_source_sg_rules,
    local.egress_prefix_list_rules
  )
}

resource "aws_vpc" "fallback" {
  count = var.enable && var.create_security_group && var.vpc_id == "" ? 1 : 0

  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = local.tags
}

resource "aws_security_group" "this" {
  count = var.enable && var.create_security_group ? 1 : 0

  name        = "${module.labels.id}-sg"
  description = "Managed security group"
  vpc_id      = local.vpc_id

  tags = local.tags

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_ec2_managed_prefix_list" "this" {
  count = var.enable && var.create_prefix_list && length(var.prefix_list_ids) == 0 ? 1 : 0

  name           = "${module.labels.id}-prefix-list"
  address_family = var.prefix_list_address_family
  max_entries    = var.prefix_list_max_entries

  dynamic "entry" {
    for_each = local.prefix_list_entries_capped
    content {
      cidr        = entry.value
      description = var.prefix_list_description
    }
  }

  tags = local.tags
}

resource "aws_vpc_security_group_ingress_rule" "this" {
  for_each = var.enable && (var.create_security_group || var.existing_security_group_id != "") ? local.ingress_rules : {}

  security_group_id            = local.security_group_id
  cidr_ipv4                    = each.value.cidr_ipv4
  cidr_ipv6                    = each.value.cidr_ipv6
  description                  = each.value.description
  from_port                    = each.value.from_port
  ip_protocol                  = each.value.ip_protocol
  prefix_list_id               = each.value.prefix_list_id
  referenced_security_group_id = each.value.referenced_security_group_id
  to_port                      = each.value.to_port
  tags                         = each.value.tags

  lifecycle {
    precondition {
      condition = alltrue([
        for rule in local.ingress_rules :
        rule.cidr_ipv4 != "0.0.0.0/0" || (
          rule.from_port != null &&
          rule.to_port != null &&
          contains([80, 443], rule.from_port) &&
          contains([80, 443], rule.to_port)
        )
      ])
      error_message = "Ingress rules using 0.0.0.0/0 must target ports 80 or 443 only."
    }
  }
}

resource "aws_vpc_security_group_egress_rule" "this" {
  for_each = var.enable && (var.create_security_group || var.existing_security_group_id != "") ? local.egress_rules : {}

  security_group_id            = local.security_group_id
  cidr_ipv4                    = each.value.cidr_ipv4
  cidr_ipv6                    = each.value.cidr_ipv6
  description                  = each.value.description
  from_port                    = each.value.from_port
  ip_protocol                  = each.value.ip_protocol
  prefix_list_id               = each.value.prefix_list_id
  referenced_security_group_id = each.value.referenced_security_group_id
  to_port                      = each.value.to_port
  tags                         = each.value.tags
}

output "security_group_id" {
  description = "Resolved security group ID"
  value       = local.security_group_id
}

output "prefix_list_id" {
  description = "Resolved managed prefix list ID"
  value       = try(local.resolved_prefix_list_ids[0], null)
}

output "vpc_id" {
  description = "Resolved VPC ID"
  value       = local.vpc_id
}

output "tags" {
  description = "Applied tags"
  value       = local.tags
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.0"
    }
    time = {
      source  = "hashicorp/time"
      version = "~> 0.9"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = {
      "kubernetes.io/cluster/demo-eks" = "owned"
    }
  }
}

locals {
  cluster_name       = "demo-eks"
  vpc_cidr           = "10.0.0.0/16"
  public_subnet_cidr = "10.0.0.0/24"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------
# Networking
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "demo-eks-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "demo-eks-igw"
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "demo-eks-public-1"
  }

  timeouts {
    create = "5m"
  }
}

resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name                                          = "demo-eks-private-${count.index + 1}"
    "kubernetes.io/role/internal-elb"             = "1"
    "kubernetes.io/cluster/${local.cluster_name}" = "shared"
  }

  timeouts {
    create = "5m"
  }
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "demo-eks-nat-eip"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  tags = {
    Name = "demo-eks-nat"
  }

  depends_on = [aws_internet_gateway.main]

  timeouts {
    create = "10m"
    delete = "10m"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "demo-eks-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id

  timeouts {
    create = "5m"
    update = "5m"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "demo-eks-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id

  timeouts {
    create = "5m"
    update = "5m"
  }
}

# ---------------------------------------------------------------------------
# KMS key for EKS secrets encryption (also used for the template bucket)
# ---------------------------------------------------------------------------

resource "aws_kms_key" "eks" {
  description             = "Customer managed key for demo-eks secrets encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableAccountAdmin"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowEksClusterRoleUseOfKey"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.eks_cluster_role.arn
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowS3ServiceUseOfKey"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:Decrypt",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "demo-eks-kms"
  }
}

resource "aws_kms_alias" "eks" {
  name          = "alias/demo-eks"
  target_key_id = aws_kms_key.eks.key_id
}

# ---------------------------------------------------------------------------
# IAM: EKS cluster role
# ---------------------------------------------------------------------------

resource "aws_iam_role" "eks_cluster_role" {
  name = "eksClusterRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "eksClusterRole"
  }
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  role       = aws_iam_role.eks_cluster_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "eks_vpc_resource_controller" {
  role       = aws_iam_role.eks_cluster_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSVPCResourceController"
}

resource "aws_iam_role_policy" "eks_cluster_kms" {
  name = "eks-cluster-kms"
  role = aws_iam_role.eks_cluster_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey"
        ]
        Resource = aws_kms_key.eks.arn
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# EKS control plane security group (explicit, Terraform-managed)
# ---------------------------------------------------------------------------

resource "aws_security_group" "eks_cluster_sg" {
  name        = "demo-eks-cluster-sg"
  description = "Control plane security group for the demo-eks cluster"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "demo-eks-cluster-sg"
  }

  timeouts {
    create = "5m"
    delete = "5m"
  }
}

# ---------------------------------------------------------------------------
# EKS control plane
# ---------------------------------------------------------------------------

resource "aws_eks_cluster" "demo" {
  name     = local.cluster_name
  role_arn = aws_iam_role.eks_cluster_role.arn
  version  = "1.30"

  bootstrap_self_managed_addons = false

  access_config {
    authentication_mode = "CONFIG_MAP"
  }

  vpc_config {
    subnet_ids              = aws_subnet.private[*].id
    security_group_ids      = [aws_security_group.eks_cluster_sg.id]
    endpoint_public_access  = false
    endpoint_private_access = true
  }

  encryption_config {
    provider {
      key_arn = aws_kms_key.eks.arn
    }
    resources = ["secrets"]
  }

  tags = {
    Name = local.cluster_name
  }

  timeouts {
    create = "5m"
    update = "5m"
    delete = "5m"
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_iam_role_policy_attachment.eks_vpc_resource_controller,
    aws_iam_role_policy.eks_cluster_kms,
  ]
}

# ---------------------------------------------------------------------------
# SSH key pair for worker nodes
# ---------------------------------------------------------------------------

resource "tls_private_key" "eks" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "local_file" "eks_key" {
  content         = tls_private_key.eks.private_key_pem
  filename        = pathexpand("~/.ssh/eks-aws.pem")
  file_permission = "0600"
}

resource "aws_key_pair" "eks_kp" {
  key_name   = "eks_kp"
  public_key = tls_private_key.eks.public_key_openssh

  tags = {
    Name = "eks_kp"
  }
}

# ---------------------------------------------------------------------------
# Node security group
# ---------------------------------------------------------------------------

resource "aws_security_group" "node_sg" {
  name        = "demo-eks-node-sg"
  description = "Security group for demo-eks unmanaged worker nodes"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "demo-eks-node-sg"
  }

  timeouts {
    create = "5m"
    delete = "5m"
  }
}

resource "aws_security_group_rule" "node_ingress_self" {
  type              = "ingress"
  description       = "Unrestricted communication between worker nodes"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  self              = true
  security_group_id = aws_security_group.node_sg.id

  timeouts {
    create = "5m"
  }
}

resource "aws_security_group_rule" "node_egress_vpc" {
  type              = "egress"
  description       = "Allow outbound traffic within the VPC CIDR only"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.node_sg.id

  timeouts {
    create = "5m"
  }
}

resource "aws_security_group_rule" "node_ingress_cluster_https" {
  type                     = "ingress"
  description              = "Control plane to node HTTPS"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.eks_cluster_sg.id
  security_group_id        = aws_security_group.node_sg.id

  timeouts {
    create = "5m"
  }
}

resource "aws_security_group_rule" "node_ingress_cluster_kubelet" {
  type                     = "ingress"
  description              = "Control plane to node kubelet"
  from_port                = 1025
  to_port                  = 65535
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.eks_cluster_sg.id
  security_group_id        = aws_security_group.node_sg.id

  timeouts {
    create = "5m"
  }
}

resource "aws_security_group_rule" "node_egress_cluster_https" {
  type                     = "egress"
  description              = "Node to control plane HTTPS"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.eks_cluster_sg.id
  security_group_id        = aws_security_group.node_sg.id

  timeouts {
    create = "5m"
  }
}

resource "aws_security_group_rule" "node_egress_cluster_kubelet" {
  type                     = "egress"
  description              = "Node to control plane kubelet"
  from_port                = 1025
  to_port                  = 65535
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.eks_cluster_sg.id
  security_group_id        = aws_security_group.node_sg.id

  timeouts {
    create = "5m"
  }
}

# ---------------------------------------------------------------------------
# IAM: worker node role and instance profile
# ---------------------------------------------------------------------------

resource "aws_iam_role" "eks_node_role" {
  name = "eks-demo-node"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "eks-demo-node"
  }
}

resource "aws_iam_role_policy_attachment" "node_worker_policy" {
  role       = aws_iam_role.eks_node_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "node_cni_policy" {
  role       = aws_iam_role.eks_node_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
}

resource "aws_iam_role_policy_attachment" "node_ecr_policy" {
  role       = aws_iam_role.eks_node_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

resource "aws_iam_role_policy_attachment" "node_ssm_policy" {
  role       = aws_iam_role.eks_node_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "eks_node_profile" {
  name = "demo-eks-node-profile"
  role = aws_iam_role.eks_node_role.name
}

# ---------------------------------------------------------------------------
# Launch template for the worker nodes
# ---------------------------------------------------------------------------

data "aws_ssm_parameter" "eks_ami" {
  name = "/aws/service/eks/optimized-ami/1.30/amazon-linux-2/recommended/image_id"
}

resource "aws_launch_template" "eks_node_lt" {
  name          = "demo-eks-node-lt"
  image_id      = data.aws_ssm_parameter.eks_ami.value
  instance_type = "t3.medium"
  key_name      = aws_key_pair.eks_kp.key_name

  vpc_security_group_ids = [aws_security_group.node_sg.id]

  iam_instance_profile {
    name = aws_iam_instance_profile.eks_node_profile.name
  }

  block_device_mappings {
    device_name = "/dev/xvda"

    ebs {
      volume_size           = 30
      volume_type           = "gp2"
      delete_on_termination = true
    }
  }

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
  }

  user_data = base64encode(<<-EOF
    #!/bin/bash
    set -o xtrace
    /etc/eks/bootstrap.sh ${local.cluster_name}
    /opt/aws/bin/cfn-signal --stack eks-cluster-stack --resource NodeGroupASG --region ${data.aws_region.current.name}
  EOF
  )

  tag_specifications {
    resource_type = "instance"

    tags = {
      Name = "demo-eks-node"
    }
  }

  tag_specifications {
    resource_type = "volume"

    tags = {
      Name = "demo-eks-node-volume"
    }
  }

  tags = {
    Name = "demo-eks-node-lt"
  }
}

resource "time_sleep" "wait_for_lt" {
  create_duration = "30s"

  depends_on = [aws_launch_template.eks_node_lt]
}

# ---------------------------------------------------------------------------
# S3 bucket + object delivering the CloudFormation template
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "cfn_templates" {
  bucket = "demo-eks-cfn-templates-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}"

  tags = {
    Name = "demo-eks-cfn-templates"
  }

  timeouts {
    create = "5m"
    update = "5m"
    delete = "5m"
  }
}

resource "aws_s3_bucket_public_access_block" "cfn_templates" {
  bucket = aws_s3_bucket.cfn_templates.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cfn_templates" {
  bucket = aws_s3_bucket.cfn_templates.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.eks.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "cfn_templates" {
  bucket = aws_s3_bucket.cfn_templates.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_object" "cfn_template" {
  bucket = aws_s3_bucket.cfn_templates.id
  key    = "eks-cluster-stack.json"

  content = jsonencode({
    AWSTemplateFormatVersion = "2010-09-09"
    Description              = "Auto Scaling Group for demo-eks unmanaged worker nodes"

    Parameters = {
      LaunchTemplateId      = { Type = "String" }
      LaunchTemplateVersion = { Type = "String" }
      SubnetIds             = { Type = "String" }
    }

    Resources = {
      NodeGroupASG = {
        Type = "AWS::AutoScaling::AutoScalingGroup"
        Properties = {
          MinSize           = "1"
          DesiredCapacity   = "3"
          MaxSize           = "4"
          VPCZoneIdentifier = { Ref = "SubnetIds" }
          LaunchTemplate = {
            LaunchTemplateId = { Ref = "LaunchTemplateId" }
            Version          = { Ref = "LaunchTemplateVersion" }
          }
        }
      }
    }

    Outputs = {
      AsgId = {
        Value = { Ref = "NodeGroupASG" }
      }
    }
  })

  server_side_encryption = "AES256"

  tags = {
    Name = "demo-eks-cfn-template"
  }
}

# ---------------------------------------------------------------------------
# CloudFormation stack driving the Auto Scaling Group
# ---------------------------------------------------------------------------

resource "aws_cloudformation_stack" "eks_cluster_stack" {
  name             = "eks-cluster-stack"
  on_failure       = "DO_NOTHING"
  disable_rollback = true

  template_url = "https://${aws_s3_bucket.cfn_templates.bucket_regional_domain_name}/${aws_s3_object.cfn_template.key}"

  parameters = {
    LaunchTemplateId      = aws_launch_template.eks_node_lt.id
    LaunchTemplateVersion = aws_launch_template.eks_node_lt.latest_version
    SubnetIds             = join(",", aws_subnet.private[*].id)
  }

  timeouts {
    create = "8m"
    update = "8m"
    delete = "8m"
  }

  depends_on = [
    time_sleep.wait_for_lt,
    aws_iam_instance_profile.eks_node_profile,
    aws_s3_object.cfn_template,
  ]
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "node_instance_role_arn" {
  description = "ARN of the worker node IAM role"
  value       = aws_iam_role.eks_node_role.arn
}

output "node_security_group_id" {
  description = "ID of the worker node security group"
  value       = aws_security_group.node_sg.id
}

output "asg_id" {
  description = "ID of the Auto Scaling Group created by the CloudFormation stack"
  value       = aws_cloudformation_stack.eks_cluster_stack.outputs["AsgId"]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.0"
    }
  }
}

# The default "aws" provider configuration (us-east-1) is injected by the
# deployment harness. The aliased provider below targets the second,
# disaster-recovery region used for cross-region replication.
provider "aws" {
  alias  = "replica"
  region = var.replica_region
}

###############################################################################
# Data sources - provider / account metadata only (greenfield account)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Input variables
###############################################################################

variable "name_prefix" {
  description = "Prefix used to name every state-management resource."
  type        = string
  default     = "eks"
}

variable "replica_region" {
  description = "Secondary region that receives replicated Terraform state objects."
  type        = string
  default     = "us-west-2"
}

variable "environment" {
  description = "Environment label applied to every taggable resource."
  type        = string
  default     = "prod"
}

variable "owner" {
  description = "Owning team label applied to every taggable resource."
  type        = string
  default     = "platform-engineering"
}

variable "stack_config" {
  description = "Map of EKS stack name => AWS region. One lock table, IAM role/policy and generated backend.tf file are produced per entry."
  type        = map(string)
  default = {
    "stack-a" = "us-east-1"
    "stack-b" = "us-west-2"
  }
}

variable "noncurrent_version_expiration_days" {
  description = "Days after which noncurrent object versions are expired from the state buckets."
  type        = number
  default     = 90
}

###############################################################################
# Locals
###############################################################################

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  primary_region = data.aws_region.current.name

  primary_stacks = {
    for name, region in var.stack_config : name => region if region == local.primary_region
  }

  replica_stacks = {
    for name, region in var.stack_config : name => region if region == var.replica_region
  }

  state_bucket_name   = "${var.name_prefix}-tf-state-${local.account_id}-${local.primary_region}"
  replica_bucket_name = "${var.name_prefix}-tf-state-${local.account_id}-${var.replica_region}"

  replication_role_name = "${var.name_prefix}-tf-state-replication-role"
  replication_role_arn  = "arn:${local.partition}:iam::${local.account_id}:role/${local.replication_role_name}"

  lock_table_names = merge(
    { for name in keys(local.primary_stacks) : name => aws_dynamodb_table.primary_locks[name].name },
    { for name in keys(local.replica_stacks) : name => aws_dynamodb_table.replica_locks[name].name },
  )

  lock_table_arns = merge(
    { for name in keys(local.primary_stacks) : name => aws_dynamodb_table.primary_locks[name].arn },
    { for name in keys(local.replica_stacks) : name => aws_dynamodb_table.replica_locks[name].arn },
  )

  tags = {
    Project     = var.name_prefix
    Purpose     = "terraform-state"
    ManagedBy   = "Terraform"
    Environment = var.environment
    Owner       = var.owner
  }
}

###############################################################################
# Primary KMS key (us-east-1)
###############################################################################

data "aws_iam_policy_document" "state_kms" {
  statement {
    sid    = "EnableAccountRootAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions = [
      "kms:CancelKeyDeletion",
      "kms:CreateAlias",
      "kms:CreateGrant",
      "kms:Decrypt",
      "kms:DeleteAlias",
      "kms:DescribeKey",
      "kms:DisableKey",
      "kms:DisableKeyRotation",
      "kms:EnableKey",
      "kms:EnableKeyRotation",
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:GetKeyPolicy",
      "kms:GetKeyRotationStatus",
      "kms:ListAliases",
      "kms:ListGrants",
      "kms:ListKeyPolicies",
      "kms:ListResourceTags",
      "kms:PutKeyPolicy",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
      "kms:RetireGrant",
      "kms:RevokeGrant",
      "kms:ScheduleKeyDeletion",
      "kms:TagResource",
      "kms:UntagResource",
      "kms:UpdateAlias",
      "kms:UpdateKeyDescription",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowS3ServiceUseViaService"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["s3.${local.primary_region}.amazonaws.com"]
    }
  }

  statement {
    sid    = "AllowReplicationRoleDecrypt"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [local.replication_role_arn]
    }

    actions   = ["kms:Decrypt", "kms:DescribeKey"]
    resources = ["*"]
  }
}

resource "aws_kms_key" "state" {
  description             = "KMS key for Terraform remote state stored in ${local.state_bucket_name}"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.state_kms.json

  tags = merge(local.tags, { Name = "${var.name_prefix}-tf-state" })
}

resource "aws_kms_alias" "state" {
  name          = "alias/${var.name_prefix}-tf-state"
  target_key_id = aws_kms_key.state.key_id
}

###############################################################################
# Replica KMS key (second region)
###############################################################################

data "aws_iam_policy_document" "replica_kms" {
  statement {
    sid    = "EnableAccountRootAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions = [
      "kms:CancelKeyDeletion",
      "kms:CreateAlias",
      "kms:CreateGrant",
      "kms:Decrypt",
      "kms:DeleteAlias",
      "kms:DescribeKey",
      "kms:DisableKey",
      "kms:DisableKeyRotation",
      "kms:EnableKey",
      "kms:EnableKeyRotation",
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:GetKeyPolicy",
      "kms:GetKeyRotationStatus",
      "kms:ListAliases",
      "kms:ListGrants",
      "kms:ListKeyPolicies",
      "kms:ListResourceTags",
      "kms:PutKeyPolicy",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
      "kms:RetireGrant",
      "kms:RevokeGrant",
      "kms:ScheduleKeyDeletion",
      "kms:TagResource",
      "kms:UntagResource",
      "kms:UpdateAlias",
      "kms:UpdateKeyDescription",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowS3ServiceUseViaService"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["s3.${var.replica_region}.amazonaws.com"]
    }
  }

  statement {
    sid    = "AllowReplicationRoleEncrypt"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [local.replication_role_arn]
    }

    actions   = ["kms:Encrypt", "kms:GenerateDataKey", "kms:DescribeKey"]
    resources = ["*"]
  }
}

resource "aws_kms_key" "replica" {
  provider = aws.replica

  description             = "KMS key for replicated Terraform remote state stored in ${local.replica_bucket_name}"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.replica_kms.json

  tags = merge(local.tags, { Name = "${var.name_prefix}-tf-state-replica" })
}

resource "aws_kms_alias" "replica" {
  provider = aws.replica

  name          = "alias/${var.name_prefix}-tf-state-replica"
  target_key_id = aws_kms_key.replica.key_id
}

###############################################################################
# Primary state bucket (us-east-1)
###############################################################################

resource "aws_s3_bucket" "state" {
  bucket = local.state_bucket_name

  tags = merge(local.tags, { Name = local.state_bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.state.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

data "aws_iam_policy_document" "state_bucket" {
  statement {
    sid    = "DenyNonTLSRequests"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.state.arn,
      "${aws_s3_bucket.state.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid    = "DenyUnencryptedObjectUploads"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:PutObject"]

    resources = ["${aws_s3_bucket.state.arn}/*"]

    condition {
      test     = "StringNotEquals"
      variable = "s3:x-amz-server-side-encryption"
      values   = ["aws:kms"]
    }
  }

  statement {
    sid    = "DenyIncorrectEncryptionKey"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:PutObject"]

    resources = ["${aws_s3_bucket.state.arn}/*"]

    condition {
      test     = "StringNotEquals"
      variable = "s3:x-amz-server-side-encryption-aws-kms-key-id"
      values   = [aws_kms_key.state.arn]
    }
  }
}

resource "aws_s3_bucket_policy" "state" {
  bucket = aws_s3_bucket.state.id
  policy = data.aws_iam_policy_document.state_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.state]
}

resource "aws_s3_bucket_lifecycle_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    id     = "state-bucket-hygiene"
    status = "Enabled"

    filter {}

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }

    noncurrent_version_expiration {
      noncurrent_days = var.noncurrent_version_expiration_days
    }
  }
}

###############################################################################
# Replica state bucket (second region)
###############################################################################

resource "aws_s3_bucket" "replica" {
  provider = aws.replica
  bucket   = local.replica_bucket_name

  tags = merge(local.tags, { Name = local.replica_bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.replica.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

data "aws_iam_policy_document" "replica_bucket" {
  statement {
    sid    = "DenyNonTLSRequests"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.replica.arn,
      "${aws_s3_bucket.replica.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id
  policy   = data.aws_iam_policy_document.replica_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.replica]
}

resource "aws_s3_bucket_lifecycle_configuration" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id

  rule {
    id     = "state-bucket-hygiene"
    status = "Enabled"

    filter {}

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }

    noncurrent_version_expiration {
      noncurrent_days = var.noncurrent_version_expiration_days
    }
  }
}

###############################################################################
# Replication IAM role + least-privilege policy
###############################################################################

data "aws_iam_policy_document" "replication_assume_role" {
  statement {
    sid     = "AllowS3ReplicationServiceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_iam_role" "replication" {
  name               = local.replication_role_name
  assume_role_policy = data.aws_iam_policy_document.replication_assume_role.json

  tags = merge(local.tags, { Name = local.replication_role_name })
}

data "aws_iam_policy_document" "replication" {
  statement {
    sid    = "SourceBucketLevelPermissions"
    effect = "Allow"

    actions = [
      "s3:GetReplicationConfiguration",
      "s3:GetBucketVersioning",
      "s3:GetBucketLocation",
      "s3:ListBucket",
    ]

    resources = [aws_s3_bucket.state.arn]
  }

  statement {
    sid    = "SourceObjectLevelPermissions"
    effect = "Allow"

    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
    ]

    resources = ["${aws_s3_bucket.state.arn}/*"]
  }

  statement {
    sid    = "DestinationObjectLevelPermissions"
    effect = "Allow"

    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
    ]

    resources = ["${aws_s3_bucket.replica.arn}/*"]
  }

  statement {
    sid    = "DecryptSourceObjects"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
    ]

    resources = [aws_kms_key.state.arn]
  }

  statement {
    sid    = "EncryptReplicaObjects"
    effect = "Allow"

    actions = [
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]

    resources = [aws_kms_key.replica.arn]
  }
}

resource "aws_iam_policy" "replication" {
  name        = "${var.name_prefix}-tf-state-replication-policy"
  description = "Least-privilege policy allowing S3 to replicate KMS-encrypted Terraform state to the replica bucket"
  policy      = data.aws_iam_policy_document.replication.json

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "replication" {
  role       = aws_iam_role.replication.name
  policy_arn = aws_iam_policy.replication.arn
}

###############################################################################
# Cross-region replication configuration on the primary bucket
###############################################################################

resource "aws_s3_bucket_replication_configuration" "state" {
  bucket = aws_s3_bucket.state.id
  role   = aws_iam_role.replication.arn

  rule {
    id     = "replicate-terraform-state-to-replica-region"
    status = "Enabled"

    filter {}

    destination {
      bucket        = aws_s3_bucket.replica.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica.arn
      }
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    delete_marker_replication {
      status = "Disabled"
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.state,
    aws_s3_bucket_versioning.replica,
    aws_iam_role_policy_attachment.replication,
  ]
}

###############################################################################
# Per-stack DynamoDB state lock tables
###############################################################################

resource "aws_dynamodb_table" "primary_locks" {
  for_each = local.primary_stacks

  name         = "${var.name_prefix}-${each.key}-lock"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  point_in_time_recovery {
    enabled = true
  }

  tags = merge(local.tags, { Name = "${var.name_prefix}-${each.key}-lock" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dynamodb_table" "replica_locks" {
  provider = aws.replica
  for_each = local.replica_stacks

  name         = "${var.name_prefix}-${each.key}-lock"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  point_in_time_recovery {
    enabled = true
  }

  tags = merge(local.tags, { Name = "${var.name_prefix}-${each.key}-lock" })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Per-stack IAM role + stack-scoped least-privilege policy
###############################################################################

data "aws_iam_policy_document" "stack_assume_role" {
  statement {
    sid     = "AllowAccountPrincipalsToAssumeStackRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }
}

resource "aws_iam_role" "stack" {
  for_each = var.stack_config

  name               = "${var.name_prefix}-${each.key}-state-role"
  assume_role_policy = data.aws_iam_policy_document.stack_assume_role.json

  tags = merge(local.tags, { Name = "${var.name_prefix}-${each.key}-state-role" })
}

data "aws_iam_policy_document" "stack" {
  for_each = var.stack_config

  statement {
    sid    = "StackStateLockTableAccess"
    effect = "Allow"

    actions = [
      "dynamodb:DescribeTable",
      "dynamodb:GetItem",
      "dynamodb:PutItem",
      "dynamodb:DeleteItem",
      "dynamodb:UpdateItem",
    ]

    resources = [local.lock_table_arns[each.key]]
  }

  statement {
    sid    = "StackStateBucketList"
    effect = "Allow"

    actions = [
      "s3:ListBucket",
      "s3:GetBucketLocation",
    ]

    resources = [aws_s3_bucket.state.arn]

    condition {
      test     = "StringLike"
      variable = "s3:prefix"
      values = [
        each.key,
        "${each.key}/*",
      ]
    }
  }

  statement {
    sid    = "StackStateObjectAccess"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
    ]

    resources = ["${aws_s3_bucket.state.arn}/${each.key}/*"]
  }

  statement {
    sid    = "StackStateKmsAccess"
    effect = "Allow"

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:GenerateDataKey",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
    ]

    resources = [aws_kms_key.state.arn]
  }
}

resource "aws_iam_policy" "stack" {
  for_each = var.stack_config

  name        = "${var.name_prefix}-${each.key}-state-policy"
  description = "Stack-scoped access to the ${each.key} state lock table, state prefix and state KMS key"
  policy      = data.aws_iam_policy_document.stack[each.key].json

  tags = merge(local.tags, { Name = "${var.name_prefix}-${each.key}-state-policy" })
}

resource "aws_iam_role_policy_attachment" "stack" {
  for_each = var.stack_config

  role       = aws_iam_role.stack[each.key].name
  policy_arn = aws_iam_policy.stack[each.key].arn
}

###############################################################################
# Generated per-stack backend.tf files
###############################################################################

resource "local_file" "stack_backend" {
  for_each = var.stack_config

  filename = "eks-stacks/${each.key}/backend.tf"

  content = <<-EOT
    terraform {
      backend "s3" {
        bucket               = "${aws_s3_bucket.state.id}"
        key                  = "${each.key}/terraform.tfstate"
        region               = "${each.value}"
        dynamodb_table       = "${local.lock_table_names[each.key]}"
        encrypt              = true
        kms_key_id           = "${aws_kms_key.state.arn}"
        workspace_key_prefix = "workspaces"
      }
    }
  EOT

  file_permission      = "0600"
  directory_permission = "0755"
}

###############################################################################
# Outputs
###############################################################################

output "primary_state_bucket_name" {
  description = "Name of the primary (us-east-1) Terraform state bucket."
  value       = aws_s3_bucket.state.id
}

output "primary_state_bucket_arn" {
  description = "ARN of the primary Terraform state bucket."
  value       = aws_s3_bucket.state.arn
}

output "replica_state_bucket_name" {
  description = "Name of the replica (disaster recovery) Terraform state bucket."
  value       = aws_s3_bucket.replica.id
}

output "replica_state_bucket_arn" {
  description = "ARN of the replica Terraform state bucket."
  value       = aws_s3_bucket.replica.arn
}

output "state_kms_key_arn" {
  description = "ARN of the primary state KMS key."
  value       = aws_kms_key.state.arn
}

output "state_kms_key_alias" {
  description = "Alias of the primary state KMS key."
  value       = aws_kms_alias.state.name
}

output "replica_kms_key_arn" {
  description = "ARN of the replica state KMS key."
  value       = aws_kms_key.replica.arn
}

output "replica_kms_key_alias" {
  description = "Alias of the replica state KMS key."
  value       = aws_kms_alias.replica.name
}

output "replication_role_arn" {
  description = "ARN of the S3 cross-region replication role."
  value       = aws_iam_role.replication.arn
}

output "stack_lock_table_names" {
  description = "Map of stack name => DynamoDB state lock table name."
  value       = local.lock_table_names
}

output "stack_state_role_arns" {
  description = "Map of stack name => per-stack state access IAM role ARN."
  value       = { for name, role in aws_iam_role.stack : name => role.arn }
}

output "stack_backend_file_paths" {
  description = "Map of stack name => generated backend.tf file path."
  value       = { for name, file in local_file.stack_backend : name => file.filename }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.99.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

locals {
  tags = {
    Project     = "websocket-to-sqs"
    Environment = "dev"
  }
}

data "aws_caller_identity" "current" {}

resource "random_pet" "this" {
  length = 2
}

data "aws_iam_policy_document" "assume_role" {
  statement {
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["apigateway.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "apigateway" {
  name               = "${random_pet.this.id}-apigateway-role"
  assume_role_policy = data.aws_iam_policy_document.assume_role.json
  tags               = local.tags
}

data "aws_iam_policy_document" "kms" {
  statement {
    sid    = "Enable IAM User Permissions"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "Allow SQS to use the key"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["sqs.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey"
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }

  statement {
    sid    = "Allow API Gateway execution role to use the key"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.apigateway.arn]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey"
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key" "queue" {
  description             = "KMS key for SQS queue encryption (${random_pet.this.id})"
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms.json
  deletion_window_in_days = 7
  tags                    = local.tags
}

resource "aws_kms_alias" "queue" {
  name          = "alias/${random_pet.this.id}-sqs"
  target_key_id = aws_kms_key.queue.key_id
}

resource "aws_sqs_queue" "main" {
  name                              = "${random_pet.this.id}-queue"
  kms_master_key_id                 = aws_kms_key.queue.arn
  kms_data_key_reuse_period_seconds = 300
  tags                              = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "apigateway_policy" {
  statement {
    effect = "Allow"

    actions = [
      "sqs:SendMessage",
      "sqs:GetQueueAttributes"
    ]

    resources = [aws_sqs_queue.main.arn]
  }

  statement {
    effect = "Allow"

    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents"
    ]

    resources = [
      aws_cloudwatch_log_group.websocket.arn,
      "${aws_cloudwatch_log_group.websocket.arn}:*"
    ]
  }
}

resource "aws_iam_role_policy" "apigateway" {
  name   = "${random_pet.this.id}-apigateway-policy"
  role   = aws_iam_role.apigateway.id
  policy = data.aws_iam_policy_document.apigateway_policy.json
}

resource "aws_cloudwatch_log_group" "websocket" {
  name              = "/aws/apigateway/${random_pet.this.id}-websocket"
  retention_in_days = 1
  tags              = local.tags
}

resource "aws_apigatewayv2_api" "websocket" {
  name                       = random_pet.this.id
  protocol_type              = "WEBSOCKET"
  route_selection_expression = "$request.body.action"
  tags                       = local.tags
}

resource "aws_apigatewayv2_integration" "connect" {
  api_id               = aws_apigatewayv2_api.websocket.id
  integration_type     = "MOCK"
  integration_method   = "POST"
  passthrough_behavior = "WHEN_NO_TEMPLATES"

  request_templates = {
    "$default" = jsonencode({ statusCode = 200 })
  }
}

resource "aws_apigatewayv2_route" "connect" {
  api_id    = aws_apigatewayv2_api.websocket.id
  route_key = "$connect"
  target    = "integrations/${aws_apigatewayv2_integration.connect.id}"
}

resource "aws_apigatewayv2_integration_response" "connect" {
  api_id                   = aws_apigatewayv2_api.websocket.id
  integration_id           = aws_apigatewayv2_integration.connect.id
  integration_response_key = "/200/"
}

resource "aws_apigatewayv2_route_response" "connect" {
  api_id             = aws_apigatewayv2_api.websocket.id
  route_id           = aws_apigatewayv2_route.connect.id
  route_response_key = "$default"
}

resource "aws_apigatewayv2_integration" "send_message" {
  api_id               = aws_apigatewayv2_api.websocket.id
  integration_type     = "AWS_PROXY"
  integration_subtype  = "SQS-SendMessage"
  integration_method   = "POST"
  integration_uri      = aws_sqs_queue.main.arn
  credentials_arn      = aws_iam_role.apigateway.arn
  passthrough_behavior = "WHEN_NO_MATCH"

  request_templates = {
    "$default" = jsonencode({
      QueueUrl    = aws_sqs_queue.main.url
      MessageBody = "$request.body"
    })
  }

  depends_on = [
    aws_iam_role.apigateway,
    aws_iam_role_policy.apigateway
  ]
}

resource "aws_apigatewayv2_route" "default" {
  api_id    = aws_apigatewayv2_api.websocket.id
  route_key = "$default"
  target    = "integrations/${aws_apigatewayv2_integration.send_message.id}"
}

resource "aws_apigatewayv2_integration_response" "send_message" {
  api_id                   = aws_apigatewayv2_api.websocket.id
  integration_id           = aws_apigatewayv2_integration.send_message.id
  integration_response_key = "/200/"

  response_templates = {
    "$default" = "$input.body"
  }
}

resource "aws_apigatewayv2_route_response" "default" {
  api_id             = aws_apigatewayv2_api.websocket.id
  route_id           = aws_apigatewayv2_route.default.id
  route_response_key = "$default"
}

resource "aws_apigatewayv2_integration" "disconnect" {
  api_id               = aws_apigatewayv2_api.websocket.id
  integration_type     = "AWS_PROXY"
  integration_subtype  = "SQS-SendMessage"
  integration_method   = "POST"
  integration_uri      = aws_sqs_queue.main.arn
  credentials_arn      = aws_iam_role.apigateway.arn
  passthrough_behavior = "WHEN_NO_MATCH"

  request_templates = {
    "$default" = jsonencode({
      QueueUrl    = aws_sqs_queue.main.url
      MessageBody = "Client disconnected"
    })
  }

  depends_on = [
    aws_iam_role.apigateway,
    aws_iam_role_policy.apigateway
  ]
}

resource "aws_apigatewayv2_route" "disconnect" {
  api_id    = aws_apigatewayv2_api.websocket.id
  route_key = "$disconnect"
  target    = "integrations/${aws_apigatewayv2_integration.disconnect.id}"
}

resource "aws_api_gateway_account" "this" {
  cloudwatch_role_arn = aws_iam_role.apigateway.arn
}

resource "aws_apigatewayv2_stage" "dev" {
  api_id      = aws_apigatewayv2_api.websocket.id
  name        = "dev"
  auto_deploy = true

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.websocket.arn
    format = jsonencode({
      requestId        = "$context.requestId"
      sourceIp         = "$context.identity.sourceIp"
      routeKey         = "$context.routeKey"
      status           = "$context.status"
      integrationError = "$context.integrationErrorMessage"
    })
  }

  tags = local.tags

  depends_on = [
    aws_api_gateway_account.this,
    aws_iam_role_policy.apigateway
  ]
}

output "websocket_endpoint" {
  value = aws_apigatewayv2_stage.dev.invoke_url
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "us_west_2"
  region = "us-west-2"
}

data "aws_caller_identity" "current" {}

locals {
  primary_bucket_name = "${var.bucket_name_primary}-${data.aws_caller_identity.current.account_id}"
  second_bucket_name  = "${var.bucket_name_secondary}-${data.aws_caller_identity.current.account_id}"
}

variable "bucket_name_primary" {
  description = "Base name for the primary replicated S3 bucket."
  type        = string
  default     = "example1"
}

variable "bucket_name_secondary" {
  description = "Base name for the secondary replicated S3 bucket."
  type        = string
  default     = "example2"
}

variable "mrap_name" {
  description = "Name of the S3 Multi-Region Access Point."
  type        = string
  default     = "example-mrap"
}

###############################################################################
# KMS keys
###############################################################################

data "aws_iam_policy_document" "kms_primary" {
  statement {
    sid    = "EnableRootAccountAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowReplicationRoleDecrypt"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.s3_replication.arn]
    }

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
    ]

    resources = ["*"]
  }
}

data "aws_iam_policy_document" "kms_secondary" {
  statement {
    sid    = "EnableRootAccountAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowReplicationRoleEncrypt"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.s3_replication.arn]
    }

    actions = [
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key" "primary" {
  description             = "SSE-KMS CMK for the primary replicated S3 bucket."
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_primary.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "primary" {
  name          = "alias/${var.bucket_name_primary}-s3"
  target_key_id = aws_kms_key.primary.key_id
}

resource "aws_kms_key" "secondary" {
  provider                = aws.us_west_2
  description             = "SSE-KMS CMK for the secondary replicated S3 bucket."
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_secondary.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "secondary" {
  provider      = aws.us_west_2
  name          = "alias/${var.bucket_name_secondary}-s3"
  target_key_id = aws_kms_key.secondary.key_id
}

###############################################################################
# S3 buckets
###############################################################################

resource "aws_s3_bucket" "primary" {
  bucket = local.primary_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "secondary" {
  provider = aws.us_west_2
  bucket   = local.second_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "primary" {
  bucket = aws_s3_bucket.primary.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_versioning" "secondary" {
  provider = aws.us_west_2
  bucket   = aws_s3_bucket.secondary.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "primary" {
  bucket = aws_s3_bucket.primary.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_ownership_controls" "secondary" {
  provider = aws.us_west_2
  bucket   = aws_s3_bucket.secondary.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_public_access_block" "primary" {
  bucket = aws_s3_bucket.primary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "secondary" {
  provider = aws.us_west_2
  bucket   = aws_s3_bucket.secondary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.primary.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "secondary" {
  provider = aws.us_west_2
  bucket   = aws_s3_bucket.secondary.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.secondary.arn
    }

    bucket_key_enabled = true
  }
}

###############################################################################
# Replication IAM role
###############################################################################

data "aws_iam_policy_document" "s3_replication_assume_role" {
  statement {
    sid     = "AllowS3ServiceAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "s3_replication" {
  name               = "${var.bucket_name_primary}-s3-replication-role"
  assume_role_policy = data.aws_iam_policy_document.s3_replication_assume_role.json
}

data "aws_iam_policy_document" "s3_replication" {
  statement {
    sid    = "SourceAndDestinationBucketPermissions"
    effect = "Allow"

    actions = [
      "s3:GetBucketVersioning",
      "s3:GetReplicationConfiguration",
      "s3:ListBucket",
    ]

    resources = [
      aws_s3_bucket.primary.arn,
      aws_s3_bucket.secondary.arn,
    ]
  }

  statement {
    sid    = "SourceObjectReadPermissions"
    effect = "Allow"

    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionTagging",
    ]

    resources = [
      "${aws_s3_bucket.primary.arn}/*",
      "${aws_s3_bucket.secondary.arn}/*",
    ]
  }

  statement {
    sid    = "DestinationObjectWritePermissions"
    effect = "Allow"

    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
    ]

    resources = [
      "${aws_s3_bucket.primary.arn}/*",
      "${aws_s3_bucket.secondary.arn}/*",
    ]
  }

  statement {
    sid    = "SourceKmsDecryptPermissions"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
    ]

    resources = [aws_kms_key.primary.arn]
  }

  statement {
    sid    = "DestinationKmsEncryptPermissions"
    effect = "Allow"

    actions = [
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]

    resources = [aws_kms_key.secondary.arn]
  }
}

resource "aws_iam_role_policy" "s3_replication" {
  name   = "${var.bucket_name_primary}-s3-replication-policy"
  role   = aws_iam_role.s3_replication.id
  policy = data.aws_iam_policy_document.s3_replication.json
}

###############################################################################
# Replication configuration
###############################################################################

resource "aws_s3_bucket_replication_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id
  role   = aws_iam_role.s3_replication.arn

  rule {
    id     = "replicate-all-kms-objects"
    status = "Enabled"

    filter {
      prefix = ""
    }

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.secondary.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.secondary.arn
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.primary,
    aws_s3_bucket_versioning.secondary,
  ]
}

###############################################################################
# Multi-Region Access Point
###############################################################################

resource "aws_s3control_multi_region_access_point" "mrap" {
  provider = aws.us_west_2

  details {
    name = var.mrap_name

    region {
      bucket = aws_s3_bucket.primary.id
    }

    region {
      bucket = aws_s3_bucket.secondary.id
    }
  }
}

resource "aws_s3control_multi_region_access_point_policy" "mrap" {
  provider = aws.us_west_2

  details {
    name   = var.mrap_name
    policy = data.aws_iam_policy_document.mrap.json
  }
}

data "aws_iam_policy_document" "mrap" {
  statement {
    sid    = "AllowOwningAccountGetAndPut"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions = [
      "s3:GetObject",
      "s3:PutObject",
    ]

    resources = ["${aws_s3control_multi_region_access_point.mrap.arn}/object/*"]
  }

  statement {
    sid    = "DenyAllOtherPrincipals"
    effect = "Deny"

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    actions = [
      "s3:GetObject",
      "s3:PutObject",
    ]

    resources = ["${aws_s3control_multi_region_access_point.mrap.arn}/object/*"]

    condition {
      test     = "StringNotEquals"
      variable = "aws:PrincipalAccount"

      values = [data.aws_caller_identity.current.account_id]
    }
  }
}

###############################################################################
# Outputs
###############################################################################

output "mrap_alias" {
  description = "Alias (hostname) of the S3 Multi-Region Access Point."
  value       = aws_s3control_multi_region_access_point.mrap.alias
}

output "mrap_arn" {
  description = "ARN of the S3 Multi-Region Access Point."
  value       = aws_s3control_multi_region_access_point.mrap.arn
}

output "primary_bucket_name" {
  description = "Name of the primary replicated S3 bucket."
  value       = aws_s3_bucket.primary.bucket
}

output "primary_bucket_arn" {
  description = "ARN of the primary replicated S3 bucket."
  value       = aws_s3_bucket.primary.arn
}

output "secondary_bucket_name" {
  description = "Name of the secondary replicated S3 bucket."
  value       = aws_s3_bucket.secondary.bucket
}

output "secondary_bucket_arn" {
  description = "ARN of the secondary replicated S3 bucket."
  value       = aws_s3_bucket.secondary.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source = "hashicorp/aws"
      # Keep the ~> 5.0 series pin required by the template objectives, while
      # excluding the specific v5.100.0 artifact that was locked by a
      # concurrent provider process (ETXTBSY on the shared plugin cache).
      # This keeps provider acquisition deterministic without changing any
      # IAM/DynamoDB/Logs resource structure.
      version = "~> 5.0, != 5.100.0"
    }
  }
}

###############################################################################
# Variables (non-infrastructure, user controlled values only)
###############################################################################

variable "project" {
  description = "Project name used for resource tagging."
  type        = string
  default     = "dynamodb-backup-automation"
}

variable "environment" {
  description = "Deployment environment (for example dev, staging, prod) used for resource tagging."
  type        = string
  default     = "dev"
}

###############################################################################
# Locals
###############################################################################

locals {
  # Static region string used to build tightly scoped IAM resource ARNs.
  aws_region = "us-east-1"

  # CloudWatch Logs ARNs for Lambda function log groups / log streams.
  lambda_log_group_arn  = "arn:aws:logs:${local.aws_region}:*:log-group:/aws/lambda/*"
  lambda_log_stream_arn = "arn:aws:logs:${local.aws_region}:*:log-group:/aws/lambda/*:*"

  # DynamoDB resource ARN patterns (tables and table backups).
  dynamodb_table_arn_patterns  = ["arn:aws:dynamodb:${local.aws_region}:*:table/*"]
  dynamodb_backup_arn_patterns = ["arn:aws:dynamodb:${local.aws_region}:*:table/*/backup/*"]

  common_tags = {
    Project     = var.project
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

###############################################################################
# Shared Lambda trust policy
###############################################################################

data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    sid     = "AllowLambdaServiceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

###############################################################################
# IAM roles
###############################################################################

resource "aws_iam_role" "create_ddb_backup_role" {
  name               = "create_ddb_backup_role"
  description        = "Execution role for the Lambda function that creates DynamoDB backups."
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json

  tags = local.common_tags
}

resource "aws_iam_role" "remove_ddb_backup_role" {
  name               = "remove_ddb_backup_role"
  description        = "Execution role for the Lambda function that lists and deletes DynamoDB backups."
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json

  tags = local.common_tags
}

###############################################################################
# Inline policy for the backup creation role
###############################################################################

data "aws_iam_policy_document" "create_ddb_backup" {
  statement {
    sid    = "CreateDynamoDBBackup"
    effect = "Allow"

    actions = [
      "dynamodb:CreateBackup",
    ]

    resources = local.dynamodb_table_arn_patterns
  }
}

resource "aws_iam_role_policy" "create_ddb_backup_policy" {
  name   = "create_ddb_backup_policy"
  role   = aws_iam_role.create_ddb_backup_role.name
  policy = data.aws_iam_policy_document.create_ddb_backup.json
}

###############################################################################
# Inline policy for the backup removal role
###############################################################################

data "aws_iam_policy_document" "remove_ddb_backup" {
  # dynamodb:ListBackups does not support resource-level permissions, so it has
  # to be scoped with Resource = "*". No wildcard Action is combined with it.
  statement {
    sid    = "ListDynamoDBBackups"
    effect = "Allow"

    actions = [
      "dynamodb:ListBackups",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "DeleteDynamoDBBackup"
    effect = "Allow"

    actions = [
      "dynamodb:DeleteBackup",
    ]

    resources = local.dynamodb_backup_arn_patterns
  }
}

resource "aws_iam_role_policy" "remove_ddb_backup_policy" {
  name   = "remove_ddb_backup_policy"
  role   = aws_iam_role.remove_ddb_backup_role.name
  policy = data.aws_iam_policy_document.remove_ddb_backup.json
}

###############################################################################
# Shared customer managed CloudWatch Logs policy
###############################################################################

data "aws_iam_policy_document" "lambda_logging" {
  statement {
    sid    = "WriteLambdaCloudWatchLogs"
    effect = "Allow"

    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = [
      local.lambda_log_group_arn,
      local.lambda_log_stream_arn,
    ]
  }
}

resource "aws_iam_policy" "lambda_logging" {
  name        = "lambda_logging"
  description = "Shared policy granting Lambda functions permission to write logs to Amazon CloudWatch Logs."
  path        = "/"
  policy      = data.aws_iam_policy_document.lambda_logging.json

  tags = local.common_tags
}

###############################################################################
# Attach the shared logging policy to both roles
###############################################################################

resource "aws_iam_role_policy_attachment" "create_ddb_backup_lambda_logging" {
  role       = aws_iam_role.create_ddb_backup_role.name
  policy_arn = aws_iam_policy.lambda_logging.arn
}

resource "aws_iam_role_policy_attachment" "remove_ddb_backup_lambda_logging" {
  role       = aws_iam_role.remove_ddb_backup_role.name
  policy_arn = aws_iam_policy.lambda_logging.arn
}

###############################################################################
# Outputs
###############################################################################

output "create_ddb_backup_role_arn" {
  description = "ARN of the IAM role used by the Lambda function that creates DynamoDB backups."
  value       = aws_iam_role.create_ddb_backup_role.arn
}

output "create_ddb_backup_role_name" {
  description = "Name of the IAM role used by the Lambda function that creates DynamoDB backups."
  value       = aws_iam_role.create_ddb_backup_role.name
}

output "remove_ddb_backup_role_arn" {
  description = "ARN of the IAM role used by the Lambda function that removes DynamoDB backups."
  value       = aws_iam_role.remove_ddb_backup_role.arn
}

output "remove_ddb_backup_role_name" {
  description = "Name of the IAM role used by the Lambda function that removes DynamoDB backups."
  value       = aws_iam_role.remove_ddb_backup_role.name
}

output "lambda_logging_policy_arn" {
  description = "ARN of the shared customer managed policy granting CloudWatch Logs write access."
  value       = aws_iam_policy.lambda_logging.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  tags = {
    Project = "projectvpc"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, {
    Name = "projectvpc"
  })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.tags, {
    Name = "projectvpc-public-subnet"
  })
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.tags, {
    Name = "projectvpc-private-subnet"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.tags, {
    Name = "projectvpc-igw"
  })
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.tags, {
    Name = "projectvpc-nat-eip"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  tags = merge(local.tags, {
    Name = "projectvpc-nat-gw"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.tags, {
    Name = "projectvpc-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.tags, {
    Name = "projectvpc-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "cloudhealth_trusted_account_id" {
  type        = string
  description = "AWS account ID trusted to assume the CloudHealth cross-account role."
  default     = "111122223333"
}

variable "environment" {
  type        = string
  description = "Deployment environment name used for tagging."
  default     = "prod"
}

variable "tags" {
  type        = map(string)
  description = "Additional tags applied to all created resources."
  default     = {}
}

locals {
  common_tags = merge(
    {
      environment = var.environment
      managed-by  = "terraform"
      purpose     = "cloudhealth-cost-analysis"
    },
    var.tags,
  )
}

resource "random_password" "external_id" {
  length  = 32
  special = false
}

resource "aws_secretsmanager_secret" "cloudhealth_external_id" {
  name        = "cloudhealth/iam-role-external-id"
  description = "External ID used by the CloudHealth-IAM-Role cross-account trust policy."

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "cloudhealth_external_id" {
  secret_id     = aws_secretsmanager_secret.cloudhealth_external_id.id
  secret_string = random_password.external_id.result
}

resource "aws_iam_role" "cloudhealth_iam_role" {
  name                 = "CloudHealth-IAM-Role"
  description          = "Cross-account role assumed by CloudHealth for read-only cost and usage analysis."
  max_session_duration = 3600

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCloudHealthAssumeRoleWithExternalId"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          AWS = var.cloudhealth_trusted_account_id
        }
        Condition = {
          StringEquals = {
            "sts:ExternalId" = random_password.external_id.result
          }
        }
      }
    ]
  })

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_policy" "cloudhealth_iam_role" {
  name        = "CloudHealth-IAM-Role"
  description = "Grants CloudHealth read-only permissions for cost and usage analysis."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "EC2ReadOnly"
        Effect   = "Allow"
        Action   = ["ec2:Describe*"]
        Resource = "*"
      },
      {
        Sid    = "S3CostAndUsageReportReadOnly"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetBucketLocation",
          "s3:GetObject"
        ]
        Resource = "*"
      },
      {
        Sid      = "RDSReadOnly"
        Effect   = "Allow"
        Action   = ["rds:Describe*"]
        Resource = "*"
      },
      {
        Sid    = "CloudWatchReadOnly"
        Effect = "Allow"
        Action = [
          "cloudwatch:Get*",
          "cloudwatch:List*"
        ]
        Resource = "*"
      },
      {
        Sid      = "CostExplorerReadOnly"
        Effect   = "Allow"
        Action   = ["ce:Get*"]
        Resource = "*"
      },
      {
        Sid      = "CostAndUsageReportReadOnly"
        Effect   = "Allow"
        Action   = ["cur:Describe*"]
        Resource = "*"
      },
      {
        Sid      = "BudgetsReadOnly"
        Effect   = "Allow"
        Action   = ["budgets:View*"]
        Resource = "*"
      },
      {
        Sid      = "SupportReadOnly"
        Effect   = "Allow"
        Action   = ["support:Describe*"]
        Resource = "*"
      },
      {
        Sid      = "OrganizationsReadOnly"
        Effect   = "Allow"
        Action   = ["organizations:Describe*"]
        Resource = "*"
      },
      {
        Sid      = "TrustedAdvisorReadOnly"
        Effect   = "Allow"
        Action   = ["trustedadvisor:Describe*"]
        Resource = "*"
      },
      {
        Sid      = "ElasticLoadBalancingReadOnly"
        Effect   = "Allow"
        Action   = ["elasticloadbalancing:Describe*"]
        Resource = "*"
      },
      {
        Sid    = "DynamoDBReadOnly"
        Effect = "Allow"
        Action = [
          "dynamodb:List*",
          "dynamodb:Describe*"
        ]
        Resource = "*"
      },
      {
        Sid    = "LambdaReadOnly"
        Effect = "Allow"
        Action = [
          "lambda:List*",
          "lambda:Get*"
        ]
        Resource = "*"
      },
      {
        Sid    = "ECSReadOnly"
        Effect = "Allow"
        Action = [
          "ecs:List*",
          "ecs:Describe*"
        ]
        Resource = "*"
      },
      {
        Sid    = "KinesisReadOnly"
        Effect = "Allow"
        Action = [
          "kinesis:List*",
          "kinesis:Describe*"
        ]
        Resource = "*"
      },
      {
        Sid    = "SNSReadOnly"
        Effect = "Allow"
        Action = [
          "sns:List*",
          "sns:Get*"
        ]
        Resource = "*"
      },
      {
        Sid    = "SQSReadOnly"
        Effect = "Allow"
        Action = [
          "sqs:List*",
          "sqs:Get*"
        ]
        Resource = "*"
      },
      {
        Sid      = "RedshiftReadOnly"
        Effect   = "Allow"
        Action   = ["redshift:Describe*"]
        Resource = "*"
      },
      {
        Sid      = "ElastiCacheReadOnly"
        Effect   = "Allow"
        Action   = ["elasticache:Describe*"]
        Resource = "*"
      },
      {
        Sid    = "IAMReadOnly"
        Effect = "Allow"
        Action = [
          "iam:Get*",
          "iam:List*"
        ]
        Resource = "*"
      }
    ]
  })

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy_attachment" "cloudhealth_iam_role" {
  role       = aws_iam_role.cloudhealth_iam_role.name
  policy_arn = aws_iam_policy.cloudhealth_iam_role.arn
}

output "cloudhealth_iam_role_arn" {
  description = "ARN of the CloudHealth cross-account IAM role."
  value       = aws_iam_role.cloudhealth_iam_role.arn
}

output "cloudhealth_iam_policy_arn" {
  description = "ARN of the CloudHealth read-only IAM policy."
  value       = aws_iam_policy.cloudhealth_iam_role.arn
}

output "cloudhealth_external_id_secret_arn" {
  description = "ARN of the Secrets Manager secret containing the generated external ID."
  value       = aws_secretsmanager_secret.cloudhealth_external_id.arn
  sensitive   = true
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

locals {
  tags = {
    Project = "endpoint-backup"
  }

  bucket_name = "endpoint-backup-${data.aws_caller_identity.current.account_id}"
}

###############################################################################
# Customer-managed KMS key for bucket default encryption (SSE-KMS)
###############################################################################

resource "aws_kms_key" "endpoint_backup" {
  description             = "Customer-managed KMS key for endpoint-backup S3 bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = local.tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowEndpointBackupUserViaS3"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_user.endpoint_backup.arn
        }
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:ViaService" = "s3.us-east-1.amazonaws.com"
          }
        }
      }
    ]
  })
}

resource "aws_kms_alias" "endpoint_backup" {
  name          = "alias/endpoint-backup"
  target_key_id = aws_kms_key.endpoint_backup.key_id
}

###############################################################################
# S3 bucket
###############################################################################

resource "aws_s3_bucket" "endpoint_backup" {
  bucket = local.bucket_name

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_accelerate_configuration" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id
  status = "Suspended"
}

resource "aws_s3_bucket_server_side_encryption_configuration" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.endpoint_backup.arn
    }
    bucket_key_enabled = true
  }
}

###############################################################################
# Bucket policy: enforce TLS and restrict compliance-mode retention
###############################################################################

resource "aws_s3_bucket_policy" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyRequestsNotOverTLS"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.endpoint_backup.arn,
          "${aws_s3_bucket.endpoint_backup.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      },
      {
        Sid       = "DenyTLSVersionBelow12"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.endpoint_backup.arn,
          "${aws_s3_bucket.endpoint_backup.arn}/*"
        ]
        Condition = {
          NumericLessThan = {
            "s3:TlsVersion" = "1.2"
          }
        }
      },
      {
        Sid       = "DenyComplianceRetentionGreaterThan90Days"
        Effect    = "Deny"
        Principal = "*"
        Action = [
          "s3:PutObject",
          "s3:PutObjectRetention"
        ]
        Resource = "${aws_s3_bucket.endpoint_backup.arn}/*"
        Condition = {
          StringEquals = {
            "s3:object-lock-mode" = "COMPLIANCE"
          }
          NumericGreaterThan = {
            "s3:object-lock-remaining-retention-days" = "90"
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.endpoint_backup]
}

###############################################################################
# IAM user + least-privilege customer-managed policy (no access keys created)
###############################################################################

resource "aws_iam_user" "endpoint_backup" {
  name = "endpoint-backup"

  tags = local.tags
}

resource "aws_iam_policy" "endpoint_backup_bucket_read_write_access" {
  name        = "endpoint-backup-bucket-read-write-access"
  description = "Read/write access to the endpoint-backup S3 bucket, including versioning, retention and restore operations."

  tags = local.tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "BucketLevelAccess"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:ListBucketVersions",
          "s3:ListBucketMultipartUploads",
          "s3:GetBucketLocation",
          "s3:GetBucketVersioning"
        ]
        Resource = aws_s3_bucket.endpoint_backup.arn
      },
      {
        Sid    = "ObjectLevelAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:GetObjectVersion",
          "s3:DeleteObjectVersion",
          "s3:AbortMultipartUpload",
          "s3:ListMultipartUploadParts",
          "s3:GetObjectRetention",
          "s3:PutObjectRetention",
          "s3:GetObjectTagging",
          "s3:PutObjectTagging",
          "s3:RestoreObject"
        ]
        Resource = "${aws_s3_bucket.endpoint_backup.arn}/*"
      },
      {
        Sid    = "S3ManagedKeyAccess"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey",
          "kms:GenerateDataKey"
        ]
        Resource = aws_kms_key.endpoint_backup.arn
        Condition = {
          StringEquals = {
            "kms:ViaService" = "s3.us-east-1.amazonaws.com"
          }
        }
      }
    ]
  })
}

resource "aws_iam_user_policy_attachment" "endpoint_backup" {
  user       = aws_iam_user.endpoint_backup.name
  policy_arn = aws_iam_policy.endpoint_backup_bucket_read_write_access.arn
}

terraform {
  required_version = ">= 1.4.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Providers - four regions: primary source (us-east-1), second source,
# first replica region, second replica region.
###############################################################################

provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "source2"
  region = "us-west-2"
}

provider "aws" {
  alias  = "replica1"
  region = "eu-west-1"
}

provider "aws" {
  alias  = "replica2"
  region = "ap-southeast-1"
}

###############################################################################
# Static provider metadata lookups (no pre-existing infrastructure required)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_region" "source2" {
  provider = aws.source2
}

data "aws_region" "replica1" {
  provider = aws.replica1
}

data "aws_region" "replica2" {
  provider = aws.replica2
}

###############################################################################
# Locals
###############################################################################

locals {
  account_id       = data.aws_caller_identity.current.account_id
  partition        = data.aws_partition.current.partition
  account_root_arn = "arn:${local.partition}:iam::${local.account_id}:root"

  tags = {
    Env = "dev"
  }

  source_bucket_arns = [
    aws_s3_bucket.source_log1a.arn,
    aws_s3_bucket.source_log1b.arn,
    aws_s3_bucket.source_log2a.arn,
    aws_s3_bucket.source_log2b.arn,
  ]

  source_object_arns = [
    for arn in local.source_bucket_arns : "${arn}/*"
  ]

  replica_bucket_arns = [
    aws_s3_bucket.replica_log1a_r1.arn,
    aws_s3_bucket.replica_log1b_r1.arn,
    aws_s3_bucket.replica_log2a_r1.arn,
    aws_s3_bucket.replica_log2b_r1.arn,
    aws_s3_bucket.replica_log1a_r2.arn,
    aws_s3_bucket.replica_log1b_r2.arn,
    aws_s3_bucket.replica_log2a_r2.arn,
    aws_s3_bucket.replica_log2b_r2.arn,
  ]

  replica_object_arns = [
    for arn in local.replica_bucket_arns : "${arn}/*"
  ]
}

###############################################################################
# Customer managed KMS keys - one per region
###############################################################################

resource "aws_kms_key" "source_key1" {
  description             = "SSE-KMS CMK for source log buckets in ${data.aws_region.current.name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableRootAccountAdmin"
        Effect    = "Allow"
        Principal = { AWS = local.account_root_arn }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "AllowS3ReplicationRoleDecrypt"
        Effect    = "Allow"
        Principal = { AWS = aws_iam_role.s3_replication.arn }
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "source_key1" {
  name          = "alias/sourcekey1"
  target_key_id = aws_kms_key.source_key1.id
}

resource "aws_kms_key" "source_key2" {
  provider                = aws.source2
  description             = "SSE-KMS CMK for source log buckets in ${data.aws_region.source2.name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableRootAccountAdmin"
        Effect    = "Allow"
        Principal = { AWS = local.account_root_arn }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "AllowS3ReplicationRoleDecrypt"
        Effect    = "Allow"
        Principal = { AWS = aws_iam_role.s3_replication.arn }
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "source_key2" {
  provider      = aws.source2
  name          = "alias/sourcekey2"
  target_key_id = aws_kms_key.source_key2.id
}

resource "aws_kms_key" "replica_key1" {
  provider                = aws.replica1
  description             = "SSE-KMS CMK for replica log buckets in ${data.aws_region.replica1.name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableRootAccountAdmin"
        Effect    = "Allow"
        Principal = { AWS = local.account_root_arn }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "AllowS3ReplicationRoleEncrypt"
        Effect    = "Allow"
        Principal = { AWS = aws_iam_role.s3_replication.arn }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:ReEncrypt*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "replica_key1" {
  provider      = aws.replica1
  name          = "alias/replicakey1"
  target_key_id = aws_kms_key.replica_key1.id
}

resource "aws_kms_key" "replica_key2" {
  provider                = aws.replica2
  description             = "SSE-KMS CMK for replica log buckets in ${data.aws_region.replica2.name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableRootAccountAdmin"
        Effect    = "Allow"
        Principal = { AWS = local.account_root_arn }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "AllowS3ReplicationRoleEncrypt"
        Effect    = "Allow"
        Principal = { AWS = aws_iam_role.s3_replication.arn }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:ReEncrypt*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "replica_key2" {
  provider      = aws.replica2
  name          = "alias/replicakey2"
  target_key_id = aws_kms_key.replica_key2.id
}

###############################################################################
# IAM role, policy and attachment used by S3 replication
###############################################################################

resource "aws_iam_role" "s3_replication" {
  name        = "s3-cross-region-replication-role"
  description = "Role assumed by S3 to replicate versioned, SSE-KMS encrypted log objects across regions"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowS3ServiceToAssumeRole"
        Effect    = "Allow"
        Principal = { Service = "s3.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_policy" "s3_replication" {
  name        = "s3-cross-region-replication-policy"
  description = "Least privilege policy allowing the S3 replication role to read source log buckets and write re-encrypted objects into the replica buckets"
  path        = "/"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SourceBucketLevelRead"
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket",
          "s3:ListBucketVersions"
        ]
        Resource = local.source_bucket_arns
      },
      {
        Sid    = "SourceObjectVersionRead"
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Resource = local.source_object_arns
      },
      {
        Sid    = "ReplicaBucketObjectWrite"
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
          "s3:ObjectOwnerOverrideToBucketOwner"
        ]
        Resource = local.replica_object_arns
      },
      {
        Sid    = "DecryptSourceKmsKeys"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey"
        ]
        Resource = [
          aws_kms_key.source_key1.arn,
          aws_kms_key.source_key2.arn
        ]
      },
      {
        Sid    = "EncryptWithReplicaKmsKeys"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:ReEncrypt*",
          "kms:DescribeKey"
        ]
        Resource = [
          aws_kms_key.replica_key1.arn,
          aws_kms_key.replica_key2.arn
        ]
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "s3_replication" {
  role       = aws_iam_role.s3_replication.name
  policy_arn = aws_iam_policy.s3_replication.arn
}

###############################################################################
# Source region 1 (us-east-1) buckets
###############################################################################

resource "aws_s3_bucket" "source_log1a" {
  bucket = "log1a.veerum-${local.account_id}"
  tags   = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "source_log1a" {
  bucket = aws_s3_bucket.source_log1a.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "source_log1a" {
  bucket                  = aws_s3_bucket.source_log1a.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "source_log1a" {
  bucket = aws_s3_bucket.source_log1a.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.source_key1.arn
    }

    bucket_key_enabled = true
  }
}

