  bucket                  = aws_s3_bucket.replica_log1b_r2.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica_log1b_r2" {
  provider = aws.replica2
  bucket   = aws_s3_bucket.replica_log1b_r2.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.replica_key2.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket" "replica_log2a_r2" {
  provider = aws.replica2
  bucket   = "log2a.veerum-replica2-${local.account_id}"
  tags     = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "replica_log2a_r2" {
  provider = aws.replica2
  bucket   = aws_s3_bucket.replica_log2a_r2.id

  versioning_configuration {
    status = "Enabled"
