###############################################################################
# Replication configuration - source region 1 buckets
###############################################################################

resource "aws_s3_bucket_replication_configuration" "source_log1a" {
  bucket = aws_s3_bucket.source_log1a.id
  role   = aws_iam_role.s3_replication.arn

  rule {
    id       = "log1a-to-replica1"
    status   = "Enabled"
    priority = 1

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica_log1a_r1.arn
      storage_class = "STANDARD"
      account       = local.account_id

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica_key1.arn
      }
    }
  }

  rule {
    id       = "log1a-to-replica2"
    status   = "Enabled"
    priority = 2

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica_log1a_r2.arn
      storage_class = "STANDARD"
      account       = local.account_id

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica_key2.arn
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.source_log1a,
    aws_s3_bucket_versioning.replica_log1a_r1,
    aws_s3_bucket_versioning.replica_log1a_r2,
  ]
}

